window.__D("text/zohar-hebrew-translation/c020",{"p":[[9522011801,"<p>בֹּא וּרְאֵה, הַשָּׂעִיר הַהוּא שֶׁשּׁוֹלְחִים יִשְׂרָאֵל לַעֲזָאזֵל לַמִּדְבָּר הַהוּא, כְּדֵי לָתֵת חֵלֶק לַצַּד הָאַחֵר הַהוּא לְהִתְעַסֵּק אִתּוֹ. וְאִם תֹּאמַר, שְׁנֵי שְׂעִירִים לָמָּה כָּאן? אֶחָד לַה', וְאֶחָד לַצַּד הָאַחֵר הַהוּא. נִיחָא הַשָּׂעִיר הַהוּא שֶׁל הַצַּד הָאַחֵר, אַךְ לַה' מַדּוּעַ?</p>\n<p>אֶלָּא, לְמֶלֶךְ שֶׁהָיָה כּוֹעֵס עַל בְּנוֹ, קָרָא לַשּׁוֹטֵר, זֶה שֶׁעוֹשֶׂה דִּין בִּבְנֵי אָדָם תָּמִיד, כְּדֵי שֶׁיִּתְכּוֹנֵן לַעֲשׂוֹת דִּין בִּבְנוֹ. הַשּׁוֹטֵר הַהוּא שָׂמַח, וְנִכְנַס לְבֵית הַמֶּלֶךְ לֶאֱכֹל שָׁם. כֵּיוָן שֶׁרָאָה אוֹתוֹ בְנוֹ, אָמַר, וַדַּאי לֹא נִכְנַס הַשּׁוֹטֵר כָּאן בְּבֵית אָבִי אֶלָּא מִשּׁוּם שֶׁכָּעַס הַמֶּלֶךְ עָלַי. מֶה עָשָׂה? הָלַךְ וְהִתְפַּיֵּס עִמּוֹ. וּמִשּׁוּם שֶׁהִתְפַּיֵּס עִמּוֹ, צִוָּה הַמֶּלֶךְ לַעֲשׂוֹת סְעוּדָה עֶלְיוֹנָה לוֹ וְלִבְנוֹ, וְצִוָּה שֶׁלֹּא יֵדַע בּוֹ הַשּׁוֹטֵר הַהוּא. לְבַסּוֹף נִכְנַס הַשּׁוֹטֵר הַהוּא. אָמַר הַמֶּלֶךְ, עַתָּה אִם יֵדַע זֶה מֵהַסְּעוּדָה הָעֶלְיוֹנָה שֶׁהֵכַנְתִּי לִי וְלִבְנִי, יִתְבַּלְבֵּל הַשֻּׁלְחָן. מֶה עָשָׂה? קָרָא לַמְמֻנֶּה עַל הַסְּעוּדָה וְאָמַר לוֹ, תָּכִין מַשֶּׁהוּ וְתָשִׂים לְפָנַי, וְתָשִׂים לִפְנֵי הַשּׁוֹטֵר הַהוּא, כְּדֵי שֶׁיַּחְשֹׁב שֶׁסּוֹעֵד לְפָנַי מִשֶּׁלִּי, וְלֹא יֵדַע מֵהַסְּעוּדָה הַחֲשׁוּבָה הַהִיא שֶׁל שִׂמְחָה שֶׁלִּי וְשֶׁל בְּנִי, וְיִקַּח הַחֵלֶק הַהוּא וְיֵלֵךְ לוֹ, וְיִתְרַחֵק מֵהַשִּׂמְחָה שֶׁל הַסְּעוּדָה שֶׁלָּנוּ. וְאִם לֹא שֶׁעָשָׂה הַמֶּלֶךְ כָּךְ, לֹא יִתְרַחֵק הַשּׁוֹטֵר הַהוּא מִבֵּית הַמֶּלֶךְ.</p>\n<p>כָּךָ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, תַּזְמִינוּ שְׁנֵי שְׂעִירִים, אֶחָד לִי וְאֶחָד לַמְקַטְרֵג הַהוּא, כְּדֵי שֶׁיַּחְשֹׁב שֶׁמִּסְּעוּדָה שֶׁלִּי הוּא אוֹכֵל, וְלֹא יֵדַע בִּסְעוּדַת הַשִּׂמְחָה הָאַחֶרֶת שֶׁלָּנוּ, וְיִקַּח הַחֵלֶק הַהוּא וְיֵלֵךְ לְדַרְכּוֹ וְיִתְרַחֵק מִבֵּיתִי. כֵּיוָן שֶׁאִמָּא הָעֶלְיוֹנָה, עוֹלָם הַבָּא, בָּאָה לִשְׁרוֹת תּוֹךְ הַהֵיכָל שֶׁל הָעוֹלָם הַתַּחְתּוֹן לִמְצֹא אוֹר (להשגיח עליה בהארה) שֶׁל הַפָּנִים, דִּין הוּא שֶׁלֹּא יִמָּצֵא הַמְקַטְרֵג הַהוּא, וְלֹא בַעֲלֵי הַדִּין לְפָנָיו, כַּאֲשֶׁר מוֹצִיא כָל הַבְּרָכוֹת וּמֵאִיר לְכֻלָּם. וְכָל שֶׁפַע הַחֵרוּת הַהוּא נִמְצָא, וְיִשְׂרָאֵל נוֹטְלִים מֵאֵלּוּ הַבְּרָכוֹת.</p>\n<p>שֶׁהֲרֵי כַּאֲשֶׁר הָעוֹלָם הַבָּא נִכְנָס לַהֵיכָל שֶׁל הָעוֹלָם הַתַּחְתּוֹן וּמוֹצֵא שֶׁשָּׂמֵחַ הָעוֹלָם הַתַּחְתּוֹן עִם בָּנָיו בַּסְּעוּדָה הָעֶלְיוֹנָה הַהִיא, אָז הוּא מְבָרֵךְ הַשֻּׁלְחָן, וְהָעוֹלָמוֹת כֻּלָּם מִתְבָּרְכִים, וְכָל שִׂמְחָה וְכָל הֶאָרַת הַפָּנִים נִמְצָאוֹת שָׁם. זֶהוּ שֶׁכָּתוּב (ויקרא טז) לִפְנֵי ה' תִּטְהָרוּ.</p>\n<p>כָּתוּב (ויקרא טז) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִם גֹּרָלוֹת גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל. זוֹהִי הַשִּׂמְחָה הַהִיא שֶׁל הַמְקַטְרֵג הַהוּא, כְּדֵי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַפִּיל עִמּוֹ גוֹרָל, וּמַזְמִין אוֹתוֹ, וְלֹא יוֹדֵעַ שֶׁאֵשׁ דּוֹלֵק שָׁם עַל רֹאשׁוֹ וְעַל הָעָם שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (משלי כה) כִּי גֶחָלִים אַתָּה חֹתֶה עַל רֹאשׁוֹ.</p>\n<p>וְסִימָנְךָ - (אסתר ה) אַף לֹא הֵבִיאָה אֶסְתֵּר הַמַּלְכָּה עִם הַמֶּלֶךְ אֶל הַמִּשְׁתֶּה אֲשֶׁר עָשָׂתָה כִּי אִם אוֹתִי. וְכָתוּב, וַיֵּצֵא הָמָן בַּיּוֹם הַהוּא שָׂמֵחַ וְטוֹב לֵב. בַּחֵלֶק הַהוּא שֶׁנּוֹטֵל, וְהוֹלֵךְ לוֹ. וּבַסּוֹף, כַּאֲשֶׁר בָּא הַמֶּלֶךְ הָעֶלְיוֹן לְבֵית הַמַּלְכָּה, הַמַּלְכָּה מְבַקֶּשֶׁת עָלֶיהָ וְעַל בָּנֶיהָ וְעַל עַמָּהּ מִן הַמֶּלֶךְ.</p>\n<p>וַאֲפִלּוּ בִּזְמַן שֶׁיִּשְׂרָאֵל בְּגָלוּת וּמִתְפַּלְלִים תְּפִלּוֹת בְּכָל יוֹם, הִיא עוֹלָה בְּיוֹם זֶה לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן וּמְבַקֶּשֶׁת עַל בָּנֶיהָ, וְאָז נִגְזָרוֹת כָּל אוֹתָן נְקָמוֹת שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת עִם אֱדוֹם, וְנִגְזָר אֵיךְ עָתִיד הַמְקַטְרֵג הַזֶּה לַעֲבֹר מִן הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח.</p>\n<p>וְסִימָנְךָ - בִּזְמַן הַגָּלוּת (אסתר ז) כִּי נִמְכַּרְנוּ אֲנִי וְגוֹ'. כִּי אֵין הַצָּר שֹׁוֶה בְּנֵזֶק הַמֶּלֶךְ. מַה זֶּה בְּנֵזֶק הַמֶּלֶךְ? כְּמוֹ שֶׁנֶּאֱמַר (יהושע ז) וְהִכְרִיתוּ אֶת שְׁמֵנוּ מִן הָאָרֶץ וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. שֶׁהֲרֵי הַשֵּׁם הָעֶלְיוֹן לֹא מִתְקַיֵּם בְּקִיּוּמוֹ, וְזֶהוּ בְּנֵזֶק הַמֶּלֶךְ.</p>\n<p>וְאָז, וְהָמָן נִבְעַת מִלִּפְנֵי הַמֶּלֶךְ וְהַמַּלְכָּה. אָז אוֹר הַפָּנִים וְכָל שִׂמְחָה נִמְצֵאת, וְיִשְׂרָאֵל יוֹצְאִים לַחֵרוּת בַּיּוֹם הַהוּא. וְאָז, מֵהַיּוֹם הַהוּא וָהָלְאָה, חֵרוּת וְשִׂמְחָה בְגִלּוּי לִשְׁלֹט עֲלֵיהֶם, וְאָז צָרִיךְ לִשְׂמֹחַ עִמָּהֶם. מִכָּאן וָהָלְאָה, כְּמוֹ שֶׁנָּתְנוּ לוֹ חֵלֶק לְהִתְרַחֵק מֵהֶם, כָּךְ גַּם נוֹתְנִים לִשְׁאָר הָעַמִּים לְהִתְרַחֵק מֵהֶם לְמַטָּה.</p>\n<p>בֹּא וּרְאֵה, מַה הוּא סוֹד הַקָּרְבָּנוֹת לְהַקְרִיב שָׂעִיר (כנגד שעיר) וְלֹא דָבָר אַחֵר? וּמַדּוּעַ שָׂעִיר בְּרֹאשׁ חֹדֶשׁ, וְכָאן גַּם כֵּן שָׂעִיר? אֶלָּא, אִם תֹּאמַר מִשּׁוּם שֶׁהוּא צַד שֶׁלּוֹ - טוֹב. מַדּוּעַ לֹא הָיָה עֵז?</p>\n<p>אֶלָּא דָּבָר זֶה צָרִיךְ, וְהוּא נִמְצָא לְבַעֲלֵי כִשּׁוּפִים, שֶׁכָּל מַעֲשֵׂיהֶם בְּמַה שֶּׁלֹּא (מתחבר) יִהְיֶה בִנְקֵבָה. וְעַל זֶה שָׂעִיר, שֶׁלֹּא הִתְחַבֵּר בִּנְקֵבָה בְּכָל הַצְּדָדִים שֶׁלּוֹ. עֵז, כַּאֲשֶׁר הִתְחַבֵּר בִּנְקֵבָה. וּמִשּׁוּם שֶׁהוּא מֶלֶךְ, נוֹתְנִים לוֹ מִשּׁוּם הַכָּבוֹד שֶׁלּוֹ, זֶה שֶׁלֹּא הִתְחַבֵּר בִּנְקֵבָה וְלֹא נָתַן כֹּחוֹ לְאַחֵר. וְזֶה יָדוּעַ לְאוֹתָם הַמְכַשְּׁפִים שֶׁמִּשְׁתַּמְּשִׁים בְּמַעֲשִׂים אֵלֶּה. וּמִפְּנֵי כָּךְ שׁוֹרִים עַל הַשָּׂעִיר הַהוּא כָּל אוֹתָם הַחֲטָאִים.</p>\n<p>בֹּא וּרְאֵה, אַף עַל גַּב שֶׁהוּא חֵלֶק לַצַּד הָאַחֵר הַהוּא - סוֹד כָּאן. כָּל אֵלּוּ צְדָדִים אֲחֵרִים שֶׁלְּמַטָּה (שגקראים מצולות ים), כֻּלָּם טְמֵאִים יוֹתֵר. וְכָל מַה שֶּׁיּוֹרְדִים מִדְּרָגוֹת תַּחְתּוֹנוֹת, כָּךְ הַטֻּמְאָה שֶׁלָּהֶם יוֹתֵר. וּמִפְּנֵי כֵן בְּעֵז, חֶלְקָם יוֹתֵר, מִשּׁוּם שֶׁהַשְּׂעָרוֹת שֶׁלּוֹ תְּלוּיוֹת יוֹתֵר מִבְּהֵמָה אַחֶרֶת, כְּמוֹ שֶׁדִּין שֶׁלָּהֶם תָּלוּי לְמַטָּה בַטֻּמְאָה. אֲבָל מַלְכוּת הָרְשָׁעָה הַזּוֹ הָאַחֶרֶת, מֶלֶךְ שֶׁל הַכֹּל בַּצַּד הַהוּא, הַטֻּמְאָה שֶׁלּוֹ הִיא יוֹתֵר מֻבְחֶרֶת, וְלֹא טֻמְאָה שְׁלֵמָה כְּאֵלֶּה הַתַּחְתּוֹנִים. וְעַל זֶה שָׂעִיר, שֶׁהַשֵּׂעָר שֶׁלּוֹ לֹא תָלוּי וְלֹא חָלָק. לֹא חָלָק, מִפְּנֵי הַטֻּמְאָה הַהִיא שֶׁלּוֹ. וְלֹא תָלוּי, כְּדֵי שֶׁלֹּא תִתְחַזֵּק בּוֹ טֻמְאָה כְּאֵלֶּה הַתַּחְתּוֹנִים, וְעַל זֶה וַדַּאי שָׂעִיר, וְלֹא אַחֵר.</p>\n<p>כִּפּוּר, מַדּוּעַ נִקְרָא כִּפּוּר? אֶלָּא מִפְּנֵי שֶׁמְּנַקֶּה כָּל טֻמְאָה וּמַעֲבִיר אוֹתָהּ מִלְּפָנָיו בַּיּוֹם הַהוּא. וְעַל זֶה יוֹם כִּפּוּר יוֹם שֶׁל נִקָּיוֹן, וְכָךְ קוֹרְאִים לוֹ, שֶׁכָּתוּב (ויקרא טז) כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם. כִּי הַיּוֹם הַזֶּה צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה כִּי בַיּוֹם הַזֶּה? אֶלָּא מִשּׁוּם שֶׁמְּטַהֵר מִקְדָּשׁ לְמַעְלָה וּמִתְנַקֶּה (ומאיר), כָּתוּב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם. יְכַפֵּר וִינַקֶּה בַתְּחִלָּה בַּיּוֹם הַזֶּה, כְּדֵי שֶׁיִּטְהַר, וּלְבַסּוֹף עֲלֵיכֶם.</p>\n<p>עוֹד, יְכַפֵּר בַּיּוֹם הַזֶּה, וִינַקֶּה לוֹ בַתְּחִלָּה. וְכָל זֶה עֲלֵיכֶם, בְּסִבַּתְכֶם צָרִיךְ לְנַקּוֹת אוֹתָהּ, וּלְטַהֵר אוֹתָהּ תְּחִלָּה. יְכַפֵּר - מִי יְכַפֵּר? אֶלָּא זֶהוּ עוֹלָם הָעֶלְיוֹן שֶׁמֵּאִיר וּמְנַקֶּה לְכֻלָּם. וְעַל זֶה כָּל צְדָדִים רָעִים, שֶׁנִּקְרָאִים מְצוּלוֹת יָם, עוֹבְרִים. וּכְמוֹ שֶׁאוֹתָן מְצוּלוֹת יָם תְּלוּיוֹת, כָּךְ גַּם תְּלוּיוֹת שְׂעָרוֹת (שלו, שהוא צד) שֶׁלּוֹ, שֶׁהוּא צַד שֶׁלָּהֶם, וְשֵׂעָר שֶׁל הַצַּד הַהוּא לֹא חָלָק.</p>\n<p>כְּמוֹ זֶה כָתוּב, (שם) וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת בְּנֵי יִשְׂרָאֵל וּמִפִּשְׁעֵיהֶם לְכָל חַ אתָם. וְכָל חַ אתָם צָרִיךְ לוֹ לוֹמַר! אֶלָּא לַהֲנָאָה שֶׁלָּהֶם. מִכָּאן וָהָלְאָה לְכָל חַטֹּאתָם, שֶׁלֹּא יָכוֹל הַמְקַטְרֵג לִשְׁלֹט עֲלֵיהֶם (ועל זה) בְּיוֹם כִּפּוּר, שֶׁהוּא הַעֲבָרַת כָּל הַחוֹבוֹת וְנִקּוּי שֶׁלָּהֶם. צְרִיכִים יִשְׂרָאֵל לְנַקּוֹת עַצְמָם וְלָלֶכֶת יְחֵפֵי רַגְלַיִם כְּמַלְאֲכֵי עֶלְיוֹן. חֲמִשָּׁה עִנּוּיִים כְּדֵי לְהֵעָזֵר בַּחֲמִשָּׁה צְדָדִים עֶלְיוֹנִים שֶׁיּוֹם הַכִּפּוּרִים מוֹצִיא אוֹתָם, וְהֵם שְׁעָרִים שֶׁלּוֹ.</p>\n<p>וְאִם שְׁתִיָּה מַחֲשִׁיב, שֶׁהִיא מִצַּד שֶׁל יִצְחָק, הֲרֵי שִׁשָּׁה. וְאַף עַל גַּב שֶׁבִּכְלַל אֲכִילָה הִיא, וְאָז הֵם שִׁשָּׁה, וְעִנּוּי אַחֲרוֹן תַּשְׁמִישׁ הַמִּטָּה הוּא, וּבְדַרְגָּה שִׁשִּׁית נִמְצָא, וּכְנֶגְדָּהּ אָנוּ עוֹשִׂים עִנּוּי זֶה.</p>"],[9522011802,"<p>כָּתוּב (במדבר כט) וּבֶעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה, וְכָתוּב (ויקרא כג) אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר - בָּעֲשִׂירִי צָרִיךְ לוֹ לוֹמַר! מַה זֶּה בֶּעָשׂוֹר? אֶלָּא מִשּׁוּם שֶׁעַתָּה בְּיוֹם זֶה, כָּל מַדְרֵגוֹת עֶלְיוֹנוֹת בָּאוֹת אֵלּוּ עַל אֵלּוּ לִשְׁרוֹת עַל הַלְּבָנָה וּלְהָאִיר אוֹתָהּ, וְכֻלָּן בְּסוֹד שֶׁל עֶשֶׂר, עַד שֶׁעוֹלָה לְמֵאָה. וְכַאֲשֶׁר עוֹמֶדֶת בְּסוֹד שֶׁל מֵאָה, אָז הַכֹּל אֶחָד, וְנִקְרָא יוֹם הַכִּפּוּרִים. וְעַל זֶה בֶּעָשׂוֹר, כְּמוֹ שֶׁאַתָּה אוֹמֵר זָכוֹר, שָׁמוֹר, שֶׁכֻּלָּם בָּאִים כְּדֵי לְעַשֵּׂר וּלְהָאִיר בְּסוֹד שֶׁל עֶשֶׂר.</p>\n<p>הֶחֱזִיר הַזָּקֵן הַזֶּה רֹאשׁוֹ כְּנֶגֶד רַבִּי שִׁמְעוֹן, וְאָמַר לוֹ, (רבי שמעון,) הֲרֵי יָדַעְתִּי שֶׁשְּׁאֵלָה תַקְשֶׁה בְכָאן, בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי. אָמַר לוֹ רַבִּי שִׁמְעוֹן, וַדַּאי, (זה בעשירי נכון הוא וכן הוא, אבל בעשור מדוע וכו') בֶּעָשׂוֹר נָכוֹן הוּא. אִם כָּךְ הוּא, מַדּוּעַ עוֹלֶה לְמֵאָה? וַהֲרֵי מֵהַפָּסוּק לֹא נִרְאֶה, אֶלָּא שֶׁעוֹלֶה לְשִׁבְעִים, מִמַּשְׁמָע שֶׁכָּתוּב בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי. וְכַאֲשֶׁר מְעַשְּׂרִים לַשְּׁבִיעִי עֶשֶׂר פְּעָמִים, הֲרֵי וַדַּאי עוֹלֶה לְשִׁבְעִים. אָמַר לוֹ, עַל זֶה הֶחֱזַרְתִּי רֹאשִׁי כְלַפֶּיךְ, שֶׁהֲרֵי יָדַעְתִּי שֶׁחָכָם אַתָּה.</p>\n<p>בֹּא וּרְאֵה, שְׁנֵי סוֹדוֹת כָּאן. אֶחָד, שֶׁהֲרֵי הַלְּבָנָה נִקְרֵאת חֹדֶשׁ הַשְּׁבִיעִי, וּמִפְּנֵי כֵן נִקְרָא חֹדֶשׁ הַשְּׁבִיעִי עָשׂוֹר, מִפְּנֵי שֶׁכְּשֶׁמְּאִירִים לָהּ עֶשֶׂר פְּעָמִים - הֲרֵי מֵאָה. וְעוֹד, דָּבָר זֶה שֶׁאָמַרְתָּ, וַדַּאי לְשִׁבְעִים עוֹלָה בְּיוֹם זֶה (ובמדרגה של שבעים היא, ובמדרגה של מאה היא, לדרגה של מאה להשלים ולהאיר). וּבְדַרְגָּה זוֹ שֶׁל שִׁבְעִים, שֶׁהֲרֵי בְּיוֹם זֶה נוֹטֵל לְכָל עַם יִשְׂרָאֵל לָדוּן, וְכֻלָּם עוֹמְדִים בַּנְּשָׁמָה יוֹתֵר מֵהַגּוּף, שֶׁהֲרֵי בְּיוֹם זֶה עִנּוּי שֶׁל הַנֶּפֶשׁ הוּא, וְלֹא שֶׁל הַגּוּף, כְּמוֹ שֶׁנֶּאֱמַר וְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם. כִּי כָל הַנֶּפֶשׁ אֲשֶׁר לֹא תְעֻנֶּה. וְיוֹם זֶה לוֹקֵחַ לְכָל הַנְּפָשׁוֹת וְנִמְצָאוֹת בִּרְשׁוּתוֹ. וְאִם לֹא עוֹמֶדֶת בְּסוֹד (ברשות) שֶׁל שִׁבְעִים, אֵין לָהּ רְשׁוּת בַּנְּפָשׁוֹת (לעמד שם), שֶׁעֲמִידַת הַנְּפָשׁוֹת בְּסוֹד שֶׁל שִׁבְעִים, כְּמוֹ שֶׁנֶּאֱמַר (תהליםצ) יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה וְגוֹ'.</p>\n<p>וְאִם תֹּאמַר, נַפְשׁוֹת הַיְלָדִים שֶׁלֹּא הִשְׁלִימוּ לְשִׁבְעִים שָׁנָה לֹא שׁוֹלֶטֶת בָּהֶם - וַדַּאי שֶׁשּׁוֹלֶטֶת בָּהֶם, אֲבָל לֹא בִשְׁלֵמוּת, כְּמִי שֶׁזָּכָה לְיָמִים הַרְבֵּה לְמִצְווֹת הַתּוֹרָה, וְעִם כָּל זֶה, בְּכָל שִׁבְעִים שָׁנָה הִיא הוֹלֶכֶת. וְעַל זֶה לָמַדְנוּ, אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט. מַה זֶּה אֶחָד? בְּיִחוּד שֶׁל שִׁבְעִים שָׁנָה, מִי שֶׁמַּרְבֶּה וּמִי שֶׁמַּמְעִיט.</p>\n<p>וְעַל זֶה בְּיוֹם הַכִּפּוּרִים עוֹבֶרֶת בְּכָל הַשִּׁבְעִים, וְנִשְׁלֶמֶת דַּרְגָּה זוֹ בְּכֻלָּם, וְכָל הַנְּשָׁמוֹת עוֹלוֹת לְפָנָיו, וְדָן אֶת כֻּלָּן בְּדִין, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עַל יִשְׂרָאֵל בְּיוֹם זֶה. מִי שֶׁלֹּא הֶעֱבִיר טִנּוּף מֵרוּחוֹ לְכַפֵּר עָלָיו, (ביום זה) כַּאֲשֶׁר עוֹלָה תְפִלָּתוֹ בְּיוֹם זֶה, טוֹבֵעַ בַּמָּקוֹם הַהוּא שֶׁנִּקְרָא רֶפֶשׁ וָטִיט, וְהוּא מְצוּלוֹת יָם, וְלֹא עוֹלֶה לִהְיוֹת עֲטָרָה בְרֹאשׁ הַמֶּלֶךְ.</p>\n<p>בְּיוֹם זֶה לֹא צָרִיךְ בֶּן אָדָם לְפָרֵשׁ חֲטָאָיו בִּפְנֵי אַחֵר, מִשּׁוּם שֶׁכַּמָה הֵם שֶׁלּוֹקְחִים הַדִּבּוּר הַהוּא וּמַעֲלִים אוֹתוֹ לְמַעְלָה, וְיֵשׁ עֵדִים בַּדִּבּוּר הַהוּא. וּמָה (מיכהז) מִשֹּׁכֶבֶת חֵיקֶךְ שְׁמֹר פִּתְחֵי פִיךְ - כָּל שֶׁכֵּן אֵלּוּ שֶׁהוֹלְכִים וּמִסְתַּכְּלִים לְקַטְרֵג עֲלֵיהֶם וּמְעִידִים עֲלֵיהֶם, וְכָל שֶׁכֵּן שֶׁעַזּוּת הוּא לִפְנֵי הַכֹּל וְחִלּוּל שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה כָּתוּב, (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ. (מכאן והלאה סוד באופן אחר)</p>\n<p>פָּתַח וְאָמַר, (שמות יב) הַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים וְגוֹ'. וְכִי כָל הַזְּמַנִּים וְהֶחֳדָשִׁים אֵינָם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? (אלא חדשיכם לא כתוב) אֶלָּא הַחֹדֶשׁ הַזֶּה לָכֶם, שֶׁלִּי הוּא, אֲבָל אֲנִי מָסַרְתִּי אוֹתוֹ לָכֶם. שֶׁלָּכֶם הוּא בְנִגְלֶה, אֲבָל שְׁבִיעִי שֶׁלִּי הוּא, וְעַל זֶה הוּא בַּכֶּסֶה וְלֹא בְגִלּוּי. חֹדֶשׁ שֶׁלָּכֶם הוּא מְסֻדָּר כְּסֵדֶר אוֹתִיּוֹת אָבִיב, שֶׁהוּא א' ב' ג'. י\"ב הוּא סוֹד אוֹת ג' (והוא א' ב' ג' כסדר האותיות). אֲבָל הַחֹדֶשׁ הַשְּׁבִיעִי, שֶׁלִּי הוּא מִסּוֹף הָאוֹתִיּוֹת (תשרי). מָה הַטַּעַם? אַתֶּם מִמַּטָּה לְמַעְלָה, וַאֲנִי מִמַּעְלָה לְמַטָּה.</p>\n<p>זֶה שֶׁלִּי. בְּרֹאשׁ הַחֹדֶשׁ אֲנִי הוּא בְכִסּוּי, וּבַעֲשָׂרָה לַחֹדֶשׁ אֲנִי הוּא, מִשּׁוּם שֶׁאֲנִי בְּחָמֵשׁ רִאשׁוֹנוֹת, וּבְחָמֵשׁ אַחֲרוֹנוֹת, וּבְחָמֵשׁ שְׁלִישִׁיּוֹת. בִּתְחִלַּת הַחֹדֶשׁ אֲנִי הוּא מִשּׁוּם חֲמִשָּׁה יָמִים. בַּעֲשָׂרָה לַחֹדֶשׁ אֲנִי הוּא מִשּׁוּם חֲמִשָּׁה יָמִים אֲחֵרִים. בַּחֲמִשָּׁה עָשָׂר לַחֹדֶשׁ אֲנִי הוּא מִשּׁוּם חָמֵשׁ שְׁלִישִׁיִּים.</p>\n<p>מָה הַטַּעַם כָּל זֶה? מִשּׁוּם שֶׁכָּל חֹדֶשׁ זֶה הוּא מֵעוֹלָם הָעֶלְיוֹן, וְעוֹלָם הָעֶלְיוֹן בְּסוֹד חָמֵשׁ הוּא, בְּכָל זְמַן וּזְמַן, וּמִשּׁוּם כָּךְ חֹדֶשׁ זֶה הוּא בְכִסּוּי וְלֹא בְגִלּוּי, מִשּׁוּם שֶׁעוֹלָם הָעֶלְיוֹן בְּכִסּוּי הוּא, וְכָל דְּבָרָיו בְּהֶסְתֵּר. וְחֹדֶשׁ זֶה הוּא שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ. כֵּיוָן שֶׁמַּגִּיעַ יוֹם הַט\"ו לַחֹדֶשׁ, אָז מִתְגַּלֶּה. הַכֹּל הוּא מַגִּיעַ בְּהִתְחַדְּשׁוּת הַלְּבָנָה, וְנִשְׁלֶמֶת הַלְּבָנָה וּמְאִירָה מֵאִמָּא הָעֶלְיוֹנָה, וְעוֹמֶדֶת לְהָאִיר לַתַּחְתּוֹנִים מִתּוֹךְ הָאוֹר הָעֶלְיוֹן, וְעַל זֶה נִקְרָא רִאשׁוֹן, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כג) וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן. עַד עַכְשָׁו עוֹמְדִים כָּל הַיָּמִים בְּסוֹד עֶלְיוֹן. מִכָּאן יוֹרְדִים לְסוֹד תַּחְתּוֹן.</p>\n<p>בֹּא וּרְאֵה, מִיּוֹם הָעֶלְיוֹן הָיוּ יָמִים אֵלּוּ הָרִאשׁוֹנִים, סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, מִי דָן דִּין שֶׁל הָעוֹלָם, שֶׁהֲרֵי דִּין לֹא נִמְצָא בְזֶה הָעוֹלָם אֶלָּא מִדִּין הַתַּחְתּוֹן? (סוד) שֶׁזֶּה - (ישעיה נד) אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא. שֶׁאִם תֹּאמַר דִּין הָעוֹלָם דָּן לְמַעְלָה, אִם כֵּן לֹא הָיָה נִקְרָא עוֹלַם הַחֵרוּת, עוֹלָם שֶׁהוּא אוֹר שֶׁל כָּל הָעוֹלָמוֹת, עוֹלָם שֶׁל כָּל הַחַיִּים, עוֹלָם שֶׁל כָּל הַחֵרוּת. וְאִם תֹּאמַר מִדִּין שֶׁל יִצְחָק - אִם הוּא מְעוֹרֵר דִּין לְגַבֵּי הָעוֹלָם הַזֶּה, לֹא יְכוֹלִים כָּל הָעוֹלָם לִסְבֹּל, שֶׁהָאֵשׁ הָעֶלְיוֹן הַתַּקִּיף הַהוּא, אֵין מִי שֶׁסּוֹבֵל אוֹתוֹ, אֶלָּא אֵשׁ שֶׁלְּמַטָּה, שֶׁהוּא אֵשׁ שֶׁסּוֹבֵל אֵשׁ.</p>\n<p>אֶלָּא, כְּמוֹ שֶׁהָעוֹלָם הַזֶּה עוֹלָם הַתַּחְתּוֹן שֶׁל כָּל הָעוֹלָמוֹת, כָּךְ גַּם כָּל דִּינָיו מֵעוֹלָם הַתַּחְתּוֹן, שֶׁל אֱלֹקִים שׁוֹפֵט. וְזֶה נִקְרָא דִין עֶלְיוֹן עַל הָעוֹלָם הַזֶּה, וּמִשּׁוּם שֶׁהוּא דַרְגָּה שְׁבִיעִית, לֹא גוֹזְרִים גְּזֵרָה עַל בֶּן אָדָם אֶלָּא מֵעֶשְׂרִים שָׁנָה וָמַעְלָה.</p>\n<p>הִסְתַּכֵּל הַזָּקֵן הַזֶּה בְּרַבִּי שִׁמְעוֹן, וְרָאָה אוֹתוֹ שֶׁזּוֹלְגוֹת עֵינָיו דְּמָעוֹת. אָמַר רַבִּי שִׁמְעוֹן, אִם הִיא שְׁבִיעִית, מַדּוּעַ מֵעֶשְׂרִים שָׁנָה וָמַעְלָה? אָמַר לוֹ, אַשְׁרֵי מִי שֶׁמְּדַבֵּר עַל אָזְנַיִם שׁוֹמְעוֹת.</p>\n<p>בֹּא וּרְאֵה, בֵּית דִּין שֶׁלְּמַטָּה בָּאָרֶץ לֹא גוֹזְרִים דִּין עַל בֶּן אָדָם עַד שְׁלֹשׁ עֶשְׂרֵה שָׁנָה. מָה הַטַּעַם? מִשּׁוּם שֶׁעוֹזְבִים שֶׁבַע שָׁנִים לַשְּׁבִיעִית, אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא. וְאֵין רְשׁוּת לָאָדָם בְּאֵלּוּ הַשֶּׁבַע. וְאֵלּוּ הַשֶּׁבַע לֹא נִמְצָאוֹת אֶלָּא עַל שְׁלֹשׁ עֶשְׂרֵה שֶׁלְּמַטָּה (בארץ), שֶׁאֵלּוּ כִסֵּא לְגַבָּיו, וּמִשּׁוּם זֶה כָּל גְּזֵרוֹת וְכָל הַדִּינִים שֶׁלְּמַטָּה, מֵאֵלּוּ הַשֶּׁבַע שָׁנִים שֶׁלְּמַטָּה, כְּלָלוּת שֶׁל עֶשְׂרִים שָׁנָה הֵם.</p>\n<p>וְדִין הָעוֹלָם בְּרֹאשׁ הַשָּׁנָה הוּא עַל יְדֵי זוֹ הַמַּדְרֵגָה, שֶׁהוּא מַמָּשׁ עוֹמֵד בְּדִין עַל בָּנָיו בָּעוֹלָם הַזֶּה כְּדֵי לְהִטַּהֵר לְגַבֵּי הָעוֹלָם הָעֶלְיוֹן, מִשּׁוּם שֶׁאֵין לוֹ סִיּוּעַ לַעֲלוֹת וּלְהִטַּהֵר אֶלָּא מִתּוֹךְ הַתַּחְתּוֹנִים.</p>"],[9522011803,"<p>וְכַאֲשֶׁר יִשְׂרָאֵל הֵם בַּחֲמִשָּׁה עָשָׂר יוֹם, אָז נוֹטֵל לְבָנָיו לִפְרֹשׂ כְּנָפָיו עֲלֵיהֶם וְלִשְׂמֹחַ עִמָּהֶם. וְעַל זֶה כָּתוּב וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן. פְּרִי זֶה הוּא אִילָן שֶׁנִּקְרָא עֵץ פְּרִי, וְנִמְצָא בוֹ פְּרִי. עֵץ הָדָר - כְּמוֹ שֶׁנֶּאֱמַר (תהלים צו) הוֹד וְהָדָר לְפָנָיו. מָה הַטַּעַם נִקְרָא הָדָר, וּמִי הוּא הָדָר? אֶלָּא זֶה צַדִּיק.</p>\n<p>מַדּוּעַ נִקְרָא הָדָר, וַהֲרֵי מָקוֹם מֻסְתָּר הוּא שֶׁאֵין לוֹ גִלּוּי, וְצָרִיךְ לְהִתְכַּסּוֹת תָּמִיד, וְאֵין הָדָר אֶלָּא מִי שֶׁמִּתְגַּלֶּה וּמִתְרָאֶה? אֶלָּא, אַף עַל גַּב שֶׁהוּא דַרְגָּה מֻסְתֶּרֶת, הִדּוּר הוּא שֶׁל כָּל הַגּוּף, וְלֹא נִמְצָא הִדּוּר לַגּוּף אֶלָּא בוֹ. מָה הַטַּעַם? מִי שֶׁאֵין עִמּוֹ מַדְרֵגָה זוֹ, אֵין בּוֹ הִדּוּר לָבֹא בִּבְנֵי אָדָם. קוֹלוֹ אֵין עִמּוֹ בְדִבּוּרוֹ (כזכר), וְהִדּוּר (ודבור) שֶׁל קוֹל נִפְסָק מִמֶּנּוּ. זְקָנוֹ וַהֲדַר זְקָנוֹ לֹא עִמּוֹ, וְאַף עַל גַּב שֶׁמִּתְכַּסֵּית הַדַּרְגָּה הַהִיא, כָּל הִדּוּר הַגּוּף תָּלוּי בּוֹ, וּמִתְכַּסֶּה וּמִתְגַּלֶּה. וּמִפְּנֵי כֵן עֵץ הָדָר הוּא, עֵץ שֶׁכָּל הִדּוּר הַגּוּף תָּלוּי בּוֹ, וְזֶהוּ הוּא עֵץ עֹשֶׂה פְּרִי.</p>\n<p>כַּפֹּת תְּמָרִים - כָּאן נִכְלֶלֶת אִשָּׁה בְּבַעְלָהּ בְּלִי פֵרוּד, כַּפֹּת תְּמָרִים כְּאֶחָד. וַעֲנַף עֵץ עָבֹת - שְׁלֹשָׁה. וְעָלִים שֶׁלּוֹ - זֶה בְּצַד זֶה, וְזֶה בְּצַד זֶה, וְאֶחָד שֶׁשּׁוֹלֵט עֲלֵיהֶם. וְעַרְבֵי נָחַל - שְׁנַיִם, שֶׁאֵין לָהֶם רֵיחַ וְטַעַם, כְּשׁוֹקַיִם בְּבֶן אָדָם. (ומפני כן) לוּלָב נוֹטֵל כֻּלָּם, כְּחוּט הַשִּׁדְרָה שֶׁמַּעֲמִיד אֶת הַגּוּף. וּמַה שֶּׁיּוֹצֵא הַחוּצָה טֶפַח - כָּךְ הוּא, כְּדֵי לְהַשְׁלִים וּלְהוֹצִיא הַכֹּל וּלְשַׁמֵּשׁ כְּמוֹ שֶׁצָּרִיךְ.</p>\n<p>(ומפני כן) בְּמִינִים אֵלּוּ צָרִיךְ בֶּן אָדָם לְהֵרָאוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. עָלִים שֶׁל אֵלּוּ הַתְּמָרִים, הֵם כָּל שְׁאָר חֵילוֹת שֶׁמִּתְאַחֲזִים בְּאֵלּוּ הַכִּנּוּיִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בָהֶם, מִפְּנֵי שֶׁצְּרִיכִים (להתאחז) לְמַטָּה כְּדֻגְמַת לְמַעְלָה. שֶׁאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁאֵין לוֹ דֻגְמָא לְמַעְלָה. כְּדֻגְמָא שֶׁל לְמַעְלָה כָּךְ יֵשׁ לְמַטָּה. וּצְרִיכִים יִשְׂרָאֵל לְהִתְאַחֵז בְּסוֹד זֶה שֶׁל הָאֱמוּנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011804,"<p>כָּתוּב (ויקרא כג) בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. זֶהוּ סוֹד הָאֱמוּנָה, וְסוֹד זֶה נֶאֱמַר עַל הָעוֹלָם הָעֶלְיוֹן. וְכָךְ לָמַדְנוּ, כַּאֲשֶׁר נִבְרָא הָעוֹלָם נֶאֱמַר פָּסוּק זֶה.</p>\n<p>כַּאֲשֶׁר הִתְחִילָה חָכְמָה לָצֵאת מִמָּקוֹם שֶׁלֹּא יָדוּעַ וְלֹא נִרְאֶה, אָז יוֹצֵאת מִדָּה אַחַת וּמַכָּה, וְהַחָכְמָה הַהִיא הָעֶלְיוֹנָה מְאִירָה וּמִתְפַּשֶּׁטֶת לְכָל הַצְּדָדִים בְּסוֹד הַמִּשְׁכָּן הָעֶלְיוֹן. וְהַמִּשְׁכָּן הָעֶלְיוֹן הַהוּא מוֹצִיא שִׁשָּׁה צְדָדִים, וְאָז הַנִּיצוֹץ הַהוּא שֶׁל הַמִּדָּה מֵאִיר לְכֻלָּם, וְאָמַר בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים.</p>\n<p>מִי הוּא סֻכֹּת חָסֵר ו'? זֶה מִשְׁכָּן תַּחְתּוֹן, שֶׁהוּא כַּעֲשָׁשִׁית, לְהַרְאוֹת אֶת כָּל הָאוֹרוֹת. וְאָז אָמַר בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים. מִי הֵם שִׁבְעַת יָמִים? מֵעוֹלָם הָעֶלְיוֹן לַתַּחְתּוֹן, שֶׁכֻּלָּם עוֹמְדִים וּמְזֻמָּנִים לְהָאִיר לְזוֹ הַסֻּכֹּת. וּמִי הִיא? זוֹ (עמוס ט) סֻכַּת דָּוִיד הַנֹּפֶלֶת. סֻכַּת שָׁלוֹם. וְצָרִיךְ הָעָם הַקָּדוֹשׁ לָשֶׁבֶת תַּחַת הַצֵּל שֶׁלָּהּ, בְּסוֹד הָאֱמוּנָה. וּמִי שֶׁיּוֹשֵׁב בְּצֵל זֶה, יוֹשֵׁב בְּאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים.</p>\n<p>וְעַל זֶה כֻּלָּם בַּסֻּכֹּת בַּסֻּכֹּת, וְאֶחָד בַּסֻּכּוֹת שָׁלֵם. אֶחָד שָׁלֵם, לְהַרְאוֹת שֶׁמִּי שֶׁיּוֹשֵׁב בְּצֵל זֶה, יוֹשֵׁב בְּאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים לְמַעְלָה, שֶׁעוֹמְדִים עַל זֶה הַתַּחְתּוֹן לְהָאִיר לוֹ, לְכַסּוֹת עָלָיו וּלְהָגֵן עָלָיו בְּשָׁעָה שֶׁצָּרִיךְ.</p>\n<p>וְעוֹד, כֻּלָּם נִקְרָאִים סֻכּוֹת בִּשְׁלֵמוּת, וְכָתוּב סֻכֹּת חָסֵר, זֶה הָעוֹלָם הַתַּחְתּוֹן שֶׁצָּרִיךְ בְּאֵלּוּ הַשִּׁבְעָה יָמִים קְדוֹשִׁים לָזוּן לִשְׁאָר הַמְמֻנִּים הַגְּדוֹלִים שֶׁל הָעַמִּים, בְּשָׁעָה שֶׁהִיא לוֹקַחַת שִׂמְחָה בְּבַעְלָהּ, וְלֹא יְקַלְקְלוּ שִׂמְחָתָהּ, כְּדֵי שֶׁיִּתְבַּלְבְּלוּ (שיתעדנו) בַּמָּזוֹן הַהוּא, הַקָּרְבָּנוֹת שֶׁלָּהֶם רַבִּים יוֹתֵר מִשְּׁאָר יָמִים, כְּדֵי שֶׁיִּתְעַסְּקוּ בָהֶם וְלֹא יִתְעָרְבוּ לְבַסּוֹף בַּשִּׂמְחָה שֶׁל יִשְׂרָאֵל. וּמִי הִיא שִׂמְחָה שֶׁל יִשְׂרָאֵל? זֶה יוֹם שְׁמִינִי עֲצֶרֶת.</p>\n<p>וּבֹא רְאֵה, בְּעוֹד שֶׁאֵלּוּ שְׁאָר הַמְמֻנִּים שְׂמֵחִים וְאוֹכְלִים בַּמָּזוֹן הַהוּא שֶׁמְּתַקְּנִים לָהֶם יִשְׂרָאֵל, הֵם מְתַקְּנִים כִּסֵּא לַקָּבָּ\"ה מִלְּמַטָּה, וּלְהַעֲלוֹת אוֹתוֹ לְמַעְלָה בְּאֵלּוּ הַמִּינִים, וּבְשִׂמְחָה, וּבְהַלֵּל, וּלְהַקִּיף הַמִּזְבֵּחַ. אָז הִיא עוֹלָה וְלוֹקַחַת בְּרָכוֹת וְשִׂמְחָה בְּבַעְלָהּ.</p>\n<p>וּשְׁאָר חַיּוֹת גְּדוֹלוֹת מְמֻנּוֹת הָעַמִּים, אוֹכְלוֹת וְשׁוֹחֲקוֹת וְרוֹמְסוֹת וְנִזּוֹנוֹת. וְהִיא נוֹטֶלֶת נְפָשׁוֹת בְּעֹנֶג לְמַעְלָה, כְּמוֹ שֶׁאָמַרְנוּ. כֵּיוָן שֶׁיּוֹרֶדֶת, וְהִיא לוֹקַחַת כָּל הַבְּרָכוֹת וְכָל הַקְּדֻשּׁוֹת וְכָל הָעִנּוּגִים, וְיִשְׂרָאֵל כָּל אֵלּוּ הַשִּׁבְעָה יָמִים הָיוּ מוֹשְׁכִים אוֹתָהּ בְּאֵלּוּ הַמַּעֲשִׂים שֶׁהֵם עוֹשִׂים וּמַקְרִיבִים לָהּ, אָז יוֹרֶדֶת לְהִתְקָרֵב בְּבָנֶיהָ וּלְשַׂמֵּחַ אוֹתָם יוֹם אֶחָד. וְהַיּוֹם הַהוּא הוּא יוֹם שְׁמִינִי, מִשּׁוּם שֶׁכָּל שִׁבְעָה יָמִים אֲחֵרִים אִתָּהּ. וְעַל זֶה הוּא שְׁמִינִי, וּשְׁמוֹנָה יָמִים כְּאֶחָד. וּמִפְּנֵי זֶה נִקְרָא עֲצֶרֶת - כִּנּוּס. מִתְכַּנְּסִים כֻּלָּם בְּיוֹם זֶה. וְנִקְרָא שְׁמִינִי, וְאֵין שְׁמִינִי אֶלָּא מִתּוֹךְ שִׁבְעָה.</p>"],[9522011805,"<p>כָּתוּב (איוב א) יְהִי שֵׁם ה' מְבֹרָךְ. מַהוּ מְבֹרָךְ? (אלאהכלידוע) אֲבָל סוֹד אֶחָד יָדַע אֶחָד מֵחֲבֵרֵנוּ, בַּמִּדְבָּר הֶרְאוּ לוֹ בַחֲלוֹם, וּשְׁמוֹ רַבִּי יִצְחָק מִכַּפְתּוֹר. מַהוּ מְבֹרָךְ? רֵאשִׁיתוֹ קָשָׁה וְסוֹפוֹ רַךְ. מ\"ב קָשֶׁה, וְדִין הוּא וַדַּאי. (ואחר כך) כְּעֵין זֶה יוֹם שֶׁל רֹאשׁ הַשָּׁנָה מ\"ב, שֶׁהֲרֵי בְּאַרְבָּעִים וּשְׁתַּיִם (ובסוד מ\"ב) אוֹתִיּוֹת נִבְרָא הָעוֹלָם, וְעַל זֶה נִבְרָא בְדִין. לְבַסּוֹף רַךְ. וְעַל זֶה לָמַדְנוּ, כָּל הַהַתְחָלוֹת קָשׁוֹת, וְסוֹף הַכֹּל רַךְ. (זה מ\"ב ובסוד של ארבעים ושתים אותיות נברא העולם, ועל זה נברא בדין לבסוףכדגמתזה) בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה מ\"ב קָשֶׁה, בְּדִין. בַּיּוֹם שֶׁל עֲצֶרֶת רַךְ, בְּשִׂמְחָה.</p>\n<p>בֹּא וּרְאֵה מַה בֵּין דִּין עֶלְיוֹן לְדִין זֶה. דִּין עֶלְיוֹן תְּחִלָּתוֹ וְסוֹפוֹ קָשֶׁה, וְאֵין מִי שֶׁיַּעֲמֹד בּוֹ, וְכָל מַה שֶּׁהוֹלֵךְ מִתְחַזֵּק, וּלְבַסּוֹף שֶׁשּׁוֹרֶה, לֹא זָז מִשָּׁם עַד שֶׁמְּכַלֶּה וּמַכְרִית הַכֹּל שֶׁלֹּא נִשְׁאָר כְּלוּם. אֲבָל דִּין אַחֵר שֶׁלְּמַטָּה, רֵאשִׁית קָשָׁה, וְכָל מַה שֶּׁהוֹלֵךְ - נֶחֱלָשׁ, עַד שֶׁמֵּאִיר פָּנִים, כְּדֻגְמַת (זה דין של הגקבה) הַנְּקֵבָה שֶׁנֶּחֱלָשׁ כֹּחָהּ.</p>\n<p>מִמָּתַי הִתְעוֹרֵר דִּין שֶׁלְּמַעְלָה לִשְׁרוֹת עַל הָעוֹלָם? בְּיוֹם הַמַּבּוּל. וְעַל זֶה לֹא נִשְׁאַר כְּלוּם בָּעוֹלָם חוּץ מֵהַתֵּבָה הַהִיא שֶׁל נֹחַ, שֶׁהִיא כַּדֻּגְמָא הָעֶלְיוֹן שֶׁסָּבְלָה לְכֹּחַ הַדִּין הַהוּא. וְאִלּוּלֵי שֶׁהִזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִמְצָא בְרַחֲמִים עַל הָעוֹלָם, כָּל הָעוֹלָם הָיָה נֶאֱבָד, שֶׁכָּתוּב (תהלים כט) ה' לַמַּבּוּל יָשָׁב. וְעַל זֶה לֹא שׁוֹרֶה דִין שֶׁלְּמַעְלָה עַל הָעוֹלָם, שֶׁלֹּא יָכוֹל הָעוֹלָם לִסְבֹּל אוֹתוֹ אֲפִלּוּ רֶגַע אֶחָד.</p>"],[9522011806,"<p>בְּתוֹךָ כָּךְ הָיָה רַבִּי שִׁמְעוֹן בּוֹכֶה וְשָׂמֵחַ. נָשְׂאוּ עֵינַיִם וְרָאוּ חֲמִשָּׁה מֵאֵלֶּה הָאֲנָשִׁים הַפְּרוּשִׁים שֶׁהָיוּ הוֹלְכִים אַחֲרָיו לְבַקֵּשׁ אוֹתוֹ. עָמְדוּ. אָמַר רַבִּי שִׁמְעוֹן, מִכָּאן וָהָלְאָה מַה שִּׁמְךְ? אָמַר, נְהוֹרַאי סָבָא, מִשּׁוּם שֶׁיֵּשׁ נְהוֹרַאי אַחֵר אֶצְלֵנוּ. הָלְכוּ רַבִּי שִׁמְעוֹן וְהַחֲבֵרִים הָאֵלֶּה עִמּוֹ שְׁלֹשָׁה מִילִין. אָמַר רַבִּי שִׁמְעוֹן לְאֵלּוּ הָאֲחֵרִים, מַה דֶּרֶךְ זוֹ אֶצְלְכֶם? אָמְרוּ, לְבַקֵּשׁ אֶת הַזָּקֵן הַזֶּה, שֶׁמִּמֵּימָיו אָנוּ שׁוֹתִים בַּמִּדְבָּר. בָּא רַבִּי שִׁמְעוֹן וּנְשָׁקוֹ. אָמַר לוֹ, שִׁמְךְ נְהוֹרַאי, וְאוֹר אַתָּה, וְאוֹר עִמְּךְ נִמְצָא.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (דניאל ב) הוּא מְגַלֶּה עֲמֻקּוֹת וְנִסְתָּרוֹת, יוֹדֵעַ מַה בַּחֹשֶׁךְ, וְהָאוֹר שׁוֹרֶה עִמּוֹ. הוּא גָּלֵא עַמִּיקָתָא וּמְסַתְּרָתָא - הַקָּדוֹשׁ בָּרוּךְ הוּא מְגַלֶּה עֲמֻקּוֹת וְנִסְתָּרוֹת, שֶׁכָּל הַדְּבָרִים הָעֲמֻקִּים וְהַסְּתוּמִים הָעֶלְיוֹנִים הוּא מְגַלֶּה לָהֶם. וּמָה הַטַּעַם מְגַלֶּה לָהֶם? מִשּׁוּם שֶׁיָּדַע מָה בַחֲשׁוֹכָא. שֶׁאִם לֹא הָיָה הַחֹשֶׁךְ, לֹא נוֹדַע הָאוֹר. וְהוּא יָדַע מַה בַּחֹשֶׁךְ, וּמִפְּנֵי כָּךְ מְגַלֶּה עֲמֻקּוֹת וְנִסְתָּרוֹת. שֶׁאִם לֹא הַחֹשֶׁךְ, לֹא יִתְגַּלּוּ הַדְּבָרִים הָעֲמֻקִּים וְהַנִּסְתָּרִים. וּנְהוֹרָא עִמֵּהּ שְׁרֵא - מַהוּ אוֹר זֶה? אוֹר שֶׁמִּתְגַּלֶּה מִתּוֹךְ הַחֹשֶׁךְ.</p>\n<p>וְאָנוּ, מִתּוֹךְ הַחֹשֶׁךְ שֶׁהָיָה בַּמִּדְבָּר, מִתְגַּלֶּה לָנוּ אוֹר זֶה. הַקָּדוֹשׁ בָּרוּךְ הוּא יַשְׁרֶה עִמְּךְ אוֹר בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. הָלְכוּ רַבִּי שִׁמְעוֹן וְהַחֲבֵרִים שְׁלֹשָׁה מִילִין אֵלּוּ אַחֲרָיו. אָמַר לוֹ, מַדּוּעַ לֹא הוֹלְכִים אֵלּוּ עִמְּךְ כְּבָרִאשׁוֹנָה? אָמַר לוֹ, לֹא רָצִיתִי לְהַטְרִיחַ לְבֶן אָדָם עִמִּי. עַכְשָׁו שֶׁבָּאוּ, נֵלֵךְ כְּאֶחָד. הָלְכוּ, וְרַבִּי שִׁמְעוֹן הָלַךְ לְדַרְכּוֹ. אָמַר רַבִּי אַבָּא, הֲרֵי אָנוּ יוֹדְעִים אֶת שְׁמוֹ, וְהוּא לֹא יוֹדֵעַ אֶת שְׁמוֹ שֶׁל מֹר? אָמַר לוֹ, מִמֶּנּוּ יָדַעְתִּי שֶׁלֹּא לְהִתְרָאוֹת. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011807,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר. כִּי תִשָּׂא אֶת רֹאשׁ בְּנֵי יִשְׂרָאֵל לִפְקֻדֵיהֶם וְגוֹ'. רַבִּי אַבָּא וְרַבִּי אָחָא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מִטְּבֶרְיָה לְצִפּוֹרִי. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אֶת רַבִּי אֶלְעָזָר שֶׁהָיָה בָּא, וְרַבִּי חִיָּיא עִמּוֹ. אָמַר רַבִּי אַבָּא, וַדַּאי שֶׁנִּשְׁתַּתֵּף עִם הַשְּׁכִינָה. חִכּוּ לָהֶם עַד שֶׁהִגִּיעוּ אֲלֵיהֶם. כֵּיוָן שֶׁהִגִּיעוּ אֲלֵיהֶם, אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּתוּב עֵינֵי ה' אֶל צַדִּיקִים וְאָזְנָיו אֶל שַׁוְעָתָם. פָּסוּק זֶה הִנּוֹ קָשֶׁה וְכוּ'.</p>\n<p>בֹּא וּרְאֵה, הֲרֵי פֵּרְשׁוּהָ, אֵין הַבְּרָכָה שֶׁלְּמַעְלָה שׁוֹרָה עַל דָּבָר שֶׁנִּמְנֶה. וְאִם תֹּאמַר, אֵיךְ יִשְׂרָאֵל נִמְנוּ? אֶלָּא כֹּפֶר נָטַל מֵהֶם, וַהֲרֵי פֵּרְשׁוּהָ, וְהַחֶשְׁבּוֹן לֹא הָיָה עַד שֶׁכָּנְסוּ אֶת כָּל אוֹתוֹ הַכֹּפֶר וְעָלָה לַחֶשְׁבּוֹן. וּבָרִאשׁוֹנָה הָיוּ מְבָרְכִים אֶת יִשְׂרָאֵל, וְאַחַר כָּךְ אֶת הַמִּנְיָן שֶׁל אוֹתוֹ הַכֹּפֶר, וְאַחַר כָּךְ חוֹזְרִים וּמְבָרְכִים אֶת יִשְׂרָאֵל. נִמְצְאוּ יִשְׂרָאֵל מְבֹרָכִים בָּרִאשׁוֹנָה וּבַסּוֹף, וְלֹא עוֹלֶה בָּהֶם הַמָּוֶת.</p>\n<p>לָמָּה הַמָּוֶת עוֹלֶה בְּמִנְיָן? אֶלָּא בִּשְׁבִיל שֶׁהַבְּרָכָה לֹא שׁוֹרָה בְּמִנְיָן. כֵּיוָן שֶׁהִסְתַּלְּקָה בְרָכָה, הַצַּד הָאַחֵר שׁוֹרֶה עָלָיו וְיָכוֹל לְהִנָּזֵק. מִשּׁוּם כָּךְ נוֹטְלִים כֹּפֶר וּפִדְיוֹן לַעֲלוֹת (מעליהם) עָלָיו מִנְיָן, וַהֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר.</p>"],[9522011808,"<p>מִצְוָה לָתֵת מַחֲצִית הַשֶּׁקֶל בְּשֶׁקֶל הַקֹּדֶשׁ. רוֹעֶה הַנֶּאֱמָן מַה זֶּה מַחֲצִית הַשֶּׁקֶל? זֶהוּ כְּמוֹ חֲצִי הַהִין, וְזוֹ ו', מְמֻצָּע בֵּין שְׁתֵּי הֵהִי\"ן. אֶבֶן לִשְׁקֹל בָּהּ, זוֹ י'. עֶשְׂרִים גֵּרָה הַשֶּׁקֶל - זוֹ יוֹ\"ד. הֶעָשִׁיר לֹא יַרְבֶּה - זֶה הָעַמּוּד הָאֶמְצָעִי, לֹא יַרְבֶּה עַל י'. וְכָךְ נֶאֱמַר בְּסֵפֶר יְצִירָה, עֶשֶׂר סְפִירוֹת בְּלִימָה, עֶשֶׂר וְלֹא אַחַד עָשָׂר. וְהַדַּל לֹא יַמְעִיט - זֶה צַדִּיק, לֹא יַמְעִיט מֵעֶשֶׂר, כְּמוֹ שֶׁנֶּאֱמַר עֶשֶׂר וְלֹא תֵשַׁע. מִמַּחֲצִית הַשֶּׁקֶל - שֶׁהוּא י'. (מחצית השקל עשר הוא). י!, (ג\"א מהצית השקל עשד הוא),</p>\n<p>אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, (מלאך) אַתָּה בַּשָּׁמַיִם, אָהוּב אַתָּה מֵרִבּוֹנְךְ, אֵין תְּמִיהָה בְּכָל אוֹתָם דְּבָרִים נִכְבָּדִים שֶׁיָּצְאוּ מִפִּיךְ, שֶׁהֲרֵי מִי שֶׁהוּא מֶלֶךְ אוֹ בֶּן הַמֶּלֶךְ, אֵין תְּמִיהָה שֶׁיַּעֲלוּ מַרְגָּלִיּוֹת בְּשֻׁלְחָנוֹ, מְלֵאוֹת סְגֻלּוֹת, מְלֵאוֹת אוֹרוֹת. לְאָדָם אַחֵר זוֹהִי תְּמִיהָה. אָמַר לוֹ, בָּרוּךְ אַתָּה הָרוֹעֶה הַנֶּאֱמָן, מִשָּׁם וְאֵילָךְ אֱמֹר אַתָּה, שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים יָרְדוּ לִשְׁמֹעַ מִמְּךְ. אָמַר לוֹ, הַשְׁלֵם דִּבּוּרְךְ. אָמַר לוֹ, אֵין כָּעֵת לוֹמַר יוֹתֵר, אֱמֹר אַתָּה עַד פַּעַם אַחֶרֶת.</p>\n<p>פָּתַח הָרוֹעֶה הַנֶּאֱמָן, מִצְוָה אַחַר זוֹ לְקַדֵּשׁ אֶת הַחֹדֶשׁ, מִשּׁוּם שֶׁהַכַּלָּה הַקְּדוֹשָׁה הִיא כַּלָּה שֶׁמִּתְקַדֶּשֶׁת עַל פִּי בֵּית דִּין, שֶׁהוּא גְבוּרָה, מִשּׁוּם שֶׁשָּׁם לְוִיִּם, שֶׁנֶּאֱמַר בָּהֶם וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. וְאַחַר שֶׁנִּרְאֵית הַלְּבָנָה שֶׁיֵּאוֹתוּ לְאוֹרָהּ, מְבָרֵךְ עָלֶיהָ: בָּרוּךְ אַתָּה יְיָ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר בְּמַאֲמָרוֹ בָּרָא שְׁחָקִים, וּבְרוּחַ פִּיו כָּל צְבָאָם. וּבְמִי מִתְקַדֶּשֶׁת וּמִתְבָּרֶכֶת? בְּתִפְאֶרֶת, מִשּׁוּם שֶׁהִיא עֲטֶרֶת תִּפְאֶרֶת לַעֲמוּסֵי בָטֶן. (עד כאן רעיא מהימנא)</p>"],[9522011809,"<p>רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. עַד שֶׁהָיוּ הוֹלְכִים יָרַד הַלַּיְלָה. יָשְׁבוּ. עַד שֶׁהָיוּ יוֹשְׁבִים הִתְחִיל הַבֹּקֶר לְהָאִיר. (אמרו, נקום ונלך) קָמוּ וְהָלְכוּ. אָמַר רַבִּי חִיָּיא, רְאֵה אֶת פְּנֵי הַמִּזְרָח שֶׁמְּאִירִים. עַכְשָׁו כָּל אוֹתָם בְּנֵי הַמִּזְרָח שֶׁל הָרֵי הָאוֹר מִשְׁתַּחֲוִים לָאוֹר הַזֶּה שֶׁמֵּאִיר בִּמְקוֹם הַשֶּׁמֶשׁ טֶרֶם שֶׁיָּצָא וְעוֹבְדִים אוֹתוֹ, שֶׁהֲרֵי כֵּיוָן שֶׁיּוֹצֵא הַשֶּׁמֶשׁ, כַּמָּה הֵם שֶׁעוֹבְדִים לַשֶּׁמֶשׁ. וְאֵלֶּה הֵם שֶׁעוֹבְדִים לָאוֹר הַזֶּה, וְקוֹרְאִים לָאוֹר הַזֶּה: אֱלֹהֵי הַמַּרְגָּלִית הַמְּאִירָה. וּשְׁבוּעָתָם הִיא בֵּאלֹ\"הַּ הַמַּרְגָּלִית הַמְּאִירָה.</p>\n<p>וְאִם תֹּאמַר שֶׁעֲבוֹדָה זוֹ הִיא לְחִנָּם - מִיָּמִים רִאשׁוֹנִים הַקַּדְמוֹנִים יָדְעוּ בָהּ חָכְמָה. בִּזְמַן שֶׁהַשֶּׁמֶשׁ מֵאִיר, טֶרֶם שֶׁיֵּצֵא, אוֹתוֹ הַמְמֻנֶּה הַמֻּפְקָד עַל הַשֶּׁמֶשׁ יוֹצֵא, וְהָאוֹתִיּוֹת הַקְּדוֹשׁוֹת שֶׁל הַשֵּׁם הָעֶלְיוֹן רְשׁוּמוֹת עַל רֹאשׁוֹ (של השמש), וּבְכֹחַ אוֹתָן הָאוֹתִיּוֹת פּוֹתֵחַ אֶת כָּל חַלּוֹנוֹת הַשָּׁמַיִם, וּמַכֶּה בָהֶם וְעוֹבֵר. וְאוֹתוֹ מְמֻנֶּה נִכְנָס לְתוֹךְ אוֹתוֹ הַזֹּהַר שֶׁמֵּאִיר סְבִיב הַשֶּׁמֶשׁ, וְשָׁם נִמְצָא, עַד שֶׁיּוֹצֵא הַשֶּׁמֶשׁ וּמִתְפַּשֵּׁט בָּעוֹלָם.</p>\n<p>וְאוֹתוֹ הַמְמֻנֶּה מֻפְקָד עַל הַזָּהָב וְעַל מַרְגָּלִיּוֹת אֲדֻמּוֹת, וְהֵם עוֹבְדִים אֶל אוֹתוֹ הַדְּיוֹקָן שֶׁל שָׁם, וּבִנְקֻדּוֹת וְסִימָנִים שֶׁיָּרְשׁוּ מֵהָרִאשׁוֹנִים מִיָּמִים קַדְמוֹנִים, הוֹלְכִים וְיוֹדְעִים נְקֻדּוֹת הַשֶּׁמֶשׁ לִמְצֹא מְקוֹמוֹת שֶׁל זָהָב וּמַרְגָּלִיּוֹת. אָמַר רַבִּי יוֹסֵי, עַד כַּמָּה יִהְיוּ עֲבוֹדוֹת רַבּוֹת אֵלּוּ בָּעוֹלָם, שֶׁהֲרֵי שֶׁקֶר אֵין לוֹ עַמּוּדִים לִתְמִיכָה?</p>"],[9522011810,"<p>פָּתַח אַחֵר (רבי חייא) וְאָמַר, (משלי יב) שְׂפַת אֱמֶת תִּכּוֹן לָעַד וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר. בֹּא וּרְאֵה, אִלּוּ כָּל בְּנֵי הָעוֹלָם הָיוּ עוֹבְדִים לַשֶּׁקֶר - הָיָה כָּךְ, אֲבָל הָאוֹר הַזֶּה וְהַ הַר שֶׁמֵּאִיר וַדַּאי הוּא אֱמֶת. כּוֹכְבֵי רוּם הָרָקִיעַ הֵם אֱמֶת. אִם בְּטִפְּשׁוּתָם וְחֶסְרוֹן דַּעְתָּם הֵם אוֹמְרִים וְקוֹרְאִים לָהֶם אֱלוֹהַּ, לֹא צָרִיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לְכַלּוֹת אֶת מַעֲשֵׂי יָדָיו מֵהָעוֹלָם. אֲבָל לֶעָתִיד לָבֹא לֹא יִכְלוּ הַכּוֹכָבִים וְהָאוֹרוֹת שֶׁל הָעוֹלָם. אֲבָל מִי יִתְכַּלֶּה? אוֹתָם שֶׁעוֹבְדִים לָהֶם.</p>\n<p>וְהַפָּסוּק הַזֶּה הוּא כָּךְ. שְׂפַת אֱמֶת תִּכּוֹן לָעַד - אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם שְׂפַת אֱמֶת, (דברים ו) ה' אֱלֹהֵינוּ ה' אֶחָד. וְהַכּל הוּא אֱמֶת וְסוֹד הָאֱמֶת. וּמְסַיְּמִים, ה' אֱלֹהֵיכֶם אֱמֶת. וְזוֹהִי שְׂפַת אֱמֶת תִּכּוֹן לָעַד.</p>\n<p>וְעַד אַרְגִּיעָה, וְעַד רֶגַע הָיָה צָרִיךְ לִהְיוֹת! מַה זֶה אַרְגִּיעָה? אֶלָּא עַד כַּמָּה יִהְיֶה קִיּוּמָם בָּעוֹלָם? עַד לֶעָתִיד לָבא, וְתִהְיֶה לִי מְנוּחָה מֵהָעֲבוֹדָה הַקָּשָׁה שֶׁעָלָיו. וּבִזְמַן שֶׁאַרְגִּיעָה, תִּתְכַּלֶּה לְשׁוֹן שֶׁקֶר, אוֹתָם שֶׁקּוֹרְאִים אֱלוֹהַּ לְמִי שֶׁאֵינוֹ אֱלוֹהַּ. אֲבָל יִשְׂרָאֵל שֶׁהֵם שְׂפַת אֱמֶת, כָּתוּב בָּהֶם (ישעיה מג) עַם זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ.</p>\n<p>נִזְכַּרְתִּי פַּעַם אַחַת שֶׁהָיִיתִי הוֹלֵךְ עִם רַבִּי אֶלְעָזָר, פָּגַשׁ בּוֹ הֶגְמוֹן. אָמַר לְרַבִּי אֶלְעָזָר, אַתָּה מַכִּיר אֶת תּוֹרַת הַיְּהוּדִים? אָמַר לוֹ, מַכִּיר. אָמַר לוֹ, הַאֵינְכֶם אוֹמְרִים שֶׁאֱמוּנַתְכֶם אֱמֶת וְתוֹרַתְכֶם אֱמֶת, וְאָנוּ שֶׁאֱמוּנָתֵנוּ שֶׁקֶר וְתוֹרָתֵנוּ שֶׁקֶר?! וַהֲרֵי כָּתוּב, שְׂפַת אֱמֶת תִּכּוֹן לָעַד וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר? אָנוּ מִימוֹת הָעוֹלָם עוֹמְדִים בְּמַלְכוּת וְלֹא סָרָה מִמֶּנּוּ לְעוֹלָמִים דּוֹר אַחַר דּוֹר, תִּכּוֹן לָעַד וַדַּאי. וְאַתֶּם מְעַט הָיָה לָכֶם בְּמַלְכוּת, וּמִיָּד סָרָה מִכֶּם, וְהַפָּסוּק הִתְקַיֵּם בָּכֶם שֶׁכָּתוּב וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר.</p>\n<p>אָמַר לוֹ, אֲנִי רוֹאֶה בְּךְ שֶׁאַתָּה חָכָם בַּתּוֹרָה. תִּפַּח רוּחוֹ שֶׁל אוֹתוֹ הָאִישׁ. אִלּוּ אָמַר הַכָּתוּב שְׂפַת אֱמֶת כּוֹנַנְתָּ לָעַד - הָיָה כְּמוֹ שֶׁאַמַרְנוּ. אֲבָל לֹא כָתוּב אֶלָּא תִּכּוֹן, עֲתִידָה שְׂפַת אֱמֶת שֶׁתִּכּוֹן מַה שֶּׁאֵין כָּךְ עַכְשָׁו, שֶׁעַכְשָׂו שְׂפַת שֶׁקֶר עוֹמֶדֶת, וּשְׂפַת אֱמֶת שׁוֹכֶבֶת לֶעָפָר, וּבְאוֹתוֹ זְמַן שֶׁל אֱמֶת תַּעֲמֹד עַל קִיּוּמָהּ וּמִתּוֹךְ אֶרֶץ תִּצְמַח, אָז שְׂפַת אֱמֶת תִּכּוֹן לָעַד וְגוֹ'.</p>\n<p>אָמַר לוֹ אוֹתוֹ הֶגְמוֹן, אַשְׁרֶיךְ, וְאַשְׁרֵי הָעָם שֶׁיּוֹרְשִׁים תּוֹרַת אֱמֶת! אַחַר יָמִים שָׁמַעְתִּי שֶׁהִתְגַּיֵּר. הָלְכוּ, הִגִּיעוּ לְשָׂדֶה אַחַת וְהִתְפַּלְלוּ תְפִלָּתָם. כֵּיוָן שֶׁהִתְפַּלְלוּ תְפִלָּתָם, אָמְרוּ, מִכָּאן וָהָלְאָה נִתְחַבֵּר בַּשְּׁכִינָה, וְנֵלֵךְ וְנִתְעַסֵּק בַּתּוֹרָה.</p>"],[9522011811,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (ישעיה מא) הֵן יֵבֹשׁוּ וְיִכָּלְמוּ כֹּל הַנֶּחֱרִים בָּךְ וְגוֹ'. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לְיִשְׂרָאֵל כָּל אוֹתָן טוֹבוֹת שֶׁאָמַר עַל יְדֵי נְבִיאֵי הָאֱמֶת, וְיִשְׂרָאֵל סָבְלוּ עֲלֵיהֶם כַּמָּה רָעוֹת בְּגָלוּתָם. וְאִלְמָלֵא כָּל אוֹתָן טוֹבוֹת שֶׁמְּחַכִּים וְרוֹאִים שֶׁכְּתוּבִים בַּתּוֹרָה, לֹא הָיוּ יְכוֹלִים לַעֲמֹד וְלִסְבֹּל אֶת הַגָּלוּת.</p>\n<p>אֲבָל הוֹלְכִים לְבֵית מִדְרָשׁוֹת, פּוֹתְחִים סְפָרִים, וְרוֹאִים כָּל אוֹתָן טוֹבוֹת שֶׁמְּחַכִּים, וְרוֹאִים שֶׁכְּתוּבִים בַּתּוֹרָה שֶׁהִבְטִיחַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם, וּמִתְנַחֲמִים בְּגָלוּתָם, וּשְׁאָר הָעַמִּים מְחָרְפִים וּמְגַדְּפִים אוֹתָם וְאוֹמְרִים: אַיֵּה אֱלֹהֵיכֶם? אַיֵּה אוֹתָן טוֹבוֹת שֶׁאַתֶּם אוֹמְרִים שֶׁמְּעֻתָּדוֹת לָכֶם, וְכִי כָּל עַמֵּי הָאָרֶץ יִתְבַּיְּשׁוּ מִכֶּם?</p>\n<p>זֶהוּ שֶׁכָּתוּב, (שם סו) שִׁמְעוּ דְּבַר ה' הַחֲרֵדִים אֶל דְּבָרוֹ אָמְרוּ אֲחֵיכֶם שּׁנְאֵיכֶם וְגוֹ'. מַה זֶּה הַחֲרֵדִים אֶל דְּבָרוֹ? אֵלּוּ שֶׁסָּבְלוּ כַּמָּה רָעוֹת, כַּמָּה שְׁמוּעוֹת שָׁמְעוּ אֵלֶּה עַל אֵלֶּה וְאֵלֶּה אַחַר אֵלֶּה וְחָרְדוּ עֲלֵיהֶן, כְּמוֹ שֶׁנֶּאֱמַר (ירמיהל) כִּי וְגוֹ' קוֹל חֲרָדָה שָׁמָעְנוּ פַּחַד וְאֵין שָׁלוֹם וְגוֹ'. אוֹתָם חֲרֵדִים תָּמִיד אֶל דְּבָרוֹ כְּשֶׁנַּעֲשָׂה הַדִּין.</p>\n<p>אָמְרוּ אֲחֵיכֶם שּנְאֵיכֶם - אֵלֶּה הֵם אֲחֵיכֶם בְּנֵי עֵשָׂו. מְנַדֵּיכֶם - כְּמוֹ שֶׁנֶּאֱמַר (איכה ד) סוּרוּ טָמֵא קָרְאוּ לָמוֹ. שֶׁאֵין עַם שֶׁמְּבַזִּים אוֹתָם בַּפָּנִים וְרוֹקְקִים בִּפְנֵי יִשְׂרָאֵל כְּמוֹ בְּנֵי אֱדוֹם, וְכֻלָּם אוֹמְרִים שֶׁטְּמֵאִים כְּמוֹ נִדָּה, וְזֶהוּ מְנַדֵּיכֶם. לְמַעַן שְׁמִי יִכְבַּד ה', אָנוּ (שאומרים) בְּנֵי אֵל חַי, שֶׁבָּנוּ יִתְכַּבֵּד שְׁמוֹ, אָנוּ שׁוֹלְטִים עַל הָעוֹלָם בִּשְׁבִיל אוֹתוֹ שֶׁנִּקְרָא גָּדוֹל, (בראשית כז) עֵשָׂו בְּנוֹ הַגָּדֹל. וּבַשֵּׁם הַזֶּה נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גָּדוֹל, (תהלים קמה) גָּדוֹל ה' וּמְהֻלָּל מְאֹד. אָנוּ בְּנֵי הַגָּדוֹל, וְהוּא גָּדוֹל. וַדַּאי לְמַעַן שְׁמִי יִכְבַּד ה'.</p>\n<p>אֲבָל אַתֶּם קְטַנִּים מֵהַכֹּל, כָּתוּב יַעֲקֹב בְּנָהּ הַקָּטָן, אַיֵּה אֱלֹהֵיכֶם? אַיֵּה אוֹתָן טוֹבוֹת שֶׁיִּתְבַּיְּשׁוּ כָּל הָעַמִּים מִשִּׂמְחַתְכֶם? מִי יִתֵּן וְנִרְאֶה בְשִׂמְחַתְכֶם כְּמוֹ שֶׁאַתֶּם אוֹמְרִים, וְהֵם יֵבוֹשׁוּ, (רוחהקדשאומר והם יבושו) (עוד, כמי) כְּמִי שֶׁתּוֹלֶה קִלְלָתוֹ בְאַחֵר, מִשּׁוּם שֶׁאַתֶּם אוֹמְרִים שֶׁאָז יֵבֹשׁוּ וְיִכָּלְמוּ, וּמִשּׁוּם כָּךְ רוּחַ הַקֹּדֶשׁ הָיְתָה אוֹמֶרֶת הַדָּבָר כָּךְ, וְעַל זֶה הֵן יֵבֹשׁוּ וְיִכָּלְמוּ כֹּל הַנֶּחֱרִים בָּךְ. מִי הֵם כֹּל הַנֶּחֱרִים בָּךְ? אֵלֶּה שֶׁחִזְּקוּ אֶת נְחִירֵיהֶם בְּרֹגֶז עָלֶיךְ בַּגָּלוּת הַזּוֹ. בְּאוֹתוֹ זְמַן יֵבֹשׁוּ וְיִכָּלְמוּ מִכָּל הַטּוֹבוֹת שֶׁיִּירְאוּ אֵצֶל יִשְׂרָאֵל.</p>"],[9522011812,"<p>אָמַר רַבִּי חִיָּיא, כָּךְ זֶה וַדַּאי, אֲבָל רָאִינוּ וְכָךְ רָאוּ גִּבּוֹרֵי הָעוֹלָם, שֶׁהֲרֵי הַגָּלוּת נִמְשֶׁכֶת וַעֲדַיִן בֶּן דָּוִד לֹא בָא. אָמַר רַבִּי יוֹסֵי, וְכָל זֶה כָּךְ הוּא, אֲבָל מִי עָשָׂה שֶׁיִּסְבְּלוּ יִשְׂרָאֵל אֶת הַגָּלוּת הַזּוֹ? כָּל אוֹתָן הַבְטָחוֹת שֶׁהִבְטִיחַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. וַהֲרֵי זֶה נִתְבָּאֵר, שֶׁנִּכְנָסִים לְבָתֵּי כְּנֵסִיּוֹת וּלְבָתֵּי מִדְרָשׁוֹת וְרוֹאִים כָּל אוֹתָן נֶחָמוֹת, וּשְׂמֵחִים בְּלִבָּם לִסְבֹּל אֶת כָּל מַה שֶּׁיָּבא עֲלֵיהֶם, וְלוּלֵא זֶה לֹא יָכְלוּ לִסְבֹּל.</p>\n<p>אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, וְהַכֹּל תָּלוּי בִּתְשׁוּבָה. וְאִם תֹּאמַר שֶׁיְּכוֹלִים עַכְשָׁו לְעוֹרֵר תְּשׁוּבָה כֻּלָּם כְּאֶחָד - לֹא יְכוֹלִים! מָה הַטַּעַם לֹא יְכוֹלִים? מִשּׁוּם שֶׁכָּתוּב, (דברים ל) וְהָיָה כִי יָבֹאוּ עָלֶיךְ כָּל הַדְּבָרִים הָאֵלֶּה. וְכָתוּב וַהֲשֵׁבֹתָ אֶל לְבָבֶךְ בְּכָל הַגּוֹיִם אֲשֶׁר הִדִּיחֲךְ וְגוֹ'. וְכָתוּב וְשַׁבְתָּ עַד ה' אֱלֹהֶיךְ וְגוֹ'. וְאָז (שם) אִם יִהְיֶה נִדַּחֲךְ בִּקְצֵה הַשָּׁמָיִם מִשָּׁם יְקַבֶּצְךְ וְגוֹ'. וְעַד שֶׁכָּל אוֹתָם דְּבָרִים לֹא יִתְקַיְּמוּ, לֹא יְכוֹלִים לְעוֹרֵר תְּשׁוּבָה מֵהֶם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כַּמָּה הִסְתַּרְתָּ כָּל הַדְּרָכִים וְהַשְּׁבִילִים מִכָּל בְּנֵי הַגָּלוּת וְלֹא הִשְׁאַרְתָּ לָהֶם פִּתְחוֹן פֶּה. אִם כָּךְ, שֶׁיִּהְיוּ כְּמוֹ שֶׁהָיוּ בְּכָל דּוֹר וָדוֹר - שֶׁלֹּא יִסְבְּלוּ גָלוּת וְלֹא שָׂכָר, וְיֵצְאוּ (אם כך, יהיו כמו שיהיו בכל דור ודור, יסבלו את הגלות ולא יצאו) מִדִּין שֶׁל הַתּוֹרָה, וְיִתְעָרְבוּ בִּשְׁאָר הָעַמִּים.</p>\n<p>פָּתַח וְאָמַר, (ישעיה כו) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ וְגוֹ'. מַה זֶּה כְּמוֹ הָרָה? דֶּרֶךְ הוּא לִמְעֻבֶּרֶת שֶׁיַּעַבְרוּ עָלֶיהָ תִּשְׁעָה חֳדָשִׁים שְׁלֵמִים. וְיֵשׁ בָּעוֹלָם כַּמָּה וְכַמָּה שֶׁלֹּא עוֹבֵר עָלֶיהָ אֶלָּא יוֹם אֶחָד אוֹ יוֹמַיִם מֵהַתְּשִׁיעִי, וְכָל הַצִּירִים וְהַחֲבָלִים שֶׁל הַמְעֻבֶּרֶת הֵם בַּתְּשִׁיעִי. וְאַף עַל גַּב שֶׁלֹּא עָבַר עָלֶיהָ אֶלָּא רַק יוֹם אֶחָד, נֶחְשָׁב עָלֶיהָ כְּאִלּוּ עָבְרוּ כָּל הַתְּשִׁיעִי שָׁלֵם. אַף כָּךְ יִשְׂרָאֵל, כֵּיוָן שֶׁטָּעֲמוּ טַעַם גָּלוּת - אִם יַחְזְרוּ בִּתְשׁוּבָה, יֵחָשֵׁב עֲלֵיהֶם כְּאִלּוּ עָבְרוּ עֲלֵיהֶם כָּל אוֹתָם דְּבָרִים שֶׁכְּתוּבִים בַּתּוֹרָה. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן שֶׁכַּמָּה וְכַמָּה יִסּוּרִים עָבְרוּ עֲלֵיהֶם מִיּוֹם שֶׁהִתְחִילָה הַגָּלוּת.</p>\n<p>אֲבָל מַהוּ שֶׁכָּתוּב (דבריםד) בַּצַּר לְךְ וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים - בֹּא וּרְאֵה כַּמָּה רַחֲמָנוּת רִחֵם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל בַּדָּבָר הַזֶּה. לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יְחִידִי וְאָהַב אוֹתוֹ אַהֲבַת נֶפֶשׁ, וּמִתּוֹךְ אַהֲבָתוֹ נָתַן אוֹתוֹ לְאִמּוֹ הַגְּבִירָה שֶׁתְּגַדֵּל אוֹתוֹ וּתְלַמֵּד אוֹתוֹ דְּרָכִים מְתֻקָּנוֹת. פַּעַם אַחַת חָטָא לְאָבִיו, בָּא אָבִיו וְהִלְקָה אוֹתוֹ, וְאַחַר כָּךְ עָבַר עַל חֶטְאוֹ. שָׁב כְּמִקֹּדֶם וְשׁוּב חָטָא לְאָבִיו, וְהוֹצִיא אוֹתוֹ אָבִיו מִבֵּיתוֹ וְרָגַז עָלָיו. יָצָא אוֹתוֹ בֵן מִבֵּיתוֹ.</p>\n<p>וּבִמְקוֹם שֶׁיֵּלֵךְ בְּדֶרֶךְ אֱמֶת וְיִהְיֶה צַדִּיק כָּרָאוּי כְּדֵי שֶׁיִּשְׁמַע אָבִיו הַמֶּלֶךְ וְתִהְיֶה עָלָיו תְּשׁוּקָתוֹ - מֶה עָשָׂה? אָמַר, הוֹאִיל וְיָצָאתִי מֵהֵיכַל אָבִי, אֶעֱשֶׂה מִכָּאן וָהָלְאָה כָּל מַה שֶּׁאֲנִי רוֹצֶה. מֶה עָשָׂה? הָלַךְ לְהִתְחַבֵּר לְזוֹנוֹת, וְהִתְלַכְלֵךְ בְּלִכְלוּךְ וְטִנֹּפֶת עִמָּן, וְלֹא הָיָה נִמְצָא אֶלָּא עִמָּן בַּחִבּוּר שֶׁלָּהֶן. כְּשֶׁהַגְּבִירָה אִמּוֹ פּוֹקֶדֶת בְּכָל יוֹם עַל אוֹתוֹ הַבֵּן וְיוֹדַעַת שֶׁבְּנָהּ הִתְחַבֵּר עִם הַזּוֹנוֹת וְכָל חַבְרוּתוֹ הָיְתָה עִמָּהֶן, מַתְחִילָה לִבְכּוֹת וּלְמָרֵר עַל בְּנָהּ.</p>\n<p>יוֹם אֶחָד נִכְנָס אֵלֶיהָ הַמֶּלֶךְ וְרוֹאֶה אוֹתָהּ בּוֹכָה. שׁוֹאֵל אוֹתָהּ: עַל מָה אַתְּ בּוֹכָה? אָמְרָה: וְאֵיךְ לֹא אֶבְכֶּה, שֶׁהֲרֵי בְּנֵנוּ מִחוּץ לְהֵיכַל הַמֶּלֶךְ? וְלֹא דַי שֶׁאֵינוֹ יוֹשֵׁב בְּהֵיכַל הַמֶּלֶךְ, אֶלָּא שֶׁהוּא יוֹשֵׁב עִם הַזּוֹנוֹת! מַה יֹּאמְרוּ כָּל בְּנֵי הָעוֹלָם - שֶׁבֶּן הַמֶּלֶךְ יוֹשֵׁב בְּבֵית זוֹנוֹת?! הִתְחִילָה לִבְכּוֹת וּלְהִתְחַנֵּן לַמֶּלֶךְ. בִּשְׁבִילֵךְ אַחֲזִיר אוֹתוֹ, וְאַתְּ הָעֲרֵבָה שֶׁלּוֹ. אָמְרָה: הֲרֵי וַדַּאי.</p>\n<p>אָמַר הַמֶּלֶךְ: הוֹאִיל וְכָךְ הוּא, לֹא צָרִיךְ לְהַחֲזִירוֹ בַּיּוֹם בְּגָלוּי, שֶׁבּוּשָׁה עֲבוּרֵנוּ לָלֶכֶת בִּשְׁבִילוֹ לְבֵית זוֹנוֹת. וְאִם לֹא הָיָה כְּמוֹ זֶה שֶׁטִּנֵּף אֶת עַצְמוֹ כָּךְ וְחִלֵּל כְּבוֹדִי, הָיִיתִי אֲנִי וְכָל הַחֲיָלוֹת שֶׁלִּי הוֹלְכִים בִּשְׁבִילוֹ בְּכַמָּה כָבוֹד וּבְכַמָּה חֲצוֹצְרוֹת לְפָנָיו, בְּכַמָּה כְּלֵי קְרָב מִימִינוֹ וּמִשְּׂמֹאלוֹ, עַד שֶׁכָּל בְּנֵי הָעוֹלָם יִזְדַּעְזְעוּ, וְיֵדְעוּ כֻלָּם שֶׁהוּא בֶּן הַמֶּלֶךְ. עַכְשָׁו כֵּיוָן שֶׁהוּא טִנֵּף אֶת עַצְמוֹ וְחִלֵּל אֶת כְּבוֹדִי, הוּא יַחֲזֹר בְּסֵתֶר שֶׁלֹּא יַכִּירוּ בוֹ. חָזַר לַמֶּלֶךְ, וְנָתַן אוֹתוֹ לְאִמּוֹ.</p>\n<p>לְיָמִים סָרַח כְּמִקֹּדֶם. מֶה עָשָׂה הַמֶּלֶךְ? הוֹצִיא אוֹתוֹ וְאֶת אִמּוֹ עִמּוֹ מִתּוֹךְ הַהֵיכָל וְאָמַר: תֵּלְכוּ שְׁנֵיכֶם, וּשְׁנֵיכֶם תִּסְבְּלוּ אֶת הַגָּלוּת וְהַמַּלְקוּת שָׁם. כֵּיוָן שֶׁשְּׁנֵיכֶם תִּסְבְּלוּ כְאֶחָד, אֲזַי אֵדַע שֶׁבְּנִי יָשׁוּב כָּרָאוּי.</p>\n<p>כָּךָ יִשְׂרָאֵל, בְּנֵי הַמֶּלֶךְ הַקָּדוֹשׁ הֵם, הוֹרִיד אוֹתָם לְמִצְרַיִם. וְאִם תֹּאמַר שֶׁבְּאוֹתוֹ זְמַן לֹא חָטְאוּ - הַגְּזֵרָה שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא בִּבְרִית בֵּין הַבְּתָרִים הָיְתָה רְאוּיָה לְהִתְקַיֵּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁגִּיחַ עַל שְׁנֵי דְבָרִים: אֶחָד עַל אוֹתוֹ דִבּוּר שֶׁאָמַר אַבְרָהָם (בראשית טז) בַּמָּה אֵדַע כִּי אִירָשֶׁנָּה, זוֹהִי סִבָּה וְעִלָּה. אֲבָל עַד שֶׁיָּצְאוּ מִמִּצְרַיִם לֹא הָיוּ גוֹי וְלֹא הָיוּ רְאוּיִים כָּרָאוּי.</p>\n<p>פָּתַח וְאָמַר, (שיר ב) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים כֵּן רַעְיָתִי בֵּין הַבָּנוֹת. רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת אֶת יִשְׂרָאֵל כְּמוֹ שֶׁלְּמַעְלָה וְלִהְיוֹת שׁוֹשַׁנָּה אַחַת בָּאָרֶץ כְּמוֹ שֶׁלְּמַעְלָה. וְהַשּׁוֹשַׁנָּה שֶׁמַּעֲלָה רֵיחַ וְנִבְחֲרָה מִכָּל שְׁאָר הַוְּרָדִים שֶׁבָּעוֹלָם אֵינָהּ אֶלָּא אוֹתָהּ שֶׁעוֹלָה בֵּין הַחוֹחִים. וְזוֹ דֶרֶךְ כָּרָאוּי. וְלָכֵן זָרַע שִׁבְעִים זוּגוֹת, שֶׁהָיוּ שִׁבְעִים נֶפֶשׁ, וְהִכְנִיסָם לְבֵין הַחוֹחִים, וְאוֹתָם חוֹחִים, מִיָּד שֶׁהָיוּ הֵם שָׁם זוּגוֹת, הֶעֱלוּ עֲנָפִים וְעָלִים וְשָׁלְטוּ עַל הָעוֹלָם, וְאָז פָּרְחָה בֵינֵיהֶם הַשּׁוֹשַׁנָּה.</p>\n<p>כֵּיוָן שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא שׁוֹשַׁנָּה וְלִלְקֹט אוֹתָהּ מִבֵּינֵיהֶם, אָז יָבְשׁוּ הַחוֹחִים וְנִזְרְקוּ וְהִתְכַּלּוּ וְלֹא נֶחְשְׁבוּ לִכְלוּם. בְּשָׁעָה שֶׁהוֹלֵךְ לִלְקֹט אֶת הַשּׁוֹשַׁנָּה הַזּוֹ וּלְהוֹצִיא בְנוֹ בְּכוֹרוֹ, בְּאוֹתוֹ זְמַן הָלַךְ הַמֶּלֶךְ בְּתוֹךְ כַּמָּה חֲיָלוֹת גְּדוֹלִים וְשַׁלִּיטִים עִם דְּגָלִים פְּרוּשִׂים, וְהוֹצִיא אֶת בְנוֹ בְּכוֹרוֹ בְּכַמָּה גְבוּרוֹת, וְהֵבִיא אוֹתוֹ לְהֵיכָלוֹ, וְיָשַׁב הַרְבֵּה בְּבֵית הַמֶּלֶךְ.</p>\n<p>כֵּיוָן שֶׁחָטָא לְאָבִיו, הוֹכִיחַ אוֹתוֹ וְהִלְקָה אוֹתוֹ, שֶׁכָּתוּב וַיִּחַר אַף ה' בְּיִשְׂרָאֵל וַיִּתְּנֵם בְּיַד שׁוֹסִים וְגוֹ'. סָרַח כְּמִקֹּדֶם וּמָרַד בְּאָבִיו, הוֹצִיא אוֹתוֹ מִבֵּיתוֹ. מֶה עָשׂוּ יִשְׂרָאֵל? רָאוּ שֶׁהֲרֵי הִתְפַּזְּרוּ בְּבָבֶל וְהִתְעָרְבוּ בָעַמִּים, לָקְחוּ נָשִׁים נָכְרִיּוֹת וְהוֹלִידוּ מֵהֶם בָּנִים. עִם כָּל זֶה הָאֵם הַקְּדוֹשָׁה הָיְתָה אַפּוֹטְרוֹפּוֹס עֲלֵיהֶם.</p>\n<p>וְעַל שֶׁעָשָׂה כָּךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, הוֹאִיל וְזוֹ בּוּשָׁה, אָז שֶׁיָּבֹא בְנִי מֵעַצְמוֹ. הוֹאִיל וְחִלֵּל כְבוֹדִי, לֹא רָאוּי שֶׁאֲנִי אֵלֵךְ לְשָׁם לְהוֹצִיא אוֹתוֹ וְלַעֲשׂוֹת לוֹ נִסִּים וּגְבוּרוֹת כְּמִקֹּדֶם. שָׁבוּ הֵם בְּלִי סִיּוּעַ שֶׁהָיוּ רְאוּיִים לוֹ, בְּלִי נִסִּים וְנִפְלָאוֹת, אֶלָּא כֻּלָּם מְפֻזָּרִים, כֻּלָּם עֲיֵפִים בְּעֹנִי, וְשָׁבוּ לְהֵיכַל הַמֶּלֶךְ בְּבוּשָׁה, וְהָאֵם הַקְּדוֹשָׁה עָרְבָה לָהֶם.</p>"],[9522011813,"<p>חָטְאוּ כְּמִקֹּדֶם. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הוֹצִיא אֶת הַבֵּן הַזֶּה כְּמִקֹּדֶם מֵהֵיכָלוֹ עִם אִמּוֹ. אָמַר, מִכָּאן וָהָלְאָה הָאֵם וּבְנָהּ יִסְבְּלוּ כַּמָּה רָעוֹת כְּאֶחָד. זֶהוּ שֶׁכָּתוּב, (ישעיהנ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְעַל זֶה כָּתוּב, (דברים ד) בַּצַּר לְךְ וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים. מַה זֶּה בְּאַחֲרִית הַיָּמִים? אֶלָּא זוֹ הָאֵם הַקְּדוֹשָׁה, שֶׁהִיא אַחֲרִית הַיָּמִים, וְעִמָּהּ סָבְלוּ כָּל מַה שֶּׁסָּבְלוּ בַגָּלוּת.</p>\n<p>וְאִלּוּ יַחְזְרוּ בִתְשׁוּבָה - אֲפִלּוּ רָעָה אַחַת אוֹ צַעַר אֶחָד שֶׁיַּעֲבֹר עֲלֵיהֶם, יֵחָשֵׁב עֲלֵיהֶם כְּאִלּוּ סָבְלוּ הַכֹּל. (ואם לא יסתם הקץ) וְאִם לֹא - כְּשֶׁיִּסְתַּיֵּם הַקֵּץ (הרע) וְכָל הַדּוֹרוֹת שֶׁלּוֹ, כְּמוֹ שֶׁאָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁכָּתוּב (ויקרא כה) לַצְּמִיתֻת לַקֹּנֶה אֹתוֹ לְדרֹתָיו. וְכָל זֶה, הַדָּבָר תָּלוּי בִּתְשׁוּבָה. אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ זֶה, וְעַל כֵּן נִמְשֶׁכֶת הַגָּלוּת.</p>\n<p>אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל מַה שֶּׁרָאָה (שהכה) (שהלקה) לְיִשְׂרָאֵל - בְּאַחֲרִית הַיָּמִים הַזּוֹ. וּבְאַחֲרִית הַיָּמִים הַזּוֹ יַעֲשֶׂה לָהֶם נִסִּים וּנְקָמוֹת, שֶׁכָּתוּב (ישעיה ב) וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית ה' בְּרֹאשׁ הֶהָרִים. מִי זֶה רֹאשׁ הֶהָרִים? זֶה אַבְרָהָם הַזָּקֵן, הַכֹּהֵן הַגָּדוֹל, הָרֹאשׁ שֶׁל הַכֹּל. וּמִשּׁוּם שֶׁהוּא רֹאשׁ, כּוֹס שֶׁל בְּרָכָה, יִהְיֶה נָכוֹן בְּרֹאשׁ הֶהָרִים, זֶה אַבְרָהָם הַזָּקֵן, רִאשׁוֹן לִשְׁאָר הֶהָרִים, כּוֹס שֶׁל בְּרָכָה, צְרִיכָה לִהְיוֹת מְתֻקֶּנֶת בְּיָמִין.</p>\n<p>וְנִשָּׂא מִגְּבָעוֹת. צָרִיךְ לִהְיוֹת נִשָּׂא מִן הַשֻּׁלְחָן שִׁעוּר שֶׁנִּקְרָא (שהוא) זֶרֶת לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ וְנִשָּׂא מִגְּבָעוֹת. מַה זֶּה מִגְּבָעוֹת? אֶלָּא בֵּינָהּ וּבֵין בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, שִׁעוּר הַזֶּרֶת הוּא. נִשָּׂא כּוֹס שֶׁל בְּרָכָה מִגְּבָעוֹת וַדַּאי, וְעַל כֵּן הַטּוֹב שֶׁיִּהְיֶה לַבֵּן הַבְּכוֹר הַזֶּה (ישראל) הוּא בְּאַחֲרִית הַיָּמִים. אֲנִי לֹא אָכַלְתִּי, וְהוֹאִיל וְלֹא הִצְטָרַפְתִּי לְזִמּוּן, אֲנִי לֹא אֶשְׁמַע וְלֹא אֹמַר אָמֵן. הַכֹּל חַיָּבִים בּוֹ.</p>\n<p>אָמַר לוֹ, יָפֶה אָמַרְתָּ, שֶׁפָּסוּק זֶה וַדַּאי כָּךְ הוּא. בְּרֹאשׁ הֶהָרִים - זֶה יָמִין, אַבְרָהָם הַזָּקֵן, שֶׁהוּא וַדַּאי רֹאשׁ הֶהָרִים. וְנִשָּׂא מִגְּבָעוֹת - מִשִּׁעוּר הַגְּבָעוֹת, שֶׁהֵם רְצוֹנוֹ. וְיָפֶה אָמַרְתָּ. וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם, מִי הוּא? אָמַר לוֹ, וַאֲפִלּוּ נָשִׁים וּקְטַנִּים וְהַשַּׁמָּשׁ שֶׁעוֹבֵד עַל הַשֻּׁלְחָן, אַף עַל גַּב שֶׁאֵינוֹ אוֹכֵל, צָרִיךְ לִשְׁמֹעַ וְלוֹמַר אָמֵן. (להריק ברכה לכוס) שֶׁלֹּא יֹאמַר אָדָם: אֲנִי לֹא אָכַלְתִּי, וְהוֹאִיל וְלֹא הִצְטָרַפְתִּי לְזִמּוּן, אֲנִי לֹא אֶשְׁמַע וְלֹא אֹמַר אָמֵן. הַכֹּל חַיָּבִים בּוֹ.</p>\n<p>דָּבָר אַחֵר וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם - אַף עַל גַּב שֶׁנָּשִׁים וּקְטַנִּים פְּטוּרִים מִן הַמִּצְווֹת, בְּכוֹס שֶׁל בְּרָכָה הַכֹּל חַיָּבִים, וּבִלְבַד שֶׁיֵּדְעוּ אֶת מִי מְבָרְכִים, וְזֶהוּ וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם. בָּא רַבִּי יוֹסֵי וּנְשָׁקוֹ. אָמַר, כַּמָּה יָפֶה דָּבָר זֶה וּמָתוֹק לַחֵךְ.</p>\n<p>עַכְשָׁו יֵשׁ לְדַיֵּק, אִם אַחֲרִית הַיָּמִים הַזּוֹ הִיא כּוֹס שֶׁל בְּרָכָה מַמָּשׁ, מַה זֶּה הַר בֵּית ה'? הָיָה לוֹ לִכְתֹּב כָּךְ: וְהָיָה אַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה בְּרֹאשׁ הֶהָרִים. מַהוּ בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית ה'? אָמַר לוֹ, אַחֲרִית הַיָּמִים הוּא הָעֵץ שֶׁל הַכֹּל, מֵרֹאשׁוֹ וְעַד סוֹפוֹ, שֶׁהוּא עֵץ טוֹב וָרַע. וּבָא הַפָּסוּק לְבָרֵר בְּאַחֲרִית הַיָּמִים, וְהוֹצִיא הַר בֵּית ה', זֶה טוֹב בְּלִי רַע. הַר בֵּית ה' וַדַּאי שֶׁאֵין שָׁם חֵלֶק לַצַּד הָאַחֵר, שֶׁהֲרֵי נִבְחַר הַר בֵּית ה' מִתּוֹךְ הָעֵץ, שֶׁהוּא אַחֲרִית הַיָּמִים. וְזוֹהִי כּוֹס שֶׁל בְּרָכָה, שֶׁהוּא נָכוֹן בְּרֹאשׁ הֶהָרִים.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי הַדֶּרֶךְ הַזּוֹ שֶׁזָּכִינוֹ לַדָּבָר הַזֶּה. אָמַר לוֹ, מִמִּי שָׁמַעְתָּ אוֹתוֹ? אָמַר לוֹ, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ וְשָׁמַעְתִּי וְרָאִיתִי אֶת רַב הַמְנוּנָא סָבָא (לרבי שמעון) שֶׁהָיָה דּוֹרֵשׁ אֶת הַפָּסוּק הַזֶּה לְרַב אָחָא. וְכֵיוָן שֶׁשָּׁמַעְתִּי, שָׂמַחְתִּי בּוֹ, וְשָׁמַרְתִּי אוֹתוֹ צְרוֹר בִּכְנַף לְבוּשִׁי שֶׁלֹּא יָסוּר מִמֶּנִּי לְעוֹלָמִים. אָמַר לוֹ, וַדַּאי שֶׁדָּבָר קָדוֹשׁ זֶה נָאוֹר מֵהַמְּנוֹרָה הַקְּדוֹשָׁה. אַשְׁרֵי הַדּוֹר שֶׁעַמּוּדֵי הָעוֹלָם וְתוֹמְכָיו שׁוֹרִים בְּתוֹכוֹ, וְאִם אַתָּה צוֹרֵר אֶת הַדָּבָר הַזֶּה בְּקֶשֶׁר אֶחָד שֶׁלֹּא יָסוּר מִמְּךְ - אֲנִי אֶצְרֹר אוֹתוֹ בִּשְׁלֹשִׁים אוֹ בְּאַרְבָּעִים קְשָׁרִים בְּכִיסִי שֶׁלֹּא יָסוּר מִמֶּנִּי לְעוֹלָמִים.</p>\n<p>עַל אוֹתוֹ דָּבָר שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, מִשּׁוּם שֶׁאַף עַל גַּב שֶׁיִּשְׂרָאֵל חָטְאוּ לְפָנָיו בְּכָל דּוֹר וָדוֹר, לֹא רָצָה מִי שֶׁיֹּאמַר עֲלֵיהֶם לָשׁוֹן הָרָע. מִנַּיִן לָנוּ? מֵהוֹשֵׁעַ, שֶׁכָּתוּב (הושע א) תְּחִלַּת דִּבֶּר ה' בְּהוֹשֵׁעַ. הֲרֵי בֵּאֲרוּ אֶת הַדָּבָר. וְעַל כֵּן הָיָה מִסְפַּר בְּנֵי יִשְׂרָאֵל כְּחוֹל הַיָּם וְגוֹ'. וּמִשּׁוּם כָּךְ בֵּרַךְ אוֹתָם בְּכַמָּה בְּרָכוֹת, לַחֲזֹר בִּתְשׁוּבָה וְלַהֲשִׁיבָם לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם, וְלֹא זָז מִשָּׁם הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁמָּחַל עַל חֲטָאֵיהֶם וְהִתְנַקּוּ לְפָנָיו.</p>"],[9522011814,"<p>מַה כָּתוּב בְּאֵלִיָּהוּ? (מלכים א יט) וַיָּבֹא וַיֵּשֶׁב תַּחַת רֹתֶם אֶחָד וְגוֹ'. אָמַר, רִבּוֹן הָעוֹלָם, אִשָּׁה אַחַת שָׁלַחְתָּ לְיִשְׂרָאֵל וּדְבוֹרָה שְׁמָהּ, שֶׁכָּתוּב (שופטים ד) וְהִיא יוֹשֶׁבֶת תַּחַת תֹּמֶר דְּבוֹרָה. זֶהוּ רֹתֶם. וְהֶחֱזִירָתָם לְמוּטָב, שֶׁכָּתוּב (שם ה) עַד שַׁקַּמְתִּי דְּבוֹרָה. וַאֲנִי נִכְנַסְתִּי בֵינֵיהֶם, וְהִכְרַזְתִּי לִפְנֵיהֶם וְלֹא יָכֹלְתִּי.</p>\n<p>עַד שֶׁהָיָה יוֹשֵׁב, הִתְגַּלָּה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר לוֹ, מַה לְּךְ פֹה אֵלִיָּהוּ? בָּרִאשׁוֹנָה הָיִיתָ מְקַטְרֵג וּמְקַנֵּא עַל הַבְּרִית, וּמִשֶּׁרָאִיתִי בְּךְ שֶׁקִּנֵּאתָ עָלַי בְּאוֹתָהּ בְּרִית, נָטַלְתִּי אוֹתָהּ בִּרְצוֹנוֹ שֶׁל מֹשֶׁה וְנָתַתִּי לְךְ, עַד שֶׁמֹּשֶׁה הָיָה אוֹמֵר, (במדבר כה) הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. עַכְשָׁו שֶׁהוּא שֶׁלְּךְ, אֵינוֹ רָאוּי לְךְ לְקַטְרֵג עָלָיו, הָיָה לְךְ לְהַשְׁאִיר אֶת קִנְאָתְךְ לִי, כְּמוֹ בָּרִאשׁוֹנָה שֶׁהָיְתָה שֶׁלִּי, נָתַתִּי אוֹתוֹ לִידֵי אַחֵר וְלֹא קִטְרַגְתִּי עָלָיו.</p>\n<p>מַה לְּךְ פֹה. מַה זֶּה פֹה? בְּרִית הַקֹּדֶשׁ פֶּה ה' הִיא. כֵּיוָן שֶׁלֹּא רָצִיתָ לְהַנִּיחַ לִי אֶת פִּיךְ, יִבָּרֵא בַּמָּקוֹם שֶׁל אוֹתוֹ הַפֶּה. שָׁנִינוּ, בְּאוֹתָהּ שָׁעָה הָעָבְרָה מִמֶּנּוּ אוֹתָהּ מַתָּנָה שֶׁנָּתַן לוֹ מֹשֶׁה. שֶׁשָּׁנִינוּ, מַה שֶּׁכָּתוּב (מלכים א יט) וַיֵּלֶךְ בְּכֹחַ הָאֲכִילָה הַהִיא וְגוֹ' עַד הַר הָאֱלֹהִים חֹרֵב - לְבַקֵּשׁ מִשָּׁם. וְכִי מִשָּׁם הָיָה מְבַקֵּשׁ? אֶלָּא לְבַקֵּשׁ כְּמִקֹּדֶם מֵאוֹתוֹ שֶׁיָּרַשׁ בְּהַר הָאֱלֹהִים אֶת הַבְּרִית הַזּוֹ. פִּנְחָס הוּא אֵלִיָּהוּ, וַדַּאי בְּדַרְגָּה אַחַת. אָמַר לוֹ מֹשֶׁה, אֵין אַתָּה יָכוֹל לְקַבֵּל מִמֶּנִּי, אֶלָּא לֵךְ לַתִּינוֹקוֹת שֶׁל יִשְׂרָאֵל וּמֵהֶם תַּרְוִיחַ וְהֵם יִתְּנוּ לְךְ. וְכָךְ הוּא עָשָׂה.</p>"],[9522011815,"<p>כַּמָּה טוֹב עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל דּוֹר וָדוֹר לְיִשְׂרָאֵל. בּא וּרְאֵה מַה כָּתוּב, (מיכה ז) וָאֶשְׁלַח לְפָנֶיךְ אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם. וַהֲרֵי כַּמָּה נְבִיאִים הָיוּ אַחֲרֵי מֹשֶׁה! וָאֶשְׁלַח לְפָנֶיךְ אֶת מֹשֶׁה אַהֲרֹן וְאֶלְעָזָר וּפִנְחָס יְהוֹשֻׁעַ וְאֵלִיָּהוּ וֶאֱלִישָׁע וְכַמָּה שְׁאָר צַדִּיקִים וַחֲסִידִים הָיָה צָרִיךְ לוֹמַר, אָז לָמָּה שְׁלֹשֶׁת אֵלֶּה? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, עַמִּי, בָּנַי, לָמָּה לֹא תִזְכְּרוּ אֶת כָּל הַטּוֹבוֹת שֶׁעָשִׂיתִי לָכֶם, שֶׁשָּׁלַחְתִּי לָכֶם אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם?</p>\n<p>לְמֶלֶךָ בָּשָׂר וָדָם שֶׁיֵּשׁ לוֹ מְדִינָה, וְשָׁלַח אֵלֶיהָ אֲנָשִׁים גְּדוֹלִים, שָׂרִים וְשַׁלִּיטִים, שֶׁיְּנַהֲלוּ אֶת הָעָם וִיעַיְּנוּ בָהֶם וּבְדִינֵיהֶם. מִי צָרִיךְ לִהְיוֹת זָקוּק בִּמְזוֹנָם וּבַדְּבָרִים שֶׁיִּצְטָרְכוּ, הֲלֹא לֹא עַם הַמְּדִינָה?! הֲרֵי בְּעַל כָּרְחָם יִצְטָרְכוּ לְהַשְׁגִּיחַ עַל דַּרְכֵיהֶם וְלָתֵת לָהֶם כָּבוֹד.</p>\n<p>שָׁלַחְתִּי אֶת מֹשֶׁה, הוּא הֵבִיא לִפְנֵיכֶם מָן לֶאֱכֹל, וְנִהֵל אֶתְכֶם וְאֶת בְּנֵיכֶם וְאֶת בְּהֶמְתְכֶם, וְהִשְׁתַּדֵּל בְּדִינֵיכֶם (במזונותיכם) וּבְכָל מַה שֶּׁהִצְטָרַכְתֶּם. שָׁלַחְתִּי אֶת אַהֲרֹן, הֵבִיא (לכם ענני) הֵיכָלוֹת שֶׁל עַנְנֵי כָבוֹד לְכַסּוֹת עֲלֵיכֶם כְּמוֹ מְלָכִים. רָחַץ אֶתְכֶם בְּטַלְלֵי כָבוֹד שֶׁלֹּא יִרְקְבוּ לְבוּשֵׁיכֶם וּמִנְעֲלֵיכֶם, שֶׁהָיוּ מִתְחַדְּשִׁים בְּכָל יוֹם. שָׁלַחְתִּי לְמִרְיָם, הֵבִיאָה בְאֵר לְהַשְׁקוֹת אֶתְכֶם, וּשְׁתִיתֶם אַתֶּם וּבְהֶמְתְכֶם. הֵם נָתְנוּ לָכֶם, וּמִשֶּׁלָּהֶם אֲכַלְתֶּם וּשְׁתִיתֶם וִישַׁבְתֶּם בְּחֻפַּת הַכָּבוֹד שֶׁלָּהֶם, וּמִשֶּׁלָּכֶם לֹא נְתַתֶּם לָהֶם. וְלֹא עוֹד, אֶלָּא שֶׁהִשְׁתַּדְּלוּ עֲלֵיכֶם וְלָקְחוּ עַל צַוָּארָם אֶת מַשַּׂאֲכֶם, וֶהֱיִיתֶם מְחָרְפִים וּמְגַדְּפִים אוֹתָם.</p>"],[9522011816,"<p>אָמַר רַבִּי יוֹסֵי, לֹא הָיָה אָב רַחֲמָן עַל בָּנָיו כְּמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וּפָסוּק הוּא שֶׁכָּתוּב, (מלכים אח) לֹא נָפַל דָּבָר אֶחָד מִכֹּל דְּבָרוֹ הַטּוֹב וְגוֹ'. בּא וּרְאֵה רַחֲמָנוּתוֹ: אִלּוּ אָמַר לֹא נָפַל דָּבָר אֶחָד מִכָּל דְּבָרוֹ וְלֹא יוֹתֵר - נוֹחַ לָעוֹלָם שֶׁלֹּא נִבְרָא. אֲבָל מִשֶּׁאָמַר מִכָּל דְּבָרוֹ הַטּוֹב, וְהוֹצִיא הָרַע לְאָחוֹר, שֶׁהֲרֵי דָּבָר שֶׁל רַע לֹא רָצָה לַעֲשׂוֹת.</p>\n<p>וְאַף עַל גַּב שֶׁהִפְחִיד וְהֵרִים רְצוּעָה, בָּאָה הָאֵם וְהֶחֱזִיקָה בִּזְרוֹעַ יְמִינוֹ, וְעָמְדָה הָרְצוּעָה בִּמְקוֹמָהּ וְלֹא יָרְדָה לְמַטָּה, וְלֹא נַעֲשָׂה (הדין), מִשּׁוּם שֶׁבְּעֵצָה אַחַת הָיוּ שְׁנֵיהֶם - אוֹתוֹ שֶׁהִפְחִיד, וְאוֹתוֹ שֶׁאָחַז בִּימִינוֹ.</p>\n<p>וְאִם תֹּאמַר, מִנַּיִן לָנוּ? זֶה מִדָּבָר שֶׁהוּא בְּגָלוּי, שֶׁכָּתוּב לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ. הִתְחִיל לְהָרִים רְצוּעָה, וּמֹשֶׁה, שֶׁלֹּא הָיָה יוֹדֵעַ דַּרְכָּה שֶׁל אֵם, שָׁתַק. כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא כָּךְ, רָמַז לוֹ, וְהִכָּה בּוֹ וְאָמַר וְעַתָּה הַנִּיחָה לִּי. מִיָּד הִרְגִּישׁ מֹשֶׁה וְאָחַז בִּזְרוֹעוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב זְכֹר לְאַבְרָהָם. זוֹ זְרוֹעַ יָמִין, וּמִשּׁוּם כָּךְ לֹא יָרְדָה הָרְצוּעָה.</p>\n<p>וְאִם תֹּאמַר, הָאֵם שֶׁהִיא רְגִילָה לֶאֱחֹז בִּרְצוּעַת הַמֶּלֶךְ, הֵיכָן הָיְתָה שֶׁהִשְׁאִירָה אֶת הַדָּבָר לְמֹשֶׁה? שָׁאַלְתִּי וְאָמַרְתִּי, וַהֲרֵי לֹא יָדַעְתִּי אֶת בֵּרוּר הַדָּבָר, עַד שֶׁנִּהְיָה לִפְנֵי הַמְּנוֹרָה הַקְּדוֹשָׁה. כְּשֶׁבָּאוּ לִפְנֵי רַבִּי שִׁמְעוֹן, רָאָה בִּפְנֵיהֶם סִימָן. אָמַר, הִכָּנְסוּ בָנִים קְדוֹשִׁים, הִכָּנְסוּ אֲהוּבֵי הַמֶּלֶךְ, הִכָּנְסוּ אֲהוּבִים שֶׁלִּי, הִכָּנְסוּ אֲהוּבִים אֵלֶּה לְאֵלֶּה.</p>\n<p>שֶׁאָמַר רַבִּי אַבָּא, כָּל הַחֲבֵרִים הַלָּלוּ שֶׁאֵין אוֹהֲבִים זֶה אֶת זֶה, מִסְתַּלְּקִים מֵהָעוֹלָם טֶרֶם שֶׁהִגִּיעַ זְמַנָּם. כָּל הַחֲבֵרִים בְּיָמָיו שֶׁל רַבִּי שִׁמְעוֹן, אַהֲבַת נֶפֶשׁ וְרוּחַ הָיְתָה בֵינֵיהֶם, וּמִשּׁוּם כָּךְ בְּדוֹרוֹ שֶׁל רַבִּי שִׁמְעוֹן הָיוּ בְּגָלוּי. שֶׁהָיָה רַבִּי שִׁמְעוֹן אוֹמֵר, כָּל הַחֲבֵרִים שֶׁאֵין אוֹהֲבִים אֵלֶּה לְאֵלֶּה, גּוֹרְמִים שֶׁלֹּא לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה, וְעוֹד - שֶׁעוֹשִׂים בָּהּ פְּגָם, שֶׁהֲרֵי בַּתּוֹרָה אַהֲבָה וְאַחֲוָה וֶאֱמֶת יֵשׁ בָּהּ. אַבְרָהָם אָהַב אֶת יִצְחָק, וְיִצְחָק אֶת אַבְרָהָם, הָיוּ מִתְחַבְּקִים זֶה בָּזֶה. בְּיַעֲקֹב שְׁנֵיהֶם אֲחוּזִים בְּאַהֲבָה וּבְאַחֲוָה, נוֹתְנִים רוּחָם זֶה בָּזֶה. גַּם הַחֲבֵרִים בְּאוֹתָהּ דֻּגְמָא הֵם צְרִיכִים, וְלֹא לַעֲשׂוֹת פְּגָם.</p>\n<p>כֵּיוָן שֶׁרָאָה סִימָן בִּפְנֵיהֶם וְאָמַר לָהֶם כָּךְ, אָמְרוּ לוֹ, וַדַּאי רוּחַ נְבוּאָה שׁוֹרָה עַל הַמְּנוֹרָה הַקְּדוֹשָׁה, וְכָךְ אָנוּ צְרִיכִים לָדַעַת. בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, דָּבָר אֶחָד מֵאוֹתָם דְּבָרִים שֶׁלָּחֲשׁוּ לִי מִתּוֹךְ רֹאשׁ הַיְשִׁיבָה שֶׁל גַּן עֵדֶן, שֶׁלֹּא אָמְרוּ בְּגָלוּי דָּבָר זֶה, סֵתֶר הוּא. וְאֹמַר לָכֶם, בָּנַי אֲהוּבַי, בָּנַי אֲהוּבֵי נַפְשִׁי, מָה אֶעֱשֶׂה. אָמְרוּ לִי בְּלַחַשׁ, וַאֲנִי אֹמַר בְּגָלוּי, וְלִזְמַן שֶׁנִּרְאֶה פָּנִים בְּפָנִים (שכינה), כָּל הַפָּנִים יִסְתַּמְּכוּ בָזֶה.</p>\n<p>בָּנַי, הַחֵטְא שֶׁעָשׂוּ (ערב רב) הָעָם שֶׁבַּחוּץ, וְהִשְׁתַּתְּפוּ בוֹ הָעָם הַקָּדוֹשׁ - בָּאֵם הֵם חָטְאוּ, שֶׁכָּתוּב קוּם עֲשֵׂה לָנוּ אֱלֹהִים, אֱלֹהִים וַדַּאי. כְּבוֹד יִשְׂרָאֵל הַזֶּה, הוּא שֶׁשּׁוֹרֶה עָלֶיהָ כְּאֵם עַל בָּנִים, וְזֶהוּ סוֹד הַכָּתוּב (תהלים קו) וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר. זֶה כְּבוֹדָם שֶׁל יִשְׂרָאֵל, הָאִמָּא שֶׁלָּהֶם. וְזֶהוּ שֶׁכָּתוּב (שמואל א ד) גָּלָה כָבוֹד. שֶׁגָּרְמוּ לַשְּׁכִינָה לִגְלוֹת בַּגָּלוּת עִמָּהֶם. וְעַל זֶה וַיָּמִירוּ אֶת כְּבוֹדָם. בַּמֶּה? בְּתַבְנִית שׁוֹר.</p>\n<p>כָּאן הוּא סוֹד הַדָּבָר. בֹּא וּרְאֵה, לְמַטָּה בְּתוֹךְ שִׁמְרֵי הַיַּיִן הַשְּׁמָרִים הָרָעִים, יָצָא מַפְגִּיעַ אֶחָד, מְקַטְרֵג, מַזִּיק קַדְמוֹן, וְהוּא בְּסוֹד דְּמוּת אָדָם. כְּשֶׁקָּרַב לְתוֹךְ הַקֹּדֶשׁ, כֵּיוָן שֶׁמָּעֳבָר מִשָּׁם וְרוֹצֶה לָרֶדֶת לְמַטָּה, רוֹצֶה לְהִתְלַבֵּשׁ בִּלְבוּשׁ לְהַזִּיק אֶת הָעוֹלָם. וְיוֹרֵד הוּא וּמַרְכְּבוֹתָיו. וְהַלְּבוּשׁ הָרִאשׁוֹן שֶׁהוּא לוֹקֵחַ - תַּבְנִית שׁוֹר, דְּמוּת שׁוֹר, וְרִאשׁוֹן לַנְּזִיקִין מֵאוֹתָם אַרְבָּעָה. הוּא שׁוֹר. וְהֵם אַרְבָּעָה אָבוֹת לְהַזִּיק לָעוֹלָם, וְכָל שְׁלֹשֶׁת אֲבוֹת הַנְּזִיקִין פְּרָט לַשּׁוֹר, כֻּלָּם שֶׁלּוֹ, וְעַל זֶה כָּתוּב וַיָּמִירוּ אֶת כְּבוֹדָם בְּתַבְנִית שׁוֹר.</p>\n<p>מַה זֶּה אֹכֵל עֵשֶׂב? הֲרֵי דָּרַשְׁנוּ בוֹ, אֲבָל עִקַּר הַדָּבָר מִתַּמְצִית שֶׁל לֶחֶם וְשִׁבְעָה מִינֵי דָגָן אֵין לוֹ בָּהֶם חֵלֶק. וּמִשּׁוּם כָּךְ הָאֵם לֹא הָיְתָה שָׁם, וְלֹא נָאֶה לָהּ לִהְיוֹת שָׁם. וּמִשּׁוּם שֶׁהָאָב הָיָה יוֹדֵעַ אֶת רַחֲמָנוּת הָאֵם וְדַרְכָּהּ, אָמַר לְמֹשֶׁה, בְּנִי אֲהוּבִי, הָעֵצָה בָּזֶה תָּמִיד בִּשְׁנֵיהֶם. וְזֶהוּ שֶׁלָּחֲשׁוּ לִי בְּלַחַשׁ, שֶׁלֹּא רָאוּי לְגַלּוֹת, שֶׁהַבֵּן לֹא יֵדַע, וְיִרְאֶה שֶׁהֲרֵי רְצוּעָה מוּכָנָה, וְתָמִיד יִפְחַד. אֲבָל שְׁנֵיהֶם בְּעֵצָה זוֹ וּבְעֵצָה אַחַת.</p>"],[9522011817,"<p>בֹּא וּרְאֵה, כָּתוּב וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה. מִי זֶה הָעָם? הֵם הָעֵרֶב רַב. מִי הָעֵרֶב רַב? וְכִי לוֹדִים וְכוּשִׁים וְכַפְתּוֹרִים וְתוֹגַרְמִים הָיוּ, שֶׁקָּרְאוּ לָהֶם עֵרֶב רַב? וַהֲלֹא מִצְרִיִּים הָיוּ, וּמִמִּצְרַיִם נָסְעוּ. וְאִלּוּ הָיוּ עִרְבּוּבְיָה שֶׁל עַמִּים רַבִּים, כָּךְ הָיָה לוֹ לִכְתֹּב: עֵרֶב רַב עָלוּ אִתָּם לְפִי הָעִרְבּוּבְיָה שֶׁלָּהֶם.</p>\n<p>אֶלָּא עֵרֶב רַב עָלָה אִתָּם - עַם אֶחָד הָיָה וְלָשׁוֹן אַחַת, אֲבָל כָּל מְכַשְּׁפֵי מִצְרַיִם וְכָל חַרְטֻמֵּיהֶם הָיוּ אֵלֶּה, שֶׁכָּתוּב בָּהֶם (שמות ז) וַיַּעֲשׂוּ גַם הֵם חַרְטֻמֵּי מִצְרַיִם. שֶׁרָצוּ לַעֲמֹד כְּנֶגֶד נִפְלְאוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁרָאוּ הַנִּסִּים וְהַנִּפְלָאוֹת שֶׁעָשָׂה מֹשֶׁה בְּמִצְרַיִם, חָזְרוּ לְמֹשֶׁה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, אַל תְּקַבֵּל אוֹתָם. אָמַר מֹשֶׁה, רִבּוֹן הָעוֹלָם, כֵּיוָן שֶׁרָאוּ גְבוּרָתְךְ הֵם רוֹצִים לְהִתְגַּיֵּר. יִירְאוּ גְבוּרָתְךְ בְּכָל יוֹם, וְיֵדְעוּ שֶׁאֵין אֱלוֹהַּ מִבַּלְעָדֶיךְ. וְקִבֵּל אוֹתָם מֹשֶׁה.</p>\n<p>לָמָּה קָרָא לָהֶם עֵרֶב רַב? אֶלָּא כָּל מְכַשְּׁפֵי מִצְרַיִם הָיוּ, וּבְרֹאשָׁם יוֹנוֹס וְיִמְבְּרוּס, וּבִשְׁעוֹת הַיּוֹם הָיוּ עוֹשִׂים כִּשְׁפֵיהֶם תָּמִיד. וְכָל הַמְּכַשְּׁפִים הַלָּלוּ הָעֶלְיוֹנִים הָיוּ מִסְתַּכְּלִים מִכַּאֲשֶׁר נוֹטֶה הַשֶּׁמֶשׁ, מֵרֵאשִׁית שֵׁשׁ שָׁעוֹת וָחֵצִי עַד רֵאשִׁית תֵּשַׁע וָחֵצִי, שֶׁהַיְנוּ עֵרֶב הַגָּדוֹל. כָּל אוֹתָם מְכַשְּׁפִים קְטַנִּים, מִתְּחִלַּת תֵּשַׁע וָחֵצִי עַד חֲצוֹת הַלַּיְלָה.</p>\n<p>אוֹתָם עֶלְיוֹנִים שֶׁבָּהֶם הָיוּ מִסְתַּכְּלִים מִכְּשֶׁנּוֹטֶה הַשֶּׁמֶשׁ, שֶׁהֲרֵי אָז מַתְחִילִים תְּשַׁע מֵאוֹת וְתִשְׁעִים וְחָמֵשׁ דְּרָגוֹת לְשׁוֹטֵט עַל הָרֵי הַחֹשֶׁךְ, וְרוּחָם הָיְתָה מְשׁוֹטֶטֶת עַל כָּל אוֹתָם מְכַשְּׁפִים (דרגות) בְּכִשְׁפֵיהֶם. וְאֵלֶּה הָיוּ עוֹשִׂים כָּל מַה שֶּׁהֵם רוֹצִים, עַד שֶׁכָּל הַמִּצְרַיִם בְּאֵלֶּה הָיָה מִבְטֶחָם. וְקָרְאוּ לָהֶם עֵרֶב רַב, מִשּׁוּם שֶׁיֵּשׁ לָהֶם עֵרֶב קָטָן, מִתֵּשַׁע שָׁעוֹת וָחֵצִי וּמַטָּה, זֶה עֵרֶב קָטָן. וּשְׁנֵי עֲרָבִים הֵם, וְעַל כָּךְ וְגַם עֵרֶב רַב עָלָה אִתָּם.</p>\n<p>וְחָכְמָתָם הָיְתָה רַבָּה, וְהֵם הִסְתַּכְּלוּ בִּשְׁעוֹת הַיּוֹם, וְהִסְתַּכְּלוּ בְּדַרְגַּת מֹשֶׁה, וְרָאוּ שֶׁהֲרֵי בְּכָל הַצְּדָדִים בְּשֵׁשׁ מֹשֶׁה: בְּשֵׁשׁ שָׁעוֹת רִאשׁוֹנוֹת שֶׁל הַיּוֹם, שֶׁהֵם לֹא יְכוֹלִים לִשְׁלֹט בָּהֶם, (בגלל שש) בְּשֵׁשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁאוֹחֲזִים בּוֹ (שאוחז בהם). וּבְכָל הַצְּדָדִים הָיָה בְּשֵׁשׁ, וּבְעַטְרוֹת הַשֵּׁשׁ הַלָּלוּ הָיָה עָתִיד לָרֶדֶת מִן הָהָר, שֶׁכָּתוּב כִּי בֹשֵׁשׁ מֹשֶׁה לָרֶדֶת מִן הָהָר.</p>\n<p>מִיָּד וַיִּקָּהֵל הָעָם עַל אַהֲרֹן, (שכך למדנו, שבאותה שעה שירד משה וקבל התורה לבדו כללות כל ישראל, והוא קבל התורה בעולם. ואפלו מגלת אסתר שכתוב (אסתר ט) וקבל היהודים, וקבלו היהודים היה צריך להיות, מהו וקבל, ' אלא זה משה שהוא היהודים, כללות כל היהודים. ויקהל העם על אהרן) לָמָּה עַל אַהֲרֹן? כְּדֵי לְהִכָּלֵל בְּצַד הַיָּמִין, שֶׁהֲרֵי הֵ ם הַשְּׂמֹאל רָצוּ מִמֶּנּוּ, וּכְדֵי שֶׁיִּהְיֶה כָּלוּל בַּיָּמִין, הִתְכַּנְּסוּ עַל אַהֲרֹן, וַיֹּאמְרוּ אֵלָיו קוּם עֲשֵׂה לָנוּ אֱלֹהִים. (אלהים ודאי רצו צד השמאל. אשר ילכו, אשר ילך היה צריך להיות, מהו אשר ילכו, ' אלא אלהים, שש מדרגות הן, (ששת ימי המעשה), כלם בצד השמאל של אלהים, שש הן. שאם תאמר שהרי הן שבע, אותו האלהים העליון לא נכנס בכלל).</p>\n<p>בֹּא וּרְאֵה, כָּל זְמַן שֶׁהָיָה מֹשֶׁה בְּמִצְרַיִם, לֹא הִזְכִּיר הַשֵּׁם שֶׁל אֱלֹהִים, אֶלָּא שֵׁם שֶׁל ה', וְעַל זֶה קָשֶׁה לוֹ לְפַרְעֹה, כְּדֵי שֶׁלֹּא יִהְיֶה תֹקֶף לְאוֹתוֹ הַצַּד הָאַחֵר וְלֹא יִתְחַזֵּק בָּעוֹלָם. עַכְשָׁו רָצוּ אֶת אוֹתוֹ הַדָּבָר, וְזֶהוּ קוּם עֲשֵׂה לָנוּ אֱלֹהִים. לָנוּ דַּוְקָא, שֶׁאָנוּ צְרִיכִים אֶת הַדָּבָר הַזֶּה לְחַזֵּק אֶת הַצַּד שֶׁלָּנוּ, שֶׁהָיָה דָחוּי עַד עַכְשָׁו.</p>\n<p>אֲשֶׁר יֵלְכוּ לְפָנֵינוּ. מָה אָמְרוּ? אֶלָּא כָּךְ אָמְרוּ, אָנוּ רוֹאִים שֶׁאַתֶּם יִשְׂרָאֵל, כָּל טוּב וְכָל הַכָּבוֹד שֶׁל הָעוֹלָם לָכֶם, וְאָנוּ דְחוּיִים בַּחוּץ. שֶׁלָּכֶם - (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם. אַף כָּךְ אֱלֹהִים אֲשֶׁר יֵלְכוּ לְפָנֵינוּ, כְּמוֹ שֶׁה' הוֹלֵךְ לִפְנֵיכֶם. שֶׁהֲרֵי יֵשׁ לָנוּ רְשׁוּת לַצַּד שֶׁלָּנוּ לָלֶכֶת אַף כָּךְ לְפָנֵינוּ, אִם נְזַמֵּן לוֹ מַעֲשֶׂה.</p>\n<p>בֹּא וּרְאֵה, כָּל עַנְנֵי הַכָּבוֹד שֶׁהָלְכוּ בַּמִּדְבָּר, לֹא הָיוּ מְכַסִּים אֶלָּא רַק אֶת בְּנֵי יִשְׂרָאֵל לְבַדָּם, וְאוֹתוֹ עֲנַן כָּבוֹד שֶׁכָּתוּב וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם, הוֹלֵךְ לִפְנֵיהֶם. וְהָעֵרֶב רַב הַלָּלוּ, וְכָל אוֹתָן בְּהֵמוֹת, צֹאן וּשְׁוָרִים, הָיוּ הוֹלְכִים מִחוּץ לַמַּחֲנֶה בָּאַחֲרוֹנָה. וּבֹא רְאֵה, כָּל אוֹתָם אַרְבָּעִים שָׁנִים שֶׁהָלְכוּ יִשְׂרָאֵל בַּמִּדְבָּר, שׁוּם לִכְלוּךְ וְטִנּוּף לֹא הָיָה בְּתוֹךְ הָעֲנָנִים בִּפְנִים. וְעַל זֶה צֹאן וּבָקָר שֶׁהָיוּ אוֹכְלִים עֵשֶׂב הָיוּ בַּחוּץ, וְכָל אוֹתָם שֶׁשּׁוֹמְרִים אוֹתָם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַבָּא, אִם כָּךְ, אוֹתָם עֵרֶב רַב לֹא הָיוּ אוֹכְלִים מִן הַמָּן? אָמַר לוֹ, וַדַּאי כָּךְ הוּא, אֶלָּא רַק מַה שֶּׁנּוֹתְנִים לָהֶם יִשְׂרָאֵל, כְּמִי שֶׁנּוֹתֵן לְעַבְדּוֹ. וּמִמֶּה הָיוּ אוֹכְלִים? מִתַּמְצִית, מַה שֶּׁנִּשְׁאַר אַחַר הָרֵחַיִם, פְּסֹלֶת. וְהַכָּתוּב מַכְרִיז וְאוֹמֵר, (שם טז) וּבְנֵי יִשְׂרָאֵל אָכְלוּ אֶת הַמָּן אַרְבָּעִים שָׁנָה. בְּנֵי יִשְׂרָאֵל, וְלֹא אֲחֵרִים. וַיִּרְאוּ בְנֵי יִשְׂרָאֵל וַיֹּאמְרוּ מָן הוּא, וְלֹא שְׁאָר הָעֵרֶב רַב, צֹאן וּבָקָר שֶׁהָיוּ בֵינֵיהֶם.</p>\n<p>עַד עַכְשָׁו הָיוּ כְנוּעִים אוֹתָם עֵרֶב רַב, וְעַכְשָׁו עָמְדוּ וְרָצוּ מַעֲשֶׂה לְחַזֵּק אֶת הַצַּד הָאַחֵר, וְאָמְרוּ, אוֹ נִהְיֶה כֻלָּנוּ עַם אֶחָד וְנִהְיֶה בַּכְּלָל עִמָּכֶם, אוֹ שֶׁיִּהְיֶה לָנוּ מִי שֶׁיֵּלֵךְ לְפָנֵינוּ כְּמוֹ שֶׁהוֹלֵךְ אֱלֹהֵיכֶם לִפְנֵיכֶם. אָמַר אַהֲרֹן, חַס וְשָׁלוֹם שֶׁאֵלֶּה יִשְׁתַּתְּפוּ בָּעָם הַקָּדוֹשׁ לִהְיוֹת הַכֹּל כְּלָל אֶחָד, וְלֹא יִתְעָרְבוּ הָעָם הַקָּדוֹשׁ בָּעָם הַזֶּה בִּכְלָל אֶחָד, אֶלָּא טוֹב לְהַפְרִידָם מִתּוֹךְ הָעָם הַקָּדוֹשׁ עַד שֶׁיָּבֹא מֹשֶׁה.</p>\n<p>וְאַהֲרֹן הִתְכַּוֵּן לְטוֹב, אֶלָּא שֶׁהָיוּ רַבִּים מִיִּשְׂרָאֵל שֶׁהִשְׁתַּתְּפוּ עִמָּהֶם בַּלֵּב. וּמִשּׁוּם כָּךְ, כְּשֶׁבָּא מֹשֶׁה, הִצְטָרֵךְ לְבָרֵר וּלְלַבֵּן אֶת הָעָם הַקָּדוֹשׁ מֵאוֹתוֹ חֵטְא, וְהִשְׁקָה אוֹתָם הַשְׁקָיָה, עַד שֶׁכֻּלָּם נִבְרְרוּ וְלֹא נִשְׁאֲרָה בָהֶם פְּסֹלֶת כְּלָל.</p>\n<p>אָמַר לָהֶם אַהֲרֹן, פָּרַקוּ נִזְמֵי הַזָּהָב. וְכִי לֹא הָיָה לָהֶם זָהָב אַחֵר? אֶלָּא אָמַר אַהֲרֹן, בְּעוֹד שֶׁיֵּשׁ לָהֶם קְטָטָה עִם בְּנֵיהֶם וּנְשֵׁיהֶם, יִתְעַכְּבוּ, וּבֵין כָּךְ יָבֹא מֹשֶׁה. בֹּא וּרְאֵה, שָׁנִינוּ קָשִׁים גֵּרִים לְיִשְׂרָאֵל כְּסַפַּחַת בִּבְשַׂר הַחַי, כָּל שֶׁכֵּן אֵלֶּה שֶׁלֹּא הָיוּ גֵרִים כָּרָאוּי. מַה הֵם עָשׂוּ? וַיִּתְפָּרַקוּ כָּל הָעָם אֶת נִזְמֵי הַזָּהָב אֲשֶׁר בְּאָזְנֵיהֶם. כַּמָּה אֲלָפִים וּרְבָבוֹת הָיוּ מִנִּזְמֵיהֶם שָׁם.</p>\n<p>מַה כָּתוּב? וַיִּקַּח מִיָּדָם וַיָּצַר אֹתוֹ בַּחֶרֶט וְגוֹ'. אַהֲרֹן לֹא נִשְׁמַר מֵאוֹתָם שְׁנֵי חֲכָמִים שֶׁהָיוּ בְרָאשֵׁיהֶם שֶׁל אוֹתוֹ עֵרֶב רַב, אֶחָד מֵהֶם הָיָה לְפָנָיו, וְהָאַחֵר הָיָה עוֹשֶׂה בִּכְשָׁפִים. כֵּיוָן שֶׁשְּׁנֵיהֶם הִתְיָעֲצוּ כְּאֶחָד, לָקְחוּ אֶת אוֹתוֹ זָהָב, (אחד) שְׁנֵי שְׁלִישׁ בְּיָד אַחַת, וּשְׁלִישׁ בַּיָּד הָאַחֶרֶת. מִשּׁוּם שֶׁכָּךְ צָרִיךְ בְּאוֹתוֹ מִין שֶׁל כִּשּׁוּף.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, אָמַר, אֵי חָסִיד קָדוֹשׁ, אַהֲרֹן מָשׁוּחַ שֶׁל הָאֵל הַגָדוֹל, בַּחֲסִידוּתְךְ נָפְלוּ כַּמָּה מֵהָעָם הַקָּדוֹשׁ, וְאַתָּה לֹא הָיִיתָ יוֹדֵעַ לְהִשָּׁמֵר. מֶה עָשׂוּ? כְּשֶׁהִגִּיעוּ שֵׁשׁ שָׁעוֹת וְהַיּוֹם הָיָה בְּמִשְׁקָל, לָקְחוּ אֶת אוֹתוֹ זָהָב שֶׁפָּרְקוּ מֵאָזְנֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּי שֶׁצָּרִיךְ לַעֲשׂוֹת כִּשּׁוּף, לֹא מִתְבַּקֵּשׁ לָחוּס עֵינוֹ עַל מָמוֹן. וְהֵם אוֹמְרִים, הַשָּׁעָה עוֹמֶדֶת לָנוּ, אִם אֵינֶנּוּ מְעַכְּבִים. זוֹ אֵינָהּ שָׁעָה לָחוּס עַל הַזָּהָב. מִיָּד - וַיִּתְפָּרַקוּ כָּל הָעָם. מַה זֶּה וַיִּתְפָּרַקוּ? כְּמוֹ שֶׁנֶּאֱמַר (מלכים א יט) מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, שֶׁהִשְׁחִיתוּ וְשָׁבְרוּ אֶת אָזְנֵיהֶם. בָּכָה כְּמִקֹּדֶם וְאָמַר, אֵי עַם קָדוֹשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן בִּבְכִיָּה וְאָמַר, (שמות כא) וְהִגִּישׁוֹ אֲדנָיו אֶל הָאֱלֹהִים וְגוֹ'. הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, הָאֹזֶן שֶׁשָּׁמְעָה בְּסִינַי (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים וְגוֹ', וְהוּא פָּרַק עֹל מַלְכוּת שָׁמַיִם מֵעָלָיו וּמָכַר עַצְמוֹ לְאַחֵר - תֵּרָצַע. וְאֵלּוּ הָרְשָׁעִים הַחַיָּבִים, אֲנָשִׁים רָעִים, בִּתְשׁוּקָתָם לַחֲזר לְסִרְחוֹנָם לֹא רָצוּ מִנְּשֵׁיהֶם וּבְנֵיהֶם אֶלָּא הַשְׁחָתַת דַּרְכָּם (אזניהם), וְהִתְפָּרְקוּ מֵעֹל שֶׁל שָׁמַיִם שֶׁצִּוָּה אוֹתָם מֹשֶׁה וְשָׁבְרוּ אָזְנֵיהֶם, שֶׁאֵין לָהֶם חֵלֶק בַּשֵּׁם הַקָּדוֹשׁ וְהָעָם הַקָּדוֹשׁ.</p>\n<p>מֶה עָשׂוּ? חִלְּקוּ שְׁנֵיהֶם אוֹתוֹ הַזָּהָב, אֶחָד נָטַל שְׁנֵי שְׁלִישִׁים, וְאֶחָד שְׁלִישִׁי. עָמְדוּ כְּנֶגֶד הַשֶּׁמֶשׁ בְּשֵׁשׁ שָׁעוֹת. עָשׂוּ כִשְׁפֵיהֶם וְכִשְּׁפוּ בְּלַהֲטֵיהֶם בַּכִּשּׁוּף שֶׁל הַפֶּה. כֵּיוָן שֶׁהִגִּיעָה רֵאשִׁית הַשָּׁעָה הַשְּׁבִיעִית, שְׁנֵיהֶם הֵרִימוּ יְדֵיהֶם עַל יְדֵי אַהֲרֹן, (ומגין שמהיד של שניהם נטל יד אחת ולא יותר, ') שֶׁכָּתוּב וַיִּקַּח מִיָּדָם. שְׁנֵיהֶם הָיוּ וְלֹא יוֹתֵר. כֵּיוָן שֶׁהוּא קִבֵּל מִיָּדָם (שתים, ולא ידיהם), יָצָא קוֹל וְאָמַר, (משלי יא) יָד לְיָד לֹא יִנָּקֶה רָע, שֶׁכָּתוּב כִּי בְרָע הוּא. הֵבִיא רָע לָעוֹלָם.</p>\n<p>סוֹד הַדָּבָר - אוֹתָם הַחוֹטְאִים הָרְשָׁעִים מְכַשְּׁפִים בְּנֵי בִלְעָם הַחוֹטֵא, בְּנֵי בָנָיו שֶׁל לָבָן הָרָשָׁע, רָאוּ שֶׁכּוֹס שֶׁל בְּרָכָה הִיא בְּיָמִין, וּמֵהַיָּמִין מִתְחַזֶּקֶת תָּמִיד (יותר), אָמְרוּ, אִם יִהְיֶה בַּצַּד הַזֶּה אוֹתוֹ רֹאשׁ שֶׁל הַיָּמִין, הֲרֵי הָעָצְמָה שֶׁלָּנוּ כָּרָאוּי.</p>\n<p>כֵּיוָן שֶׁהִגִּיעַ שֶׁבַע שָׁעוֹת שֶׁל הַיּוֹם, נָתְנוּ לוֹ לְאַהֲרֹן מִיָּד. אִם הוּא הָיָה אוֹמֵר לָהֶם שִׂימוּ אוֹתוֹ בָּאָרֶץ בַּתְּחִלָּה וַאֲנִי אֶטֹּל - לֹא הָיוּ יְכוֹלִים בְּכִשְׁפֵיהֶם לַעֲשׂוֹת כְּלוּם. אֶלָּא נָטַל מִיָּדָם. וְהַכָּתוּב מִתְרַעֵם וְאוֹמֵר, וַיִּקַּח מִיָּדָם. רְאוּ מֶה עָשָׂה אַהֲרֹן אִישׁ נָבִיא, אִישׁ חָכָם, שֶׁלֹּא יָדַע לְהִשָּׁמֵר. שֶׁאִלּוּ נָטַל מִן הָאָרֶץ, כָּל כְּשָׁפִים שֶׁבָּעוֹלָם לֹא הָיוּ יְכוֹלִים לְהַצְלִיחַ. אֲבָל בַּמָּה הִצְלִיחוּ בַּמַּעֲשֶׂה הַזֶּה? מִשּׁוּם שֶׁוַּיִּקַּח מִיָּדָם, וְלֹא מִן הָאָרֶץ.</p>\n<p>וַיָּצַר אֹתוֹ בַּחֶרֶט. לֹא כְּמוֹ שֶׁחוֹשְׁבִים בְּנֵי אָדָם שֶׁעָשָׂה צִיּוּרִים בִּמְחוּגָה אוֹ בְּדָבָר אַחֵר. אֶלָּא בָּא הַכָּתוּב לְהוֹכִיחַ אֶת הַדָּבָר, שֶׁאַהֲרֹן לֹא יָדַע לְהִשָּׁמֵר. אִלּוּ כְּשֶׁנָּטַל מִידֵיהֶם הָיָה זוֹרֵק לָאָרֶץ, וְאַף עַל גַּב שֶׁאַחַר כָּךְ יִטֹּל אוֹתוֹ, אָז לֹא הָיָה מַצְלִיחַ הַמַּעֲשֶׂה הָרָע הַזֶּה. אֲבָל בַּכֹּל הָיָה סִיּוּעַ רַע, שֶׁלָּקַח זָהָב וּטְמָנוֹ מֵהָעַיִן, רַע אַחַר רַע. מַה זֶּה וַיָּצַר אֹתוֹ בַּחֶרֶט? שֶׁשָּׂם אֶת כָּל הַזָּהָב בְּכִיס אֶחָד וְנִשְׁמַר מֵהָעַיִן, וְאָז הַכֹּל עָלָה לְמַעֲשֶׂה.</p>\n<p>בְּסִפְרוֹ שֶׁל חֲנוֹךְ מָצָאנוּ שֶׁכָּךְ הָיָה אוֹמֵר, בֵּן יָחִיד יִוָּלֵד לְאוֹתוֹ רֹאשׁ הַלָּבָן, וּכְשֶׁיָּבֹאוּ אוֹתָם מִבְּשַׂר הַחֲמוֹרִים, יַטְעוּ אוֹתוֹ בְּאוֹתוֹ שֶׁיַּכְנִיס (שיטל) מַרְגָּלִיּוֹת בְּפַעֲמוֹנֵי זָהָב לְלֹא דַעְתּוֹ, וּדְמוּת תְּצֻיַּר בְּצִיּוּר בַּחֶרֶט. מַה זֶּה בַּחֶרֶט? בְּחֶרֶט אֱנוֹשׁ, זֶהוּ קוּלְמוֹס שֶׁל אֱנוֹשׁ הָרָשָׁע שֶׁהִטְעָה בְּנֵי אָדָם.</p>\n<p>וַדַּאי זֶהוּ בֵּרוּר הַדָּבָר, שֶׁאֱנוֹשׁ כְּשֶׁהִטְעָה אֶת הָעוֹלָם, בְּקוּלְמוֹס הָיָה רוֹשֵׁם רִשּׁוּמִים שֶׁל כָּל הַדְּמֻיּוֹת וַעֲבוֹדוֹת זָרוֹת בְּאוֹתוֹ קוּלְמוֹס (רזם רשום), וְלָכֵן כָּתוּב בַּחֶרֶט, אוֹתוֹ שֶׁנּוֹדַע לַעֲשׂוֹת כָּךְ. וְזֶהוּ בֵּרוּר הַדָּבָר.</p>\n<p>וְהַכֹּל הָיָה, שֶׁוַּדַּאי בְּכִיס הִשְׁלִיךְ הַזָּהָב וְכִסָּה אוֹתוֹ מִן הָעַיִן, כְּמוֹ שֶׁאָמְרוּ אוֹתָם מְכַשְּׁפִים, וְכָךְ צָרִיךְ בְּמִינֵי הַכְּשָׁפִים הַלָּלוּ. וְזֶהוּ מַעֲשֵׂיהֶם שֶׁל הַכְּשָׁפִים הַלָּלוּ - דָּבָר שֶׁצָּרִיךְ בְּגִלּוּי לְגַלּוֹת אַחַר כָּךְ, צָרִיךְ הַסְתָּרָה וְכִסּוּי בָּרִאשׁוֹנָה, שֶׁיִּתְכַּסֶּה מִן הָעַיִן, וְאַחַר כָּךְ יֵצֵא הָאֻמָּן לְאֻמָּנוּתוֹ. וְדָבָר שֶׁצָּרִיךְ אַחַר כָּךְ כִּסּוּי, צָרִיךְ בָּרִאשׁוֹנָה בְּגִלּוּי.</p>\n<p>עֵכְשָׁו, בָּנַי אֲהוּבַי, אֲהוּבֵי נַפְשִׁי, מָה אֶעֱשֶׂה? וַדַּאי שֶׁצָּרִיךְ לְגַלּוֹת. הַקְשִׁיבוּ וְהַסְתִּירוּ הַדְּבָרִים. בְּצַד הַקְּדֻשָּׁה הַהוּא, אֱלֹהִים אֱמֶת, מֶלֶךְ עַל הָעוֹלָם, בִּשְׁלֹשָׁה (דברים) עוֹלָמוֹת (אלו) הִתְחַזֵּק - בִּבְרִיאָה, בִּיצִירָה, בַּעֲשִׂיָּה. וַהֲרֵי נֶאֱמַר הַסּוֹד שֶׁל כָּל אֶחָד וְאֶחָד כָּאן. כְּנֶגֶד בְּרִיאָה - וַיִּקַּח מִיָּדָם, דָּבָר שֶׁלֹּא הָיָה בּוֹ עַד עַכְשָׁו כְּלוּם. כְּנֶגֶד יְצִירָה - וַיָּצַר אֹתוֹ בַּחֶרֶט. כְּנֶגֶד עֲשִׂיָּה - וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה. מִי רָאָה כַּכְּשָׁפִים הָאֵלֶּה בְּכָל הָעוֹלָם?</p>\n<p>עַכְשָׁו יֵשׁ לוֹמַר, וְכִי לֹא כָתוּב וָאַשְׁלִיכֵהוּ בָאֵשׁ, וְלֹא יוֹתֵר, וְאָז וַיֵּצֵא הָעֵגֶל הַזֶּה, וְעַכְשָׁו אַתָּה אוֹמֵר וַיַּעֲשֵׂהוּ עֵגֶל מַסֵּכָה? אֶלָּא חַס וְשָׁלוֹם שֶׁאַהֲרֹן עָשָׂה, וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב וַיִּקַּח אֶת הָעֵגֶל אֲשֶׁר עָשׂוּ. אֲבָל מִמַּה שֶּׁכָּתוּב וַיִּקַּח מִיָּדָם וְכָתוּב וַיָּצַר אֹתוֹ, מִכֹּחַ שְׁנֵי אֵלֶּה נַעֲשָׂה הַכֹּל. כִּבְיָכוֹל הוּא עָשָׂה אוֹתוֹ. שֶׁאִם שְׁנֵי אֵלֶּה לֹא הָיוּ, לֹא הָיָה נַעֲשֶׂה וְלֹא יוֹצֵא לְאֻמָּנוּת. אֲבָל מִי גָרַם שֶׁנַּעֲשָׂה? שְׁנֵי אֵלֶּה. (כביכולויעשהו, הואודאיעשהו) בְּעוֹד שֶׁהוּא לוֹקֵחַ מִיָּדָם, הֵם עָשׂוּ כִשְׁפֵיהֶם וְלוֹחֲשִׁים בְּפִיהֶם, וּמוֹשְׁכִים רוּחַ לְמַטָּה מֵהַצַּד הָאַחֵר.</p>\n<p>וּמָשְׁכוּ שְׁתֵּי רוּחוֹת כְּאַחַת, אַחַת מֵהַזָּכָר וְאַחַת מֵהַנְּקֵבָה. שֶׁכְּשֶׁמִּתְלַבֵּשׁ הַזָּכָר בִּדְמוּת הַשּׁוֹר, הַנְּקֵבָה בִּדְמוּת הַחֲמוֹר, וּשְׁנֵיהֶם הָיוּ כְלוּלִים כְּאֶחָד. לָמָּה שְׁנֵי אֵלֶּה? אֶלָּא שׁוֹר הֲרֵי נֶאֱמַר, וַחֲמוֹר לָמָּה? מִשּׁוּם שֶׁבַּמְכַשְּׁפִים הַמִּצְרִיִּים הַלָּלוּ כָּתוּב בָּהֶם, (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם.</p>\n<p>וְלָכֵן כָּל אֵלּוּ מִיִּשְׂרָאֵל שֶׁמֵּתוּ הִתְחַבְּרוּ עִמָּהֶם בְּלִבָּם. וּמִשּׁוּם שֶׁהָיוּ שְׁתֵּי דְמֻיּוֹת, כָּתוּב אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל, וְלֹא כָתוּב זֶה, אֶלָּא אֵלֶּה. שְׁנַיִם הָיוּ כְּאֶחָד. אֲשֶׁר הֶעֱלוּךְ מֵאֶרֶץ מִצְרַיִם, הֶעֱלוּךְ וְלֹא כָתוּב הֶעֶלְךְ.</p>\n<p>וַיַּעָשֵׂהוּ עֵגֶל מַסֵּכָה וַיֹּאמְרוּ. לֹא כָתוּב וַיֹּאמֶר, אֶלָּא וַיֹּאמְרוּ, שֶׁאַהֲרֹן לֹא אָמַר דָּבָר. שָׁנִינוּ, מֵאָה וְעֶשְׂרִים וְחָמֵשׁ קַנְתָּרִים הָיוּ בוֹ.</p>\n<p>אֵיךְ כָּתוּב וַיִּקַּח מִיָּדָם? וְכִי בְיָדָם הָיוּ כָּל הַקַּנְטָרִים הַלָּלוּ? אֶלָּא מִכְּלָל שֶׁל אוֹתָם קַנְטָרִים לָקַח מְלֹא יְדֵיהֶם, וְאוֹתוֹ מְעַט הִתְעַלָּה עַל הַכֹּל כְּאִלּוּ הַכֹּל הָיָה בִּידֵיהֶם.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וַיַּרְא אַהֲרֹן וַיִּבֶן מִזְבֵּחַ לְפָנָיו. אֵי חָסִיד קָדוֹשׁ, כַּמָּה רְצוֹנְךְ הָיָה לְטוֹב וְלֹא יָדַעְתָּ לְהִשָּׁמֵר. כֵּיוָן שֶׁזְּרָקוֹ לָאֵשׁ, הִתְחַזֵּק כֹּחַ הַצַּד הָאַחֵר שָׁם בָּאֵשׁ, וְיָצְאָה דְמוּת שׁוֹר, כְּמוֹ שֶׁנֶּאֱמַר בִּשְׁתֵּי הַמְשָׁכוֹת שֶׁל הַצַּד הָאַחֵר. מִיָּד - וַיַּרְא אַהֲרֹן. מַה זֶּה וַיַּרְא אַהֲרֹן? רָאָה שֶׁהַצַּד הָאַחֵר הִתְחַזֵּק. מִיָּד - וַיִּבֶן מִזְבֵּחַ לְפָנָיו. שֶׁאִלְמָלֵא הִקְדִּים וּבָנָה הַמִּזְבֵּחַ הַזֶּה, הָעוֹלָם הָיָה חוֹזֵר לְחֻרְבָּנוֹ.</p>\n<p>לְלִסְטִים שֶׁהָיָה יוֹצֵא לְאַבֵּד וְלַהֲרֹג בְּנֵי אָדָם, רָאָה לִגְיוֹן הַמֶּלֶךְ שֶׁאוֹתוֹ הַלִּסְטִים יוֹצֵא בְּכֹחַ חָזָק, מֶה עָשָׂה אוֹתוֹ לִגְיוֹן? שִׁדֵּל אֶת הַמֶּלֶךְ לָצֵאת לַדֶּרֶךְ, וּמָשַׁךְ אוֹתוֹ הַלִּגְיוֹן לְאוֹתָהּ הַדֶּרֶךְ. כְּשֶׁעֲדַיִן הַלִּסְטִים הוֹלֵךְ בְּאוֹתָהּ הַדֶּרֶךְ, רָאָה דְּמוּת הַמֶּלֶךְ עוֹמֶדֶת לְפָנָיו. כֵּיוָן שֶׁרָאָה אֶת הַמֶּלֶךְ שֶׁהָיָה הוֹלֵךְ לְפָנָיו בַּדֶּרֶךְ, מִיָּד נִרְתַּע וְחָזַר לְאָחוֹר.</p>\n<p>כָּךָ וַיַּרְא אַהֲרֹן שֶׁהַצַּד הָאַחֵר מִתְגַּבֵּר, אָחַז בָּרְפוּאָה וְהֶחֱזִיק בְּצַד הַקְּדֻשָּׁה וְשָׂם אוֹתוֹ לְפָנָיו. כֵּיוָן שֶׁרָאָה הַצַּד הָרָע אֶת דְּיוֹקַן הַמֶּלֶךְ שֶׁעוֹמֵד לְפָנָיו, מִיָּד חָזַר לְאָחוֹר וְנֶחֱלַשׁ כֹּחוֹ וְחֵילוֹ, שֶׁהֲרֵי הִתְחַזֵּק, (מיד ויבן מזבח לפניו) וְהַמִּזְבֵּחַ הַזֶּה הִתְגַּבֵּר, וְנֶחֱלַשׁ הַצַּד הָאַחֵר.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וַיִּקְרָא אַהֲרֹן וַיֹּאמַר חַג לַה' מָחָר. חַג לַה', וְלֹא לָעֵגֶל. וּלְצַד הַקְּדֻשָּׁה עָשָׂה, וּלְצַד הַקְּדֻשָּׁה קָרָא וְאָמַר. וְזוֹ הָרְפוּאָה שֶׁהִקְדִּים, שֶׁאִלְמָלֵא עָשָׂה אֶת זֶה, לֹא עָמַד הָעוֹלָם עַל מְקוֹמוֹ, וְעִם כָּל זֶה לֹא שָׁכַךְ רָגְזוֹ מֵאַהֲרֹן, אַף עַל גַּב שֶׁלֹּא הִתְכַּוֵּן לְרַע.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַהֲרֹן, שְׁנֵי הַמְכַשְּׁפִים הַלָּלוּ מָשְׁכוּ אוֹתְךְ לְמַה שֶּׁרָצוּ, חַיֶּיךְ שֶׁשְּׁנֵי בָנֶיךְ יִפְּלוּ, וְעַל הַחֵטְא הַזֶּה יָמוּתוּ (ובחטא הזה הם יתפסו). זֶהוּ שֶׁכָּתוּב (דברים ט) וּבְאַהֲרֹן הִתְאַנַּף ה' מְאֹד לְהַשְׁמִידוֹ. מַה זֶּה לְהַשְׁמִידוֹ? אֵלּוּ בָּנָיו, כְּמוֹ שֶׁנֶּאֱמַר (עמוסב) וָאַשְׁמִיד פִּרְיוֹ מִמַּעַל, שֶׁפִּרְיוֹ שֶׁל אָדָם אֵלּוּ הֵם בָּנָיו.</p>\n<p>בֹּא וּרְאֵה, אַהֲרֹן שָׂם אֶת אוֹתוֹ מִזְבֵּחַ לְפָנָיו, וְהָעֵגֶל שָׁב לַאֲחוֹרָיו. בָּנָיו שָׂמוּ אֶת הַצַּד הָאַחֵר לְפָנָיו, וְצַד הַקְּדֻשָּׁה חָזַר לְאָחוֹר, שֶׁכָּתוּב (ויקרא י) וַיַּקְרִיבוּ לִפְנֵי ה'. לִפְנֵי ה' שָׂמוּ. נִתְפְּסוּ בַּחֵטְא הַזֶּה.</p>\n<p>אַהֲרֹן חָשַׁב, שֶׁבֵּינְתַיִם יָבא מֹשֶׁה, וְלָכֵן אֶת אוֹתוֹ מִזְבֵּחַ לֹא הָרַס מֹשֶׁה, שֶׁאִלּוּ הָיָה כְּמוֹ שֶׁחוֹשְׁבִים בְּנֵי אָדָם, הַדָּבָר הָרִאשׁוֹן שֶׁהִצְטָרֵךְ מֹשֶׁה - לְנַתֵּץ אֶת אוֹתוֹ מִזְבֵּחַ הָיָה צָרִיךְ, כְּמוֹ שֶׁהִתְנַבֵּא הַנָּבִיא עִדּוֹ עַל הַמִּזְבֵּחַ בְּבֵית אֵל, וּנְבוּאָתוֹ עַל אוֹתוֹ מִזְבֵּחַ הָיְתָה. אֲבָל כָּאן הָיָה דָּבָר אַחֵר כְּמוֹ שֶׁנִּתְבָּאֵר. וְכָתוּב וַיִּקַּח אֶת הָעֵגֶל אֲשֶׁר עָשׂוּ, וְלֹא כָתוּב וַיִּנְתֹּץ אֶת הַמִּזְבֵּחַ.</p>\n<p>בֹּא וּרְאֵה, וַיִּקְרָא אַהֲרֹן - הוּא הִכְרִיז בְּקוֹל וְאָמַר. כָּתוּב כָּאן וַיִּקְרָא וַיֹּאמַר, וְכָתוּב בְּיוֹנָה וַיִּקְרָא וַיּאמַר. מַה שָּׁם הִכְרִיז לְדִין, אַף כָּאן הִכְרִיז לְדִין. חַג לַה' מָחָר, נִבָּא נְבוּאָה בְּאוֹתָהּ רוּחַ שֶׁל מִזְבֵּחַ, שֶׁעָתִיד הַדִּין לִשְׁרוֹת עֲלֵיהֶם. חַג לַה', לַעֲשׂוֹת בָּכֶם דִּין.</p>\n<p>וּשְׁלשָה דִינִים הָיוּ: אֶחָד, וַיִּגֹּף ה' אֶת הָעָם. וְאֶחָד בִּבְנֵי לֵוִי. וְאֶחָד שֶׁהִשְׁקָה אֶת בְּנֵי יִשְׂרָאֵל. וְהַיְנוּ חַג שֶׁל בְּנֵי לֵוִי. לַה' - שֶׁוַּיִּגֹּף ה'. מָחָר - שֶׁהִשְׁקָה אוֹתָם משֶׁה. וְלָנוּ בְּאוֹתוֹ לַיְלָה, וּלְמָחָר נִמְצְאוּ נְפוּחִים וּמֵתִים. וְאוֹתָם הַמַּיִם הָיוּ מְכַשְׁכְּשִׁים בִּמְעֵיהֶם כָּל הַלַּיְלָה, וּבַבֹּקֶר נִמְצְאוּ מֵתִים, וְלָכֵן חַג לַה' מָחָר. וְכָל הָרְפוּאָה שֶׁעָשָׂה אַהֲרֹן, מִשּׁוּם שֶׁכָּתוּב וַיִּבֶן מִזְבֵּחַ לְפָנָיו.</p>\n<p>בֹּא וּרְאֵה, (אותו מזבח של קדשה היה) שֶׁכָּתוּב וַיַּרְא אֶת הָעֵגֶל וּמְחֹלֹת, וְאִלּוּ מִזְבֵּחַ לֹא כָתוּב. שֶׁהֲרֵי אַהֲרֹן יְדִיעָה הָיָה יוֹדֵעַ שֶׁכָּתוּב (שמות כב) זבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ, וַדַּאי נִצַּל אַהֲרֹן בְּעֵצָה טוֹבָה שֶׁהִנְהִיג לְנַפְשׁוֹ, וְהַכֹּל בְּרָצוֹן שָׁלֵם טוֹב, שֶׁלֹּא הִתְכַּוֵּן לְרַע.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, אַבָּא, וַדַּאי כָּךְ הוּא, וְיִשְׂרָאֵל לֹא הָיוּ. אֲבָל יָרָבְעָם שֶׁעָשָׂה עֲגָלִים, הֲרֵי יִשְׂרָאֵל הָיוּ, וְעֵגֶל עָשׂוּ. אָמַר לוֹ, וַדַּאי, וּפֵרְשׁוּהָ, אֲבָל יָרָבְעָם חָטָא וְהֶחֱטִיא, וְלֹא כְּמוֹ שֶׁאָמְרוּ. שֶׁוַּדַּאי חֵטְא רַע עָשָׂה, וּבַמַּלְכוּת חָטָא.</p>\n<p>אָמַר יָרָבְעָם, הֲרֵי וַדַּאי שֶׁהֲרֵי צַד הַקְּדֻשָּׁה לֹא שׁוֹרָה אֶלּא רַק בְּלֵב כָּל הָעוֹלָם, וְזוֹ יְרוּשָׁלַיִם. אֲנִי לֹא יָכוֹל לִמְשֹׁךְ אֶת אוֹתוֹ הַצַּד לְכָאן, מָה אֶעֱשֶׂה? מִיָּד - (מלכים א יב) וַיִּוָּעַץ הַמֶּלֶךְ וַיַּעַשׂ וְגוֹ'. נָטַל עֵצָה רָעָה. אָמַר, הֲרֵי הַצַּד הָאַחֵר שֶׁנִּמְשָׁךְ מִיָּד לְכָל מָקוֹם, וְכָל שֶׁכֵּן בָּאָרֶץ הַזּוֹ, שֶׁתְּשׁוּקָתוֹ לִשְׁרוֹת בְּתוֹכָהּ, אֲבָל לֹא יָכוֹל לְהִתְלַבֵּשׁ אֶלָּא רַק בִּדְמוּת שֶׁל שׁוֹר.</p>\n<p>שְׁנֵי עֲגָלִים לָמָּה? אֶלָּא אָמַר יָרָבְעָם, (במצרים ובמדבר) בַּמִּדְבָּר הָיוּ אוֹתָם מְכַשְּׁפִים, שֶׁכָּתוּב (יחזקאל כג) בְּשַׂר חֲמוֹרִים בְּשָׂרָם. (לא אותם מצרים, אלא) כָּאן אוֹתָן שְׁתֵּי רוּחוֹת רָעוֹת יִתְלַבְּשׁוּ כָּרָאוּי, זָכָר וּנְקֵבָה הֵם. שֶׁהֲרֵי הַזָּכָר הָיָה בְּבֵית אֵל, וְהַנְּקֵבָה הָיְתָה בְּדָן. וּמִתּוֹךְ שֶׁכָּתוּב נֹפֶת תִּטֹּפְנָה שִׂפְתֵי זָרָה, נִמְשְׁכוּ יִשְׂרָאֵל אַחֲרָיו יוֹתֵר, שֶׁכָּתוּב וַיֵּלְכוּ הָעָם לִפְנֵי הָאֶחָד עַד דָּן. וּמִשּׁוּם כָּךְ הָיוּ שְׁנֵי עֲגָלִים, וּמָשַׁךְ אוֹתָם יָרָבְעָם לָאָרֶץ הַקְּדוֹשָׁה, וְהָיָה חֵטְא עָלָיו וְעַל כָּל יִשְׂרָאֵל, וּמָנַע בְּרָכוֹת מִן הָעוֹלָם, וְעָלָיו כָּתוּב (משלי כח) גּוֹזֵל אָבִיו וְאִמּוֹ וְגוֹ'.</p>\n<p>וְעַל כֵּן הָיוּ הָעֲגָלִים, שֶׁהֲרֵי הַלְּבוּשׁ הָרִאשׁוֹן שֶׁמִּתְלַבֵּשׁ הַצַּד הָאַחֵר הוּא שׁוֹר, כְּמוֹ שֶׁנִּתְבָּאֵר. וְאִם תֹּאמַר, לָמָּה הוּא עֵגֶל וְלֹא שׁוֹר? אֶלָּא וַדַּאי כָּךְ רָאוּי, וְכֵן בְּכָל הַצְּדָדִים, רֵאשִׁית הַלְּבוּשׁ הוּא קָטָן, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וְלָכֵן, בָּנַי אֲהוּבַי, כֵּיוָן שֶׁרָצוּ אֱלֹהִים, וּבַצַּד שֶׁל אֱלֹהִים נִבְנָה הַמַּעֲשֶׂה, הָאֱלֹהִים הַקָּדוֹשׁ, הָאֵם, שֶׁאוֹחֶזֶת תָּמִיד בִּזְרוֹעַ הַמֶּלֶךְ וּמַעֲלָה אֶת הָרְצוּעָה, לֹא הָיְתָה שָׁם, וְהִצְטָרֵךְ מֹשֶׁה לִהְיוֹת שָׁם בִּמְקוֹמָהּ. כֵּיוָן שֶׁרָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, הִסְתַּכֵּל.</p>\n<p>שָׁלש פְּעָמִים רָמַז לוֹ, אֵי מֹשֶׁה הָרוֹעֶה הַנֶּאֱמָן, כַּמָּה חָזָק כֹּחֲךְ, כַּמָּה גְּבוּרָתְךְ גְּדוֹלָה. שָׁלֹשׁ פְּעָמִים רָמַז לוֹ, שֶׁכָּתוּב וְעַתָּה הַנִּיחָה לִּי - הֲרֵי אֶחָד. וְיִחַר אַפִּי בָהֶם וַאֲכַלֵּם - הֲרֵי שְׁתַּיִם. וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל - הֲרֵי שָׁלֹשׁ. חָכְמָתוֹ שֶׁל מֹשֶׁה בִּשְׁלֹשֶׁת הָרְמָזִים הַלָּלוּ. אָחַז בִּזְרוֹעַ יְמִינוֹ - כְּנֶגֶד הַנִּיחָה לִּי. אָחַז בִּזְרוֹעַ שְׂמֹאלוֹ - כְּנֶגֶד וְיִחַר אַפִּי בָהֶם וַאֲכַלֵּם. הִתְחַבֵּק בְּגוּף הַמֶּלֶךְ - כְּנֶגֶד וְאֶעֱשֶׂה אוֹתְךְ לְגוֹי גָּדוֹל. וּכְשֶׁהִתְחַבֵּק בַּגּוּף, וּשְׁתֵּי זְרוֹעוֹת מִצַּד זֶה וּמִצַּד זֶה, לֹא יָכוֹל לְהִתְנַעְנֵעַ לְצַד בָּעוֹלָם. זוֹ הָיְתָה חָכְמָתוֹ שֶׁל מֹשֶׁה, (שבדברי) שֶׁמִּינֵי רְמָזִים שֶׁל הַמֶּלֶךְ הִכִּיר בְּכָל אֶחָד מֵהֶם מֵאֵיזֶה מָקוֹם יַחֲזִיק, וּבְחָכְמָה הוּא עָשָׂה.</p>\n<p>בָּאוּ רַבִּי אֶלְעָזָר וְהַחֲבֵרִים וְנָשְׁקוּ יָדוֹ. הָיָה שָׁם רַבִּי אַבָּא. אָמַר, אִלְמָלֵא לֹא בָאתִי לָעוֹלָם אֶלָּא לִשְׁמֹעַ אֶת זֶה - דַּי לָנוּ. בָּכָה וְאָמַר, וַי רַבִּי, כְּשֶׁתִּסְתַּלֵּק מִן הָעוֹלָם, מִי יָאִיר וִיגַלֶּה אוֹרוֹת הַתּוֹרָה? דָּבָר זֶה בַּחֲשֵׁכָה נִסְתָּר עַד עַכְשָׁו, שֶׁיָּצָא מִשָּׁם, וַהֲרֵי מֵאִיר עַד רוּם הָרָקִיעַ, וּבְכִסֵּא הַמֶּלֶךְ הוּא רָשׁוּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ עַכְשָׁו בַּדָּבָר הַזֶּה. וְכַמָּה שִׂמְחָה עַל שִׂמְחָה נוֹסְפָה מִלִּפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. מִי יָעִיר דִּבְרֵי חָכְמָה בָּעוֹלָם הַזֶּה כְּמוֹתְךְ.</p>\n<p>בֹּא וּרְאֵה, טֶרֶם חָטָא אָדָם, הָיָה עוֹלֶה וְעוֹמֵד בְּחָכְמַת הָאוֹר הָעֶלְיוֹן, וְלֹא הָיָה נִפְרָד מֵעֵץ הַחַיִּים. כֵּיוָן שֶׁהִגְדִּיל תְּשׁוּקָתוֹ לָדַעַת וְלָרֶדֶת לְמַטָּה, נִמְשַׁךְ אַחֲרֵיהֶם, עַד שֶׁנִּפְרַד מֵעֵץ הַחַיִּים, וְיָדַע רַע וְעָזַב הַטּוֹב. וְלָכֵן כָּתוּב (תהליםח) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. מִי שֶׁנִּמְשָׁךְ בָּרָע, אֵין לוֹ דִּיּוּר עִם עֵץ הַחַיִּים. וְטֶרֶם שֶׁחָטְאוּ, הָיוּ שׁוֹמְעִים קוֹל מִלְמַעְלָה וְיוֹדְעִים אֶת הַחָכְמָה הָעֶלְיוֹנָה וְלֹא פוֹחֲדִים. כֵּיוָן שֶׁחָטְאוּ, אֲפִלּוּ קוֹל שֶׁלְּמַטָּה לֹא יָכְלוּ לַעֲמֹד בּוֹ.</p>\n<p>כְּמוֹ זֶה, טֶרֶם שֶׁחָטְאוּ יִשְׂרָאֵל, בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי, הָעָבְרָה מֵהֶם זֻהַמְתּוֹ שֶׁל הַנָּחָשׁ הַזֶּה, שֶׁהֲרֵי אָז בִּטּוּל שֶׁל יֵצֶר הָרָע הָיָה בָּעוֹלָם, וְדָחוּ אוֹתוֹ מֵהֶם, וְאָז נֶאֶחְזוּ בְּעֵץ הַחַיִּים וְעָלוּ לְמַעְלָה, וְלֹא יָרְדוּ לְמַטָּה. אָז הָיוּ מַכִּירִים וְהָיוּ רוֹאִים אַסְפַּקְלָרְיוֹת הָעֶלְיוֹנוֹת, וְעֵינֵיהֶם הוּאֲרוּ, וְשָׂמְחוּ לְהַכִּיר וְלִשְׁמֹעַ. וְאָז חָגַר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲגוֹרוֹת שֶׁל אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ שֶׁלֹּא יוּכַל לִשְׁלֹט עֲלֵיהֶם הַנָּחָשׁ הַזֶּה, וְלֹא יְטַמֵּא אוֹתָם כְּבָרִאשׁוֹנָה.</p>\n<p>כֵּיוָן שֶׁחָטְאוּ בָּעֵגֶל, הָעָבְרוּ מֵהֶם כָּל אוֹתָן הַדְּרָגוֹת וְהָאוֹרוֹת הָעֶלְיוֹנִים, וְהָעָבְרָה מֵהֶם חֲגוֹרַת כְּלֵי הַזַּיִן שֶׁהִתְעַטְּרוּ מֵהַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, וְהִמְשִׁיכוּ עֲלֵיהֶם הַנָּחָשׁ הָרָע כְּמִקֹּדֶם, וְגָרְמוּ מָוֶת לְכָל הָעוֹלָם. וְאַחַר כָּךְ מַה כָּתוּב? וַיַּרְא אַהֲרֹן וְכָל בְּנֵי יִשְׂרָאֵל אֶת מֹשֶׁה וְהִנֵּה קָרַן עוֹר פָּנָיו וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.</p>\n<p>בֹּא וּרְאֵה, מַה כָּתוּב בָּרִאשׁוֹנָה? (שמות יד) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה. וְכֻלָּם רָאוּ אֶת הַזְּהָרִים הָעֶלְיוֹנִים נְאוֹרִים בָּאַסְפַּקְלַרְיָה הַמְּאִירָה, שֶׁכָּתוּב (שם כ) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת. וְעַל הַיָּם הָיוּ רוֹאִים וְלֹא פוֹחֲדִים, שֶׁכָּתוּב זֶה אֵלִי וְאַנְוֵהוּ. אַחַר שֶׁחָטְאוּ, פְּנֵי הַסַּרְסוּר לֹא הָיוּ יְכוֹלִים לִרְאוֹת. מַה כָּתוּב? וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.</p>\n<p>וּבֹא רְאֵה, מַה כָּתוּב בָּהֶם? וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, שֶׁהָעָבְרוּ מֵהֶם אוֹתָם כְּלֵי זַיִן שֶׁהִתְחַבְּרוּ בָהֶם בְּהַר סִינַי, כְּדֵי שֶׁלֹּא יִשְׁלֹט אוֹתוֹ הַנָּחָשׁ הָרָע. כֵּיוָן שֶׁהָעָבְרוּ מֵהֶם, מַה כָּתוּב? וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה. אָמַר רַבִּי אֶלְעָזָר, מָה הַפָּסוּק הַזֶּה לָזֶה? אֶלָּא כֵּיוָן שֶׁיָּדַע מֹשֶׁה שֶׁהָעָבְרוּ מִיִּשְׂרָאֵל אוֹתָם כְּלֵי זַיִן עֶלְיוֹנִים, אָמַר, הֲרֵי וַדַּאי מִכָּאן וָהָלְאָה הַנָּחָשׁ הָרָע יָבא לָדוּר בֵּינֵיהֶם. וְאִם יַעֲמֹד הַמִּקְדָּשׁ כָּאן בֵּינֵיהֶם, יִטְמָא. מִיָּד - וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה הַרְחֵק מִן הַמַּחֲנֶה. מִשּׁוּם שֶׁמֹּשֶׁה רָאָה שֶׁהֲרֵי אָז יִשְׁלֹט הַנָּחָשׁ הָרָע מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן.</p>\n<p>וְקָרָא לוֹ אֹהֶל מוֹעֵד. וְכִי לֹא בָּרִאשׁוֹנָה אֹהֶל מוֹעֵד? אֶלָּא בָּרִאשׁוֹנָה אֹהֶל סְתָם, וְכָעֵת אֹהֶל מוֹעֵד. מַה זֶּה מוֹעֵד? רַבִּי אֶלְעָזָר אָמַר לְטוֹב. רַבִּי אַבָּא אָמַר לְרַע. רַבִּי אֶלְעָזָר אָמַר לְטוֹב - מַה מּוֹעֵד הוּא יוֹם שִׂמְחַת הַלְּבָנָה, שֶׁנּוֹסְפָה בּוֹ קְדֻשָּׁה, לֹא שׁוֹלֵט בָּהּ פְּגָם, אַף כָּאן קוֹרֵא לָהּ בַּשֵּׁם הַזֶּה, לְהַרְאוֹת שֶׁהֲרֵי הִתְרַחֵק מִבֵּינֵיהֶם וְלֹא נִפְגְּמָה, וְלָכֵן כָּתוּב וְקָרָא לוֹ אֹהֶל מוֹעֵד.</p>\n<p>וְרַבִּי אַבָּא אָמַר לְרַע - שֶׁהֲרֵי בָּרִאשׁוֹנָה הָיָה אֹהֶל סְתָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לג) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח, וְעַכְשָׁו אֹהֶל מוֹעֵד. בָּרִאשׁוֹנָה לָתֵת רְפוּאוֹת לָעוֹלָם שֶׁלֹּא יִשְׁלֹט בָּהֶם הַמָּוֶת - מִכָּאן וָהָלְאָה אֹהֶל מוֹעֵד, כְּמוֹ שֶׁנֶּאֱמַר (איובל) וּבֵית מוֹעֵד לְכָל חָי. כָּאן נִתָּן בּוֹ זְמַן וְחַיִּים קְצוּבִין לָעוֹלָם. בַּתְּחִלָּה לֹא נִפְגַּם - וְעַכְשָׁו נִפְגָּם. בָּרִאשׁוֹנָה חֲבֵרוֹת וְזִוּוּג לַלְּבָנָה עִם הַשֶּׁמֶשׁ שֶׁלֹּא יוּסְרוּ - עַכְשָׁו אֹהֶל מוֹעֵד, זִוּוּגָם מִזְּמַן לִזְמַן. וּמִשּׁוּם כָּךְ, וְקָרָא לוֹ אֹהֶל מוֹעֵד, מַה שֶּׁלֹּא הָיָה קֹדֶם.</p>"],[9522011818,"<p>רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב לַיְלָה אֶחָד וְעוֹסֵק בַּתּוֹרָה, וְהָיוּ יוֹשְׁבִים לְפָנָיו רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי יוֹסֵי. אָמַר רַבִּי יְהוּדָה, הֲרֵי כָּתוּב וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב, וְאָמַרְנוּ שֶׁגָּרְמוּ מָוֶת עֲלֵיהֶם מֵאוֹתוֹ זְמַן וָמַעְלָה וְשָׁלַט בָּהֶם אוֹתוֹ הַנָּחָשׁ הָרָע שֶׁהוּסַר מֵהֶם בָּרִאשׁוֹנָה. יִשְׂרָאֵל מֵילָא, אֲבָל יְהוֹשַׁע שֶׁלֹּא חָטָא, הַאִם הוּסַר מִמֶּנּוּ אוֹתוֹ כְּלֵי זַיִן עֶלְיוֹן שֶׁקִּבֵּל עִמָּהֶם בְּהַר סִינַי אוֹ לֹא?</p>\n<p>אִם תֹּאמַר שֶׁלֹּא הוּסַר מִמֶּנּוּ, אִם כָּךְ, אָז לָמָּה מֵת כִּשְׁאָר כָּל בְּנֵי הָאָדָם? וְאִם תֹּאמַר שֶׁהוּסַר מִמֶּנּוּ, לָמָּה? וַהֲרֵי לֹא חָטָא! שֶׁהֲרֵי הוּא הָיָה עִם מֹשֶׁה בְּשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל. וְאִם תֹּאמַר שֶׁלֹּא קִבֵּל אוֹתָהּ הָעֲטָרָה בְּהַר סִינַי כְּמוֹ שֶׁקִּבְּלוּ יִשְׂרָאֵל, לָמָּה?</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים יד) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ. פָּסוּק זֶה אָמְרוּ בוֹ הַחֲבֵרִים מַה שֶּׁאָמְרוּ. אֲבָל כִּי צַדִּיק ה' - צַדִּיק הוּא וּשְׁמוֹ צַדִּיק, וּמִשּׁוּם כָּךְ צְדָקוֹת אָהֵב. יָשָׁר וְהוּא יָשָׁר, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) צַדִּיק וְיָשָׁר. וְעַל זֶה יֶחֱזוּ פָנֵימוֹ, כָּל בְּנֵי הָעוֹלָם, וִיתַקְּנוּ דַרְכֵיהֶם לָלֶכֶת בְּדֶרֶךְ יָשָׁר כָּרָאוּי.</p>\n<p>וּבֹא רְאֵה, כְּשֶׁדָּן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא דָן אוֹתוֹ אֶלָּא לְפִי רֹב בְּנֵי הָאָדָם. וּבֹא רְאֵה, כְּשֶׁחָטָא אָדָם בָּעֵץ שֶׁאָכַל מִמֶּנּוּ, גָּרַם לְאוֹתוֹ עֵץ שֶׁשּׁוֹרֶה בּוֹ הַמָּוֶת לְכָל הָעוֹלָם, וְגָרַם פְּגָם לְהַפְרִיד אִשָּׁה מִבַּעְלָהּ, וְעָמַד הַחֵטְא שֶׁל הַפְּגָם הַזֶּה בַּלְּבָנָה עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי. כֵּיוָן שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי, הָעֳבַר אוֹתוֹ הַפְּגָם שֶׁל הַלְּבָנָה וְעָמַד לְהָאִיר תָּמִיד. כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל בָּעֵגֶל, שָׁבָה הַלְּבָנָה כְּמִקֹּדֶם לִפְגָמָהּ, וְשָׁלַט הַנָּחָשׁ הָרָע, וְאָחַז בָּהּ וּמָשַׁךְ אוֹתָהּ אֵלָיו וְנִפְגְּמָה.</p>\n<p>וּכְשֶׁיָּדַע מֹשֶׁה שֶׁחָטְאוּ יִשְׂרָאֵל וְהָעָבְרוּ מֵהֶם אוֹתָם כְּלֵי זַיִן הַקְּדוֹשִׁים, יָדַע וַדַּאי שֶׁהֲרֵי הַנָּחָשׁ אָחַז בַּלְּבָנָה לִמְשֹׁךְ אוֹתָהּ אֵלָיו וְנִפְגְּמָה. אָז הוֹצִיא אוֹתָהּ בַּחוּץ. וְכֵיוָן שֶׁעָמְדָה לְהִפָּגֵם, אַף עַל גַּב שֶׁיְּהוֹשֻׁעַ עוֹמֵד בַּעֲטֶרֶת כְּלֵי הַזַּיִן שֶׁלָּהּ, כֵּיוָן שֶׁהַפְּגָם שׁוֹרֶה בָּהּ וְחָזְרָה לִכְמוֹ שֶׁנִּפְגְּמָה בְּחֶטְאוֹ שֶׁל אָדָם, לֹא יָכוֹל אָדָם לְהִתְקַיֵּם, פְּרָט לְמֹשֶׁה שֶׁשָּׁלַט בָּהּ, וּמוֹתוֹ הָיָה בְּצַד אַחֵר. וְעַל זֶה לֹא הָיָה בָּהּ רְשׁוּת לְקַיֵּם אֶת יְהוֹשֻׁעַ תָּמִיד וְלֹא מִישֶׁהוּ אַחֵר. וְעַל כֵּן קוֹרֵא לָהּ אֹהֶל מוֹעֵד, שֶׁהֲרֵי שׁוֹרֶה בָּהּ זְמַן קָצוּב לְכָל הָעוֹלָם.</p>\n<p>וְלָכֵן סוֹד הַדָּבָר - יֵשׁ יָמִין לְמַעְלָה וְיֵשׁ יָמִין לְמַטָּה. יֵשׁ שְׂמֹאל לְמַעְלָה וְיֵשׁ שְׂמֹאל לְמַטָּה. יֵשׁ יָמִין לְמַעְלָה בִּקְדֻשָּׁה עֶלְיוֹנָה. וְיֵשׁ יָמִין לְמַטָּה שֶׁהוּא בַּצַּד הָאַחֵר. יֵשׁ שְׂמֹאל לְמַעְלָה בִּקְדֻשָּׁה עֶלְיוֹנָה, לְעוֹרֵר אַהֲבָה, לְהִתְקַשֵּׁר לַלְּבָנָה, בְּמָקוֹם קָדוֹשׁ לְמַעְלָה לְהָאִיר.</p>\n<p>וְיִשִׁ שְׂמֹאל לְמַטָּה שֶׁמַּפְרִיד אַהֲבָה שֶׁלְּמַעְלָה, וּמַפְרִיד אוֹתָהּ מִלְּהָאִיר בַּשֶּׁמֶשׁ וּלְהִתְקָרֵב עִמּוֹ, וְזֶהוּ הַצַּד שֶׁל הַנָּחָשׁ הָרָע. שֶׁכַּאֲשֶׁר הַשְּׂמֹאל הַזֶּה שֶׁלְּמַטָּה מִתְעוֹרֵר, אָז הוּא מוֹשֵׁךְ אֶת הַלְּבָנָה וּמַפְרִידָהּ מִלְמַעְלָה, וְאוֹרָהּ נֶחְשָׁךְ, וְנִדְבֶּקֶת בַּנָּחָשׁ, וְאָז שׁוֹאֶבֶת מָוֶת לְמַטָּה לַכֹּל, כִּי נִדְבֶּקֶת בַּנָּחָשׁ וּמִתְרַחֶקֶת מֵעֵץ הַחַיִּים, וְלָכֵן גּוֹרֶמֶת מָוֶת לְכָל הָעוֹלָם. וְזֶהוּ כַּאֲשֶׁר נִטְמָא הַמִּקְדָּשׁ עַד זְמַן קָצוּב כְּשֶׁמִּתְתַּקֶּנֶת הַלְּבָנָה וְשָׁבָה לְהָאִיר, וְזֶהוּ אֹהֶל מוֹעֵד.</p>\n<p>וְעַל זֶה יְהוֹשֻׁעַ לֹא מֵת, אֶלָּא בְּעֶטְיוֹ שֶׁל הַנָּחָשׁ הַזֶּה שֶׁקָּרַב וּפָגַם אֶת הַמִּשְׁכָּן כְּבָרִאשׁוֹנָה. וְזֶהוּ סוֹד הַכָּתוּב יְהוֹשֻׁעַ בִּן נוּן נַעַר. שֶׁאַף עַל גַּב שֶׁהוּא נַעַר לְמַטָּה לְקַבֵּל אוֹר, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. כְּמוֹ שֶׁזֶּה נִפְגָּם, כָּךְ גַּם זֶה נִפְגָּם, אַף עַל גַּב שֶׁמִּין קָדוֹשׁ הָיָה לוֹ, כֵּיוָן שֶׁנִּפְגְּמָה הַלְּבָנָה, כָּךְ וַדַּאי לֹא נִצּוֹל לְבַדּוֹ מִמֶּנּוּ מֵאוֹתוֹ גָּוֶן מַמָּשׁ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>אַשְׁרֵי הַצַּדִּיקִים שֶׁיּוֹדְעִים סוֹדוֹת הַתּוֹרָה וְנִדְבָּקִים בַּתּוֹרָה, וּמְקַיְּמִים הַפָּסוּק שֶׁכָּתוּב, (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה וְגוֹ'. וּבִשְׁבִילָהּ יִזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא, שֶׁכָּתוּב (דבריםל) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ וְגוֹ'.</p>"],[9522011819,"<p>וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (שמואל א טו) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי לְכוּ סֻרוּ רְדוּ וְגוֹ'. בֹּא וּרְאֵה מַה כָּתוּב בַּעֲמָלֵק, פָּקַדְתִּי אֵת אֲשֶׁר עָשָׂה עֲמָלֵק לְיִשְׂרָאֵל וְגוֹ'. וְהַקָּדוֹשׁ בָּרוּךְ הוּא, בְּכָל הַקְּרָבוֹת שֶׁעָשׂוּ שְׁאָר הָעַמִּים לְגַבֵּי יִשְׂרָאֵל, מָה הַטַּעַם לֹא הָיָה קָשֶׁה לְפָנָיו כְּמוֹ הַקְּרָב שֶׁעָשָׂה עֲמָלֵק אִתָּם? אֶלָּא וַדַּאי הַקְּרָב שֶׁל עֲמָלֵק הָיָה בְּכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה, שֶׁהֲרֵי בְּאוֹתוֹ זְמַן הִתְחַזֵּק הַנָּחָשׁ הָרָע לְמַעְלָה, וְהִתְחַזֵּק לְמַטָּה.</p>\n<p>מָה הַנָּחָשׁ הָרָע אוֹרֵב עַל פָּרָשַׁת דְּרָכִים, אַף כָּאן גַּם עֲמָלֵק נָחָשׁ רָע הָיָה לְיִשְׂרָאֵל, שֶׁאָרַב לָהֶם עַל פָּרָשַׁת דְּרָכִים, שֶׁכָּתוּב (שמואל א טו) אֲשֶׁר שָׂם לוֹ בַּדֶּרֶךְ בַּעֲלֹתוֹ מִמִּצְרָיִם. אוֹרֵב הָיָה לוֹ לְמַעְלָה לְטַמֵּא אֶת הַמִּקְדָּשׁ, וְאוֹרֵב הָיָה לְמַטָּה לְטַמֵּא אֶת יִשְׂרָאֵל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (דברים כה) אֲשֶׁר קָרְךְ בַּדֶּרֶךְ. כָּתוּב כָּאן אֲשֶׁר קָרְךְ, וְכָתוּב שָׁם (שםכג) כִּי יִהְיֶה בְךְ אִישׁ אֲשֶׁר לֹא טָהוֹר מִקְּרֵה לָיְלָה.</p>\n<p>וְעַל זֶה כָּתוּב בְּבִלְעָם, (במדבר כג) וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וַיִּקָּר - לְשׁוֹן טֻמְאָה נָקַט. וְאִם תֹּאמַר, הֲרֵי כָּתוּב אֱלֹהִים, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין לוֹ אוֹתוֹ מָקוֹם שֶׁל טֻמְאָה לְהִטָּמֵא בּוֹ בְּאוֹתָהּ דַּרְגָּה שֶׁהוּא נִדְבַּק לְהִטָּמֵא בָּהּ. מֶה עָשָׂה בִּלְעָם? הוּא חָשַׁב בְּאוֹתָם קָרְבָּנוֹת לַעֲלוֹת לְמַעְלָה. מִיָּד הִזְמִין לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ מָקוֹם. אָמַר לוֹ, הִנֵּה טֻמְאָה אֵלֶיךְ כְּמוֹ שֶׁרָאוּי לְךְ. וְעַל זֶה וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם.</p>\n<p>כְּמוֹ כֵן אֲשֶׁר קָרְךְ בַּדֶּרֶךְ וְגוֹ', הִזְמִין לְךְ אוֹתוֹ הַנָּחָשׁ הָרָע לְמַעְלָה לְטַמֵּא אוֹתְךְ בְּכָל הַצְּדָדִים. וְאִלְמָלֵא שֶׁהִתְחַזֵּק מֹשֶׁה לְמַעְלָה וִיהוֹשֻׁעַ לְמַטָּה, לֹא יָכְלוּ לוֹ יִשְׂרָאֵל. וּמִשּׁוּם כָּךְ שָׁמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָהּ שִׂנְאָה לְדוֹרֵי דוֹרוֹת. מָה הַטַּעַם? מִשּׁוּם שֶׁחָשַׁב לַעֲקֹר אוֹת הַבְּרִית מִמְּקוֹמָהּ, וּמִשּׁוּם כָּךְ פָּקַדְתִּי, בִּפְקִידָה, שֶׁהֲרֵי שָׁם נִרְמָז סוֹד הָאוֹת הַבְּרִית הַקְּדוֹשָׁה.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי. מִי זֶה הַקֵּינִי? זֶה יִתְרוֹ. וְכִי מִי נָתַן כָּאן אֶת בְּנֵי יִתְרוֹ לִהְיוֹת דִּיּוּרָם בַּעֲמָלֵק, וַהֲרֵי הָיוּ שְׁרוּיִים בִּירִיחוֹ? אֶלָּא הֲרֵי כָּתוּב (שופטים א) וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים אֶת בְּנֵי יְהוּדָה מִדְבַּר יְהוּדָה וְגוֹ'. וּכְשֶׁעָלוּ מִשָּׁם, שְׁרוּיִים הָיוּ בִּתְחוּמוֹ שֶׁל עֲמָלֵק עַד לְאוֹתוֹ זְמַן שֶׁבָּא שָׁאוּל הַמֶּלֶךְ, שֶׁכָּתוּב וַיָּסַר קֵינִי מִתּוֹךְ עֲמָלֵק.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי בִּזְמַן שֶׁנִּמְצָאִים רְשָׁעִים, (נענשו) אוֹתָם חֲסִידִים וְצַדִּיקִים שֶׁנִּמְצָאִים בֵּינֵיהֶם נִתְפָּסִים בַּחֲטָאֵיהֶם, וַהֲרֵי פֵּרְשׁוּהָ. כְּמוֹ זֶה, אִלְמָלֵא אוֹתָהּ עִרְבּוּבְיָה שֶׁהִתְחַבְּרוּ בָהֶם בְּיִשְׂרָאֵל, לֹא נֶעֶנְשׁוּ יִשְׂרָאֵל עַל מַעֲשֵׂה הָעֵגֶל.</p>\n<p>וּבֹא רְאֵה מַה כָּתוּב בָּרִאשׁוֹנָה, (שמות כה) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְהַכְלִיל אֶת כֻּלָּם, מִשּׁוּם שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת אֶת מַעֲשֵׂה הַמִּשְׁכָּן מִכָּל הַצְּדָדִים, בְּמֹחַ וּקְלִפָּה. וּמִשּׁוּם שֶׁהָיוּ אוֹתָם עֵרֶב רַב עִמָּהֶם, נֶאֱמַר מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ, לְהַכְלִילָם בֵּין יִשְׂרָאֵל, שֶׁהֵם מֹחַ, וְכֻלָּם הִצְטַוּוּ.</p>\n<p>אַחַר כָּךְ סָטָה כָּל מִין לְמִינוֹ, וּבָאוּ אוֹתָם עֵרֶב רַב וְעָשׂוּ אֶת הָעֵגֶל, וְסָטוּ אַחֲרֵיהֶם אוֹתָם שֶׁמֵּתוּ וְגָרְמוּ לְיִשְׂרָאֵל מָוֶת וְהֶרֶג. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וָהָלְאָה מַעֲשֵׂה הַמִּשְׁכָּן לֹא יִהְיֶה אֶלָּא רַק מִצִּדָּם שֶׁל יִשְׂרָאֵל לְבַדָּם. מִיָּד - וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת יִשְׂרָאֵל וְגוֹ'. וְכָתוּב אַחֲרָיו, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. מֵאִתְּכֶם וַדַּאי, וְלֹא כָּרִאשׁוֹנָה שֶׁכָּתוּב מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ. וַיַּקְהֵל מֹשֶׁה וְגוֹ', מֵאֵיזֶה מָקוֹם הִקְהִיל אוֹתָם? אֶלָּא מִשּׁוּם שֶׁהָיוּ אוֹתָם עֵרֶב רַב בֵּינֵיהֶם, הִצְטָרֵךְ מֹשֶׁה לְכַנְּסָם וּלְיַחֲדָם מִבֵּינֵיהֶם.</p>\n<p>וַיַּקְהֵל מֹשֶׁה. רַבִּי אַבָּא פָּתַח, (דברים לא) הַקְהֵל אֶת הָעָם הָאֲנָשִׁים וְהַנָּשִׁים וְהַטַּף. מַה לְּהַלָּן כְּלָל שֶׁל כָּל יִשְׂרָאֵל, אַף כָּאן כְּלָל שֶׁל כָּל יִשְׂרָאֵל. וּמִי הֵם? שִׁשִּׁים רִבּוֹא.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח אֶת הַפָּסוּק בְּיִשְׂרָאֵל, כְּשֶׁיָּרַד מֹשֶׁה מֵהַר סִינַי, שֶׁכָּתוּב (שמות לב) וַיִּשְׁמַע יְהוֹשֻׁעַ אֶת קוֹל הָעָם בְּרֵעֹה וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנֶה. וַיִּשְׁמַע יְהוֹשֻׁעַ, וְכִי יְהוֹשֻׁעַ שָׁמַע וּמֹשֶׁה לֹא שָׁמַע?! אֶלָּא וַדַּאי, עַד עַכְשָׁו יְהוֹשֻׁעַ לֹא הָיָה יוֹדֵעַ, וּמֹשֶׁה הָיָה יוֹדֵעַ. אִם כָּךְ, מַה זֶּה בְּרֵעֹה? אֶלָּא בְּרֵעֹה כָּתוּב בְּה', שֶׁאוֹתוֹ קוֹל הָיָה בַּצַּד הָאַחֵר. וִיהוֹשֻׁעַ, שֶׁהָיָה פְּנֵי הַלְּבָנָה, הִתְבּוֹנֵן בְּאוֹתוֹ קוֹל שֶׁהָיָה שֶׁל צַד הָרָעָה, מִיָּד - וַיֹּאמֶר אֶל מֹשֶׁה קוֹל מִלְחָמָה בַּמַּחֲנֶה.</p>\n<p>בְּאוֹתָהּ שָׁעָה נִשְׁבְּרוּ שְׁנֵי לוּחוֹת הָאֶבֶן שֶׁהָיוּ בָּרִאשׁוֹנָה. וַהֲרֵי בֵּאַרְנוּ, שֶׁהֵם כָּבְדוּ עַל יָדוֹ, וְנָפְלוּ וְנִשְׁבְּרוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁפָּרְחוּ הָאוֹתִיּוֹת מִתּוֹךְ לוּחוֹת הָאֲבָנִים.</p>\n<p>בֹּא וּרְאֵה, בְּאַרְבַּע תְּקוּפוֹת בַּשָּׁנָה מִתְעוֹרֵר קוֹל בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, בְּאוֹתוֹ קוֹל שֶׁהִתְעוֹרְרוּת הַצַּד הָאַחֵר מִתְעוֹרֵר בּוֹ, וְאוֹתָהּ הִתְעוֹרְרוּת הַצַּד הָאַחֵר נִכְנֶסֶת בֵּין קוֹל לְקוֹל, וְנֶחְשָׁךְ הָאוֹר בַּקּוֹל שֶׁלְּמַטָּה. מִשּׁוּם שֶׁלֹּא הִגִּיעַ הָאוֹר שֶׁל הַקּוֹל שֶׁלְּמַעְלָה לַקּוֹל שֶׁלְּמַטָּה, אָז מַקְדִּימָה אוֹתָהּ הִתְעוֹרְרוּת, וְנִכְנָס בֵּין זֶה לָזֶה הַנָּחָשׁ שֶׁמְּפַתֶּה אֶת הָאִשָּׁה וְנוֹטֵל אוֹר, וְאוֹתוֹ קוֹל הוּא קוֹל מִלְחָמָה, קוֹל רָעָה, וְזֶהוּ בְּרֵעֹה.</p>\n<p>וְעַל זֶה שָׁמַע יְהוֹשֻׁעַ וְלֹא מֹשֶׁה, מִשּׁוּם שֶׁנָּטְלָה אוֹתָהּ רָעָה אֶת אוֹר הַלְּבָנָה שֶׁאָחַז בָּהּ יְהוֹשֻׁעַ, וּמֹשֶׁה שֶׁהָיָה אָחוּז בַּשֶּׁמֶשׁ לֹא שָׁמַע, וְכָל הָאוֹר שֶׁל יִשְׂרָאֵל כֻּלָּם נֶחְשַׁךְ מִשּׁוּם אוֹתָהּ רָעָה שֶׁנִּדְבְּקָה בָּהֶם. כֵּיוָן שֶׁמָּחַל הַקָּדוֹשׁ בָּרוּךְ הוּא עַל חֲטָאֵיהֶם, אָז וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וַיֹּאמֶר אֲלֵהֶם אֵלֶּה הַדְּבָרִים וְגוֹ', שֶׁהֲרֵי אוֹתוֹ עֵרֶב רַב הָעֳבַר מֵהֶם.</p>"],[9522011820,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וּמִתְעַסְּקִים בַּתּוֹרָה טֶרֶם שֶׁנֶּחֱלַק הַלַּיְלָה. בֵּין כָּךְ קָרָא הַגֶּבֶר. בֵּרְכוּ בְרָכָה. (אמר לו רבי אלעזר, כעת הוא הזמן שהקדוש ברוך הוא נכנס בגן עדן להשתעשע עם הצדיקים. אמר לו רבי יוסי, למה משתעשע הקדוש ברוך הוא) בָּכָה רַבִּי אֶלְעָזָר וְאָמַר, בּא וּרְאֵה, עַד כָּאן זִעְזַע הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים וְהִכָּה בָּהֶם, וּבָכָה עַל חָרְבַּן בֵּית הַמִּקְדָּשׁ, וְהוֹרִיד שְׁתֵּי דְמָעוֹת לְתוֹךְ הַיָּם הַגָּדוֹל וְנִזְכַּר בְּבָנָיו מִתּוֹךְ בְּכִיָּה.</p>\n<p>מִשּׁוּם שֶׁהַלַּיְלָה נֶחֱלָק לִשְׁלֹשָׁה צְדָדִים בִּשְׁתֵּים עֶשְׂרֵה שָׁעוֹת שֶׁהָיוּ רְשׁוּמִים בּוֹ, וְאִם נוֹסָפוֹת שְׁעוֹת הַלַּיְלָה, אוֹתָן שָׁעוֹת שֶׁנּוֹסְפוּ הֵן שֶׁל הַיּוֹם, וְלֹא נֶחֱשָׁבוֹת מֵהַלַּיְלָה, פְּרָט לִשְׁתֵּים עֶשְׂרֵה שֶׁהֵן שֶׁלּוֹ. וְאוֹתָן שְׁתֵּים עֶשְׂרֵה נֶחֱלָקוֹת לִשְׁלֹשָׁה צְדָדִים, וּשְׁלֹשָׁה מַחֲנוֹת שֶׁל מַלְאָכִים קְדוֹשִׁים נֶחְלְקוּ (התמגו) בְּאוֹתָם שְׁלֹשָׁה צְדָדִים.</p>\n<p>מַחֲנֶה רִאשׁוֹן מְמֻנֶּה בְּאַרְבַּע שָׁעוֹת רִאשׁוֹנוֹת שֶׁל רֵאשִׁית הַלַּיְלָה לְשַׁבֵּחַ אֶת אֲדוֹנָם. וּמַה הֵם אוֹמְרִים? (תהלים כד) לַה' הָאָרֶץ וּמְלֹאָהּ וְגוֹ', כִּי הוּא עַל יַמִּים יְסָדָהּ וְגוֹ', מִי יַעֲלֶה בְהַר ה' וְגוֹ', נְקִי כַפַּיִם וּבַר לֵבָב וְגוֹ'. מָה הַטַּעַם שֶׁל זֶה? מִשּׁוּם שֶׁכַּאֲשֶׁר הַלַּיְלָה פּוֹרֵשׂ כְּנָפָיו עַל הָעוֹלָם, אָז כָּל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת וְיוֹצֵאת נִשְׁמָתָם לַעֲלוֹת לְמַעְלָה, וְאוֹתָם מַלְאָכִים עוֹמְדִים וְאוֹמְרִים, מִי יַעֲלֶה בְהַר ה'. הַר ה' - זֶה הַר הַבַּיִת. מְקוֹם קָדְשׁוֹ - זֶה עֶזְרַת יִשְׂרָאֵל. כְּמוֹ שֶׁלְּמַעְלָה, כָּךְ גַּם לְמַטָּה.</p>\n<p>מִשּׁוּם שֶׁבְּכָל רָקִיעַ וְרָקִיעַ כַּמָּה מְמֻנִּים וְכַמָּה שָׂרִים עוֹמְדִים שָׁם, וּכְשֶׁהַנְּשָׁמוֹת יוֹצְאוֹת, רוֹצוֹת לַעֲלוֹת לְמַעְלָה, וְאִם אֵינָן זוֹכוֹת דּוֹחִים אוֹתָן הַחוּצָה, וְהוֹלְכוֹת וּמְשׁוֹטְטוֹת בָּעוֹלָם, וְלוֹקְחִים אוֹתָן כַּמָּה קְבוּצוֹת שֶׁל רוּחוֹת וּמוֹדִיעִים לָהֶם דְּבָרִים כּוֹזְבִים, וְלִפְעָמִים דִּבְרֵי אֱמֶת מִמַּה שֶּׁעָתִיד לָבא בַּזְּמַן הַקָּרוֹב, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וְאוֹתָן נִשְׁמוֹת הַצַּדִּיקִים הוֹלְכוֹת וּמְשׁוֹטְטוֹת לְמַעְלָה, וּפוֹתְחִים לָהֶם פְּתָחִים, וּמַעֲלִים אוֹתָן לְתוֹךְ אוֹתוֹ מָקוֹם שֶׁנִּקְרָא הַר ה', כְּמוֹ הַסּוֹד שֶׁל הַר הַבַּיִת לְמַטָּה, וּמִשָּׁם נִכְנָסִים לְתוֹךְ אוֹתוֹ מָקוֹם שֶׁנִּקְרָא מְקוֹם קָדְשׁוֹ, שֶׁשָּׁם נִרְאוֹת כָּל הַנְּשָׁמוֹת לִפְנֵי אֲדוֹנָם. כְּמוֹ כֵן אוֹתוֹ מָקוֹם שֶׁנִּרְאוּ יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הַמָּקוֹם שֶׁנִּקְרָא עֶזְרַת יִשְׂרָאֵל. בְּשָׁעָה שֶׁהַנְּשָׁמוֹת עוֹמְדוֹת שָׁם, אֲזַי שִׂמְחַת רִבּוֹנָם הִיא, לְתַקֵּן בָּהֶם הַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים, וְשָׁם רוֹשְׁמִים אֶת כָּל מַעֲשֵׂיהֶם וּזְכֻיּוֹתֵיהֶם.</p>\n<p>מַחֲנֶה שֵׁנִי מְמֻנֶּה בְּאַרְבַּע שָׁעוֹת אֲחֵרוֹת, וְאֵינָם אוֹמְרִים שִׁירָה, פְּרָט לִשְׁעָתַיִם, עַד שֶׁנֶּחֱלָק הַלַּיְלָה וְנִכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן.</p>\n<p>וְאֵלֶּה הֵם אֲבֵלֵי צִיּוֹן וְאוֹתָם שֶׁבּוֹכִים עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ. וּבִתְחִלַּת אַרְבַּע הַשָּׁעוֹת הָאֶמְצָעִיּוֹת פּוֹתְחִים וְאוֹמְרִים, (תהלים קלז) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ וְגוֹ', וְאֵלֶּה הֵם שֶׁבּוֹכִים עַל נַהֲרוֹת בָּבֶל עִם יִשְׂרָאֵל, מִמַּשְׁמָע שֶׁכָּתוּב גַּם בָּכִינוּ. וּמִנַּיִן לָנוּ שֶׁבּוֹכִים שָׁם? שֶׁכָּתוּב הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה. מַה זֶּה חֻצָה? זוֹ בָּבֶל, מִשּׁוּם שֶׁכֻּלָּם לִוּוּ אֶת הַשְּׁכִינָה עַד בָּבֶל, וְשָׁם הֵם בָּכוּ עִם יִשְׂרָאֵל. וְעַל זֶה פּוֹתְחִים בָּזֶה, וּמְסַיְּמִים: זְכֹר ה' לִבְנֵי אֱדוֹם וְגוֹ'.</p>\n<p>וְאָז מִתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲלוֹתָיו וּמַכֶּה בָּרְקִיעִים, כְּמוֹ שֶׁאָמַרְנוּ, וּמִזְדַּעְזְעִים שְׁנֵים עָשָׂר אַלְפֵי עוֹלָמוֹת וְגוֹעִים וּבוֹכִים, שֶׁכָּתוּב (ירמיה כה) ה' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וְנִזְכָּר בְּיִשְׂרָאֵל, וּמוֹרִיד שְׁתֵּי דְמָעוֹת לְתוֹךְ הַיָּם הַגָּדוֹל, וְאָז מִתְעוֹרֶרֶת שַׁלְהֶבֶת אַחַת שֶׁבְּצַד צָפוֹן, וּמַכֶּה רוּחַ אֶחָד שֶׁבְּצַד צָפוֹן בְּאוֹתָהּ הַשַּׁלְהֶבֶת, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם. וּבְאוֹתָהּ שָׁעָה נֶחֱלָק הַלַּיְלָה, וְהַשַּׁלְהֶבֶת הוֹלֶכֶת וּמַכָּה בְּכַנְפֵי הַתַּרְנְגוֹל וְקוֹרֵא, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן.</p>\n<p>וְלַקָּדוֹשׁ בָּרוּךָ הוּא אֵין מְנוּחָה עַד שֶׁנִּכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם נִשְׁמוֹת הַצַּדִּיקִים. וְהַסִּימָן - כִּי נִמְכַּרְנוּ אֲנִי וְעַמִּי וְגוֹ'. (אסתר ז) וַיֹּאמֶר הַמֶּלֶךְ מִי הוּא זֶה וְגוֹ', וְהַמֶּלֶךְ קָם בַּחֲמָתוֹ מִמִּשְׁתֵּה הַיַּיִן אֶל גִּנַּת הַבִּיתָן וְגוֹ'.</p>\n<p>בְּשָׁעָה שֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן, אָז כָּל אוֹתָם עֲצֵי הַגָּן וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים פּוֹתְחִים וְאוֹמְרִים, (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְגוֹ'. מִי זֶה מֶלֶךְ הַכָּבוֹד וְגוֹ'. שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם גְוֹ'. וּבְשָׁעָה שֶׁנִּשְׁמוֹת הַצַּדִּיקִים שֶׁבָּאָרֶץ חוֹזְרוֹת לְגוּפָן, אָז מַחֲזִיקִים בָּהֶם כָּל אוֹתָם מַלְאָכִים, וְאוֹמְרִים (שם קלד) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה'. וְלָמַדְנוּ שֶׁזֶּה הַמַּחֲנֶה הַשְּׁלִישִׁי שֶׁאוֹמֵר אֶת זֶה בְּאַרְבַּע הַשָּׁעוֹת הָאַחֲרוֹנוֹת.</p>\n<p>וְאוֹמְרִים שִׁירָה עַד שֶׁעוֹלֶה אוֹר הַבֹּקֶר, וְאָז מְשַׁבְּחִים אֶת אֲדוֹנָם כָּל אוֹתָם כּוֹכָבִים וּמַזָּלוֹת, וְכָל אוֹתָם הַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁשִּׁלְטוֹנָם בַּיּוֹם, כֻּלָּם מְשַׁבְּחִים אֶת אֲדוֹנָם וְאוֹמְרִים שִׁירָה. זֶהוּ שֶׁכָּתוּב (איובלח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>\n<p>בְּשָׁעָה שֶׁיּוֹצֵאת הַשֶּׁמֶשׁ בַּיּוֹם, יִשְׂרָאֵל נוֹטְלִים שִׁירָה לְמַטָּה, וְהַשֶּׁמֶשׁ לְמַעְלָה, שֶׁכָּתוּב יִירָאוּךְ עִם שָׁמֶשׁ. בְּשָׁעָה שֶׁנּוֹסֵעַ הַשֶּׁמֶשׁ בְּגַלְגַּלָּיו, פּוֹתֵחַ בְּקוֹל נְעִימָה וְאוֹמֵר שִׁירָה. וְאֵיזוֹ שִׁירָה אוֹמְרִים? (תהליםקד) הוֹדוּ לַה' קִרְאוּ בִשְׁמוֹ וְגוֹ'. (שם) שִׁירוּ לוֹ זַמְּרוּ לוֹ וְגוֹ'. וְיִשְׂרָאֵל מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיּוֹם עִם הַשֶּׁמֶשׁ. זֶהוּ שֶׁכָּתוּב (שםעב) יִירָאוּךְ עִם שָׁמֶשׁ. וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ אֶת הַפָּסוּק הַזֶּה, אָמַר רַבִּי אֶלְעָזָר, אִלְמָלֵא שֶׁבְּנֵי הָעוֹלָם הֵם אֲטוּמֵי לֵב וּסְתוּמֵי עֵינַיִם, לֹא יְכוֹלִים לַעֲמֹד מִקּוֹל הַנְּעִימָה שֶׁל גַּלְגַּל הַשֶּׁמֶשׁ כְּשֶׁנּוֹסֵעַ (ויוצא) וּמְשַׁבֵּחַ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9522011821,"<p>בֵּינְתַיִם שֶׁהִתְעַסְּקוּ בַתּוֹרָה, הֵאִיר הַיּוֹם. קָמוּ וְהָלְכוּ לִפְנֵי רַבִּי שִׁמְעוֹן. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, אַתָּה וְהַחֲבֵרִים, הַסְתִּירוּ עַצְמְכֶם שְׁלֹשֶׁת הַיָּמִים הַלָּלוּ שֶׁלֹּא תֵצְאוּ הַחוּצָה, כִּי מַלְאַךְ הַמָּוֶת נִמְצָא בָּעִיר, וְיֵשׁ לוֹ רְשׁוּת לְהַשְׁחִית, וְכֵיוָן שֶׁנִּתְּנָה לוֹ רְשׁוּת לְהַשְׁחִית, יָכוֹל לְהַשְׁחִית אֶת כָּל מִי שֶׁנִּרְאֶה לְפָנָיו.</p>\n<p>וְעוֹד, שֶׁאָדָם שֶׁנִּרְאֶה לְפָנָיו, הוּא עוֹלֶה וּמַסְטִין עָלָיו וּמַזְכִּיר חֲטָאָיו, וּמְבַקֵּשׁ דִּין מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא זָז מִשָּׁם עַד שֶׁנִּדּוֹן אוֹתוֹ הָאָדָם וְנִתֶּנֶת לוֹ רְשׁוּת וְהוֹרֵג אוֹתוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הָאֱלֹהִים, רֹב הָעוֹלָם לֹא מֵתִים טֶרֶם מַגִּיעַ זְמַנָּם, רַק כְּשֶׁלֹּא יָדְעוּ לִשְׁמֹר עַצְמָם, שֶׁהֲרֵי בְּשָׁעָה שֶׁמּוֹצִיאִים אֶת הַמֵּת מִבֵּיתוֹ לְבֵית הַקְּבָרוֹת, מַלְאַךְ הַמָּוֶת נמְצָא בֵּין הַנָּשִׁים. וְלָמָּה בֵּין הַנָּשִׁים? שֶׁכָּךְ הִיא דַּרְכּוֹ מִיּוֹם שֶׁפִּתָּה אֶת חַוָּה, וּבִגְלָלָהּ גָּרַם מָוֶת לְכָל הָעוֹלָם, וְעַל זֶה (כאשר) הוֹרֵג אָדָם, וְהָאֲנָשִׁים נִמְצָאִים עִם הַמֵּת, וְנִכְנָס בֵּין הַנָּשִׁים בַּדֶּרֶךְ.</p>\n<p>וְיִשִׁ לוֹ רְשׁוּת לַהֲרֹג בְּנֵי אָדָם, וּמִסְתַּכֵּל בִּפְנֵיהֶם בַּדֶּרֶךְ שֶׁנִּרְאִים לְפָנָיו, מִשָּׁעָה שֶׁמּוֹצִיאִים אוֹתוֹ מִבֵּיתוֹ לְבֵית הַקְּבָרוֹת עַד שֶׁחוֹזְרִים לְבֵיתָם, וּבִגְלָלָם גּוֹרֵם מָוֶת לְכַמָּה גְבָרִים בָּעוֹלָם טֶרֶם שֶׁמַּגִּיעַ זְמַנָּם. וְעַל זֶה כָּתוּב, (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. מִשּׁוּם שֶׁעוֹלֶה וּמַסְטִין וּמַזְכִּיר חֲטָאֵי הָאָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִדּוֹן עַל אוֹתָם חֲטָאִים וּמִסְתַּלֵּק טֶרֶם הִגִּיעַ זְמַנּוֹ.</p>\n<p>וּמַה תַּקָּנָתוֹ? בְּשָׁעָה שֶׁנּוֹטְלִים אֶת הַמֵּת לְבֵית הַקְּבָרוֹת, יַחֲזִיר אָדָם פָּנָיו וְיַעֲזֹב אֶת הַנָּשִׁים אַחַר כְּתֵפָיו. וְאִם הֵן מַקְדִּימוֹת, יֵלֵךְ לְאָחוֹר, כְּדֵי שֶׁלֹּא יִתְרָאֶה עִמָּהֶן פָּנִים בְּפָנִים. וְאַחַר שֶׁחוֹזְרִים מִבֵּית הַקְּבָרוֹת, לֹא יַחֲזר בְּאוֹתָהּ דֶּרֶךְ שֶׁעוֹמְדוֹת הַנָּשִׁים וְלֹא יִסְתַּכֵּל בָּהֶן כְּלָל, אֶלָּא יִסְטֶה לְדֶרֶךְ אַחֶרֶת. וּמִשּׁוּם שֶׁבְּנֵי אָדָם לֹא יוֹדְעִים וְלֹא מִתְבּוֹנְנִים בָּזֶה, רֹב הָעוֹלָם נִדּוֹנִים בְּדִין וּמִסְתַּלְּקִים טֶרֶם הִגִּיעַ זְמַנָּם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אִם כָּךְ, טוֹב לוֹ לָאָדָם שֶׁלֹּא יְלַוֶּה אֶת הַמֵּת. אָמַר לוֹ, לֹא, שֶׁהֲרֵי אָדָם שֶׁנִּשְׁמָר כְּמוֹ זֶה, רָאוּי לַאֲרִיכוּת יָמִים, וְכָל שֶׁכֵּן לָעוֹלָם הַבָּא.</p>\n<p>בֹּא וּרְאֵה, לֹא לְחִנָּם תִּקְּנוּ הָרִאשׁוֹנִים שׁוֹפָר לִמְשֹׁךְ מֵת מֵהַבַּיִת לְבֵית הַקְּבָרוֹת. וְאִם תֹּאמַר שֶׁעַל הַמֵּת וּכְבוֹדוֹ לְבַד זֶה - לֹא! אֶלָּא כְּדֵי לְהָגֵן עַל הַחַיִּים שֶׁלֹּא יִשְׁלֹט עֲלֵיהֶם מַלְאַךְ הַמָּוֶת לְהַסְטִין לְמַעְלָה וְיִשָּׁמְרוּ מִמֶּנּוּ.</p>\n<p>פָּתַח וְאָמַר, (במדבר י) וְכִי תָבאוּ מִלְחָמָה בְּאַרְצְכֶם עַל הַצַּר הַצֹּרֵר אֶתְכֶם וְגוֹ'. וְדִיַּקְנוּ עַל הַצַּר, זֶה מַלְאַךְ הַמָּוֶת, הַצּוֹרֵר אֶתְכֶם תָּמִיד וְהוֹרֵג בְּנֵי אָדָם, (ומציק לחיים) וְרוֹצֶה לַהֲרֹג אֲחֵרִים. מַהִי תַקָּנָתוֹ? וַהֲרֵעֹתֶם. אִם בְּרֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין לְמַעְלָה, מַלְאַךְ הַמָּוֶת הַזֶּה יוֹרֵד לְמַטָּה כְּדֵי לְהַשְׁגִּיחַ עַל מַעֲשֵׂי בְּנֵי הָאָדָם וְלַעֲלוֹת לְמַעְלָה לְהַסְטִין עֲלֵיהֶם. וְיִשְׂרָאֵל שֶׁיּוֹדְעִים שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת יוֹרֵד מַטָּה וְעוֹלֶה לְמַעְלָה כְּדֵי לִהְיוֹת קָטֵגוֹר עֲלֵיהֶם, מְקַדְּמִים בַּשּׁוֹפָר לְיַבֵּב עָלָיו שֶׁלֹּא יוּכַל לָהֶם, וּלְהָגֵן עֲלֵיהֶם.</p>\n<p>וְכָל שֶׁכֵּן בְּשָׁעָה שֶׁעוֹשֶׂה דִין וְהוֹרֵג בְּנֵי אָדָם וְנִמְצָא לְמַטָּה, וְכָל שֶׁכֵּן בְּשָׁעָה שֶׁהוֹלְכִים לְבֵית הַקְּבָרוֹת וְחוֹזְרִים מִבֵּית הַקְּבָרוֹת, שֶׁהֲרֵי בְּשָׁעָה שֶׁנָּשִׁים נוֹטְלוֹת רַגְלֵיהֶן עִם הַמֵּת, הוּא יוֹרֵד וְנִמְצָא לִפְנֵיהֶם, שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת. יוֹרְדוֹת לְאָן? לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא מָוֶת. וְעַל זֶה חַוָּה גָּרְמָה מָוֶת לְכָל הָעוֹלָם, הָרַחֲמָן יַצִּילֵנוּ.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (שם ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת וְגוֹ'. וַהֲרֵי בֵּאַרְנוּ. אֲבָל כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת - זֶה מַלְאַךְ הַמָּוֶת, וְכָךְ הוּא, וְכָךְ נִקְרָא. אָכְלָה וּמָחֲתָה פִיהָ - שׂוֹרֶפֶת אֶת הָעוֹלָם בְּשַׁלְהֲבוֹתֶיהָ וְהוֹרֶגֶת בְּנֵי אָדָם טֶרֶם שֶׁהִגִּיעַ זְמַנָּם. וְאָמְרָה לֹא פָעַלְתִּי אָוֶל, שֶׁהֲרֵי דִּין צָרִיךְ עֲלֵיהֶם, וְנִמְצְאוּ בַחֲטָאִים, וּבְדִין אֱמֶת הֵם מֵתוּ.</p>\n<p>בְּשָׁעָה שֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל וּמֵתוּ כָּל אוֹתָם הֲמוֹנִים, הָיָה מַלְאַךְ הַמָּוֶת נִמְצָא בֵּין הַנָּשִׁים בְּתוֹךְ מַחֲנֵה יִשְׂרָאֵל. כֵּיוָן שֶׁהִסְתַּכֵּל מֹשֶׁה שֶׁהֲרֵי מַלְאַךְ הַמָּוֶת נִמְצָא בֵּין הַנָּשִׁים וּמַחֲנֵה יִשְׂרָאֵל בֵּינֵיהֶם, מִיָּד כִּנֵּס אֶת כָּל הַגְּבָרִים לְבַדָּם. זֶהוּ שֶׁכָּתוּב וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל. אֵלּוּ הַגְּבָרִים, שֶׁכִּנֵּס אוֹתָם וְהִפְרִידָם לְבַדָּם.</p>\n<p>וּמַלְאַךָ הַמָּוֶת לֹא הָיָה נִפְרָד מִתּוֹךְ הַנָּשִׁים עַד שֶׁהוּקַם הַמִּשְׁכָּן, שֶׁכָּתוּב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. וַאֲפִלּוּ בְּשָׁעָה שֶׁהַנָּשִׁים הָיוּ נוֹתְנוֹת נְדָבָה לַמִּשְׁכָּן, לֹא הָיָה סָר מִבֵּינֵיהֶם, עַד שֶׁרָאָה מֹשֶׁה וְנָתַן לַגְּבָרִים עֵצָה שֶׁלֹּא יָבאוּ בְּחִבּוּר אֶחָד עִמָּהֶם וְלֹא יִתְרָאוּ פָּנִים בְּפָנִים, אֶלָּא אַחַר כִּתְפֵיהֶם. וְזֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים. (ויבאו האנשים על הנשים לא כתוב, אלא ויבאו על) וַיָּבִיאוּ לֹא כָתוּב, אֶלָּא וַיָּבֹאוּ. לֹא הָיוּ הוֹלְכִים בְּדֶרֶךְ אַחַת, אֶלָּא אַחַר כִּתְפֵיהֶן, מִשּׁוּם שֶׁמַּלְאַךְ הַמָּוֶת לֹא נִפְרַד מִבֵּינֵיהֶן עַד שֶׁהַמִּשְׁכָּן הוּקַם.</p>\n<p>בֹּא וּרְאֵה, אֵינוֹ נִמְצָא בֵּין הַנָּשִׁים פָּחוֹת מִשֶּׁבַע נָשִׁים, וְלֹא פָּחוֹת מֵעֶשֶׂר. וּבַדֶּרֶךְ בְּגִלּוּי בְּשֶׁבַע הוּא נִמְצָא, וּמְבַקֵּשׁ דִּין. בְּעֶשֶׂר הוּא מַסְטִין לַהֲרֹג. וּמִשּׁוּם שֶׁנִּמְצָא בֵּינֵיהֶן בַּדֶּרֶךְ בְּגִלּוּי, כָּתוּב וַיָּבאוּ הָאֲנָשִׁים עַל הַנָּשִׁים. וְנִשְׁמְרוּ כָּל אוֹתוֹ יוֹם הַחֲבֵרִים וְעָסְקוּ בַתּוֹרָה.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית ז) וַיֹּאמֶר ה' אֶל נֹחַ בֹּא אַתָּה וְכָל בֵּיתְךְ אֶל הַתֵּבָה. הֲרֵי בֵּאַרְנוּ הַפָּסוּק, אֲבָל בֹּא וּרְאֵה, וְכִי לֹא יָכֹל הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת נֹחַ בְּמָקוֹם אֶחָד בָּעוֹלָם, שֶׁיִּהְיֶה הַמַּבּוּל בְּכָל הָעוֹלָם וְלֹא יִהְיֶה בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁכָּתוּב בְּגִדְעוֹן (שופטים ו) וַיְהִי חֹרֶב אֶל הַגִּזָּה לְבַדָּהּ, אוֹ לִשְׁמֹר אוֹתוֹ בְּאֶרֶץ יִשְׂרָאֵל שֶׁכָּתוּב בָּהּ (יחזקאל כב) לֹא גֻשְׁמָהּ בְּיוֹם זָעַם, שֶׁלֹּא יֵרְדוּ עָלֶיהָ מֵי הַמַּבּוּל?</p>\n<p>אֶלָּא, כֵּיוָן שֶׁהַמַּשְׁחִית יָרַד לָעוֹלָם, מִי שֶׁאֵינוֹ סוֹגֵר אֶת עַצְמוֹ וְנִמְצָא לְפָנָיו בְּגָלוּי - מִתְחַיֵּב בְּנַפְשׁוֹ, שֶׁהוּא הָרַג אֶת עַצְמוֹ. מִנַּיִן לָנוּ? מִלּוֹט, שֶׁכָּתוּב (בראשית יט) הִמָּלֵט עַל נַפְשֶׁךְ אַל תַּבִּיט אַחֲרֶיךְ. מָה הַטַּעַם אַל תַּבִּיט אַחֲרֶיךְ? מִשּׁוּם שֶׁהַמַּשְׁחִית הוֹלֵךְ אַחַר כְּתֵפוֹ, וְאִם מַחֲזִיר רֹאשׁוֹ וּמִתְבּוֹנֵן בּוֹ פָּנִים בְּפָנִים, יָכוֹל לְהַזִּיק לוֹ.</p>\n<p>וְעַל זֶה כָּתוּב, (שם) וַיִּסְגֹּר ה' בַּעֲדוֹ, שֶׁלֹּא יִתְרָאֶה לִפְנֵי הַמַּשְׁחִית וְלֹא יִשְׁלֹט עָלָיו מַלְאַךְ הַמָּוֶת. וְעַד שֶׁהָיוּ טְמוּנִים, מֵתוּ שְׁלֹשָׁה עָשָׂר אֲנָשִׁים בָּעִיר. אָמַר רַבִּי שִׁמְעוֹן, בָּרוּךְ הָרַחֲמָן שֶׁלֹּא הִסְתַּכֵּל בִּדְיוֹקְנֵיכֶם מַלְאַךְ הַמָּוֶת.</p>\n<p>וַיַּקְהֵל מֹשֶׁה וְגוֹ'. הֶחֱזִיר לָהֶם כְּמִקֹּדֶם מַעֲשֵׂה הַמִּשְׁכָּן. אָמַר רַבִּי חִיָּיא, הַכֹּל כְּמוֹ שֶׁנִּתְבָּאֵר. וּמַעֲשֵׂה הַמִּשְׁכָּן לֹא נַעֲשָׂה כִּי אִם מִיִּשְׂרָאֵל לְבַדָּם, וְלֹא מֵאוֹתָם עֵרֶב רַב, מִשּׁוּם שֶׁאוֹתָם עֵרֶב רַב מָשְׁכוּ אֶת מַלְאַךְ הַמָּוֶת לָרֶדֶת לָעוֹלָם. כֵּיוָן שֶׁהִסְתַּכֵּל בּוֹ מֹשֶׁה, זָרַק הַחוּצָה אֶת אוֹתָם עֵרֶב רַב, וְכִנֵּס אֶת יִשְׂרָאֵל לְבַדָּם. זֶהוּ שֶׁכָּתוּב וַיַּקְהֵל מֹשֶׁה וְגוֹ'.</p>"],[9522011822,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (משלי ה) מִי עָלָה שָׁמַיִם וַיֵּרַד מִי אָסַף רוּחַ בְּחָפְנָיו מִי צָרַר מַיִם בַּשִּׂמְלָה מִי הֵקִים כָּל אַפְסֵי אָרֶץ מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע. פָּסוּק זֶה הֲרֵי בֵּאַרְנוּ, וְכַמָּה עַמּוּדִים יֵשׁ בּוֹ. וְהַכֹּל נֶאֱמַר עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא הַכֹּל. וְנֶאֱמַר, מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. מַה שְּׁמוֹ? יהו\"ה. וּמַה שֶּׁם בְּנוֹ? יִשְׂרָאֵל, שֶׁכָּתוּב (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וַהֲרֵי בֵּאַרְנוּ. מִי עָלָה שָׁמַיִם, הֲרֵי פֵּרְשׁוּהוּ, זֶה מֹשֶׁה, שֶׁכָּתוּב (שם כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶת ה'.</p>\n<p>דָּבָר אַחֵר מִי עָלָה שָׁמַיִם - זֶה אֵלִיָּהוּ, שֶׁכָּתוּב בּוֹ (מלכים בב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם. וְכִי אֵיךְ יָכֹל אֵלִיָּהוּ לַעֲלוֹת לַשָּׁמַיִם, וַהֲרֵי כָּל הַשָּׁמַיִם לֹא יְכוֹלִים לִסְבֹּל אֲפִלּוּ גַּרְעִין שֶׁל חַרְדַּל מִגּוּף הָעוֹלָם הַזֶּה, וְאַתָּה אוֹמֵר וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם?</p>\n<p>אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (שמותיט) וַיֵּרֶד ה' עַל הַר סִינַי. וְכָתוּב (שם כב) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה בְּהַר סִינַי, וְכָתוּב וּמַרְאֵה כְּבוֹד ה' כְּאֵשׁ אֹכֶלֶת בְּרֹאשׁ הָהָר, אֵיךְ יָכֹל מֹשֶׁה לַעֲלוֹת אֵלָיו? אֶלָּא כָּתוּב בְּמֹשֶׁה, וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. שֶׁנִּכְנַס לְתוֹךְ הֶעָנָן כְּמִי שֶׁמִּתְלַבֵּשׁ בִּלְבוּשׁ, כָּךְ גַּם הִתְלַבֵּשׁ בֶּעָנָן וְנִכְנַס לְתוֹכוֹ, וּבֶעָנָן נִקְרַב לָאֵשׁ וְיָכֹל לִקְרַב. אַף כָּךְ אֵלִיָּהוּ, שֶׁכָּתוּב וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם, שֶׁנִּכְנַס בְּאוֹתָהּ סֳעָרָה וְהִתְלַבֵּשׁ בְּאוֹתָהּ סֳעָרָה וְעָלָה לְמַעְלָה.</p>\n<p>וְסוֹד מָצָאנוּ בְּסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן, שֶׁאָמַר בְּאוֹתָן תּוֹלְדוֹת הָעוֹלָם, שֶׁתִּהְיֶה רוּחַ אַחַת שֶׁתֵּרֵד לָעוֹלָם לָאָרֶץ וְתִתְלַבֵּשׁ בְּגוּף וּשְׁמוֹ אֵלִיָּהוּ, וּבְאוֹתוֹ גוּף יִסְתַּלֵּק, וְיִשָּׁלֵל מִגּוּפוֹ, וְיִשָּׁאֵר בַּסֳעָרָה, וְגוּף שֶׁל אוֹר אַחֵר יִזְדַּמֵּן לוֹ לִהְיוֹת בְּתוֹךְ הַמַּלְאָכִים. וּכְשֶׁיֵּרֵד, יִתְלַבֵּשׁ בְּאוֹתוֹ גוּף שֶׁיִּשָּׁאֵר בְּאוֹתוֹ הָעוֹלָם, וּבְאוֹתוֹ גוּף יִתְרָאֶה לְמַטָּה, וּבְגוּף אַחֵר יִתְרָאֶה לְמַעְלָה. וְזֶהוּ סוֹד שֶׁל מִי עָלָה שָׁמַיִם וַיֵּרַד. לֹא הָיָה אָדָם שֶׁעָלָה לַשָּׁמַיִם רוּחוֹ וְיָרַד אַחַר כָּךְ לְמַטָּה, פְּרָט לְאֵלִיָּהוּ, שֶׁהוּא עָלָה לְמַעְלָה וְיָרַד לְמַטָּה.</p>\n<p>דָּבָר אַחֵר מִי עָלָה שָׁמַיִם - זֶה אֵלִיָּהוּ. וַיֵּרַד - זֶה יוֹנָה, שֶׁהוֹרִיד אוֹתוֹ הַדָּג לְתוֹךְ הַתְּהוֹמוֹת לְעִמְקֵי הַיָּם. יוֹנָה בָּא מִכֹּחוֹ שֶׁל אֵלִיָּהוּ. אֵלִיָּהוּ עָלָה, וְיוֹנָה יָרַד. זֶה שָׁאַל נַפְשׁוֹ לָמוּת, וְזֶה שָׁאַל נַפְשׁוֹ לָמוּת. וּמִשּׁוּם כָּךְ נִקְרָא בֶּן אֲמִתַּי, וְכָתוּב (מלכים א יז) וּדְבַר ה' בְּפִיךְ אֱמֶת.</p>\n<p>מִי צָרַר מַיִם - זֶה אֵלִיָּהוּ, שֶׁצָּרַר אֶת צְרוֹר הַמַּיִם בָּעוֹלָם, וְלֹא יָרְדוּ טַל וּמָטָר מִשָּׁמַיִם. בַּשִּׂמְלָה - זֶה אֵלִיָּהוּ, שֶׁהָיָה (מכה באדרתו) מֵבִיא אַדַּרְתּוֹ לַעֲשׂוֹת נִסִּים. מִי אָסַף רוּחַ בְּחָפְנָיו - זֶה אֵלִיָּהוּ, שֶׁהֶחֱזִיר רוּחוֹ שֶׁל אָדָם לְתוֹךְ מֵעָיו. (אסףכמושגאמר (מלכים ב ה) ואסף המצרע).</p>\n<p>מִי הֵקִים כָּל אַפְסֵי אָרֶץ - זֶה אֵלִיָּהוּ, שֶׁלְּאַחַר שֶׁצָּרַר מַיִם וְנִשְׁבַּע עַל (המטר) הַשָּׁמַיִם, אַחַר כָּךְ חָזַר בִּתְפִלָּתוֹ וְהֵקִים כָּל הָעוֹלָם וְהוֹרִיד מָטָר וְנִתַּן מָזוֹן לַכֹּל. מַה שְּׁמוֹ - זֶה אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ - זֶה אֵלִיָּהוּ. מַה שְּׁמוֹ - כְּשֶׁעָלָה לְמַעְלָה, אֵלִיָּהוּ. וּמַה שֶּׁם בְּנוֹ - כְּשֶׁיָּרַד לְמַטָּה וְנַעֲשָׂה שָׁלִיחַ לַעֲשׂוֹת נִסִּים, אֵלִיָּהוּ שְׁמוֹ.</p>\n<p>דָּבָר אַחֵר מִי עָלָה שָׁמַיִם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ. וְסוֹד הַדָּבָר - מִ\"י, וַהֲרֵי בֵּאַרְנוּ. וְכָאן הוּא סוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, אַרְבָּעָה צִדְדֵי הָעוֹלָם שֶׁהֵם יְסוֹדוֹת רִאשׁוֹנִים שֶׁל הַכֹּל, וְכֻלָּם תְּלוּיִים בְּאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא מִ\"י, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁעָמְדָה שְׁעַת רָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַחֵד הַמֶּרְכָּבָה הָעֶלְיוֹנָה (במרכבההתחתונה) לִהְיוֹת הַכֹּל אֶחָד, אָז יָצָא קוֹל מֵאוֹתוֹ מָקוֹם עֶלְיוֹן קָדוֹשׁ שֶׁנִּקְרָא שָׁמַיִם, וְכִנֵּס אֶת כָּל אוֹתָם קְדוֹשִׁים שֶׁלְּמַטָּה, וְכָל אוֹתָם גְּדוֹלִים קְדוֹשִׁים וּמַחֲנוֹת הָעֶלְיוֹנִים, לִהְיוֹת כֻּלָּם מְזֻמָּנִים כְּאֶחָד. זֶהוּ שֶׁכָּתוּב וַיַּקְהֵל מֹשֶׁה, זֶה סוֹד שֶׁל שָׁמַיִם. אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל - אֵלֶּה הֵם שְׁנֵים עָשָׂר מַחֲנוֹת עֶלְיוֹנִים קְדוֹשִׁים.</p>\n<p>וַיֹּאמֶר אֲלֵהֶם. וּמָה אָמַר? זֶה הַדָּבָר וְגוֹ', קְחוּ מֵאִתְּכֶם תְּרוּמָה. הִתְתַּקְּנוּ כֻלְּכֶם לְהַעֲלוֹת עֲלֵיכֶם וְלִטֹּל עֲלֵיכֶם כְּבוֹד הַכִּסֵּא הַקָּדוֹשׁ לַעֲלוֹת לְמַעְלָה.</p>\n<p>הַפְרִידוּ מִכֶּם אוֹתָם נִכְבָּדִים, אוֹתָם גְּדוֹלִים עֶלְיוֹנִים לְהַעֲלוֹת אֶת אוֹתָהּ תְּרוּמָה, סוֹד הַכִּסֵּא הַקָּדוֹשׁ, לְהִתְחַבֵּר בָּאָבוֹת (בבעלה), שֶׁהֲרֵי הַגְּבִירָה אֵינָהּ רְאוּיָה לָבֹא לְבַעְלָה אֶלָּא בְּאוֹתָן בְּתוּלוֹת עַלְמוֹתֶיהָ, שֶׁיָּבאוּ עִמָּהּ וּמַנְהִיגוֹת אוֹתָהּ, עַד שֶׁמַּגִּיעָה לְבַעְלָהּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מה) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ וְגוֹ'. וְכָל כָּךְ לָמָּה? כְּדֵי לָבֹא לְהִתְחַבֵּר עִם בַּעְלָהּ.</p>"],[9522011823,"<p>כֹּל נְדִיב לִבּוֹ - אֵלּוּ אוֹתָם אַרְבָּעָה מַחֲנוֹת עֶלְיוֹנִים שֶׁבִּכְלָלָם כְּלוּלִים כָּל אוֹתָם שְׁאָר הַמַּחֲנוֹת, וְאֵלֶּה הֵם שֶׁיּוֹצְאִים בָּאָבוֹת הָעֶלְיוֹנִים שֶׁנִּקְרָאִים נְדִיבִים, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (במדבר כא) כָּרוּהָ נְדִיבֵי הָעָם, אֵלּוּ הָאָבוֹת.</p>\n<p>יְבִיאֶהָ, לֹא כָתוּב יְבִיאוּהָ, אֶלָּא יְבִיאֶהָ, לְיַחֵד הַכֹּל כְּאֶחָד. וְכֵן לֹא כָתוּב יָבִיא, אֶלָּא יְבִיאֶהָ, לְהַעֲלוֹתָהּ לְבַעְלָהּ בְּכָבוֹד כְּמוֹ שֶׁצָּרִיךְ. אֵת תְּרוּמַת ה' - אֶת, לְרַבּוֹת כָּל אוֹתָם הַמַּחֲנוֹת הָעֶלְיוֹנִים הָאֲחֵרִים, לְחַבֵּר הַכֹּל כְּאֶחָד, וְהֵם שְׁנֵים עָשָׂר בִּכְלָל אֶחָד. זָהָב. וָכֶסֶף. וּנְחֹשֶׁת. תְּכֵלֶת. וְאַרְגָּמָן. וְתוֹלַעַת שָׁנִי. וְשֵׁשׁ וְעִזִּים. וְעֹרֹת אֵילִם מְאָדָּמִים. וְעֹרֹת תְּחָשִׁים. וַעֲצֵי שִׁטִּים. וְשֶׁמֶן לַמָּאוֹר. וּבְשָׂמִים לְשֶׁמֶן הַמִּשְׁחָה. וְלִקְטֹרֶת הַסַּמִּים. אֵלּוּ הֵם שְׁנֵים עָשָׂר מַחֲנוֹת עֶלְיוֹנִים, שֶׁכֻּלָּם כְּלוּלִים כְּאֶחָד בִּכְלָל שֶׁל אַרְבָּעָה שֶׁנִּקְרְאוּ חַיּוֹת הַקֹּדֶשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וְכָל אֵלֶּה עוֹלִים לַכִּסֵּא הַקָּדוֹשׁ לְהַעֲלוֹתוֹ לְמַעְלָה לְהִתְחַבֵּר עִם בַּעְלָהּ כְּדֵי לִהְיוֹת הַכֹּל אֶחָד, וּכְדֵי שֶׁיִּמָּצֵא עִמָּהּ בְּכָבוֹד עֶלְיוֹן. וְאָז יוֹשֵׁב הַמֶּלֶךְ הָעֶלְיוֹן עַל הַכִּסֵּא הַקָּדוֹשׁ, וּמִתְחַבֶּרֶת אִשָּׁה עִם בַּעְלָהּ לִהְיוֹת הַכֹּל אֶחָד, וְאָז הִיא שִׂמְחַת הַכֹּל.</p>\n<p>בֹּא וּרְאֵה, כָּאן מַתְחִיל לִמְנוֹת זָהָב בָּרִאשׁוֹנָה, וְאַחַר כָּךְ כֶּסֶף, מִשּׁוּם שֶׁהַחֶשְׁבּוֹן הַזֶּה מִלְּמַטָּה. אֲבָל כְּשֶׁבָּא לִמְנוֹת מֵחֶשְׁבּוֹן הַמֶּרְכָּבָה הָעֶלְיוֹנָה, מַתְחִיל לִמְנוֹת מִיָּמִין בָּרִאשׁוֹנָה, וְאַחַר כָּךְ מִשְּׂמֹאל. מִנַּיִן לָנוּ? שֶׁכָּתוּב (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב. כֶּסֶף בַּתְּחִלָּה וְאַחַר כָּךְ הַזָּהָב. וּבַמֶּרְכָּבָה שֶׁלְּמַטָּה מַתְחִילִים מִשְּׂמֹאל וְאַחַר כָּךְ מִיָּמִין, שֶׁכָּתוּב זָהָב וָכֶסֶף וּנְחֹשֶׁת. זָהָב בַּתְּחִלָּה וְאַחַר כָּךְ כֶּסֶף.</p>\n<p>וְכָל אוֹתָן מֶרְכָּבוֹת נִקְרָאוֹת נְדִיב לֵב. כֹּל - לִכְלֹל אֶת כָּל שְׁאָר הַמֶּרְכָּבוֹת. לֵב, מַה זֶּה לֵב? הַיְנוּ סוֹד הַכָּתוּב (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד. וְזֶהוּ הַלֵּב שֶׁל הַכֹּל, וְזֶהוּ הַכִּסֵּא הַקָּדוֹשׁ, וְעַל זֶה נִקְרָאִים לֵב. כֹּל נְדִיב לֵב, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁאַרְבַּעַת הַמַּחֲנוֹת הַלָּלוּ הַכְּלָל שֶׁל כֻּלָּם נִקְרָאִים בְּסוֹד אֶחָד, נְדִיב לֵב. תְּרוּמַת ה' - זֶה הַכִּסֵּא הַקָּדוֹשׁ. וּמִשּׁוּם שֶׁהֵרִימוּ אוֹתָהּ לְמַעְלָה וּמַעֲלִים אוֹתָהּ לְמַעְלָה, נִקְרֵאת תְּרוּמַת ה'.</p>\n<p>וְעַל זֶה, כְּשֶׁרָאָה יְחֶזְקֵאל סוֹד הַחַיּוֹת שֶׁהָיוּ עוֹלוֹת, לֹא רָאָה מַה זֶּה שֶׁעוֹלוֹת, מִשּׁוּם שֶׁהִיא עוֹלָה לַמֶּלֶךְ הָעֶלְיוֹן בְּסֵתֶר וּבִטְמִירוּת בְּכָבוֹד עֶלְיוֹן.</p>\n<p>וְכָל חֲכַם לֵב בָּכֶם - אֵלֶּה הֵם שִׁשִּׁים מְקוֹרוֹת שֶׁמַּשְׁקִים אֶת הָעוֹלָם, וּמֵהֶם הוּא מֻשְׁקֶה. יָבאוּ, לָמָּה יָבאוּ? אֶלָּא שֶׁיָּבֹאוּ לָקַחַת מֵעִם גִּנְזֵי הַחַיִּים. יָבאוּ וְאַחַר כָּךְ וְיַעֲשׂוּ, מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה אוֹתָם לֵהָנוֹת אֶת הָעוֹלָם.</p>\n<p>קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. רַבִּי יְהוּדָה פָּתַח, (ישעיה נח) הֲלוֹא פָרֹס לָרָעֵב לַחְמֶךְ וְגוֹ'. בּא וּרְאֵה, אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם כְּשֶׁעָנִי פּוֹגֵשׁ אוֹתוֹ. שֶׁאוֹתוֹ הֶעָנִי הוּא דּוֹרוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁשָּׁלַח אֵלָיו. מִי שֶׁמְּקַבֵּל אֶת אוֹתוֹ דוֹרוֹן בְּסֵבֶר פָּנִים, אַשְׁרֵי חֶלְקוֹ!</p>\n<p>בֹּא וּרְאֵה, מִי שֶׁחָס עַל הֶעָנִי וּמֵשִׁיב אֶת נַפְשׁוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלֶה עָלָיו כְּאִלּוּ הוּא בָּרָא אֶת נַפְשׁוֹ. וְעַל כֵּן, אַבְרָהָם שֶׁהָיָה חָס עַל כָּל בְּנֵי הָעוֹלָם, הֶעֱלָה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאִלּוּ הוּא בָּרָא אוֹתָם, שֶׁכָּתוּב (בראשית יב) וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן.</p>\n<p>וְאַף עַל גַּב שֶׁהֲרֵי בֵּאַרְנוּ, הֲלוֹא פָרֹס, מַה זֶּה פָרֹס? לִפְרֹס לוֹ מַפָּה בְּלֶחֶם וּמָזוֹן לֶאֱכֹל. דָּבָר אַחֵר הֲלוֹא פָרֹס, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ה) פְּרֵס פְּרִיסַת וְגוֹ'. שֶׁצָּרִיךְ לִפְרֹס פְּרוּסוֹת לֶחֶם לְפָנָיו כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ, וְיִפְרֹס לְפָנָיו בְּעַיִן טוֹבָה. לַחְמֶךְ, לֹא כָתוּב לֶחֶם, אֶלָּא לַחְמֶךְ, אוֹתוֹ שֶׁהוּא שֶׁלְּךְ. מִמָּמוֹנְךְ, וְלֹא שֶׁל גָּזֵל, וְלֹא שֶׁל עֹשֶׁק, וְלֹא שֶׁל גְּנֵבָה. שֶׁאִם כָּךְ, זוֹ אֵינָהּ זְכוּת, אֶלָּא אוֹי לוֹ שֶׁבָּא לְהַזְכִּיר אֶת חֲטָאָיו. כְּמוֹ כֵן קְחוּ מֵאִתְּכֶם תְּרוּמָה, לְהָרִים מִמַּה שֶּׁהוּא שֶׁלָּכֶם, וְלֹא מֵעֹשֶׁק, וְלֹא מִגָּזֵל, וְלֹא מִגְּנֵבָה, וְכָךְ פֵּרְשׁוּהוּ.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יִצְחָק וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. עַד שֶׁהָיוּ הוֹלְכִים, פָּגַשׁ בָּהֶם רַבִּי אַבָּא. אָמַר רַבִּי חִיָּיא, וַדַּאי שְׁכִינָה עִמָּנוּ. כְּשֶׁהִגִּיעַ אֲלֵיהֶם, אָמַר רַבִּי אַבָּא, כָּתוּב (מלכים א ב) מִן הַיּוֹם אֲשֶׁר הוֹצֵאתִי אֶת עַמִּי אֶת יִשְׂרָאֵל מִמִּצְרַיִם לֹא בָחַרְתִּי בְעִיר מִכֹּל שִׁבְטֵי יִשְׂרָאֵל וָאֶבְחַר בְּדָוִד וְגוֹ' לִבְנוֹת בַּיִת לִהְיוֹת שְׁמִי שָׁם. פָּסוּק זֶה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. שֶׁכָּתוּב לֹא בָחַרְתִּי בְעִיר, וָאֶבְחַר בְּדָוִד. מַה זֶּה עִם זֶה? וָאֶבְחַר בִּירוּשָׁלַיִם הָיָה צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא כְּשֶׁיֵּשׁ רָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת עִיר, מִסְתַּכֵּל בָּרִאשׁוֹנָה בְּאוֹתוֹ הָרֹאשׁ שֶׁמַּנְהִיג אֶת הָעָם שֶׁל הָעִיר, וְאַחַר כָּךְ אֶת בְּנֵי הָעִיר, וּמֵבִיא אֶת הָעָם לְשָׁם. זֶהוּ שֶׁכָּתוּב לֹא בָחַרְתִּי בְעִיר, עַד שֶׁהִתְבּוֹנַנְתִּי בְּדָוִד לִהְיוֹת רוֹעֶה עַל יִשְׂרָאֵל, מִשּׁוּם שֶׁהָעִיר וְכָל בְּנֵי הָעִיר כֻּלָּם עוֹמְדִים בִּזְכוּת הָרוֹעֶה שֶׁמַּנְהִיג אֶת הָעָם. אִם הָרוֹעֶה הוּא טוֹב - טוֹב לוֹ, טוֹב לָעִיר, טוֹב לָעָם. וְאִם הָרוֹעֶה הוּא רַע - אוֹי לוֹ, אוֹי לָעִיר וְאוֹי לָעָם! וְעַכְשָׁו הִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, וְעָלָה בִרְצוֹנוֹ לִבְנוֹת אוֹתָהּ, וְהֶעֱמִיד בָּרֹאשׁ אֶת דָּוִד. זֶהוּ שֶׁכָּתוּב וָאֶבְחַר בְּדָוִד עַבְדִּי. (והעמיד בראש הדור את רבי שמעון וחבריו לעמד לפניו).</p>\n<p>דָּבָר חָדָשׁ שָׁמַעְנוּ. פָּתַח וְאָמַר, (תהליםקמו) אַשְׁרֵי שֶׁאֵל יַעֲקֹב בְּעֶזְרוֹ שִׂבְרוֹ עַל ה' אֱלֹהָיו. וְכִי אֵל יַעֲקֹב, וְלֹא אֵל אַבְרָהָם, וְלֹא אֵל יִצְחָק? אֶלָּא אֵל יַעֲקֹב, מִשּׁוּם שֶׁיַּעֲקֹב לֹא בָטַח בְּאָבִיו וְלֹא בְאִמּוֹ כְּשֶׁבָּרַח מִלִּפְנֵי אָחִיו וְהָלַךְ יְחִידִי בְּלִי מָמוֹן, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לב) כִּי בְמַקְלִי עָבַרְתִּי אֶת הַיַּרְדֵּן הַזֶּה, וְהוּא בָּטַח בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב (שם כח) אִם יִהְיֶה אֱלֹהִים עִמָּדִי וּשְׁמָרַנִי וְגוֹ'. וְהַכֹּל שָׁאַל מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן לוֹ.</p>\n<p>שִׂבְרוֹ עַל ה' אֱלֹהָיו. שִׂבְרוֹ, וְלֹא אָמַר תִּקְוָתוֹ וְלֹא בִטְחוֹנוֹ, אֶלָּא שִׂבְרוֹ. אַל תִּקְרֵי שִׂבְרוֹ אֶלָּא שִׁבְרוֹ, שֶׁנּוֹחַ לַצַּדִּיקִים לִשְׁבֹּר אֶת עַצְמָם וּלְהִשָּׁבֵר שֶׁבֶר עַל שֶׁבֶר, וְהַכֹּל עַל ה' אֱלֹהָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מד) כִּי עָלֶיךְ הֹרַגְנוּ כָל הַיּוֹם. כִּי עָלֶיךְ נָשָׂאנוּ חֶרְפָּה.</p>\n<p>כְּמוֹ שֶׁיַּעֲקֹב, שֶׁכָּתוּב וַיַּרְא יַעֲקֹב כִּי יֵשׁ שֶׁבֶר בְּמִצְרָיִם, שֶׁהֲרֵי שִׁבְרוֹן הַגָּלוּת רָאָה שֶׁהָיָה לוֹ בְּמִצְרַיִם, וְשָׂם חָזְקוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. וּבְנֵי יַעֲקֹב סָבְלוּ אֶת שֶׁבֶר הַגָּלוּת וְלֹא הִשְׁתַּנּוּ מִתּוֹךְ סוֹד הָאֱמוּנָה שֶׁל אֲבוֹתֵיהֶם, וּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה רָגִיל בַּגָּלוּת בְּפִיהֶם.</p>\n<p>וְעַל זֶה כָּתוּב בְּמֹשֶׁה, (שמות ג) וְאָמְרוּ לִי' מַה' שְּׁמוֹ' מַה'. מִשּׁוּם שֶׁהָיוּ מַכִּירִים אוֹתוֹ וְלֹא שְׁכָחוּהוּ לְעוֹלָמִים וְסָבְלוּ אֶת שֶׁבֶר הַגָּלוּת עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ זוֹכִים לִגְאֻלּוֹת וּלְנִסִּים וּלְאוֹתוֹת רַבִּים.</p>\n<p>וְאַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, שֶׁסּוֹבְלִים אֶת שֶׁבֶר הַגּוּף מִמָּקוֹם לְמָקוֹם עַל הַקָּדוֹשׁ בָּרוּךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה שֶׁזַּכָּאִים אַתֶּם לַעֲשׂוֹת לָכֶם נִסִּים וּפֻרְקָן וְשֶׁתִּזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא. הָלְכוּ כֻלָּם כְּאֶחָד.</p>\n<p>פָּתַח וְאָמַר, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה' כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ וְגוֹ'. בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָדָם שָׂם רְצוֹנוֹ לַעֲבוֹדַת רִבּוֹנוֹ, אוֹתוֹ רָצוֹן עוֹלֶה בָּרִאשׁוֹנָה עַל הַלֵּב, שֶׁהוּא קִיּוּם וִיסוֹד שֶׁל כָּל הַגּוּף. אַחַר כָּךְ עוֹלֶה אוֹתוֹ רָצוֹן טוֹב עַל כָּל אֶבְרֵי הַגּוּף, וּרְצוֹנָם שֶׁל כָּל אֶבְרֵי הַגּוּף וּרְצוֹן הַלֵּב מִתְחַבְּרִים כְּאֶחָד, וְהֵם מוֹשְׁכִים עֲלֵיהֶם אֶת זֹהַר הַשְּׁכִינָה לָדוּר עִמָּהֶם, וְאוֹתוֹ אָדָם הִנּוֹ חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב קְחוּ מֵאִתְּכֶם תְּרוּמָה. מֵאִתְּכֶם הָיְתָה הַמְשָׁכָה לְקַבֵּל עֲלֵיכֶם אוֹתָהּ תְּרוּמָה לִהְיוֹת חֵלֶק לַה'.</p>\n<p>וְאִם תֹּאמַר שֶׁלֹּא בִּרְשׁוּת הָאָדָם עוֹמֵד הַדָּבָר - בֹּא וּרְאֵה מַה כָּתוּב, כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת ה'. כֹּל נְדִיב לִבּוֹ וַדַּאי. מִי שֶׁיִּתְרַצֶּה לִבּוֹ, יַמְשִׁיךְ אֶת הַשְּׁכִינָה אֵלָיו. זֶהוּ שֶׁכָּתוּב יְבִיאֶהָ, אַף עַל גַּב שֶׁהִיא בַּעֲלִיָּה לְמַעְלָה, יְבִיאֶהָ מִמָּקוֹם עֶלְיוֹן לִמְשֹׁךְ אוֹתָהּ לָדוּר עִמּוֹ.</p>\n<p>וּכְשֶׁתָּבֹא לִשְׁרוֹת עִמּוֹ, כַּמָּה בְרָכוֹת וְכַמָּה עֹשֶׁר תָּבִיא עִמָּהּ. זֶהוּ שֶׁכָּתוּב זָהָב וָכֶסֶף וּנְחֹשֶׁת. לֹא חָסֵר לוֹ כָּל עֹשֶׁר הָעוֹלָם. זֶה לִשְׁאָר בְּנֵי הָעוֹלָם. אֲבָל אַתֶּם קְדוֹשִׁים עֶלְיוֹנִים - קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. אָמַר רַבִּי חִיָּיא, מִי שֶׁהִתְחִיל לְהָרִים - הוּא שֶׁיָּרִים.</p>"],[9522011824,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, (יונהב) וַיֹּאמֶר ה' לַדָּג וְגוֹ'. וְכִי בְּאֵיזֶה מָקוֹם אָמַר לוֹ? אֶלָּא בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם בְּמַעֲשֵׂה בְרֵאשִׁית, בַּיּוֹם הַחֲמִישִׁי בָּרָא אֶת דְּגֵי הַיָּם, וְאָז צִוָּה וְאָמַר שֶׁיִּהְיֶה מְזֻמָּן דָּג אֶחָד לִבְלֹעַ אֶת יוֹנָה, וְיִהְיֶה בְמֵעָיו שְׁלֹשָׁה יָמִים וּשְׁלֹשָׁה לֵילוֹת, וְאַחַר כָּךְ יַשְׁלִיכֶנּוּ בַּחוּץ.</p>\n<p>וְלֹא זֶה לְבַדּוֹ, אֶלָּא כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית - בַּכֹּל הִתְנָה עִמּוֹ. בַּיּוֹם הָרִאשׁוֹן בָּרָא שָׁמַיִם, הִתְנָה עִמָּם שֶׁיַּעֲלוּ אֶת אֵלִיָּהוּ הַשָּׁמַיְמָה בְּתוֹךְ סֳעָרָה, וְכָךְ הָיָה, שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם. בְּאוֹתוֹ יוֹם בָּרָא אֶת הָאוֹר, וְהִתְנָה עִמּוֹ שֶׁיַּחֲשִׁיךְ לַשֶּׁמֶשׁ בְּמִצְרַיִם שְׁלֹשָׁה יָמִים, שֶׁכָּתוּב (שמות י) וַיְהִי חֹשֶׁךְ אֲפֵלָה בְּכָל אֶרֶץ מִצְרַיִם שְׁלֹשֶׁת יָמִים.</p>\n<p>בַּיּוֹם הַשֵּׁנִי בָּרָא אֶת הָרָקִיעַ, שֶׁיִּהְיֶה מַפְרִיד בֵּין מַיִם לָמַיִם, כַּכָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, וְהִתְנָה עִמָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהַמַּיִם יִהְיוּ מַפְרִידִים לְיִשְׂרָאֵל בֵּין טֻמְאָה וְטָהֳרָה לְהִטָּהֵר בָּהֶם, וְכָךְ הָיָה.</p>\n<p>בַּיּוֹם הַשְּׁלִישִׁי הוֹצִיא אֶרֶץ מִתּוֹךְ הַיָּם וְכִנֵּס אֶת הַמַּיִם, וְעָשָׂה מֵאוֹתוֹ קִבּוּץ שֶׁהִתְכַּנְּסוּ לְמָקוֹם אֶחָד אֶת הַיָּם, וְהִתְנָה עִם הַיָּם לְהַעֲבִיר אֶת יִשְׂרָאֵל בְּתוֹכוֹ בַּיַּבָּשָׁה וּלְהַטְבִּיעַ אֶת הַמִּצְרִים, וְכָךְ הָיָה, שֶׁכָּתוּב (שמות יד) וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. אַל תִּקְרֵי לְאֵיתָנוֹ אֶלָּא לִתְנָאוֹ, לְמַה שֶּׁהִתְנָה עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית. עוֹד הִתְנָה עִם הָאָרֶץ, שֶׁתִּפְתַּח אֶת פִּיהָ בְּמַחֲלֻקְתּוֹ שֶׁל קֹרַח וְתִבְלַע אֶת קֹרַח וְאֶת כָּל עֲדָתוֹ, וְכָךְ הָיָה, שֶׁכָּתוּב (במדבר טז) וַתִּפְתַּח הָאָרֶץ אֶת פִּיהָ וַתִּבְלַע אֹתָם, וְאֶת קֹרַח.</p>\n<p>בַּיּוֹם הָרְבִיעִי בָּרָא שֶׁמֶשׁ וּלְבָנָה, שֶׁכָּתוּב יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, וְהִתְנָה עִם הַשֶּׁמֶשׁ לִהְיוֹת עוֹמֶדֶת בַּחֲצִי הַשָּׁמַיִם בִּימֵי יְהוֹשֻׁעַ, שֶׁכָּתוּב (יהושע י) וַיַּעֲמֹד הַשֶּׁמֶשׁ בַּחֲצִי הַשָּׁמַיִם. הִתְנָה עִם הַכּוֹכָבִים לַעֲשׂוֹת קְרָב עִם סִיסְרָא, שֶׁכָּתוּב (שופטים ה) הַכּוֹכָבִים מִמְּסִלּוֹתָם נִלְחֲמוּ עִם סִיסְרָא.</p>\n<p>בַּיּוֹם הַחֲמִישִׁי בָּרָא אֶת דְּגֵי הַיָּם וְעוֹפוֹת הַשָּׁמַיִם, הִתְנָה עִם הָעוֹפוֹת שֶׁהָעוֹרְבִים יָזוּנוּ אֶת אֵלִיָּהוּ בַּזְּמַן שֶׁעָצַר אֶת הַשָּׁמַיִם, שֶׁכָּתוּב (מלכים א יז) וְאֶת הָעֹרְבִים צִוִּיתִי לְכַלְכֶּלְךְ שָׁם. צִוִּיתִי דַּוְקָא. וְהִתְנָה עִם דְּגֵי הַיָּם לְהַזְמִין דָּג אֶחָד שֶׁיִּבְלַע אֶת יוֹנָה וְלִזְרֹק אוֹתוֹ הַחוּצָה.</p>\n<p>בַּיּוֹם הַשִּׁשִּׁי בָּרָא אֶת הָאָדָם, וְהִתְנָה עִמּוֹ שֶׁתֵּצֵא מִמֶּנּוּ אִשָּׁה שֶׁתָּזוּן אֶת אֵלִיָּהוּ, שֶׁנֶּאֱמַר הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךְ. הִנֵּה צִוִּיתִי - מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם. וְכָךְ בְּכָל מַעֲשֶׂה וּמַעֲשֶׂה שֶׁהִתְחַדֵּשׁ בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא צִוָּה אֶת אוֹתוֹ מַעֲשֶׂה מִיּוֹם שֶׁנִּבְרָא הָאָדָם. אַף כָּאן וַיֹּאמֶר ה' לַדָּג, וַיֹּאמֶר - מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית אָמַר לוֹ.</p>"],[9522011825,"<p>כָּאן יֵשׁ לָנוּ סֶמֶךְ הָעוֹלָם עַל מַעֲשֵׂי בְּנֵי אָדָם בָּעוֹלָם הַזֶּה. יוֹנָה שֶׁיָּרַד לַסְּפִינָה, זוֹהִי נִשְׁמַת הָאָדָם שֶׁיּוֹרֶדֶת לָעוֹלָם הַזֶּה לִהְיוֹת בְּגוּף הָאָדָם. לָמָּה נִקְרֵאת יוֹנָה? מִשּׁוּם שֶׁכֵּיוָן שֶׁמִּשְׁתַּתֶּפֶת בַּגּוּף, אֲזַי הִיא יוֹנָה בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (ויקראכה) וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ. וְאָז הָאָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה כְּמוֹ סְפִינָה בְּתוֹךְ הַיָּם הַגָּדוֹל שֶׁמְּחַשֶּׁבֶת לְהִשָּׁבֵר, כְּמוֹ שֶׁנֶּאֱמַר וְהָאֳנִיָּה חִשְּׁבָה לְהִשָּׁבֵר.</p>\n<p>וְאָדָם, כְּשֶׁהוּא חוֹטֵא בָּעוֹלָם הַזֶּה וְחוֹשֵׁב שֶׁבּוֹרֵחַ מִלִּפְנֵי אֲדוֹנוֹ וְלֹא שָׂם לֵב לְאוֹתוֹ הָעוֹלָם, וְאָז מַטִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ סְעָרָה חֲזָקָה - זוֹהִי גְּזֵרַת הַדִּין שֶׁעוֹמֶדֶת תָּמִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְבַקֶּשֶׁת אֶת דִּין הָאָדָם מִלְּפָנָיו, וְזוֹהִי שֶׁמַּטָּה אֶת הַסְּפִינָה וּמַזְכִּירָה אֶת חֲטָאֵי הָאָדָם לִתְפֹּס אוֹתוֹ.</p>\n<p>כֵּיוָן שֶׁנִּתְפָּס אָדָם עַל יְדֵי אוֹתָהּ סְעָרָה בְּבֵית חָלְיוֹ, מַה כָּתוּב? וְיוֹנָה יָרַד אֶל יַרְכְּתֵי הַסְּפִינָה וַיִּשְׁכַּב וַיֵּרָדַם. אַף עַל גַּב שֶׁאָדָם בְּבֵית חָלְיוֹ, הַנְּשָׁמָה לֹא מִתְעוֹרֶרֶת לָשׁוּב לִפְנֵי אֲדוֹנָהּ וְלִפְדּוֹת אֶת חֲטָאָיו. מַה כָּתוּב? וַיִּקְרַב אֵלָיו רַב הַחֹבֵל. מִי זֶה רַב הַחוֹבֵל? זֶה יֵצֶר טוֹב שֶׁמַּנְהִיג אֶת הַכֹּל. וַיֹּאמֶר לוֹ מַה לְּךְ נִרְדָּם קוּם קְרָא אֶל אֱלֹהֶיךְ וְגוֹ'. אֵין הַשָּׁעָה לִישֹׁן, שֶׁהֲרֵי מַעֲלִים אוֹתְךְ לַדִּין עַל כָּל מַה שֶּׁעָשִׂיתָ בָּעוֹלָם הַזֶּה, שׁוּב מֵחֶטְאֲךְ.</p>\n<p>הִתְבּוֹנֵן בַּדְּבָרִים הַלָּלוּ וְשׁוּב לַאֲדוֹנְךְ. מַה מְּלַאכְתְּךְ - שֶׁאַתָּה עָסַקְתָּ בָּהּ בָּעוֹלָם הַזֶּה, וְהוֹדֶה עָלֶיהָ לִפְנֵי רִבּוֹנְךְ. וּמֵאַיִן תָּבוֹא - הִסְתַּכֵּל מֵאַיִן בָּאתָ, מִטִּפָּה סְרוּחָה, וְאַל תִּתְגָּאֶה לְפָנָיו. מָה אַרְצֶךְ - הִסְתַּכֵּל שֶׁהֲרֵי מֵהָאָרֶץ נִבְרֵאתָ וְלָאָרֶץ תָּשׁוּב. וְאֵי מִזֶּה עַם אָתָּה - הִסְתַּכֵּל אִם יֵשׁ לְךְ זְכוּת אָבוֹת שֶׁתָּגֵן עָלֶיךְ.</p>\n<p>כֵּיוָן שֶׁמַּעֲלִים אוֹתוֹ לְדִין בְּבֵית דִּין שֶׁל מַעְלָה, אוֹתָהּ סְעָרָה, שֶׁהִיא גְּזֵרַת הַדִּין שֶׁסּוֹעֶרֶת עַל הָאָדָם, מְבַקֶּשֶׁת מֵהַמֶּלֶךְ לָדוּן אוֹתָם הַתְּפוּסִים שֶׁל הַמֶּלֶךְ, וְכֻלָּם בָּאִים אֶחָד אֶחָד לְפָנָיו. בְּאוֹתָהּ שָׁעָה מִתְקָרְבִים בֵּית הַדִּין. יֵשׁ מֵהֶם שֶׁפּוֹתְחִים בִּזְכוּת, וְיֵשׁ מֵהֶם שֶׁפּוֹתְחִים בְּחוֹבָה, וּגְזֵרַת הַדִּין תּוֹבַעַת דִּין.</p>\n<p>וְאִם אוֹתוֹ אָדָם לֹא זוֹכֶה בַדִּין, מַה כָּתוּב? וַיַּחְתְּרוּ הָאֲנָשִׁים לְהָשִׁיב אֶל הַיַּבָּשָׁה וְלֹא יָכֹלוּ. הֵם מִשְׁתַּדְּלִים אוֹתָם שֶׁמּוֹרִים זְכוּתוֹ לַהֲשִׁיבוֹ אֶל הָעוֹלָם הַזֶּה וְלֹא יָכֹלוּ. מָה הַטַּעַם? כִּי הַיָּם הוֹלֵךְ וְסֹעֵר עֲלֵיהֶם. גְּזֵרַת הַדִּין הוֹלֶכֶת וְסוֹעֶרֶת בַּחֲטָאֵי הָאָדָם וּמִתְגַּבֶּרֶת עֲלֵיהֶם.</p>\n<p>אֶחָד שֶׁכּוֹתֵב כָּל הַזְּכֻיּוֹת וְכָל הַחֲטָאִים שֶׁעָשָׂה הָאָדָם בָּעוֹלָם הַזֶּה. וְאֶחָד שֶׁעוֹשֶׂה חֶשְׁבּוֹן יָמָיו. וְאֶחָד שֶׁהָיָה הוֹלֵךְ עִמּוֹ כְּשֶׁהָיָה בִּמְעֵי אִמּוֹ, וַהֲרֵי בֵּאַרְנוּ שֶׁגְּזֵרַת הַדִּין לֹא שׁוֹכֶכֶת עַד לְאוֹתוֹ זְמַן, שֶׁכָּתוּב וַיִּשְׂאוּ אֶת יוֹנָה. וַיִּשְׂאוּ, כְּשֶׁנּוֹטְלִים אוֹתוֹ מִבֵּיתוֹ לְבֵית הַקְּבָרוֹת.</p>\n<p>וְאָז מַכְרִיזִים עָלָיו. אִם הוּא צַדִּיק - מַכְרִיזִים עָלָיו וְאוֹמְרִים: תְּנוּ כָבוֹד לִדְמוּת הַמֶּלֶךְ, (ישעיהנז) יָבוֹא שָׁלוֹם יָנוּחוּ עַל מִשְׁכְּבוֹתָם הֹלֵךְ נְכֹחוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם נח) וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ כְּבוֹד ה' יַאַסְפֶךְ. וְאִם הוּא רָשָׁע - מַכְרִיזִים עָלָיו וְאוֹמְרִים: אוֹי לוֹ לִפְלוֹנִי, טוֹב לוֹ שֶׁלֹּא הָיָה נִבְרָא. וְאָז מַה כָּתוּב? וַיְטִלֻהוּ אֶל הַיָּם וַיַּעֲמֹד הַיָּם מִזַּעְפּוֹ. כְּשֶׁמַּכְנִיסִים אוֹתוֹ לְבֵית הַקְּבָרוֹת, שֶׁהוּא מְקוֹם הַדִּין, אָז גְּזֵרַת הַדִּין שֶׁהָיְתָה סוֹעֶרֶת, שׁוֹכֶכֶת מִזַּעְפָּהּ. וְהַדָּג שֶׁבָּלַע אוֹתוֹ זֶהוּ הַקֶּבֶר.</p>\n<p>מַה כָּתוּב? וַיְהִי יוֹנָה בִּמְעֵי הַדָּג. מְעִי הַדָּג זֶהוּ בֶּטֶן שְׁאוֹל. מִנַּיִן לָנוּ? שֶׁכָּתוּב מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי. וְהוּא הָיָה בִּמְעֵי הַדָּג, וְקוֹרֵא לוֹ בֶּטֶן שְׁאוֹל, שְׁלֹשָׁה יָמִים וּשְׁלֹשָׁה לֵילוֹת. אֵלּוּ שְׁלֹשָׁה יָמִים שֶׁאָדָם בַּקֶּבֶר וְנִבְקָעִים מֵעָיו.</p>\n<p>לְאַחַר שְׁלֹשָׁה יָמִים אוֹתָהּ טִנֹּפֶת נֶהְפֶּכֶת עַל פָּנָיו, וְאוֹמֶרֶת לוֹ: טֹל מַה שֶּׁנָּתַתָּ בִּי. אָכַלְתָּ וְשָׁתִיתָ כָּל יוֹם וְלֹא נָתַתָּ לַעֲנִיִּים, וְכָל יָמֶיךְ הָיוּ כְּמוֹ חַגִּים וּמוֹעֲדִים, וְהָעֲנִיִּים הָיוּ רְעֵבִים, שֶׁלֹּא אָכְלוּ עִמְּךְ. טֹל מַה שֶּׁנָּתַתָּ בִּי. זֶהוּ שֶׁכָּתוּב (מלאכי ב) וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם וְגוֹ', וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>לְאַחַר זֶה, מִשְּׁלֹשָׁה יָמִים וָהָלְאָה, אָז נִדּוֹן הָאָדָם מֵעֵינָיו, מִיָּדָיו, מֵרַגְלָיו, וּפֵרְשׁוּהָ עַד שְׁלֹשִׁים יָמִים. כָּל אוֹתָם שְׁלֹשִׁים יָמִים נִדּוֹנִים הַנֶּפֶשׁ וְהַגּוּף כְּאֶחָד, וּמִשּׁוּם כָּךְ הַנְּשָׁמָה נִמְצֵאת בָּאָרֶץ לְמַטָּה, שֶׁאֵינָהּ עוֹלָה לִמְקוֹמָהּ, כְּאִשָּׁה שֶׁיּוֹשֶׁבֶת בַּחוּץ כָּל יְמֵי הַטֻּמְאָה. אַחַר כָּךְ הַנְּשָׁמָה עוֹלָה, וְהַגּוּף נִרְקָב בָּאָרֶץ, עַד אוֹתוֹ זְמַן שֶׁיָּעִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמֵּתִים.</p>\n<p>וְעָתִיד קוֹל אֶחָד לְהָעִיר בְּבֵית הַקְּבָרוֹת וְיֹאמַר, (ישעיה כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר כִּי טַל אוֹרֹת טַלֶּךְ וָאָרֶץ רְפָאִים תַּפִּיל. אֵימָתַי זֶה יִהְיֶה? בִּזְמַן שֶׁיָּעֳבַר מַלְאַךְ הַמָּוֶת מִן הָעוֹלָם, שֶׁכָּתוּב (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ'. כֵּיוָן שֶׁבִּלַּע הַמָּוֶת לָנֶצַח, אַחַר כָּךְ, וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ. אָז כָּתוּב, וַיֹּאמֶר ה' לַדָּג וַיָּקֵא אֶת יוֹנָה אֶל הַיַּבָּשָׁה.</p>\n<p>כֵּיוָן שֶׁהִתְעוֹרֵר אוֹתוֹ קוֹל בֵּין הַקְּבָרִים, אֲזַי כָּל הַקְּבָרִים יָקִיאוּ אֶת אוֹתָם הַמֵּתִים שֶׁבָּהֶם הַחוּצָה. זֶהוּ שֶׁכָּתוּב וָאָרֶץ רְפָאִים תַּפִּיל. מַה זֶּה תַּפִּיל? שֶׁתָּקִיא אוֹתָם הַחוּצָה. רְפָאִים, מַה זֶּה רְפָאִים? שֶׁקִּבְּלוּ רְפוּאָה כְּמִקֹּדֶם, וְנִרְפְּאוּ עֲצָמוֹת בַּעֲצָמוֹת, וְאֵלֶּה נִקְרָאִים רְפָאִים.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (בשאר עובדי כוכבים ומזלות) (ישעיה כו) רְפָאִים בַּל יָקוּמוּ? אֶלָּא וַדַּאי כָּל הָעוֹלָם יִתְרַפְּאוּ עַצְמוֹתָם בְּבֵית הַקְּבָרוֹת, אֲבָל מֵהֶם יָקוּמוּ וּמֵהֶם לֹא יָקוּמוּ. וְעַל זֶה כָּתוּב רְפָאִים בַּל יָקוּמוּ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם נְבֵלָתִי יְקוּמוּן. וּבַדָּג הַזֶּה מָצָאנוּ דְבָרִים לִרְפוּאָה שֶׁל כָּל הָעוֹלָם.</p>\n<p>הַדָּג הַזֶּה, כֵּיוָן שֶׁבָּלַע אֶת יוֹנָה, הוּא מֵת, וּבוֹ הָיָה יוֹנָה שְׁלֹשָׁה יָמִים, וְאַחַר כָּךְ חָזַר לַחַיִּים כְּמִקֹּדֶם וְהֵקִיא אֶת יוֹנָה הַחוּצָה, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב וַיִּתְפַּלֵּל יוֹנָה אֶל ה' אֱלֹהָיו מִמְּעֵי הַדָּגָה. כָּתוּב כָּאן הַדָּגָה, וְכָתוּב שָׁם (שמות ז) וְהַדָּגָה אֲשֶׁר בַּיְאֹר מֵתָה, וַהֲרֵי פֵּרְשׁוּהָ. כְּמוֹ זֶה עֲתִידָה אֶרֶץ יִשְׂרָאֵל לְהִתְעוֹרֵר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וָאָרֶץ רְפָאִים תַּפִּיל.</p>\n<p>וַהֲרֵי בֵּאַרְנוּ, שֶׁשִּׁבְעָה דִינִים יַחְלְפוּ עַל הָאָדָם כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה. אֶחָד - אוֹתוֹ דִין עֶלְיוֹן כְּשֶׁיּוֹצֵאת הָרוּחַ מִן הַגּוּף. ב' - כְּשֶׁמַּעֲשָׂיו וּדְבָרָיו הוֹלְכִים לְפָנָיו וּמַכְרִיזִים עָלָיו. ג' - כְּשֶׁנִּכְנָס לַקֶּבֶר. ד' - דִּין הַקֶּבֶר. ה' - דִּין הַתּוֹלַעַת. ו' - דִּין הַגֵּיהִנֹּם. ז' - דִּין הָרוּחַ שֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וְלֹא מוֹצֵאת מְקוֹם מְנוּחָה עַד שֶׁיֻּשְׁלְמוּ מַעֲשָׂיו. מִשּׁוּם זֶה צָרִיךְ אָדָם לְהִתְבּוֹנֵן תָּמִיד בְּמַעֲשָׂיו וִיָשׁוּב לִפְנֵי אֲדוֹנוֹ.</p>\n<p>וּכְשֶׁהִתְבּוֹנֵןֹ דָּוִד הַמֶּלֶךְ בְּדִינֵי הָאָדָם הַלָּלוּ, הִקְדִּים וְאָמַר, (תהלים קד) בָּרְכִי נַפְשִׁי אֶת ה', בְּטֶרֶם תֵּצֵא מִן הָעוֹלָם, בְּעוֹד שֶׁאַתְּ נִמְצֵאת עִם הַגּוּף. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ - הֵם אֶבְרֵי הַגּוּף שֶׁמִּשְׁתַּתְּפִים כְּאֶחָד עִם הָרוּחַ. עַכְשָׁו כְּשֶׁתִּמָּצְאוּ עִמָּהּ, הַקְדִּימוּ לְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ טֶרֶם שֶׁיָּבא זְמַן שֶׁלֹּא תוּכְלוּ לְבָרֵךְ וְלַחֲזֹר בִּתְשׁוּבָה. וְעַל זֶה אָמַר בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. בָּאוּ אוֹתָם הַחֲבֵרִים וְנָשְׁקוּ אֶת רֹאשׁוֹ.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. בּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא בְרָאוֹ אֶלָּא כְּדֵי שֶׁיָּבֹאוּ יִשְׂרָאֵל וִיקַבְּלוּ אֶת הַתּוֹרָה. בַּתּוֹרָה נִבְרָא הָעוֹלָם, וְעַל הַתּוֹרָה הוּא עוֹמֵד. זֶהוּ שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. הַתּוֹרָה הִיא אֹרֶךְ חַיִּים בָּעוֹלָם הַזֶּה, וְאֹרֶךְ הַחַיִּים בָּעוֹלָם הַבָּא.</p>\n<p>וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ הִשְׁתַּדֵּל בְּהֵיכָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֵיכָלוֹ הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא הַתּוֹרָה. וּכְשֶׁאָדָם עוֹסֵק בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד שָׁם וּמַקְשִׁיב לְקוֹלוֹ, כַּכָּתוּב (מלאכי ג) וַיַּקְשֵׁב ה' וַיִּשְׁמָע וְגוֹ'. וְנִצּוֹל הָאָדָם מִשְּׁלֹשָׁה דִינִים: מִדִּין הָעוֹלָם הַזֶּה, וּמִדִּין מַלְאַךְ הַמָּוֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט עָלָיו, וּמִדִּין הַגֵּיהִנֹּם.</p>"],[9522011826,"<p>וַיִּכָּתֵב סֵפֶר זִכָּרוֹן. מִי הוּא? אֶלָּא יֵשׁ סֵפֶר לְמַעְלָה וְיֵשׁ סֵפֶר לְמַטָּה. זִכָּרוֹן - (אות) הַבְּרִית הַקָּדוֹשׁ שֶׁנּוֹטֵל וְכוֹנֵס אֵלָיו אֶת כָּל הַחַיִּים שֶׁלְּמַעְלָה. סֵפֶר זִכָּרוֹן - שְׁתֵּי דְרָגוֹת שֶׁהֵן אַחַת, וְסוֹד זֶה שֵׁם יְהֹוָ\"ה שֵׁם אֶחָד. יְהֹוָ\"ה אֶחָד. וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>מִשּׁוּם שֶׁיֵּשׁ שֵׁם וְיֵשׁ שֵׁם. שֵׁם לְמַעְלָה, שֶׁהוּא נִרְשָׁם (נקרא שם) מִמַּה שֶּׁלֹּא יָדוּעַ וְלֹא נִרְמָז בִּידִיעָה כְּלָל, וְזוֹ נִקְרֵאת נְקֻדָּה עֶלְיוֹנָה. שֵׁם לְמַטָּה, שֶׁנִּקְרָא שֵׁם, מִקְצֵה הַשָּׁמיִם וְעַד קְצֵה הַשָּׁמַיִם, מִשּׁוּם שֶׁקְּצֵה הַשָּׁמַיִם נִקְרָא זִכָּרוֹן. וְהַשֵּׁם הַזֶּה הוּא נְקֻדָּה שֶׁלְּמַטָּה, שֶׁהוּא שֵׁם מֵאוֹתוֹ זִכָּרוֹן, שֶׁהוּא קְצֵה הַשָּׁמַיִם, שֶׁנּוֹטֵל אֶת כָּל הַחַיִּים שֶׁלְּמַעְלָה. וְזֶהוּ קְצֵה הַשָּׁמַיִם שֶׁלְּמַטָּה. וְהַשֵּׁם שֶׁלּוֹ הִיא הַנְּקֻדָּה שֶׁלְּמַטָּה. נְקֻדָּה זוֹ הִיא סֵפֶר שֶׁעוֹמֵד בְּחֶשְׁבּוֹן, וְזֶהוּ וּלְחֹשְׁבֵי שְׁמוֹ. הַסֵּפֶר שֶׁאָמַרְנוּ וְשֵׁם - דָּבָר אֶחָד הוּא בְּכָל הַצְּדָדִים.</p>\n<p>הַנְּקֻדָּה הַזּוֹ, מִשּׁוּם שֶׁהִיא עוֹמֶדֶת בָּאֶמְצַע, הִיא עֶלְיוֹנָה עַל כָּל הַנֶּאֱחָזִים בָּהּ. שִׁשָּׁה צְדָדִים אֲחוּזִים בַּסֵפֶר הָעֶלְיוֹן, וְהוּא עֶלְיוֹן עֲלֵיהֶם. שִׁשָּׁה צְדָדִים נֶאֱחָזִים בַּסֵּפֶר הַתַּחְתּוֹן, וְהוּא עֶלְיוֹן עֲלֵיהֶם. וְעַל זֶה סֵפֶר עֶלְיוֹן וְסֵפֶר תַּחְתּוֹן, וְהַכֹּל נִקְרָא תּוֹרָה.</p>\n<p>מַה בֵּין זֶה לָזֶה? אֶלָּא, סֵפֶר עֶלְיוֹן הוּא תּוֹרָה שֶׁבִּכְתָב, מִשּׁוּם שֶׁהִיא סְתוּמָה וְלֹא עוֹמֶדֶת, אֶלָּא רַק בִּכְתָב, שֶׁשָּׁם הוּא הַמָּקוֹם לְהִתְגַּלּוֹת לְמַטָּה. וּמִי הוּא הָעוֹלָם הַבָּא? סֵפֶר הַתַּחְתּוֹן, זוֹ תּוֹרָה שֶׁנִּקְרֵאת תּוֹרָה שֶׁבְּעַל פֶּה. וּמִי הוּא עַל פֶּה? אֵלּוּ הַמֶּרְכָּבוֹת שֶׁל מַטָּה, שֶׁהִיא עוֹמֶדֶת עֲלֵיהֶן. וּמִשּׁוּם שֶׁאֵינָן בִּכְלָל שֶׁל כְּתִיבָה שֶׁלְּמַעְלָה, נִקְרָאִים עַל פֶּה.</p>\n<p>וְתוֹרָה זוֹ עוֹמֶדֶת עַל פֶּה, מִשּׁוּם שֶׁכָּתוּב (בראשית ב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. וְתוֹרָה הָעֶלְיוֹנָה, אַף עַל גַּב שֶׁהִיא עוֹמֶדֶת לְמַעְלָה, לֹא נִקְרֵאת עַל הַכְּתָב, אֶלָּא שֶׁבִּכְתָב, שֶׁעוֹמֶדֶת בִּכְתָב, וְאוֹתוֹ הַכְּתָב נַעֲשֶׂה הֵיכָל אֵלֶיהָ, וְהִיא עוֹמֶדֶת בְּתוֹךְ אוֹתוֹ הַהֵיכָל וְנִשְׁמֶרֶת שָׁם. וּמִשּׁוּם כָּךְ נִקְרֵאת תּוֹרָה שֶׁבִּכְתָב וְלֹא עַל כְּתָב.</p>\n<p>אֲבָל הַתּוֹרָה שֶׁלְּמַטָּה הִיא עוֹמֶדֶת עַל מַרְכְּבוֹתֶיהָ, וְנִקְרֵאת עַל פֶּה, שֶׁעוֹמֶדֶת עֲלֵיהֶן. וּמִשּׁוּם שֶׁלֹּא נֶחְשֶׁבֶת (נתנה) מִבִּפְנִים מִכְּלָל שֶׁל כְּתִיבָה, לֹא נַעֲשׂוּ הֵיכָל לַנְּקֻדָּה הַזּוֹ כְּמוֹ אוֹתָהּ נְקֻדָּה עֶלְיוֹנָה. וּמִשּׁוּם שֶׁעוֹמֶדֶת עֲלֵיהֶן נִקְרֵאת תְּרוּמָה.</p>"],[9522011827,"<p>עוֹד שָׁמַעְתִּי מִן הַמְּנוֹרָה הַקְּדוֹשָׁה. תְּרוּמָה, מַה זֶּה תְּרוּמָה? כְּמוֹ שֶׁבֵּאַרְנוּ, שְׁנַיִם מִמֵּאָה. בֹּא וּרְאֵה, כָּל הַדְּרָגוֹת הַלָּלוּ הַקְּדוֹשׁוֹת שֶׁבְּסוֹד הָאֱמוּנָה שֶׁנִּגְלָה בָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא, הֵן עֶשֶׂר דְּרָגוֹת, וְהֵן עֶשֶׂר אֲמִירוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ. וְאֵלּוּ הָעֶשֶׂר עוֹלִים לְמֵאָה. וּכְשֶׁאָנוּ צְרִיכִים הַנְּקֻדָּה הַתַּחְתּוֹנָה הַזּוֹ לְהָרִים אוֹתָהּ, אָסוּר לָנוּ לְקַחְתָּהּ לְבַדָּהּ, אֶלָּא אוֹתָהּ עִם בַּעְלָהּ, וְהֵם הַשְּׁנַיִם מֵהַמֵּאָה שֶׁאָמַרְנוּ, מִשּׁוּם שֶׁאֵין צָרִיךְ לְהַפְרִידָם כְּלָל, אֶלָּא לְיַחֲדָהּ עִם בַּעְלָהּ. וְלָכֵן נִקְרֵאת תְּרוּמָה בִּכְלָל אֶחָד.</p>"],[9522011828,"<p>וּבֹא רְאֵה, בְּכָל יוֹם הַכָּרוֹז קוֹרֵא: כָּל בְּנֵי הָעוֹלָם, בָּכֶם עוֹמֵד הַדָּבָר הַזֶּה. וְזֶהוּ קְחוּ מֵאִתְּכֶם תְּרוּמָה לַה'. וְאִם תֹּאמְרוּ שֶׁהַדָּבָר קָשֶׁה עֲלֵיכֶם - כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ.</p>\n<p>מַה זֶּה יְבִיאֶהָ? אֶלָּא מִכָּאן לָמַדְנוּ אֶת סוֹד הַתְּפִלָּה, שֶׁאָדָם שֶׁפּוֹחֵד מֵרִבּוֹנוֹ וּמְכַוֵּן לִבּוֹ וּרְצוֹנוֹ בַּתְּפִלָּה, מְתַקֵּן תִּקּוּן הָעֶלְיוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ. בָּרִאשׁוֹנָה בְּשִׁירוֹת וְתִשְׁבָּחוֹת שֶׁאוֹמְרִים הַמַּלְאָכִים הָעֶלְיוֹנִים לְמַעְלָה. וּבְאוֹתָהּ עֲרִיכַת הַתִּשְׁבָּחוֹת שֶׁאוֹמְרִים יִשְׂרָאֵל לְמַטָּה, הִיא מְקַשֶּׁטֶת אֶת עַצְמָהּ וּמִתְתַּקֶּנֶת בְּתִקּוּנֶיהָ כְּמוֹ אִשָּׁה שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ.</p>\n<p>וּבְסִדּוּר הַתְּפִלָּה, בְּאוֹתוֹ הַתִּקּוּן שֶׁל תְּפִלַּת מְיֻשָּׁב, מַתְקִינִים אֶת עַלְמוֹתֶיהָ וְכָל אֵלּוּ שֶׁלָּהּ. וּמִתְקַשְּׁטוֹת כָּל עַלְמוֹתֶיהָ, וְאַחַר כָּךְ הַכֹּל מְתֻקָּנִים וּמְסֻדָּרִים. וּכְשֶׁמַּגִּיעִים לֶאֱמֶת וְיַצִּיב, אָז הַכֹּל מְתֻקָּנִים, הִיא וְעַלְמוֹתֶיהָ, עַד שֶׁמַּגִּיעִים לְגָאַל יִשְׂרָאֵל, וְאָז צָרִיךְ לַעֲמֹד הַכֹּל עַל מְקוֹמָם.</p>\n<p>מִשּׁוּם שֶׁכַּאֲשֶׁר מַגִּיעַ אָדָם לֶאֱמֶת וְיַצִּיב וְהַכֹּל מְתֻקָּן, עַלְמוֹתֶיהָ נוֹטְלוֹת אוֹתָהּ, וְהִיא נוֹטֶלֶת אֶת עַצְמָהּ לַמֶּלֶךְ הָעֶלְיוֹן. כֵּיוָן שֶׁמַּגִּיעִים לְגָאַל יִשְׂרָאֵל, אֲזַי הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן נוֹסֵעַ בְּדַרְגוֹתָיו וְיוֹצֵא לְקַבֵּל אוֹתָהּ.</p>\n<p>וְאָנוּ מִלִּפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן צְרִיכִים לַעֲמֹד עַל מְקוֹמֵנוּ בְּאֵימָה בִּרְעָדָה, שֶׁהֲרֵי אָז הוּא מוֹשִׁיט יְמִינוֹ אֵלֶיהָ, וְאַחַר כָּךְ אֶת שְׂמֹאלוֹ שֶׁשָּׂם לָהּ תַּחַת רֹאשָׁהּ, וְאַחַר כָּךְ מִתְחַבְּקִים שְׁנֵיהֶם כְּאֶחָד בִּנְשִׁיקָה. וְאֵלֶּה הֵן הַשָּׁלֹשׁ הָרִאשׁוֹנוֹת, וְצָרִיךְ אָדָם לָשִׂים לִבּוֹ וּרְצוֹנוֹ וּלְכַוֵּן בְּכָל הַתִּקּוּנִים וְהַסִּדּוּרִים הַלָּלוּ שֶׁל הַתְּפִלָּה, פִּיו וְלִבּוֹ וּרְצוֹנוֹ כְּאֶחָד.</p>\n<p>עַכְשָׁו שֶׁהַמֶּלֶךְ הָעֶלְיוֹן וְהַגְּבִירָה הֵם בְּחִבּוּר אֶחָד בְּשִׂמְחָה בְּאוֹתָן נְשִׁיקוֹת - מִי שֶׁצָּרִיךְ לְבַקֵּשׁ בַּקָּשׁוֹת, יְבַקֵּשׁ, שֶׁהֲרֵי אָז שְׁעַת רָצוֹן הִיא. כֵּיוָן שֶׁשּׁוֹאֵל אָדָם שְׁאֵלוֹתָיו מִלִּפְנֵי הַמֶּלֶךְ וְהַגְּבִירָה, אָז יַתְקִין עַצְמוֹ בִּרְצוֹנוֹ וְלִבּוֹ לְשָׁלֹשׁ אֲחֵרוֹת לְעוֹרֵר שִׂמְחָה שֶׁבַּסֵּתֶר, שֶׁהֲרֵי מֵאֵלּוּ הַשָּׁלֹשׁ הוּא מִתְבָּרֵךְ בִּדְבֵקוּת אַחֶרֶת. וְיַתְקִין אָדָם אֶת עַצְמוֹ לָצֵאת מִפְּנֵיהֶם, וּלְהַנִּיחָם בְּשִׂמְחָה גְּנוּזָה שֶׁל אֵלּוּ הַשָּׁלֹשׁ. וְעִם כָּל זֶה, שֶׁיִּהְיֶה רְצוֹנוֹ שֶׁיִּתְבָּרְכוּ הַתַּחְתּוֹנִים מֵאוֹתָן בְּרָכוֹת שֶׁל שִׂמְחָה נִסְתֶּרֶת.</p>\n<p>וְאָז צָרִיךְ לִפֹּל עַל פָּנָיו וְלִמְסֹר אֶת נַפְשׁוֹ בְּשָׁעָה שֶׁהִיא לוֹקַחַת אֶת הַנְּפָשׁוֹת וְהָרוּחוֹת. אָז זוֹ הַשָּׁעָה לִמְסֹר נַפְשׁוֹ בְּתוֹךְ אוֹתָן נְפָשׁוֹת שֶׁהִיא לוֹקַחַת, שֶׁהֲרֵי אָז צְרוֹר הַחַיִּים הוּא כָּרָאוּי.</p>\n<p>דָּבָר זֶה שָׁמַעְתִּי בַּסּוֹדוֹת שֶׁל הַמְּנוֹרָה הַקְּדוֹשָׁה, וְלֹא נִתְּנָה לִי רְשׁוּת לְגַלּוֹת, פְּרָט לָכֶם חֲסִידִים עֶלְיוֹנִים. שֶׁאִם בְּאוֹתָהּ שָׁעָה שֶׁהִיא לוֹקַחַת נְפָשׁוֹת וְרוּחוֹת בְּרָצוֹן שֶׁל דְּבֵקוּת אַחַת, הוּא יָשִׂים לִבּוֹ וּרְצוֹנוֹ לָזֶה, וְנוֹתֵן נַפְשׁוֹ בִּדְבֵקוּת בְּאוֹתוֹ הָרָצוֹן לְהַכְלִילָהּ בְּאוֹתָהּ הַדְּבֵקוּת. אִם מִתְקַבֶּלֶת בְּאוֹתָהּ שָׁעָה בְּאוֹתוֹ הָרָצוֹן שֶׁל אוֹתָן נְפָשׁוֹת רוּחוֹת וּנְשָׁמוֹת שֶׁהִיא לוֹקַחַת, זֶהוּ אָדָם שֶׁנִּצְרָר בִּצְרוֹר הַחַיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וְעוֹד, שֶׁצָּרִיךְ לְהִכָּלֵל מִכָּל הַצְּדָדִים, הַמֶּלֶךְ וְהַגְּבִירָה, מִלְמַעְלָה וּמִלְּמַטָּה, וּלְהִתְעַטֵּר בַּנְּשָׁמוֹת בְּכָל הַצְּדָדִים. מִתְעַטֶּרֶת בַּנְּשָׁמוֹת מִלְמַעְלָה, וּמִתְעַטֶּרֶת בַּנְּשָׁמוֹת מִלְּמַטָּה. וְאִם אָדָם יְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לְכָל זֶה וְיִמְסֹר נַפְשׁוֹ מִלְּמַטָּה בִּדְבֵקוּת וּבְרָצוֹן כְּמוֹ שֶׁנֶּאֱמַר, אֲזַי הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ שָׁלוֹם לְמַטָּה, כְּמוֹ שֶׁאוֹתוֹ הַשָּׁלוֹם שֶׁלְּמַעְלָה, לְאוֹתוֹ שֶׁמְּבָרֵךְ אֶת הַגְּבִירָה וּמַכְלִיל אוֹתָהּ וּמְעַטֵּר אוֹתָהּ בְּכָל הָעֲטָרוֹת.</p>\n<p>אַף כָּךְ, לָאִישׁ הַזֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ שָׁלוֹם לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שופטים ו) וַיִּקְרָא לוֹ ה' שָׁלוֹם. וְכָל יָמָיו כָּךְ קוֹרְאִים לוֹ לְמַעְלָה - שָׁלוֹם, מִשּׁוּם שֶׁהִכְלִיל וְעִטֵּר אֶת הַגְּבִירָה לְמַטָּה כְּמוֹ שֶׁאוֹתוֹ שָׁלוֹם לְמַעְלָה.</p>\n<p>וְכַאֲשֶׁר אוֹתוֹ הָאָדָם מִסְתַּלֵּק מִן הָעוֹלָם הַזֶּה, נִשְׁמָתוֹ עוֹלָה וּבוֹקַעַת אֶת כָּל אוֹתָם הָרְקִיעִים וְאֵין מוֹחֶה בְּיָדָהּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לָהּ וְאוֹמֵר, (ישעיה נז) יָבוֹא שָׁלוֹם. וְהַשְּׁכִינָה אוֹמֶרֶת, יָנוּחוּ עַל מִשְׁכְּבוֹתָם וְגוֹ'. וְיִפְתְּחוּ לָהּ שְׁלֹשָׁה עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר, וְלֹא יִהְיֶה מִי שֶׁיִּמְחֶה בְיָדָהּ. וְעַל כָּךְ, אַשְׁרֵי מִי שֶׁיָּשִׂים לִבּוֹ וּרְצוֹנוֹ לָזֶה, וְעַל זֶה כָּתוּב, כֹּל נְדִיב לִבּוֹ יְבִיאֶהָ אֵת תְּרוּמַת ה' לַמֶּלֶךְ הָעֶלְיוֹן, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>הֵרִים רַבִּי אַבָּא אֶת קוֹלוֹ וְאָמַר, אוֹי, רַבִּי שִׁמְעוֹן, אַתָּה בַּחַיִּים, וַאֲנִי בּוֹכֶה עָלֶיךְ. לֹא עָלֶיךְ אֲנִי בּוֹכֶה, אֶלָּא אֲנִי בּוֹכֶה עַל הַחֲבֵרִים וּבוֹכֶה עַל הָעוֹלָם. רַבִּי שִׁמְעוֹן הוּא כְּמוֹ מְנוֹרָה שֶׁל נֵר שֶׁדּוֹלֵק לְמַעְלָה וְדוֹלֵק לְמַטָּה, וּבָאוֹר שֶׁדּוֹלֵק לְמַטָּה מְאִירִים לְכָל הָעוֹלָם. (מאיר למעלה) אוֹי לָעוֹלָם כְּשֶׁיִּסְתַּלֵּק הָאוֹר שֶׁלְּמַטָּה לָאוֹר שֶׁלְּמַעְלָה, מִי יָאִיר לָנוּ אֶת אוֹר הַתּוֹרָה לָעוֹלָם? קָם רַבִּי אַבָּא וְנָשַׁק אֶת רַבִּי חִיָּיא. אָמַר לוֹ, הַדְּבָרִים הַלָּלוּ הָיוּ תַחַת יָדְךְ, וְעַל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁלָחַנִי עַד לְכָאן לְהִתְחַבֵּר עִמָּכֶם. אַשְׁרֵי חֶלְקִי.</p>\n<p>רַבִּי יוֹסֵי פָּתַח פָּסוּק אַחֲרָיו וְאָמַר, וְכָל חֲכַם לֵב בָּכֶם יָבֹאוּ וְיַעֲשׂוּ וְגוֹ'. פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, (דברים א) הָבוּ לָכֶם אֲנָשִׁים חֲכָמִים וּנְבֹנִים, בָּחַן אֶת כָּל יִשְׂרָאֵל וְלֹא מָצָא נְבוֹנִים. זֶהוּ שֶׁכָּתוּב וָאֶקַּח אֶת רָאשֵׁי שִׁבְטֵיכֶם אֲנָשִׁים חֲכָמִים וִידֻעִים, וְאִלּוּ נְבוֹנִים לֹא כָתוּב. וְאִם תֹּאמַר שֶׁנָּבוֹן הִיא דַּרְגָּה יוֹתֵר עֶלְיוֹנָה מֵחָכָם - כָּךְ זֶה וַדַּאי!</p>\n<p>מַה בֵּין זֶה לָזֶה? חָכָם, הֲרֵי פֵּרְשׁוּהָ, שֶׁאֲפִלּוּ תַּלְמִיד הַמַּחְכִּים אֶת רַבּוֹ נִקְרָא חָכָם. חָכָם, שֶׁיּוֹדֵעַ לְעַצְמוֹ כָּל מַה שֶּׁצָּרִיךְ. בְּנָבוֹן יֵשׁ כַּמָּה דְרָגוֹת - שֶׁמִּסְתַּכֵּל בַּכֹּל, וְיוֹדֵעַ בְּשֶׁלּוֹ וּבַאֲחֵרִים, וְסִימָנְךְ - (משלי יב) יוֹדֵעַ צַדִּיק נֶפֶשׁ בְּהֶמְתּוֹ. (שמואל ב כג) צַדִּיק מוֹשֵׁל יִרְאַת אֱלֹהִים. וְכָאן חֲכַם לֵב דַּוְקָא. בַּלֵּב חָכָם, וְלֹא בְמָקוֹם אַחֵר, מִשּׁוּם שֶׁעוֹמֵד בַּלֵּב, וְנָבוֹן לְמַעְלָה וּלְמַטָּה, מִסְתַּכֵּל בְּעַצְמוֹ וּבְשֶׁל אֲחֵ רִים.</p>"],[9522011829,"<p>פָּתַח וְאָמַר, (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה וְגוֹ'. כָּאן בַּתְּפִלָּה שֶׁצָּרִיךְ אָדָם לְהִתְפַּלֵּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִיא עֲבוֹדָה אַחַת גְּדוֹלָה וְנִכְבָּדָה מֵאוֹתָן הָעֲבוֹדוֹת שֶׁל רִבּוֹנוֹ. בֹּא וּרְאֵה, יֵשׁ עֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעוֹמֶדֶת בְּמַעֲשֶׂה, שֶׁהִיא עֲבוֹדָה שֶׁעוֹמֶדֶת בְּמַעֲשֵׂה הַגּוּף וְהִיא עֲבוֹדָה. וְיֵשׁ עֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִיא עֲבוֹדָה יוֹתֵר פְּנִימִית, שֶׁהִיא עִקַּר הַכֹּל, וְעוֹמֶדֶת בְּאוֹתָהּ עֲבוֹדָה פְּנִימִית שֶׁהִיא עִקַּר הַכֹּל.</p>\n<p>בַּגּוּף יֵשׁ שְׁנֵים עָשָׂר אֵיבָרִים שֶׁעוֹמְדִים בְּמַעֲשֵׂה הַגּוּף, כְּמוֹ שֶׁבֵּאַרְנוּ, וְאֵלּוּ הֵם אֶבְרֵי הַגּוּף וַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהַמַּעֲשֶׂה עוֹמֵד בָּהֶם. מִשּׁוּם שֶׁעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא בִּשְׁנֵי צְדָדִים, בְּאֶבְרֵי הַגּוּף הַחִיצוֹנִיִּים, וְיֵשׁ שְׁנֵים עָשָׂר אֵיבָרִים אֲחֵרִים פְּנִימִיִּים לִפְנִים מֵהַגּוּף. וְהֵם תִּקּוּנִים פְּנִימִיִּים לִפְנִים מֵהַגּוּף לְתַקֵּן בָּהֶם הַתִּקּוּן שֶׁל הָרוּחַ, שֶׁהִיא עֲבוֹדָה נִכְבָּדָה פְּנִימִית שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ בְּתוֹךְ הַסּוֹדוֹת הַפְּנִימִיִּים שֶׁאָמַר רַבִּי שִׁמְעוֹן, וְהֵם סוֹד הַחָכְמָה הָעֶלְיוֹנָה, וְנוֹדְעוּ בֵּין הַחֲבֵרִים, אַשְׁרֵי חֶלְקָם.</p>\n<p>תְּפִלַּת הָאָדָם הִיא עֲבוֹדַת הָרוּחַ, וְהִיא עוֹמֶדֶת בְּסוֹדוֹת עֶלְיוֹנִים, וַאֲנָשִׁים לֹא יוֹדְעִים, שֶׁהֲרֵי תְּפִלַּת הָאָדָם בּוֹקַעַת אֲוִירִים וּבוֹקַעַת רְקִיעִים וּפוֹתַחַת פְּתָחִים וְעוֹלָה לְמַעְלָה.</p>\n<p>בְּשָׁעָה שֶׁמֵּאִיר הָאוֹר וְנִפְרָד הָאוֹר מִן הַחֲשֵׁכָה, אֲזַי הַכָּרוֹז הוֹלֵךְ בְּכָל הָרְקִיעִים: הִתְתַּקְּנוּ בַּעֲלֵי הַפְּתָחִים, בַּעֲלֵי הַהֵיכָלוֹת, כָּל אֶחָד וְאֶחָד עַל מִשְׁמַרְתּוֹ, מִשּׁוּם שֶׁאוֹתָם שֶׁשּׁוֹלְטִים בַּיּוֹם אֵינָם שׁוֹלְטִים בַּלַּיְלָה. וּכְשֶׁנִּכְנָס הַלַּיְלָה, מָעֳבָרִים שַׁלִּיטֵי הַיּוֹם, וּמִתְמַנִּים שַׁלִּיטִים אֲחֵרִים שֶׁשּׁוֹלְטִים בַּלַּיְלָה, וּמִתְחַלְּפִים אֵלֶּה בְּאֵלֶּה.</p>\n<p>וְסוֹד זֶה - (בראשית א) אֶת הַמָּאוֹר הַגָּדֹל לְמֶמְשֶׁלֶת הַיּוֹם וְגוֹ'. וּמֶמְשֶׁלֶת הַיּוֹם וּמֶמְשֶׁלֶת הַלַּיְלָה, יֵשׁ שַׁלִּיטִים שֶׁמְּמֻנִּים בַּיּוֹם, וְיֵשׁ שַׁלִּיטִים שֶׁמְּמֻנִּים בַּלַּיְלָה. וְאֵלּוּ נִקְרְאוּ מֶמְשֶׁלֶת הַיּוֹם, וְאֵלּוּ נִקְרָאִים מֶמְשֶׁלֶת הַלַּיְלָה.</p>\n<p>כְּשֶׁנִּכְנָס הַלַּיְלָה, יוֹצֵא כָּרוֹז: הִתְתַּקְּנוּ שַׁלִּיטֵי הַלַּיְלָה כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. וּכְשֶׁמֵּאִיר הַיּוֹם, כָּרוֹז יוֹצֵא: הִתְתַּקְּנוּ שַׁלִּיטֵי הַיּוֹם כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. (אז מעברים שליטי הלילה ומתמגים שליטי היום) וּכְשֶׁהַכָּרוֹז מַכְרִיז, אָז כֻּלָּם, כָּל אֶחָד וְאֶחָד נִפְקָד עַל אוֹתוֹ מָקוֹם שֶׁרָאוּי לוֹ. אֲזַי הַשְּׁכִינָה מַקְדִּימָה וְיוֹרֶדֶת, וְיִשְׂרָאֵל נִכְנָסִים לְבֵית הַכְּנֶסֶת לְשַׁבֵּחַ אֶת רִבּוֹנָם וּפוֹתְחִים בְּשִׁירוֹת וְתִשְׁבָּחוֹת.</p>\n<p>שֶׁצָרִיךָ לוֹ לָאָדָם, שֶׁכֵּיוָן שֶׁהִתְקִין עַצְמוֹ לַעֲבוֹדַת הַמַּעֲשֶׂה בְּתִקּוּנֵי מִצְוָה וּקְדֻשָּׁה, לְיַחֵד לִבּוֹ בַּתִּקּוּן שֶׁל הָעֲבוֹדָה הַפְּנִימִית שֶׁל אֲדוֹנוֹ, וְלָשִׂים אֶת לִבּוֹ וּרְצוֹנוֹ בְּאוֹתָהּ עֲבוֹדָה שֶׁל אוֹתָם דְּבָרִים (שאומר), שֶׁהֲרֵי הַדִּבּוּר עוֹלֶה.</p>\n<p>וְאוֹתָם הַמְמֻנִּים שֶׁעוֹמְדִים בָּאֲוִיר, הִתְמַנּוּ לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. לְצַד מִזְרָח הִתְמַנָּה מְמֻנֶּה אֶחָד שֶׁעוֹמֵד בָּאֲוִיר לְאוֹתוֹ צַד, וּשְׁמוֹ גְּזַרְדִּיָּ\"א, וְעִמּוֹ שָׂרִים מְמֻנִּים אֲחֵרִים, שֶׁהֵם מְחַכִּים לְאוֹתוֹ דִבּוּר שֶׁל תְּפִלָּה, וְעוֹלֶה בָּאֲוִיר בְּאוֹתוֹ צַד, וְנוֹטֵל אוֹתוֹ אוֹתוֹ הַמְמֻנֶּה.</p>\n<p>אִם הַדִּבּוּר הַזֶּה הוּא כָּרָאוּי, וְכָל אוֹתָם שָׂרִים נוֹשְׁקִים אֶת אוֹתוֹ דִבּוּר וְעוֹלִים עִמּוֹ עַד לְאוֹתוֹ אֲוִיר שֶׁל הָרָקִיעַ לְמַעְלָה, שֶׁשָּׁם מְמֻנִּים שָׂרִים אֲחֵרִים - בְּשָׁעָה שֶׁנּוֹשְׁקִים אֶת אוֹתוֹ דִבּוּר, פּוֹתְחִים וְאוֹמְרִים: אַשְׁרֵיכֶם יִשְׂרָאֵל שֶׁאַתֶּם יוֹדְעִים לְעַטֵּר אֶת אֲדוֹנְכֶם בַּעֲטָרוֹת קְדוֹשׁוֹת. אַשְׁרֵי הַפֶּה שֶׁדִּבּוּר שֶׁל הָעֲטָרָה הַזּוֹ יָצָא מִמֶּנּוּ.</p>\n<p>וְאָז פּוֹרְחוֹת הָאוֹתִיּוֹת שֶׁעוֹמְדוֹת בָּאֲוִיר שֶׁבַּשֵּׁם הַקָּדוֹשׁ שֶׁל שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת, שֶׁאוֹתוֹ שֵׁם שׁוֹלֵט בָּאֲוִיר, וְזֶהוּ שֵׁם שֶׁהָיָה טָס בּוֹ אֵלִיָּהוּ עַד שֶׁעָלָה לַשָּׁמַיִם. וְזֶהוּ מַה שֶּׁאָמַר עוֹבַדְיָה לְאֵלִיָּהוּ, (מלכים א יח) וְרוּחַ ה' יִשָּׂאֲךְ. מִשּׁוּם שֶׁבַּשֵּׁם הַזֶּה הָיָה טָס בּוֹ אֵלִיָּהוּ בָּאֲוִיר, וְזֶהוּ הַשֵּׁם שֶׁשּׁוֹלֵט בָּאֲוִיר.</p>\n<p>וְאוֹתָן הָאוֹתִיּוֹת פּוֹרְחוֹת וְעוֹלוֹת בְּאוֹתוֹ דִבּוּר, וְאוֹתוֹ הַמְמֻנֶּה שֶׁמַּפְתְּחוֹת הָאֲוִיר בְּיָדוֹ, וְכָל אוֹתָם הַמְמֻנִּים הָאֲחֵרִים, כֻּלָּם עוֹלִים בּוֹ עַד לָרָקִיעַ, וְנִמְסָר בְּיַד מְמֻנֶּה אַחֵר לְהַעֲלוֹתוֹ לְמַעְלָה.</p>\n<p>לְצַד דָּרוֹם יֵשׁ מְמֻנֶּה אַחֵר שֶׁשּׁוֹלֵט בָּאֲוִיר לְאוֹתוֹ הַצַּד, וְכַמָּה מְמֻנִּים וְשָׂרִים אֲחֵרִים עִמּוֹ, וּשְׁמוֹ פְּסַגְנִיָּ\"ה, וּבוֹ נֶאֱחָזִים (ולו נמסרו) מַפְתְּחוֹת הָאֲוִיר שֶׁל אוֹתוֹ צַד. וְכָל אוֹתָם בַּעֲלֵי צָרָה שֶׁמִּתְפַּלְלִים תְּפִלָּה לַאֲדוֹנָם מִתּוֹךְ צָרָה, מִתּוֹךְ שִׁבְרוֹן הַלֵּב - אִם אוֹתוֹ הַדִּבּוּר כָּרָאוּי, הוּא עוֹלֶה לָאֲוִיר בְּאוֹתוֹ צַד, וְהַמְמֻנֶּה הַזֶּה נוֹטֵל אוֹתוֹ וְנוֹשֵׁק אוֹתוֹ (משום שעלה באותו צד). וּכְשֶׁנּוֹשֵׁק אוֹתוֹ, פּוֹתֵחַ וְאוֹמֵר: הַקָּדוֹשׁ בָּרוּךְ הוּא יָחוּס כְּנֶגְדְּךְ (ועליך), וּבִשְׁבִילְךְ יִתְמַלֵּא בְרַחֲמִים.</p>\n<p>עוֹלִים עִמָּהּ כָּל אוֹתָם מְמֻנִּים קְדוֹשִׁים וְכָל אוֹתָם שָׂרִים שֶׁל אוֹתוֹ הַצַּד, וּפוֹרְחוֹת הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהֵן אַרְבַּע אוֹתִיּוֹת שֶׁמִּתְעַטְּרוֹת וְשׁוֹלְטוֹת בְּאוֹתוֹ צַד שֶׁל הָאֲוִיר, וְעוֹלִים בְּאוֹתוֹ הַצַּד שֶׁל הָאֲוִיר עַד לָרָקִיעַ, עַד לְאוֹתוֹ הַמְמֻנֶּה שֶׁל הָרָקִיעַ שֶׁשּׁוֹלֵט בְּאוֹתוֹ הַצַּד.</p>\n<p>לְצַד צָפוֹן יֵשׁ מְמֻנֶּה אַחֵר, וְעִמּוֹ כַּמָּה שָׂרִים מְמֻנִּים שֶׁשּׁוֹלְטִים בָּאֲוִיר, וּשְׁמוֹ שֶׁל אוֹתוֹ מְמֻנֶּה פְּתַחְיָ\"ה, וְזֶהוּ שֶׁהִתְמַנָּה בָּאֲוִיר שֶׁל אוֹתוֹ צַד, וְכָל אוֹתָם שֶׁמִּתְפַּלְלִים תְּפִלּוֹת עַל שׂוֹנְאִים שֶׁמְּצִיקִים לָהֶם, וּכְשֶׁדִּבּוּר שֶׁל אוֹתָהּ תְּפִלָּה עוֹלֶה לָאֲוִיר בְּאוֹתוֹ צַד - אִם הוּא צַדִּיק, נוֹטֵל אוֹתוֹ הַמְמֻנֶּה הַזֶּה וְנוֹשֵׁק אוֹתוֹ.</p>\n<p>אֲזַי מִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁיּוֹצֵאת מִתּוֹךְ הַתְּהוֹם שֶׁבְּצַד הַצָּפוֹן, וְאוֹתָהּ רוּחַ קוֹרֵאת בְּכָל אוֹתָם הָאֲוִירִים, וְכֻלָּם נוֹטְלִים אוֹתוֹ דִבּוּר וּמַעֲלִים אוֹתוֹ עַד לָרָקִיעַ וְנוֹשְׁקִים אוֹתוֹ, וּפוֹתְחִים וְאוֹמְרִים: רִבּוֹנְךְ יַפִּיל שׂוֹנַאֲךְ לְפָנֶיךְ.</p>\n<p>וְהוֹלֵךָ וְעוֹלֶה וּבוֹקֵעַ רְקִיעִים (אוירים). עַד שֶׁעוֹלִים עִמּוֹ לָרָקִיעַ הָרִאשׁוֹן, עוֹלָה הַתְּפִלָּה וּמַגִּיעָה לִמְמֻנֶּה אֶחָד שֶׁהִתְמַנָּה לְצַד מַעֲרָב, וְשָׁם עוֹמְדִים תִּשְׁעָה פְתָחִים, שֶׁבָּהֶם עוֹמְדִים כַּמָּה שָׂרִים וְכַמָּה מְמֻנִּים, וַעֲלֵיהֶם מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ זְבוּלִיאֵ\"ל.</p>\n<p>וְזְהִוּ שֶׁרוֹצֶה לְשַׁמֵּשׁ בָּרָקִיעַ הַזֶּה בַּיּוֹם, וְלֹא נִתֶּנֶת לוֹ רְשׁוּת, עַד שֶׁעוֹלֶה אוֹר הַלְּבָנָה, וְאָז הוּא מוֹצִיא כָּל אוֹתָם הַחֲיָלוֹת וְכָל אוֹתָם מְמֻנִּים. וּכְשֶׁמֵּאִיר הַיּוֹם, נִכְנָסִים כֻּלָּם לְפֶתַח אֶחָד, שֶׁהֵם תִּשְׁעָה פְתָחִים, שֶׁהוּא פֶּתַח עֶלְיוֹן עַל כֻּלָּם. וּכְשֶׁהַתְּפִלָּה עוֹלָה, הִיא נִכְנֶסֶת בְּאוֹתוֹ פֶּתַח, וְכָל הַשָּׂרִים וְכָל הַמְמֻנִּים יוֹצְאִים מֵאוֹתוֹ פֶתַח. וַעֲלֵיהֶם זְבוּלִיאֵ\"ל, אוֹתוֹ מְמֻנֶּה גָּדוֹל, וְיוֹצְאִים כֻּלָּם וְנוֹשְׁקִים אוֹתוֹ, וּמַגִּיעִים עִמּוֹ עַד לָרָקִיעַ הַשֵּׁנִי.</p>\n<p>(ברקיע השני עולה התפלה עד אותו רקיע, ונפתחים) וּכְשֶׁעוֹלָה הַתְּפִלָּה עַד לְאוֹתוֹ רָקִיעַ, נִפְתָּחִים שְׁנֵים עָשָׂר שַׁעֲרֵי אוֹתוֹ הָרָקִיעַ, וּבְאוֹתוֹ הַשַּׁעַר הַשְּׁנֵים עָשָׂר עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ עָנָאֵ\"ל, וְזֶה מְמֻנֶּה עַל כַּמָּה חֲיָלוֹת, עַל כַּמָּה מַחֲנוֹת, וּכְשֶׁתְּפִלָּה עוֹלָה, עוֹמֵד הַמְמֻנֶּה הַזֶּה וּמַכְרִיז עַל כָּל אוֹתָם פְּתָחִים וְאוֹמֵר: (ישעיה כו) פִּתְחוּ שְׁעָרִים וְגוֹ', וְכָל הַשְּׁעָרִים נִפְתָּחִים, וְנִכְנֶסֶת הַתְּפִלָּה לְכָל אוֹתָם הַפְּתָחִים.</p>\n<p>וְאָז מִתְעוֹרֵר מְמֻנֶּה אֶחָד זָקֵן לְיָמִים שֶׁעוֹמֵד לְצַד דָּרוֹם, שֶׁשְּׁמוֹ עַזְרִיאֵ\"ל הַזָּקֵן, וְלִפְעָמִים הוּא נִקְרָא מַחֲנִיאֵ\"ל, מִשּׁוּם שֶׁהִתְמַנָּה עַל שִׁשִּׁים רִבּוֹא מַחֲנוֹת, וְכֻלָּם בַּעֲלֵי כְנָפַיִם, בַּעֲלֵי מַחֲנוֹת, מְלֵאִים עֵינַיִם. וְאֶצְלָם עוֹמְדִים אוֹתָם מַחֲנוֹת בַּעֲלֵי אָזְנַיִם. וְנִקְרָאִים אָזְנַיִם, מִשּׁוּם שֶׁהֵם מַקְשִׁיבִים לְכָל אוֹתָם שֶׁמִּתְפַּלְלִים תְּפִלָּתָם בְּלַחַשׁ וּבִרְצוֹן הַלֵּב, שֶׁלֹּא נִשְׁמַעַת אוֹתָהּ תְּפִלָּה לְאַחֵר. הַתְּפִלָּה הַזּוֹ עוֹלָה, וּמַקְשִׁיבִים לָהּ כָּל אוֹתָם שֶׁנִּקְרָאִים בַּעֲלֵי אָזְנַיִם.</p>\n<p>וְאִם אוֹתָהּ תְּפִלָּה נִשְׁמַעַת לְאָזְנֵי אָדָם, אֵין מִי שֶׁמַּקְשִׁיב לָהּ לְמַעְלָה, וְלֹא מַקְשִׁיבִים לָהּ אֲחֵרִים, פְּרָט לְמִי שֶׁשּׁוֹמֵעַ בָּרִאשׁוֹנָה. מִשּׁוּם כָּךְ צָרִיךְ לְהִשָּׁמֵר שֶׁלֹּא יִשְׁמְעוּ אֶת אוֹתָהּ תְּפִלָּה בְּנֵי אָדָם. וְעוֹד, שֶׁדִּבּוּר שֶׁל תְּפִלָּה נֶאֱחָז בָּעוֹלָם הָעֶלְיוֹן, וְדָבָר שֶׁל הָעוֹלָם הָעֶלְיוֹן אֵין צָרִיךְ לִשְׁמֹעַ.</p>\n<p>כְּמוֹ זֶה מִי שֶׁקּוֹרֵא בְּסֵפֶר תּוֹרָה, אֶחָד קוֹרֵא וְאֶחָד לִשְׁתֹּק. וְאִם שְׁנַיִם קוֹרְאִים בַּתּוֹרָה, הֵם גּוֹרְעִים בָּאֱמוּנָה שֶׁלְּמַעְלָה, מִשּׁוּם שֶׁאֶחָד קוֹל וְאֶחָד דִּבּוּר הַכֹּל אֶחָד, אָז שְׁנֵי קוֹלוֹת וּשְׁנֵי דִבּוּרִים זוֹ גְרִיעוּת הָאֱמוּנָה. אֶלָּא שֶׁיִּהְיֶה קוֹל וְדִבּוּר אֶחָד כְּמוֹ שֶׁצָּרִיךְ, כְּדֵי שֶׁיִּהְיֶה אוֹתוֹ קוֹל וְאוֹתוֹ דִבּוּר אֶחָד.</p>\n<p>וְאוֹתוֹ הַמְמֻנֶּה שֶׁשְּׁמוֹ עַזְרִיאֵ\"ל הַזָּקֵן, כְּשֶׁאוֹתָהּ תְּפִלָּה עוֹלָה בְּלַחַשׁ, כָּל אוֹתָן שִׁשִּׁים רִבּוֹא מַחֲנוֹת, וְכָל אוֹתָם בַּעֲלֵי עֵינַיִם, וְכָל אוֹתָם בַּעֲלֵי אָזְנַיִם, כֻּלָּם יוֹצְאִים וְנוֹשְׁקִים אוֹתוֹ דִבּוּר שֶׁל תְּפִלָּהה שֶׁעוֹלֶה. זֶהוּ שֶׁכָּתוּב (תהלים לד) עֵינֵי ה' אֶל צַדִּיקִים וְאָזְנָיו אֶל שַׁוְעָתָם. עֵינֵי ה' אֶל צַדִּיקִים - אֵלּוּ בַּעֲלֵי הָעֵינַיִם שֶׁלְּמַטָּה, מִשּׁוּם שֶׁיֵּשׁ (שאין) בַּעֲלֵי עֵינַיִם שֶׁלְּמַעְלָה. וְאָזְנָיו אֶל שַׁוִעָתָם - אֵלֶּה בַּעֲלֵי הָאָזְנַיִם.</p>\n<p>הָרָקִֹיעַ הַשְּׁלִישִׁי, אוֹתָהּ תְּפִלָּה עוֹלָה וּמַגִּיעָה לְאוֹתוֹ רָקִיעַ, וְשָׁם אוֹתוֹ אוֹתוֹ שֶׁנִּקְרָא גְּדַרְיָ\"ה, וְעִמּוֹ כַּמָּה שָׂרִים וְכַמָּה מְמֻנִּים, וְהוּא מְשַׁמֵּשׁ שָׁלֹשׁ פְּעָמִים בְּיוֹם כְּנֶגֶד שַׁרְבִיט אֶחָד שֶׁל זֹהַר שֶׁיּוֹצֵא, עוֹלֶה וְיוֹרֵד, וְלֹא עוֹמֵד בְּמָקוֹם אֶחָד, וְזֶהוּ שַׁרְבִיט שֶׁנּוֹסֵעַ שָׁלֹשׁ פְּעָמִים וְנִגְנָז. וּכְשֶׁתְּפִלָּה עוֹלָה, יוֹרֵד אוֹתוֹ שַׁרְבִיט וּמִשְׁתַּחֲוֶה לִפְנֵי אוֹתָהּ תְּפִלָּה, וְהָרָקִיעַ הַזֶּה נִקְרָא רְקִיעַ הַשַּׁרְבִיט.</p>\n<p>וּכְשֶׁעוֹלָה אוֹתָהּ תְּפִלָּה, אוֹתוֹ הַמְמֻנֶּה לְאַחַר שֶׁהִשְׁתַּחֲוָה, מַכֶּה בְּאוֹתוֹ הַשַּׁרְבִיט בַּסֶּלַע הֶחָזָק שֶׁמֵּאִיר וְעוֹמֵד בְּאֶמְצַע הָרָקִיעַ, וְיוֹצְאִים מִתּוֹךְ אוֹתוֹ סֶלַע שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים וַחֲמִשָּׁה חֲיָלוֹת שֶׁגְּנוּזִים שָׁם מִיּוֹם שֶׁיָּרְדָה תוֹרָה לָאָרֶץ, מִשּׁוּם שֶׁהִתְחַזְּקוּ לְהִתְחַבֵּר (לסרב) שֶׁלֹּא תֵרֵד לָאָרֶץ, וְנָזַף בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִכְנְסוּ לְתוֹךְ אוֹתוֹ סֶלַע, וְאֵינָם יוֹצְאִים, פְּרָט לְאוֹתוֹ זְמַן שֶׁהַתְּפִלָּה עוֹלָה, פּוֹתְחִים וְאוֹמְרִים: (שם ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ וְגוֹ'. זוֹהִי תְפִלָּה שֶׁעוֹלָה עַל כָּל אוֹתָם רְקִיעִים. אָז מִשְׁתַּחֲוִים אֵלֶיהָ.</p>\n<p>מִכָּאן וָהָלְאָה, הַתְּפִלָּה מִתְעַטֶּרֶת בַּעֲטָרוֹת עֶלְיוֹנוֹת, וְעוֹלָה לְתוֹךְ הָרָקִיעַ הָרְבִיעִי, וְאָז הַשֶּׁמֶשׁ יוֹצֵא בְּדַרְגוֹתָיו, וְשַׁמְשִׁיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל יוֹצֵא, וּשְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה מַחֲנוֹת עִמּוֹ, לְתוֹךְ אוֹתוֹ רָקִיעַ, וְהֵם נִקְרָאִים יְמוֹת הַחַמָּה, וְכֻלָּם מְעַטְּרִים אֶת אוֹתָהּ תְּפִלָּה בַּעֲטָרוֹת שֶׁל בְּשָׂמִים שֶׁל גַּן עֵדֶן.</p>\n<p>וְשָׁם מִתְעַכֶּבֶת הַתְּפִלָּה, עַד שֶׁכָּל הַמַּחֲנוֹת עוֹלִים עִמּוֹ לְתוֹךְ אוֹתוֹ הָרָקִיעַ הַחֲמִישִׁי, וְשָׁם נִמְצָא מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ גַּדְרִיאֵ\"ל, וְהוּא בַּעַל הַקְּרָבוֹת שֶׁל שְׁאָר הָעַמִּים. וּכְשֶׁתְּפִלָּה עוֹלָה, אָז הוּא מִזְדַּעֲזֵעַ עִם כָּל מַחֲנוֹתָיו, וְנִשְׁבָּר כֹּחָם, וְיוֹצְאִים וּמִשְׁתַּחֲוִים וּמְעַטְּרִים אֶת אוֹתָהּ הַתְּפִלָּה.</p>\n<p>וְעוֹלִים עִמָּהּ עַד שֶׁמַּגִּיעִים לָרָקִיעַ הַשִּׁשִּׁי, וְאָז יוֹצְאִים כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת וּמְקַבְּלִים אֶת אוֹתָהּ תְּפִלָּה, וְעוֹלִים עִמָּהּ עַד שֶׁמַּגִּיעִים לְשִׁבְעִים שְׁעָרִים, שֶׁשָּׁם עוֹמֵד מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ עַנְפִיאֵ\"ל, מְמֻנֶּה גָּדוֹל, וְהוּא מְעַטֵּר אֶת אוֹתָהּ תְּפִלָּה בְּשִׁבְעִים עֲטָרוֹת.</p>\n<p>וְכֵיוָן שֶׁהַתְּפִלָּה מִתְעַטֶּרֶת בְּכָל הָעֲטָרוֹת הַלָּלוּ, אֲזַי מִתְחַבְּרִים כָּל אוֹתָם הַחֲיָלוֹת שֶׁל כָּל הָרְקִיעִים, וּמַעֲלִים אֶת אוֹתָהּ הַתְּפִלָּה שֶׁמִּתְעַטֶּרֶת בְּכָל הָעֲטָרוֹת לָרָקִיעַ הַשְּׁבִיעִי, וְאָז נִכְנֶסֶת הַתְּפִלָּה, וְסַנְדַּלְפוֹ\"ן נִכְבָּד גָּדוֹל, שֶׁכָּל מַפְתְּחוֹת אֲדוֹנָיו בְּיָדוֹ, מַכְנִיס אֶת אוֹתָהּ תְּפִלָּה לְתוֹךְ שִׁבְעָה הֵיכָלוֹת.</p>\n<p>בֹא וּרְאֶה אָמַר רַבִּי שִׁמְעוֹן שִׁבְעָה מְדוֹרִים הֵם וכו'. שִׁבְעַת הַהֵיכָלוֹת הַלָּלוּ הֵם הֵיכְלוֹת הַמֶּלֶךְ, וּכְשֶׁהַתְּפִלָּה הַזּוֹ מִתְעַטֶּרֶת בְּכָל הָעֲטָרוֹת הַלָּלוּ כְּשֶׁנִּכְנֶסֶת, מְחַבֵּר אוֹתָם כְּאֶחָד, לְהִתְעַטֵּר לְמַעְלָה לִהְיוֹת הַכֹּל אֶחָד כָּרָאוּי. וּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בְּכָל הָעֲטָרוֹת, מַעְלָה וּמַטָּה, לִהְיוֹת אֶחָד, וְאָז כָּתוּב בְּרָכוֹת לְרֹאשׁ צַדִּיק.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁיּוֹדֵעַ לְסַדֵּר תְּפִלָּתוֹ כָּרָאוּי. בַּתְּפִלָּה הַזּוֹ שֶׁמִּתְעַטֵּר בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא מְחַכֶּה עַד שֶׁיִּסְתַּיְּמוּ כָּל תְּפִלּוֹתֵיהֶם שֶׁל יִשְׂרָאֵל, וְאָז הַכֹּל הוּא בִּשְׁלֵמוּת כָּרָאוּי מַעְלָה וּמַטָּה. עַד כָּאן דִּבְרֵי הַתְּפִלָּה לָדַעַת סוֹדוֹת עֶלְיוֹנִים. מִכָּאן וָהָלְאָה יֵשׁ אֶת מִצְווֹת הַתּוֹרָה, שֶׁהֵן עוֹמְדוֹת בְּדִבּוּר כְּמוֹ שֶׁעוֹמְדוֹת בְּמַעֲשֶׂה.</p>\n<p>וְהֵן שֵׁשׁ מִצְווֹת, וְעוֹמְדוֹת אַף כָּאן בַּתְּפִלָּה. אַחַת - לְיִרְאָה אֶת הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא. שְׁתַּיִם - לְאַהֲבָה אוֹתוֹ. שְׁלִישִׁית - לְבָרְכוֹ. רְבִיעִית - לְיַחֲדוֹ. חֲמִישִׁית - שֶׁיְּבָרֵךְ הַכֹּהֵן אֶת הָעָם. שִׁשִּׁית - לִמְסֹר לוֹ אֶת נִשְׁמָתוֹ. וְאֵלּוּ שֵׁשׁ מִצְווֹת שֶׁעוֹמְדוֹת בִּתְפִלָּה שֶׁל דִּבּוּר, פְּרָט לְאוֹתָן מִצְווֹת שֶׁעוֹמְדוֹת בְּמַעֲשֶׂה, כְּמוֹ צִיצִית וּתְפִלִּין.</p>\n<p>לְיִרְאָה אֶת ה' - מִצְוָה זוֹ עוֹמֶדֶת בַּתִּשְׁבָּחוֹת הַלָּלוּ שֶׁאָמַר דָּוִד הַמֶּלֶךְ וּבְאוֹתָם קָרְבָּנוֹת שֶׁל הַתּוֹרָה, שֶׁשָּׁם צָרִיךְ אָדָם לִפְחֹד מִלִּפְנֵי אֲדוֹנוֹ, מִשּׁוּם שֶׁאוֹתָן שִׁירוֹת עוֹמְדוֹת בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יִרְאָה, וְכָל אוֹתָם הַלְלוּיָהּ שֶׁהֵם סוֹד שֶׁל יִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא. וְצָרִיךְ אָדָם לָשִׂים רְצוֹנוֹ בְּאוֹתָן שִׁירוֹת בְּיִרְאָה, וּפֵרְשׁוּהָ הַחֲבֵרִים, כָּל אוֹתָם הַסּוֹדוֹת שֶׁל שִׁירוֹת וְתִשְׁבָּחוֹת וְכָל אוֹתָם סוֹדוֹת שֶׁל הַלְלוּיָהּ.</p>\n<p>כֵּיוָן שֶׁמַּגִּיעַ אָדָם לְיִשְׁתַּבַּח, יָשִׂים רְצוֹנוֹ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ יוֹצֵר אוֹר, יוֹצֵר הַמְּאוֹרוֹת, לְאַהֲבָה אוֹתוֹ, כְּשֶׁמַּגִּיעַ לְאַהֲבַת עוֹלָם, וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ (דברים ו), שֶׁזֶּהוּ סוֹד שֶׁל אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי פֵּרְשׁוּהָ. לְיַחֲדוֹ - שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, שֶׁכָּאן עוֹמֵד סוֹד הַיִּחוּד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לְיַחֵד אֶת שְׁמוֹ בִּרְצוֹן הַלֵּב כָּרָאוּי, וּמִשָּׁם וָהָלְאָה אַזְכָּרַת יְצִיאַת מִצְרַיִם, שֶׁהִיא מִצְוָה לְהַזְכִּיר אֶת יְצִיאַת מִצְרַיִם, שֶׁכָּתוּב (שם כד) וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ בְּאֶרֶץ מִצְרָיִם.</p>\n<p>שֶׁהַכֹּהֵן יְבָרֵךְ אֶת הָעָם - כְּדֵי לְהַכְלִיל אֶת יִשְׂרָאֵל כְּאֶחָד בְּשָׁעָה שֶׁנּוֹטְלִים בְּרָכוֹת מִלְמַעְלָה, שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה נוֹטֶלֶת כְּנֶסֶת יִשְׂרָאֵל בְּרָכוֹת, וּשְׁעַת רָצוֹן הִיא לִמְסֹר נַפְשׁוֹ אֵלָיו וְלָתֵת לוֹ אֶת הַנְּשָׁמָה בִּרְצוֹן הַלֵּב. כְּשֶׁנּוֹפְלִים אַפַּיִם וְאוֹמְרִים (תהלים כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, שֶׁיְּכַוֵּן לִבּוֹ וּרְצוֹנוֹ אֵלָיו לִמְסֹר לוֹ הַנֶּפֶשׁ בְּרָצוֹן שָׁלֵם. וְאֵלּוּ הֵן שֵׁשׁ מִצְווֹת שֶׁעוֹמְדוֹת בַּתְּפִלָּה, שֶׁעוֹלוֹת לְשֵׁשׁ מֵאוֹת מִצְווֹת שֶׁל הַתּוֹרָה.</p>\n<p>וְאִם תֹּאמַר, שְׁלֹשׁ עֶשְׂרֵה אֲחֵרוֹת יוֹתֵר? אֵלּוּ עוֹמְדִים לְהַמְשִׁיךְ שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים, שֶׁהַכֹּל כָּלוּל בָּהֶן. (באלו) שֵׁשׁ הַמִּצְווֹת הַלָּלוּ שֶׁהַתְּפִלָּה מִתְעַטֶּרֶת בָּהֶן.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁשָּׂם לִבּוֹ וּרְצוֹנוֹ לָזֶה וּלְהַשְׁלִים אוֹתָם בְּכָל יוֹם. וּבָאֵלּוּ תְּלוּיוֹת אֲחֵרוֹת רַבּוֹת. אֲבָל כְּשֶׁמַּגִּיעַ אָדָם לַמְּקוֹמוֹת הַלָּלוּ, צָרִיךְ לְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לְהַשְׁלִים אוֹתָהּ מִצְוָה שֶׁעוֹמֶדֶת בְּאוֹתוֹ דִּבּוּר, וְאָז מַכְרִיזִים עָלָיו וְאוֹמְרִים: (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ.</p>\n<p>פָּתַח רַבִּי יִצְחָק אַחֲרָיו וְאָמַר, וַיַּקְהֵל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְגוֹ'. לָמָּה כִּנֵּס אוֹתָם? כְּדֵי לִמְסֹר לָהֶם אֶת הַשַּׁבָּת כְּמִקֹּדֶם, שֶׁהֲרֵי בָּרִאשׁוֹנָה טֶרֶם שֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל, מָסַר לָהֶם אֶת הַשַּׁבָּת, וְזֶהוּ שֶׁלֹּא שָׁמְרוּ אוֹתָם הָעֵרֶב רַב. כֵּיוָן שֶׁשָּׁמְעוּ בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל, אָמְרוּ: וְאָנוּ נִמְנָע מִמֶּנּוּ הַדָּבָר הַזֶּה?! מִיָּד - (שמות לב) וַיִּקָּהֵל הָעָם עַל אַהֲרֹן וְגוֹ', וְנִמְשְׁכוּ רַבִּים אַחֲרֵיהֶם. אַחַר שֶׁמֵּתוּ אוֹתָם שֶׁמֵּתוּ, כִּנֵּס מֹשֶׁה אֶת בְּנֵי יִשְׂרָאֵל לְבַדָּם, וְנָתַן לָהֶם שַׁבָּת כְּמִקֹּדֶם. זֶהוּ שֶׁכָּתוּב שֵׁשֶׁת יָמִים תֵּעָשֶׂה מְלָאכָה וְגוֹ'.</p>"],[9522011830,"<p>לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם. כָּאן יֵשׁ סוֹד הַסּוֹדוֹת לְאוֹתָם שֶׁיּוֹדְעִים הַחָכְמָה הָעֶלְיוֹנָה. אֶת סוֹד הַשַּׁבָּת הֲרֵי בֵּאֲרוּ הַחֲבֵרִים, אֲבָל סוֹד זֶה נִמְסַר לַחֲכָמִים עֶלְיוֹנִים, שֶׁהֲרֵי שַׁבָּת הִיא סוֹד עֶלְיוֹן.</p>\n<p>בֹּא וּרְאֵה, (ביום הששי בשעה שמגיע) בְּשָׁעָה שֶׁבְּיוֹם שִׁשִּׁי מַגִּיעַ הָעֶרֶב, אָז כּוֹכָב אֶחָד מִצַּד צָפוֹן מֵאִיר, וְעִמּוֹ שִׁבְעִים כּוֹכָבִים אֲחֵרִים, וְאוֹתוֹ כּוֹכָב מַכֶּה בְּאוֹתָם הַכּוֹכָבִים הָאֲחרִים, וְכֻלָּם נִכְלָלִים בְּאוֹתוֹ כּוֹכָב, וְנַעֲשֶׂה כְּלָל אֶחָד שֶׁל שִׁבְעִים. וְאוֹתוֹ כּוֹכָב מִתְפַּשֵּׁט וְנַעֲשֶׂה כִּמְדוּרָה אַחַת לוֹהֶטֶת בְּכָל הַצְּדָדִים. אֲזַי מִתְפַּשֶּׁטֶת אוֹתָהּ מְדוּרָה סְבִיב אֶלֶף הָרִים, וְעוֹמֶדֶת כְּחוּט אֶחָד שֶׁמַּקִּיף.</p>\n<p>וּמְדוּרַת הָאֵשׁ הַזּוֹ מוֹשֶׁכֶת אֵלֶיהָ גְּוָנִים אֲחֵרִים שֶׁהֵם לְתוֹךְ מִמֶּנָּה. גָּוֶן רִאשׁוֹן יָרֹק. כֵּיוָן שֶׁעוֹמֵד גָּוֶן זֶה, עוֹלָהּ אוֹתָהּ מְדוּרַת אֵשׁ וּמְדַלֶּגֶת לְמַעְלָה עַל אוֹתוֹ גָּוֶן יָרֹק, וְנִכְנֶסֶת לִפְנִים מִמֶּנּוּ, וְזוֹרֶקֶת אוֹתוֹ גָּוֶן יָרֹק הַחוּצָה, וְעוֹמֵד הַיָּרֹק בַּחוּץ, וְאוֹתָהּ מְדוּרַת אֵשׁ שֶׁל הַכּוֹכָב הַכָּלוּל לִפְנִים.</p>\n<p>אַחַר כָּךְ מַמְשִׁיכָה אַחֲרֶיהָ גָּוֶן שֵׁנִי לָבָן, וְאוֹתוֹ לָבָן נִכְנָס פְּנִימָה. כֵּיוָן שֶׁעוֹמֵד הַגָּוֶן הַזֶּה, עוֹלָה אוֹתָהּ מְדוּרַת אֵשׁ שֶׁל אוֹתוֹ כּוֹכָב, וְזוֹרֶקֶת אֶת אוֹתוֹ לָבָן הַחוּצָה, וְהִיא נִכְנֶסֶת פְּנִימָה. וְכָךְ כָּל אוֹתָם הַגְּוָנִים, עַד שֶׁזּוֹרֶקֶת אוֹתָם הַחוּצָה, וְהִיא נִכְנֶסֶת פְּנִימָה וּקְרֵבָה לְאוֹתָהּ נְקֻדָּה טְמִירָה לִטֹּל אוֹר.</p>\n<p>פָּתַח וְאָמַר, (יחזקאל א) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגוֹ'. יְחֶזְקֵאל רָאָה אֶת הַמַּרְאֶה הַזֶּה בְּתִקּוּן שֶׁלֹּא עוֹמֵד, פְּרָט לְשָׁעָה שֶׁעוֹמֵד אוֹתוֹ כּוֹכָב שֶׁאָמַרְנוּ, אֲבָל הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. וְהִנֵּה רוּחַ סְעָרָה, פֵּרְשׁוּהוּ שֶׁהָיָה בָּא לִכְבֹּשׁ אֶת כָּל הָעוֹלָם לִפְנֵי נְבוּכַדְנֶצַּר הָרָשָׁע. אֲבָל רוּחַ הַסְּעָרָה הַזּוֹ הִיא הַכּוֹכָב שֶׁאָמַרְנוּ, שֶׁבּוֹלֵעַ שִׁבְעִים כּוֹכָבִים, וְזוֹ רוּחַ הַסְּעָרָה שֶׁרָאָה אֵלִיָּהוּ, (מלכים א יט) מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, וְזֶה שֶׁעוֹמֵד תָּמִיד לִפְנֵי הַכֹּל לִשְׁמֹר אוֹתוֹ שֶׁבִּפְנִים כְּמוֹ קְלִפָּה לַמֹּחַ.</p>\n<p>וְלָמָּה נִקְרֵאת סְעָרָה? שֶׁמַּסְעִירָה הַכֹּל, מַעְלָה וּמַטָּה. בָּאָה מִן הַצָּפוֹן, שֶׁהֲרֵי מֵאוֹתוֹ צַד הִיא בָּאָה, וְסִימָנְךְ - (ירמיה א) מִצָּפוֹן תִּפָּתַח הָרָעָה, שֶׁהֲרֵי כַּמָּה צְדָדִים אֲחֵרִים נֶאֱחָזִים בְּאוֹתָהּ רוּחַ סְעָרָה, וּמִשּׁוּם כָּךְ יוֹצֵאת מִן הַצָּפוֹן.</p>\n<p>עָנָן, מִשּׁוּם שֶׁהִיא פְּסֹלֶת הַזָּהָב. וּמִצַּד הַצָּפוֹן זֶה נֶאֱחָז. וְזוֹהִי הַנְּקֻדָּה הָאֶמְצָעִית שֶׁעוֹמֶדֶת בְּחָרְבָּה. וּמִשּׁוּם שֶׁיּוֹדֵעַ לְפַתּוֹת, שׁוֹלֵט בְּתוֹךְ אוֹתָהּ נְקֻדָּה שֶׁל יִשּׁוּב וְכָל דִּבְרֵי הַיִּשּׁוּב, פְּרָט לְאֶרֶץ יִשְׂרָאֵל. כְּשֶׁיִּשְׂרָאֵל שׁוֹרִים בְּתוֹכָהּ, הוּא (לא) שׁוֹלֵט עֲלֵיהֶם. וְאַחַר שֶׁחָטְאוּ יִשְׂרָאֵל, (לא) שׁוֹלֵט עַל הָאָרֶץ הַקְּדוֹשָׁה, מִשּׁוּם שֶׁכָּתוּב הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב.</p>\n<p>הֶעָנָן הַגָּדוֹל הַזֶּה הוּא עָנָן שֶׁל חֲשֵׁכָה שֶׁמַּחְשִׁיךְ אֶת כָּל הָעוֹלָם. בּא וּרְאֵה מַה בֵּין עָנָן לְעָנָן. אוֹתוֹ עָנָן שֶׁכָּתוּב (במדברי) וַעֲנַן ה' עֲלֵיהֶם יוֹמָם. (שם יד) וַעֲנָנְךְ עֹמֵד עֲלֵהֶם. זֶהוּ עָנָן שֶׁמֵּאִיר וְזוֹהֵר, וְכָל הָאוֹרוֹת נִרְאִים בְּתוֹךְ אוֹתוֹ עָנָן. אֲבָל הֶעָנָן הַזֶּה הוּא עָנָן חָשׁוּךְ שֶׁלֹּא מֵאִיר כְּלָל, אֲבָל מוֹנֵעַ אֶת כָּל הָאוֹרוֹת שֶׁלֹּא יְכוֹלִים לְהֵרָאוֹת לְפָנָיו.</p>\n<p>גָּדוֹל, לָמָּה נִקְרָא גָדוֹל, וַהֲרֵי הוּא קָטָן? אֶלָּא הוּא גָּדוֹל כֵּיוָן שֶׁשּׁוֹלֵט. דָּבָר אַחֵר גָּדוֹל - אוֹתוֹ חֹשֶׁךְ גָּדוֹל, כֵּיוָן שֶׁמְּכַסֶּה אֶת כָּל הָאוֹרוֹת וְאֵינָם נִרְאִים לְפָנָיו, וְהוּא גָּדוֹל (שולט) עַל כָּל מַעֲשֵׂי הָעוֹלָם.</p>\n<p>וְאֵשׁ מִתְלַקַּחַת, שֶׁהֲרֵי הָאֵשׁ שֶׁל הַדִּין הַקָּשֶׁה לֹא זָזָה מִמֶּנּוּ לְעוֹלָמִים. וְנֹגַהּ לוֹ סָבִיב, אַף עַל גַב שֶׁכָּל זֶה עוֹמֵד בּוֹ - נֹגַהּ לוֹ סָבִיב. מִכָּאן לָמַדְנוּ, שֶׁאַף עַל גַּב שֶׁאֵין זֶה צַד, אֶלָּא צַד שֶׁל טֻמְאָה - נֹגַהּ לוֹ סָבִיב, וְלֹא צָרִיךְ לָאָדָם לִדְחוֹתוֹ הַחוּצָה. מָה הַטַּעַם? מִשּׁוּם שֶׁנֹּגַהּ לוֹ סָבִיב, צַד שֶׁל קְדֻשָּׁה שֶׁל אֱמוּנָה יֵשׁ לוֹ, וְלֹא צָרִיךְ לִנְהֹג בּוֹ קָלוֹן, וְלָכֵן צָרִיךְ לָתֵת לוֹ חֵלֶק בְּצַד הַקְּדֻשָּׁה שֶׁל הָאֱמוּנָה.</p>\n<p>רַב הַמְנוּנָא סָבָא כָּךְ אָמַר, וְכִי נֹגַהּ לוֹ סָבִיב, וְצָרִיךְ לִנְהֹג בּוֹ קָלוֹן, הַנֹּגַהּ לוֹ הַזֶּה הוּא בִּפְנִים, וְלֹא עוֹמֵד בַּחוּץ. וּמִשּׁוּם שֶׁהַנֹּגַהּ לוֹ הַזֶּה עוֹמֵד בִּפְנִים, כָּתוּב וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ. מִתּוֹכָהּ שֶׁל מִי? מִתּוֹכָהּ שֶׁל אוֹתוֹ נֹגַהּ. כְּעֵין הַחַשְׁמַל - חָשׁ מָל, הֲרֵי פֵּרְשׁוּהָ, חַיּוֹת שֶׁל אֵשׁ מְמַלְּלוֹת.</p>\n<p>אֲבָל מֵהַמְּנוֹרָה הַקְּדוֹשָׁה שָׁמַעְתִּי עָלֶיהָ סוֹד הַסּוֹדוֹת. כְּשֶׁעָרְלָה שׁוֹרָה עַל הַבְּרִית הַקְּדוֹשָׁה לְטַמֵּא אֶת הַמִּקְדָּשׁ, אָז אוֹתוֹ מִקְדָּשׁ מִתְעַכֵּב מִלְּגַלּוֹת אֶת סוֹד אוֹת הַבְּרִית מִתּוֹךְ הָעָרְלָה, וּכְשֶׁהַנֹּגַהּ הַזֶּה נִכְנָס פְּנִימָה וּמַפְרִיד בֵּין הָעָרְלָה לְבֵין הַמִּקְדָּשׁ, אָז נִקְרָא חַשְׁמַל, חָשׁ וְנִגְלֶה, מָל. מַה זֶּה מָל? כְּמוֹ שֶׁנֶּאֱמַר (יהושע ה) מָל יְהוֹשֻׁעַ. סוֹד שֶׁל אוֹת בְּרִית מִתְעַכֵּב מִלְּהִתְגַּלּוֹת מִתּוֹךְ עָרְלָה.</p>\n<p>וְיִשִׁ סוֹד אַחֵר, שֶׁהֲרֵי אוֹרוֹ נִרְאֶה וְלֹא נִרְאֶה, וּכְשֶׁמִּתְגַּלֶּה חַשְׁמַל, מָעֳבָר אוֹרוֹ. אֲבָל הַסּוֹד הָרִאשׁוֹן הוּא בְּסוֹד הַכָּתוּב כָּרָאוּי, וְהַכֹּל הוּא יָפֶה, וְנָאֶה הוּא.</p>\n<p>בַּנֹּגַהּ הַזֶּה מְפַתֶּה אֶת הָאִשָּׁה לִטֹּל אֶת אוֹרָהּ, וְעַל כֵּן כָּתוּב, (משלי ה) וְחָלָק מִשֶּׁמֶן חִכָּהּ. שָׂם אֶת אוֹתוֹ הָאוֹר כְּנֶגֶד הַבְּרִית, וּמִשּׁוּם כָּךְ מְפַתֶּה אוֹתָהּ וְנוֹטֶלֶת אֶת אוֹרוֹ. וְזֶהוּ הַפִּתּוּי שֶׁמְּפַתֶּה אֶת הָאִשָּׁה, שֶׁכָּתוּב נֹפֶת תִּ פְנָה שִׂפְתֵי זָרָה וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, בַּיּוֹם הַשִּׁשִּׁי כְּשֶׁמַּגִּיעַ זְמַן הָעֶרֶב, קוֹפֵץ בִּפְנִים אוֹתוֹ (מדורת) אוֹר הָאֵשׁ, וְעוֹלָה לְמַעְלָה לְהִכָּנֵס לְתוֹךְ הַגְּוָנִים. אָז מִתְתַּקְּנִים יִשְׂרָאֵל לְמַטָּה, וּמְסַדְּרִים סְעוּדוֹת וּמַתְקִינִים שֻׁלְחָנוֹת, כָּל אֶחָד וְאֶחָד אֶת שֻׁלְחָנוֹ. אָז שַׁלְהֶבֶת אַחַת יוֹצֵאת וּמַכָּה בְּאוֹתָהּ מְדוּרָה. כֵּיוָן שֶׁמַּכָּה בָּהּ, מִתְגַּלְגְּלוֹת אוֹתָהּ שַׁלְהֶבֶת וְאוֹתָהּ מְדוּרָה, וְנִכְנָסוֹת לְנֶקֶב תְּהוֹם רַבָּה, וְנִטְמָנוֹת שָׁם וְיוֹשְׁבוֹת שָׁם.</p>\n<p>וְאוֹתָהּ שַׁלְהֶבֶת הִיא מִצַּד הַיָּמִין, וּמִשּׁוּם שֶׁהִיא מִצַּד הַיָּמִין, מַעֲבִירָה אֶת אוֹתָהּ מְדוּרָה, וּמַכְנִיסָה אוֹתָהּ לְנֶקֶב תְּהוֹם רַבָּה, וְיוֹשֶׁבֶת שָׁם עַד צֵאת הַשַּׁבָּת. כֵּיוָן שֶׁיּוֹצֵאת הַשַּׁבָּת, צָרִיךְ לְעַם יִשְׂרָאֵל לְבָרֵךְ עַל הָאֵשׁ, וְיוֹצֵאת אוֹתָהּ שַׁלְהֶבֶת בַּבְּרָכָה שֶׁלְּמַטָּה, וְשׁוֹלֶטֶת עַל אוֹתָהּ מְדוּרָה כָּל אוֹתוֹ הַלַּיְלָה, וְנִכְנַעַת אוֹתָהּ מְדוּרָה.</p>"],[9522011831,"<p>בֹּא וּרְאֵה, כֵּיוָן שֶׁנִּכְנֶסֶת שַׁבָּת וְנִטְמֶנֶת אוֹתָהּ מְדוּרָה, כָּל הָאִשִּׁים שֶׁל הָאֵשׁ הַקָּשָׁה נִטְמָנוֹת וְנִכְנָעוֹת, וַאֲפִלּוּ אֵשׁ הַגֵּיהִנֹּם וְהָרְשָׁעִים שֶׁבַּגֵּיהִנֹּם יֵשׁ לָהֶם מְנוּחָה, וְכֻלָּם מַעְלָה וּמַטָּה יֵשׁ לָהֶם מְנוּחָה. כְּשֶׁיּוֹצֵאת שַׁבָּת וְיִשְׂרָאֵל מְבָרְכִים עַל הָאֵשׁ, אָז יוֹצְאִים כָּל הָאִשִּׁים שֶׁטְּמוּנִים, כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ. וּכְדֵי שֶׁלֹּא לְעוֹרֵר אֵשׁ אַחֶרֶת, כָּתוּב לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבֹתֵיכֶם בְּיוֹם הַשַּׁבָּת, וַהֲרֵי פֵּרְשׁוּהָ, וְאֵשׁ הַמִּזְבֵּחַ לָמָּה?</p>\n<p>הִתְתַּקְּנוּ מֶרְכָּבוֹת, הִתְתַּקְּנוּ מַחֲנוֹת כְּנֶגֶד רִבּוֹנְכֶם. אָז יוֹצֵאת רוּחַ אַחַת מִצַּד הַדָּרוֹם, וְאוֹתָהּ רוּחַ נִפְרֶשֶׁת עַל כָּל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת שֶׁל צַד יָמִין, וּמִתְלַבְּשׁוֹת בּוֹ, וְאוֹתָהּ רוּחַ נִקְרֵאת לְבוּשׁ כָּבוֹד שֶׁל שַׁבָּת. אָז הַשֻּׁלְחָנוֹת שֶׁל הָעוֹלָם הַזֶּה מְתֻקָּנוֹת בְּהֵיכָל אֶחָד. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁסִּדּוּר שֻׁלְחָנוֹ נִרְאֶה שָׁם כָּרָאוּי, וְהַכֹּל עוֹמֵד מְתֻקָּן בְּלִי בוּשָׁה, אִישׁ כְּפִי כֹחוֹ.</p>\n<p>כְּשֶׁנִּכְנֶסֶת שַׁבָּת, צְרִיכִים אוֹתוֹ עַם קָדוֹשׁ לִרְחֹץ עַצְמָם מִשִּׁמּוּשׁ הַחֹל. מָה הַטַּעַם? מִשּׁוּם שֶׁבַּחֹל רוּחַ אַחֶרֶת הוֹלֶכֶת וּמְשׁוֹטֶטֶת וְשׁוֹרָה עַל הָעָם, וּכְשֶׁרוֹצֶה אָדָם לָצֵאת מֵאוֹתָהּ רוּחַ וּלְהִכָּנֵס בְּרוּחַ אַחֶרֶת קְדוֹשָׁה עֶלְיוֹנָה, צָרִיךְ לִרְחֹץ עַצְמוֹ כְּדֵי לְהַשְׁרוֹת עָלָיו אוֹתָהּ רוּחַ עֶלְיוֹנָה קְדוֹשָׁה.</p>\n<p>בֹּא וּרְאֵה הַסּוֹד הָעֶלְיוֹן שֶׁל הַדָּבָר. כָּל אוֹתָם שִׁשָּׁה יָמִים (עומד הדבר של הכל) נֶאֱחָזִים בְּסוֹד שֶׁל נְקֻדָּה קְדוֹשָׁה אַחַת, וְכָל הַיָּמִים אֲחוּזִים בּוֹ. וְיֵשׁ יָמִים אֲחֵרִים שֶׁעוֹמְדִים מִבַּחוּץ בַּצַּד הָאַחֵר, וְיֵשׁ יָמִים אֲחֵרִים שֶׁעוֹמְדִים בִּפְנִים מֵעִגּוּל קָדוֹשׁ, וַאֲחוּזִים בִּנְקֻדָּה קְדוֹשָׁה.</p>\n<p>וְיִשְׂרָאֵל קְדוֹשִׁים, וְכָל אֵלּוּ שֶׁמִּתְעַסְּקִים בַּקְּדֻשָּׁה, כָּל יְמֵי הַשָּׁבוּעַ, נֶאֱחָזִים כָּל אֵלּוּ הַשִּׁשָּׁה יָמִים, בְּאֵלּוּ הַשִּׁשָּׁה יָמִים שֶׁבִּפְנִים שֶׁמְּאֻחָדִים בַּנְּקֻדָּה הַהִיא, נֶאֱחָזִים בָּזוֹ כְּדֵי לִשְׁמֹר אוֹתָם, וְכָל אוֹתָם שֵׁשֶׁת יְמֵי (ואותם ששה ימים שבפנים) הַשַּׁבָּת אוֹתָהּ נְקֻדָּה הִיא נִסְתֶּרֶת. כֵּיוָן שֶׁנִּכְנֶסֶת שַׁבָּת, אָז עוֹלָה אוֹתָהּ נְקֻדָּה וּמִתְעַטֶּרֶת וְנֶאֱחֶזֶת לְמַעְלָה, וְכֻלָּם טְמוּנִים בְּתוֹכָהּ.</p>\n<p>בֹּא וּרְאֵה, יֵשׁ יָמִים וְיֵשׁ יָמִים. יְמֵי חֹל, כְּמוֹ שֶׁנֶּאֱמַר, וְאֵלֶּה עוֹמְדִים מִחוּץ לָעַמִּים. יְמֵי הַשַּׁבָּת, שֶׁהֵם יְמֵי הַשָּׁבוּעַ, עוֹמְדִים לְיִשְׂרָאֵל. וּכְשֶׁעוֹלָה הַנְּקֻדָּה הַזּוֹ, הַכֹּל נִגְנָז, וְהִיא עוֹלָה. כֵּיוָן שֶׁהִיא עוֹלָה, אָז נִקְרֵאת שַׁבָּת.</p>\n<p>מַה זֶּה שַׁבָּת? אִם תֹּאמַר בִּשְׁבִיל שְׁבִיתָה, שֶׁכָּתוּב כִּי בוֹ שָׁבַת - יָפֶה הוּא. אֲבָל סוֹד הַדָּבָר - כֵּיוָן שֶׁעוֹלָה הַנְּקֻדָּה הַזּוֹ וְהָאוֹר מֵאִיר, אָז הִיא מִתְעַטֶּרֶת בָּאָבוֹת. כֵּיוָן שֶׁהִיא מִתְעַטֶּרֶת בָּאָבוֹת, אָז מִתְחַבֶּרֶת וְנֶאֱחֶזֶת בָּהֶם לִהְיוֹת אֶחָד, וְהַכֹּל נִקְרָא שַׁבָּת. שַׁבָּת - ש' בַּת. ש' הֲרֵי פֵּרְשׁוּהָ, הַסּוֹד שֶׁל שְׁלֹשָׁה אָבוֹת שֶׁנֶּאֱחָזִים בְּבַת יְחִידָה, וְהִיא מִתְעַטֶּרֶת בָּהֶם, וְהֵם בָּעוֹלָם הַבָּא, וְהַכֹּל אֶחָד הוּא. וְזֶהוּ ש' בַּת, לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וְאִם תֹּאמַר, שַׁבָּת הַגָּדוֹל, וְהוּא לְמַעְלָה, לָמָּה נִקְרָא שַׁבָּת? אֶלָּא וַדַּאי כָּךְ הוּא. וְסוֹד הַדָּבָר - בְּכָל מָקוֹם הַנְּקֻדָּה, שֶׁהִיא עִקָּר שֶׁל כָּל הָעַיִן, נִקְרֵאת בַּת, כְּמוֹ שֶׁנֶּאֱמַר (תהלים יז) שָׁמְרֵנִי כְּאִישׁוֹן בַּת עָיִן, מִשּׁוּם שֶׁהִיא (נקדה) הָעִקָּר שֶׁל כָּל הָעַיִן, וְהִיא נִקְרֵאת בַּת.</p>\n<p>הָעוֹלָם הַבָּא הוּא הֵיכָל לְאוֹתָהּ נְקֻדָּה עֶלְיוֹנָה, וּכְשֶׁהִיא עוֹמֶדֶת וְנוֹטֶלֶת בִּכְנָפֶיהָ אֶת הָאָבוֹת לְהִתְעַטֵּר לְמַעְלָה, הַכֹּל נִקְרָא שַׁבָּת. וּכְשֶׁהָאָבוֹת מִתְעַטְּרִים לְמַעְלָה בְּתוֹךְ הַנְּקֻדָּה הָעֶלְיוֹנָה, נִקְרָא שַׁבָּת. וּכְשֶׁנְּקֻדָּה תַּחְתּוֹנָה מִתְעַטֶּרֵת בָּאָבוֹת, נִקְרָא שַׁבָּת.</p>"],[9522011832,"<p>כְּשֶׁהַנְּקֹֻדָּה הַתַּחְתּוֹנָה הַזּוֹ עוֹלָה, וְנִרְאֵית וּמִתְקַשֶּׁטֶת, (אותה נקדה תחתונהכאשרעולהלהתעטרבאבות) אָז כָּל הַשִּׂמְחָה נִמְצֵאת לְמַעְלָה וּלְמַטָּה, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה. וּבַלַּיְלָה הַזֶּה הַנְּקֻדָּה הַזּוֹ אוֹרָהּ מִתְפַּשֵּׁט, וּפוֹרֵשׂ כְּנָפָיו עַל הָעוֹלָם, וְכָל הַשַּׁלִּיטִים הָאֲחֵרִים מָעֳבָרִים, וְנִמְצֵאת שְׁמִירָה עַל הָעוֹלָם.</p>\n<p>וְאָז נוֹסֶפֶת רוּחַ נְשָׁמָה בְּיִשְׂרָאֵל לְכָל אֶחָד וְאֶחָד, וּבְאוֹתָהּ נְשָׁמָה יְתֵרָה שׁוֹכְחִים כָּל הָעֶצֶב וְהַחֵמָה, וּכְלוּם לֹא נִמְצָא פְּרָט לַשִּׂמְחָה לְמַעְלָה וּלְמַטָּה. אוֹתָהּ רוּחַ שֶׁיּוֹרֶדֶת וְנוֹסֶפֶת בִּבְנֵי הָעוֹלָם, כְּשֶׁיּוֹרֶדֶת, רוֹחֶצֶת בַּבְּשָׂמִים שֶׁל גַּן עֵדֶן, וְיוֹרֶדֶת וְשׁוֹרָה עַל הָעָם הַקָּדוֹשׁ. אַשְׁרֵיהֶם כְּשֶׁהָרוּחַ הַזּוֹ מִתְעוֹרֶרֶת.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁאוֹתָהּ רוּחַ יוֹרֶדֶת, יוֹרְדִים עִמָּהּ לְתוֹךְ גַּן הָעֵדֶן שִׁשִּׁים מֶרְכָּבוֹת מְעֻטָּרוֹת לְשִׁשָּׁה צְדָדִים. וּכְשֶׁמַּגִּיעִים לְגַן עֵדֶן, אֲזַי כָּל אוֹתָן הָרוּחוֹת וְהַנְּשָׁמוֹת שֶׁבְּגַן עֵדֶן, כֻּלָּן מִתְעוֹרְרוֹת לְאוֹתָהּ (מתעטרות באותה) רוּחַ. הַכָּרוֹזִים קוֹרְאִים וְאוֹמְרִים: אַשְׁרֵיכֶם יִשְׂרָאֵל, הָעָם הַקָּדוֹשׁ, שֶׁרְצוֹן רִבּוֹנְכֶם מִתְעוֹרֵר אֲלֵיכֶם.</p>\n<p>סוֹד הַסּוֹדוֹת לְיוֹדְעֵי הַחָכְמָה. אַשְׁרֵיהֶם כְּשֶׁרוּחַ זוֹ מִתְעוֹרֶרֶת. הָרוּחַ הַזּוֹ הִיא הִתְפַּשְּׁטוּת הַנְּקֻדָּה הַזּוֹ, וְיוֹצֵאת מִמֶּנָּה וּמִתְפַּשֶּׁטֶת בָּעוֹלָם, וְאוֹתָהּ הִיא סוֹד הַשַּׁבָּת שֶׁשָּׁרוּי לְמַטָּה, וְעַל כָּךְ כָּתוּב בּוֹ שְׁמִירָה, (שמות לא) וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת, וַהֲרֵי פֵּרְשׁוּהָ, לֹא כָתוּב שַׁבָּת, אֶלָּא אֶת הַשַּׁבָּת, לְרַבּוֹת אוֹתָהּ רוּחַ שֶׁשּׁוֹרָה עַל הַכֹּל, וְצָרִיךְ לִשְׁמֹר אוֹתָהּ הוֹאִיל וְעוֹמֶדֶת עִם הָאָדָם. וְעַל זֶה כָּתוּב, (ישעיה נו) כָּל שֹׁמֵר שַׁבָּת מֵחַלְּלוֹ.</p>\n<p>בַּסּוֹד הַזֶּה יֵשׁ סוֹד אַחֵר. הָרוּחָ הַזּוֹ נֶהֱנֵית בַּיּוֹם הַזֶּה מֵהֲנָאָתָם שֶׁל יִשְׂרָאֵל וּמֵהָעֹנֶשׁ שֶׁלָּהֶם, וּמִשּׁוּם כָּךְ צָרִיךְ לָתֵת לָהּ עֹנֶג בְּמַאֲכָל וּבְמִשְׁתֶּה שָׁלֹשׁ פְּעָמִים בְּשָׁלֹשׁ סְעוּדוֹת שֶׁל שְׁלֹשׁ דַּרְגוֹת הָאֱמוּנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְזוֹ נוֹטֶלֶת שִׂמְחָה וָעֹנֶג בְּאוֹתָן סְעוּדוֹת שֶׁל יִשְׂרָאֵל. אַשְׁרֵי חֶלְקוֹ מִי שֶׁמְּהַנֶּה אוֹתָהּ וּמְעַנֵּג אוֹתָהּ בַּיּוֹם הַזֶּה.</p>\n<p>הָרוּחַ הַזּוֹ נֶהֱנֵית כָּל שֵׁשֶׁת הַיָּמִים מֵהָרוּחַ הָעֶלְיוֹנָה שֶׁל עַתִּיק כָּל הָעַתִּיקִים, וְכֵיוָן שֶׁיּוֹרֶדֶת בְּיוֹם הַשַּׁבָּת וְרוֹחֶצֶת בְּגַן עֵדֶן בַּלַּיְלָה, מִתְעַנֶּגֶת מֵעֹנֶג הַגּוּף בַּסְּעוּדוֹת שֶׁל הָאֱמוּנָה, וּמִתְעַטֶּרֶת (ומתעגגת) הָרוּחַ הַזּוֹ מִמַּעְלָה וּמִמַּטָּה, וְנִרְוֵית בְּכָל הַצְּדָדִים בָּעֲטָרָה (בענג) שֶׁלְּמַעְלָה וּמַטָּה.</p>\n<p>וְהוֹאִיל וְעוֹמֵד עִם הָאָדָם, צָרִיךְ לוֹ לִשְׁמֹר אוֹתוֹ, וְעַל זֶה כָּתוּב וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל אֶת הַשַּׁבָּת. אֶת הַשַּׁבָּת - שַׁבָּת זוֹ הִיא נְקֻדָּה תַּחְתּוֹנָה. אֶת הַשַּׁבָּת - זוֹהִי אוֹתָהּ רוּחַ, הִתְפַּשְּׁטוּתָהּ שֶׁל אוֹתָהּ נְקֻדָּה. אוֹתָהּ הַהִתְפַּשְּׁטוּת, כְּשֶׁנּוֹסָפוֹת קְדֻשּׁוֹת וּבְרָכוֹת מִלְמַעְלָה עַל אוֹתָהּ נְקֻדָּה, הַכֹּל נָאוֹר, וְנַעֲשֵׂית רוּחַ מְאִירָה בְּכָל הַצְּדָדִים, מִתְחַלֵּק לְמַעְלָה וּמֵאִיר, וְנֶחֱלָק לְמַטָּה וּמֵאִיר. וְזֶהוּ שֶׁכָּתוּב בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל, חֵלֶק יְרֻשָּׁה יֵשׁ לָנוּ כְּאֶחָד.</p>\n<p>הַחֵלֶק שֶׁלְּמַעְלָה מִתְעַטֵּר בַּיּוֹם הַזֶּה מֵהָעֹנֶג הָעֶלְיוֹן הַקָּדוֹשׁ, וְנֶהֱנֶה מֵהַזִּיו הָעֶלְיוֹן שֶׁל עַתִּיק כָּל הָעַתִּיקִים. הַחֵלֶק הַתַּחְתּוֹן מִתְעַטֵּר בַּיּוֹם הַזֶּה מֵהָעֹנֶג שֶׁלְּמַטָּה שֶׁנֶּהֱנֶה בַּסְּעוּדוֹת הַלָּלוּ, וְעַל כֵּן צָרִיךְ לְעַנְּגוֹ בְּמַאֲכָל וּבְמִשְׁתֶּה, בִּלְבוּשֵׁי כָבוֹד וּבְשִׂמְחַת הַכֹּל.</p>\n<p>וּכְשֶׁמִּתְעַטֵר הַחֵלֶק הַזֶּה לְמַטָּה וְנִשְׁמָר כְּמוֹ שֶׁצָּרִיךְ, עוֹלֶה לְמַעְלָה, וּמִתְחַבֵּר בְּאוֹתוֹ חֵלֶק אַחֵר. וְהַנְּקֻדָּה הַזּוֹ נוֹטֶלֶת הַכֹּל מִמַּעְלָה וּמִמַּטָּה, וְנִכְלֶלֶת מִכָּל הַצְּדָדִים. וּמִשּׁוּם שֶׁמִּתְעַטֶּרֶת בְּשַׁבָּת מִמַּעְלָה וּמִמַּטָּה, כָּל שְׁאָר הַיָּמִים נוֹתְנִים כֹּחַ לַכֹּל, וְנוֹתְנִים לָהּ שִׁלְטוֹן מִמַּעְלָה וּמִמַּטָּה. וּבְסוֹדוֹת סִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ נִמְצָא הַסּוֹד הַזֶּה, וּבֵאֵר אוֹתוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל.</p>\n<p>כָּתוּב וַיִּנָּפַשׁ, וּפֵרְשׁוּהָ - וַי נֶפֶשׁ שֶׁאָבְדָה, וְיָפֶה הוּא. אֲבָל אִם כָּךְ, וַי לַגּוּף הָיָה צָרִיךְ לוֹמַר, שֶׁמִּמֶּנּוּ אָבְדָה נֶפֶשׁ! אֲבָל סוֹד הַדָּבָר - בָּאָדָם יֵשׁ נֶפֶשׁ שֶׁנּוֹטֶלֶת וּמוֹשֶׁכֶת אֵלָיו אֶת הָרוּחַ הַזּוֹ מֵעֶרֶב שַׁבָּת, וְאוֹתָהּ הָרוּחַ שְׁרוּיָה בְּתוֹךְ אוֹתָהּ הַנֶּפֶשׁ וְדָרָה בָּהּ כָּל יוֹם הַשַּׁבָּת, וְאָז אוֹתָהּ נֶפֶשׁ יְתֵרָה הִיא בְּרִבּוּי וְתוֹעֶלֶת יוֹתֵר מִמַּה שֶּׁהָיְתָה.</p>\n<p>וְעַל זֶה שָׁנִינוּ, כָּל נַפְשׁוֹת יִשְׂרָאֵל מִתְעַטְּרוֹת בְּיוֹם הַשַּׁבָּת, וְהָעֲטָרָה שֶׁלָּהֶם, שֶׁשּׁוֹרָה הָרוּחַ הַזּוֹ בְּתוֹכָם. כֵּיוָן שֶׁיּוֹצֵאת שַׁבָּת וְאוֹתָהּ רוּחַ עוֹלָה לְמַעְלָה, אֲזַי וַי לַנֶּפֶשׁ שֶׁאִבְּדָה מַה שֶּׁאִבְּדָה. אִבְּדָה אוֹתָהּ עֲטָרָה עֶלְיוֹנָה וְאוֹתוֹ כֹּחַ קָדוֹשׁ שֶׁהָיָה בָּהּ. וְזֶהוּ וַיִּנָּפַשׁ, וַי נֶפֶשׁ, שֶׁאִבְּדָה מַה שֶּׁאִבְּדָה.</p>\n<p>עוֹנַת הַחֲכָמִים שֶׁיּוֹדְעִים הַסּוֹדוֹת הָעֶלְיוֹנִים, מִלֵּיל שַׁבָּת לְלֵיל שַׁבָּת, וּפֵרְשׁוּהָ. אֲבָל סוֹד זֶה שָׁאַלְתִּי אֶת הַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁהֲרֵי רָאִינוּ שֶׁהַכֶּתֶר הַתַּחְתּוֹן הַזֶּה לוֹקֵחַ מַה שֶּׁלּוֹקֵחַ בַּיּוֹם, וּבַלַּיְלָה נוֹתֵן מָזוֹן לְכָל צְבָאוֹ, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. לוֹקַחַת בַּיּוֹם וְנוֹתֶנֶת בַּלַּיְלָה. וְעַכְשָׁו אָמַר מֹר, שֶׁהַזִּוּוּג נִמְצָא בַּלַּיְלָה הַזֶּה?</p>\n<p>אָמַר, וַדַּאי שֶׁהַזִּוּוּג נִמְצָא בַּלַּיְלָה הַזֶּה. מָה הַטַּעַם? מִשּׁוּם שֶׁבַּלַּיְלָה הַזֶּה מַפְרִישָׁה נְשָׁמוֹת לְכָל אוֹתָם הַחֲכָמִים שֶׁיּוֹדְעִים אֶת סוֹדוֹת הַחָכְמָה, וְהַחִבּוּר וְהַזִּוּוּג לֹא נִמְצָא בְּיוֹם אַחֵר בְּכָל הַשִּׂמְחָה בְּלִי עִרְבּוּבְיָה (אלא בשביל זה) אַחֶרֶת כְּמוֹ זֶה. מִשּׁוּם שֶׁאוֹתָן נְשָׁמוֹת שֶׁמְּחַלֶּקֶת, מְחַלֶּקֶת אוֹתָן לַחֲכָמִים, לְצַדִּיקִים וְלַחֲסִידִים כָּרָאוּי. (ועוד, בכל) וּבְכָל לַיְלָה וְלַיְלָה נִמְצָא זִוּוּג וַדַּאי. מָתַי? בַּחֲצוֹת הַלַּיְלָה. וַהֲרֵי בֵּאַרְנוּ. אֲבָל לֹא בְּכָל הַצְּדָדִים כְּמוֹ בַּזִּוּוּג הַזֶּה.</p>\n<p>וּמִשּׁוּם כָּךְ, הַחֲכָמִים שֶׁיּוֹדְעִים הַסּוֹדוֹת, צְרִיכִים לְסַדֵּר תַּשְׁמִישָׁם בַּלַּיְלָה הַזֶּה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל יְמוֹת הַשַּׁבָּת יֵשׁ לָהֶם רוּחַ אַחֶרֶת שֶׁשּׁוֹרָה עַל הָעוֹלָם, וּבַלַּיְלָה הַזֶּה יֵשׁ לָהֶם רוּחַ אַחֶרֶת קְדוֹשָׁה עֶלְיוֹנָה שֶׁיּוֹרֶדֶת לְבָנִים קְדוֹשִׁים, וְאוֹתָהּ רוּחַ נוֹשֶׁבֶת מֵעַתִּיק (הקדוש) כָּל הָעַתִּיקִים, וְיוֹרֶדֶת לְתוֹךְ הַנְּקֵדָּה הַתַּחְתּוֹנָה לָתֵת לָהּ מְנוּחָה לַכֹּל. וְזֶה מִתְחַלֵּק לְכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל.</p>\n<p>וּכְשֶׁאוֹתָם חֲכָמִים יוֹשְׁבִים בְּאוֹתָהּ רוּחַ קְדוֹשָׁה, הָרוּחַ הָעֶלְיוֹנָה, צְרִיכִים לְשַׁמֵּשׁ אֶת מִטָּתָם, שֶׁהָרוּחַ הַזּוֹ מַמְשִׁיכָה אַחֲרֶיהָ לְמַטָּה אֶת כָּל אוֹתָן נְשָׁמוֹת קְדוֹשׁוֹת, וְיוֹרְשִׁים קְדוֹשִׁים עֶלְיוֹנִים בָּרוּחַ הַזּוֹ נְשָׁמוֹת קְדוֹשׁוֹת לִבְנֵיהֶם כָּרָאוּי.</p>"],[9522011833,"<p>כֵּיוָן שֶׁהָרוּחַ הַזּוֹ שׁוֹרָה עַל הָעוֹלָם, כָּל הָרוּחוֹת הָרָעוֹת וְכָל הַמְקַטְרְגִים הָרָעִים הִסְתַּלְּקוּ מִן הָעוֹלָם, וְלֹא צְרִיכִים לְהִתְפַּלֵּל עַל שְׁמִירָה, מִשּׁוּם שֶׁיִּשְׂרָאֵל שְׁמוּרִים בְּאוֹתָהּ רוּחַ, וְסֻכַּת שָׁלוֹם פּוֹרֶסֶת כְּנָפֶיהָ עֲלֵיהֶם, וְהֵם שְׁמוּרִים מֵהַכֹּל.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁלֹּא יֵצֵא אָדָם יְחִידִי, לֹא בְּלֵיל רְבִיעִי שֶׁל שַׁבָּת וְלֹא בְּלֵיל שַׁבָּת, וְצָרִיךְ אָדָם לְהִשָּׁמֵר. וַהֲרֵי אָמַרְנוּ, שֶׁבְּלֵיל הַשַּׁבָּת שְׁמוּרִים אֲנָשִׁים מִכָּל הַמְקַטְרְגִים שֶׁל הָעוֹלָם וְלֹא צְרִיכִים לְהִתְפַּלֵּל עַל שְׁמִירָה?</p>\n<p>בֹּא וּרְאֵה, כָּךְ זֶה וַדַּאי, לֵיל רְבִיעִי שֶׁל שַׁבָּת צְרִיכִים לְהִשָּׁמֵר מֵהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (בראשית א) יְהִי מְאֹרֹת. מְאֵרַת כָּתוּב חָסֵר, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁבִּגְלַל שֶׁהִיא חֲסֵרָה, כַּמָּה קְבוּצוֹת שֶׁל רוּחוֹת נִכְלְלוּ בַּמְּאֹרֹת הַזֶּה. קְלָלוֹת וּמְאֵרֹת הֵן בִּפְגִימַת הַלְּבָנָה, וְכֻלָּם שׁוֹלְטִים בְּאוֹתוֹ הַלַּיְלָה.</p>\n<p>בְּלֵיל הַשַּׁבָּת, כֵּיוָן שֶׁכֻּלָּם מִתְפַּזְּרִים לְהִכָּנֵס לַנֶּקֶב שֶׁל הֶעָפָר, שֶׁלֹּא יְכוֹלִים לִשְׁלֹט, צָרִיךְ אָדָם יְחִידִי לְהִשָּׁמֵר. וְעוֹד, אַף עַל גַּב שֶׁלֹּא יְכוֹלִים לִשְׁלֹט, נִרְאִים לִפְעָמִים, וּבֶן אָדָם יְחִידִי צָרִיךְ לְהִשָּׁמֵר.</p>\n<p>דָּבָר זֶה כָּךְ שָׁנִינוּ, וְאִם כָּךְ, זֶה חִסָּרוֹן שֶׁל הַשְּׁמִירָה. אֲבָל בְּשַׁבָּת הַשְּׁמִירָה מְצוּיָה לָעָם הַקָּדוֹשׁ, וּכְשֶׁנִּכְנֶסֶת שַׁבָּת, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַטֵּר כָּל אֶחָד וְאֶחָד מִיִּשְׂרָאֵל, וְרוֹצֶה שֶׁיִּשְׁמְרוּ אֶת הָעֲטָרָה הַקְּדוֹשָׁה הַזּוֹ שֶׁהִתְעַטְּרוּ בָהּ. וְאַף עַל גַּב שֶׁהֵם אֵינָם נִמְצָאִים בְּיִשּׁוּב, לִפְעָמִים הֵם נִרְאִים לְאָדָם יְחִידִי וּמוּרָע מַזָּלוֹ. וְצָרִיךְ לְאָדָם לְהִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה וְלִשְׁמֹר אוֹתָהּ.</p>\n<p>סוֹף סוֹף, שְׁמִירָה נִמְצֵאת בְּאוֹתוֹ לַיְלָה לָעָם הַקָּדוֹשׁ, הוֹאִיל וְסֻכַּת שָׁלוֹם פְּרוּסָה עַל הָעָם, שֶׁהֲרֵי שָׁנִינוּ, בְּכָל מָקוֹם שֶׁנִּמְצֵאת סֻכַּת שָׁלוֹם, הַצַּד הָאַחֵר לֹא נִמְצָא שָׁם, וְלָכֵן שְׁמִירָה הִיא וּשְׁמִירָה מְצוּיָה.</p>\n<p>יוֹם הַשַּׁבָּת שִׂמְחָה הִיא לַכֹּל, וְהַכֹּל נִשְׁמָר לְמַעְלָה וּלְמַטָּה. וְהָאוֹר (והגקדה) הַתַּחְתּוֹן מֵאִיר לַעֲלוֹת לְמַעְלָה בַּיֹּפִי שֶׁל שִׁבְעִים הָעֲטָרוֹת שֶׁהֵן הַחֲלָקִים הַיְתֵרִים, וְהַזָּקֵן שֶׁל כָּל הַזְּקֵנִים מִתְעוֹרֵר.</p>\n<p>אָז כְּשֶׁעוֹלֶה הָאוֹר, הָעָם הַקָּדוֹשׁ מַקְדִּימִים לְבֵית הַכְּנֶסֶת בִּלְבוּשׁ כָּבוֹד בְּשִׂמְחָה, מִתְעַטְּרִים בַּעֲטָרָה קְדוֹשָׁה שֶׁלְּמַעְלָה בְּאוֹתָהּ רוּחַ שֶׁעוֹמֶדֶת עֲלֵיהֶם לְמַטָּה, מְשַׁבְּחִים בְּשִׁירוֹת וְתִשְׁבָּחוֹת, וְהַתִּשְׁבָּחוֹת עוֹלוֹת לְמַעְלָה, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתוֹנִים בְּשִׂמְחָה, וְכֻלָּם מִתְעַטְּרִים כְּאֶחָד. פּוֹתְחִים הָעֶלְיוֹנִים וְאוֹמְרִים: אַשְׁרֵיכֶם הָעָם הַקָּדוֹשׁ בָּאָרֶץ, שֶׁרִבּוֹנְכֶם הִתְעַטֵּר עֲלֵיכֶם, וְכָל הַחֲיָלוֹת הַקְּדוֹשִׁים מִתְעַטְּרִים בִּשְׁבִילְכֶם.</p>\n<p>הַיּוֹם הַזֶּה הוּא יוֹם הַנְּשָׁמוֹת, וְלֹא יוֹם הַגּוּף, מִשּׁוּם שֶׁשִּׁלְטוֹן צְרוֹר הַנְּשָׁמוֹת הוּא, וְכָל הָעֶלְיוֹנִים וְהַתְּתּוֹנִים עוֹמְדִים בְּזִוּוּג אֶחָד, בַּעֲטָרָה שֶׁל רוּחַ יְתֵרָה עֶלְיוֹנָה קְדוֹשָׁה.</p>"],[9522011834,"<p>תְּפִלַּת הַשַּׁבָּת שֶׁל הָעָם הַקָּדוֹשׁ, שָׁלֹשׁ תְּפִלּוֹת נִמְצָאוֹת בַּיּוֹם הַזֶּה כְּנֶגֶד שָׁלֹשׁ שַׁבָּתוֹת, וּפֵרְשׁוּהָ, וְהַכֹּל אֶחָד. כֵּיוָן שֶׁנִּכְנְסוּ הָעָם הַקָּדוֹשׁ לְבֵית הַכְּנֶסֶת, אָסוּר לְהִשְׁתַּדֵּל אֲפִלּוּ בְּצֹרֶךְ בֵּית הַכְּנֶסֶת, אֶלָּא בְּדִבְרֵי תִשְׁבָּחוֹת וּתְפִלָּה וְתוֹרָה וְכָרָאוּי לָהֶם.</p>\n<p>וּמִי שֶׁמִּשְׁתַּדֵּל בִּדְבָרִים אֲחֵרִים וּבְדִבְרֵי הָעוֹלָם, זֶהוּ אָדָם שֶׁמְּחַלֵּל שַׁבָּת, וְאֵין לוֹ חֵלֶק בְּעַם יִשְׂרָאֵל. שְׁנֵי מַלְאָכִים מְמֻנִּים עַל זֶה בְּיוֹם הַשַּׁבָּת, וְהֵם שָׂמִים יְדֵיהֶם עַל רֹאשׁוֹ וְאוֹמְרִים: אוֹי לִפְלוֹנִי שֶׁאֵין לוֹ חֵלֶק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. וְעַל זֶה צָרִיךְ לְהִשְׁתַּדֵּל בִּתְפִלָּה וּבְשִׁירִים וּבְתִשְׁבָּחוֹת שֶׁל אֲדוֹנָם, וּלְהִשְׁתַּדֵּל בַּתּוֹרָה.</p>\n<p>הַיּוֹם הַזֶּה הוּא יוֹם הַנְּשָׁמוֹת שֶׁמִּתְעַטֵּר אוֹתוֹ צְרוֹר הַנְּשָׁמוֹת (בתשבחות של אדונם). מִשּׁוּם כָּךְ מְשַׁבְּחִים בְּתִשְׁבָּחוֹת תִּשְׁבַּחַת הַנְּשָׁמָה, וְהַיְנוּ נִשְׁמַת כָּל חַי תְּבָרֵךְ אֶת שִׁמְךְ ה' אֱלֹהֵינוּ וְרוּחַ כָּל בָּשָׂר וְכוּ'. וְאֵין הַתִּשְׁבַּחַת אֶלָּא בְּצַד שֶׁל נְשָׁמָה וְרוּחַ, וְהַיּוֹם הַזֶּה עוֹמֵד בְּרוּחַ וּנְשָׁמָה, וְלֹא שֶׁל גּוּף.</p>\n<p>הַתִּשְׁבַּחַת שֶׁל דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה, סוֹד הַיּוֹם, שֶׁמֶשׁ קְדוֹשָׁה שֶׁהִיא אוֹר הַיּוֹם, הַיְנוּ יוֹצֵר אוֹר. סוֹד הָאוֹר הַמֵּאִיר, שֶׁמִּמֶּנּוּ נִזּוֹנִים וּמְאִירִים כָּל אוֹתָן הַצְּבָאוֹת, הַמֶּרְכָּבוֹת, וְהַכּוֹכָבִים וְהַמַּזָּלוֹת, וְכָל אוֹתָם שֶׁשּׁוֹלְטִים עַל הָעוֹלָם.</p>\n<p>תִּשְׁבַּחְתּוֹ שֶׁל הָעוֹלָם הַבָּא בַּיּוֹם הַזֶּה, הַיְנוּ אֵל אָדוֹן. וְהַתִּשְׁבַּחַת הַזּוֹ הִיא בְּסוֹד עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת עֶלְיוֹנוֹת קְדוֹשׁוֹת שֶׁמִּתְעַטְּרוֹת בָּאָבוֹת וּבַמֶּרְכָּבָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה.</p>\n<p>הָאוֹתִיּוֹת הַקְּטַנּוֹת הֵן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, שֶׁהֵן הָעוֹלָם הַתַּחְתּוֹן, שֶׁהֵן אֵל בָּרוּךְ גְּדוֹל דֵּעָה וְכוּ', וְאֵין בֵּין תֵּבָה לְתֵבָה רֶוַח אַחֵר, אֶלָּא אוֹת רְשׁוּמָה בְּכָל תֵּבָה וְתֵבָה. וּבָעוֹלָם הָעֶלְיוֹן יֵשׁ רֶוַח, וְהַצְּדָדִים הַקְּדוֹשִׁים בֵּין אוֹת לְאוֹת. וְזוֹהִי תִשְׁבַּחַת עַל תִּשְׁבַּחַת, שֶׁהָאוֹתִיּוֹת הָעֶלְיוֹנוֹת שֶׁל הַיּוֹם הַשְּׁבִיעִי מְשַׁבְּחוֹת וְאוֹמְרוֹת לַמֶּלֶךְ הָעֶלְיוֹן יוֹצֵר בְּרֵאשִׁית.</p>\n<p>כְּשֶׁהַתִּשְׁבַּחַת הַזּוֹ עוֹלָה לְמַעְלָה, שִׁשִּׁים מֶרְכָּבוֹת עֶלְיוֹנוֹת שֶׁאָמַרְנוּ, מִזְדַּמְּנוֹת וְלוֹקְחוֹת אֶת הַתִּשְׁבַּחַת הַזּוֹ מֵהָעָם הַקָּדוֹשׁ, וּמַעֲלִים אוֹתָהּ לְהִתְעַטֵּר בָּהּ בְּכַמָּה מֶרְכָּבוֹת עֶלְיוֹנוֹת שֶׁמְּמֻנּוֹת. וְכָל אוֹתָם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כֻּלָּם מִתְעַטְּרִים בַּתִּשְׁבַּחַת הַ את, וְכָל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים, כֻּלָּם עוֹלִים בַּתִּשְׁבַּחַת הַזּוֹ עַד סוֹד הַכִּסֵּא.</p>\n<p>וּכְשֶׁמַּגִּיעָה לַכִּסֵּא הַקָּדוֹשׁ הַתִּשְׁבַּחַת הַזּוֹ שֶׁל כָּל יִשְׂרָאֵל, עוֹמֶדֶת שָׁם עַד הַזְּמַן שֶׁאוֹמְרִים הַקְּדֻשָּׁה הָעֶלְיוֹנָה שֶׁל מוּסָף. וְאָז הָעֲלִיָּה שֶׁלְּמַטָּה לְמַעְלָה, לְהֵאָחֵז הַכֹּל לְמַעְלָה לְמַעְלָה לִהְיוֹת הַכֹּל אֶחָד. זוֹהִי הַתִּשְׁבַּחַת שֶׁעוֹלָה עַל כָּל הַתִּשְׁבָּחוֹת.</p>\n<p>מִכָּאן וָהָלְאָה סִדּוּר הַתְּפִלָּה שֶׁל שְׁאָר הַיָּמִים, עַד יִשְׂמַח מֹשֶׁה וְכוּ', הַשִּׂמְחָה שֶׁל הַדַּרְגָּה הָעֶלְיוֹנָה, עִקַּר הָאָבוֹת, שֶׁשָּׂמֵחַ בְּאוֹתוֹ חֵלֶק שֶׁלּוֹ כְּשֶׁהַכִּסֵּא עוֹלֶה אֵלָיו וְנוֹטֵל אוֹתָהּ, וּמִתְחַבְּרִים כְּאֶחָד. וְזוֹהִי שִׂמְחַת הַתּוֹרָה הָעֶלְיוֹנָה שֶׁלְּמַעְלָה, תּוֹרָה שֶׁבִּכְתָב. שֶׁשָּׂמֵחַ בַּתּוֹרָה שֶׁלְּמַטָּה, תּוֹרָה שֶׁבְּעַל פֶּה, וּמִתְחַבְּרִים זֶה עִם זוֹ.</p>\n<p>כֵּיוָן שֶׁהִתְחַבְּרוּ כְּאֶחָד, צָרִיךְ אָדָם לְהַכְלִיל בְּאוֹתָהּ שִׂמְחָה אֶת הָעָם הַקָּדוֹשׁ, יִשְׂמְחוּ בְמַלְכוּתְךְ שׁוֹמְרֵי שַׁבָּת וְכוּ', אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִמְנוּחָתֵנוּ.</p>"],[9522011835,"<p>סוֹד סֵפֶר הַתּוֹרָה בַּיּוֹם הַזֶּה הֲרֵי פֵּרְשׁוּהוּ, שֶׁשָּׁנִינוּ כָּתוּב (נחמיה ח) וַיִּקְרְאוּ בַסֵפֶר בְּתוֹרַת הָאֱלֹהִים מְפֹרָשׁ וְשׂוֹם שֶׂכֶל וַיָּבִינוּ בַּמִּקְרָא, וַהֲרֵי בֵּאֲרוּ אֶת הַסּוֹד, שֶׁהֵם פִּסּוּקִים, טְעָמִים וּמָסֹרֶת, וְכָל אוֹתָם דִּיּוּקִים (תקונים) וְסוֹדוֹת עֶלְיוֹנִים, הַכֹּל נִמְסַר לְמֹשֶׁה מִסִּינַי. אִם בְּכָל הַדִּיּוּקִים הַלָּלוּ נִמְסְרָה תוֹרָה לְמֹשֶׁה, אָז סֵפֶר תּוֹרָה שֶׁהוּא בְּכָל אוֹתָן קְדֻשּׁוֹת, לָמָּה הוּא חָסֵר מִכָּל הַתִּקּוּנִים הָאֵלּוּ וְהַסּוֹדוֹת שֶׁנִּמְסְרוּ לוֹ לְמֹשֶׁה בַּתּוֹרָה?</p>\n<p>אֶלָּא סוֹד זֶה, כְּשֶׁהַכִּסֵּא הַקָּדוֹשׁ מִתְעַטֵּר, וְנִכְלֶלֶת בַּתּוֹרָה שֶׁבִּכְתָב כָּל אוֹתָן דְּמֻיּוֹת, וְכָל אוֹתָם טְעָמִים וּמָסוֹרוֹת, כֻּלָּם נִכְנָסִים בִּגְנִיזָה וְנִרְשְׁמוּ בְּתוֹךְ הַכִּסֵּא הַקָּדוֹשׁ, וְאוֹתָן דְּיוֹקְנָאוֹת שֶׁהִכְנִיסָה תוֹרָה שֶׁבִּכְתָב בַּתּוֹרָה שֶׁבְּעַל פֶּה, וּבָהֶם הִתְעַבְּרָה כְּמוֹ אִשָּׁה שֶׁהִתְעַבְּרָה מֵהַזָּכָר, וְנִשְׁאֲרוּ הָאוֹתִיּוֹת הָעֶלְיוֹנוֹת לְבַדָּן בִּקְדֻשָּׁתָן כָּרָאוּי. וּלְהֵרָאוֹת בְּבֵית הַכְּנֶסֶת, שֶׁהֲרֵי מִתְבָּרֶכֶת וּמִתְעַטֶּרֶת הַכִּסֵּא מִסּוֹד תּוֹרָה שֶׁבִּכְתָב, וְשָׁם מַכְנִיסָה כָּל אוֹתָן דְּמֻיּוֹת וּמִתְקַדֶּשֶׁת מִמֶּנּוּ, צָרִיךְ לְהֵרָאוֹת בָּאוֹתִיּוֹת לְבַדָּן כָּרָאוּי.</p>\n<p>וְאָז הַכֹּל מִתְקַדֵּשׁ בִּקְדֻשָּׁה עֶלְיוֹנָה כָּרָאוּי, כָּל שֶׁכֵּן וְכָל שֶׁכֵּן בַּיּוֹם הַזֶּה. בַּיּוֹם הַזֶּה צָרִיךְ לְהַעֲלוֹת שִׁבְעָה אֲנָשִׁים כְּנֶגֶד שִׁבְעָה קוֹלוֹת, שֶׁהֵם סוֹד הַתּוֹרָה, וּבִזְמַנִּים וּבְמוֹעֲדִים חָמֵשׁ תּוֹךְ סוֹד זֶה. בְּיוֹם הַכִּפּוּרִים שֵׁשׁ תּוֹךְ הַסּוֹד הָעֶלְיוֹן הַזֶּה.</p>\n<p>וְהַסֹל סוֹד אֶחָד. חָמֵשׁ, שֶׁהֵם חָמֵשׁ דְּרָגוֹת לְמַטָּה מִדַּרְגַּת הָאוֹר הָרִאשׁוֹן לְמַטָּה, וְהֵם סוֹד הַתּוֹרָה. שֵׁשׁ, שֶׁהֵם שִׁשָּׁה צְדָדִים, וְהַכֹּל סוֹד אֶחָד. שֶׁבַע הֵם שִׁבְעָה קוֹלוֹת, וְכֻלָּם סוֹד אֶחָד אֵלֶּה וְאֵלֶּה.</p>\n<p>בְּרֹאשׁ חֹדֶשׁ נוֹסָף אֶחָד עַל שְׁלֹשָׁה בִּשְׁבִיל הַשֶּׁמֶשׁ שֶׁמֵּאִיר בְּאוֹתוֹ זְמַן לַלְּבָנָה, וְנוֹסָף אוֹר עַל הַלְּבָנָה, וְזֶהוּ סוֹד מוּסָף. בְּסֵפֶר תּוֹרָה צָרִיךְ לְהִשָּׁמַע קוֹל אֶחָד וְדִבּוּר.</p>\n<p>הַסִּדּוּר לְסַדֵּר הָעָם הַקָּדוֹשׁ בַּיּוֹם הַזֶּה וּבִשְׁאָר הַיָּמִים שֶׁלַּסֵּפֶר תּוֹרָה צָרִיךְ לְסַדֵּר וּלְתַקֵּן תִּקּוּן בְּכִסֵּא אֶחָד שֶׁנִּקְרָא תֵּבָה, וְאוֹתוֹ כִּסֵּא שֶׁיִּהְיֶה בְּשֵׁשׁ דְּרָגוֹת לַעֲלוֹת בָּהֶם, וְלֹא יוֹתֵר, שֶׁכָּתוּב וְשֵׁשׁ מַעֲלוֹת לַכִּסֵּא. וְדַרְגָּה אַחַת לְמַעְלָה לָשִׂים עָלָיו סֵפֶר תּוֹרָה וּלְהַרְאוֹתוֹ לַכֹּל.</p>\n<p>כְּשֶׁעוֹלֶה לְשָׁם סֵפֶר תּוֹרָה, אָז צְרִיכִים כָּל הָעָם לְסַדֵּר עַצְמָם לְמַטָּה בְּאֵימָה וָפַחַד, בְּרֶתֶת וּבְזִיעַ וּלְכַוֵּן לִבָּם, כְּאִלּוּ שֶׁכָּעֵת עוֹמְדִים עַל הַר סִינַי לְקַבֵּל תּוֹרָה, וְיִהְיוּ מַקְשִׁיבִים וּמַטִּים אָזְנֵיהֶם. וְאֵין רְשׁוּת לָעָם לִפְתֹּחַ פִּיהֶם אֲפִלּוּ בְּדִבְרֵי תוֹרָה, כָּל שֶׁכֵּן בְּדָבָר אַחֵר, אֶלָּא כֻּלָּם בְּאֵימָה, כְּמִי שֶׁאֵין לוֹ פֶּה, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (נחמיה ח) וּכְפִתְחוֹ עָמְדוּ כָל הָעָם. (שם) וְאָזְנֵי כָל הָעָם אֶל סֵפֶר הַתּוֹרָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כְּשֶׁמּוֹצִיאִים סֵפֶר תּוֹרָה בְּצִבּוּר לִקְרֹא בוֹ, נִפְתָּחִים שַׁעֲרֵי רַחֲמִים בַּשָּׁמַיִם, וּמְעוֹרְרִים אֶת הָאַהֲבָה לְמַעְלָה, וְצָרִיךְ אָדָם לוֹמַר כָּךְ.</p>\n<p>בָּרוּךָ שְׁמוֹ שֶׁל רִבּוֹן הָעוֹלָם, בָּרוּךְ כִּתְרְךְ וּמְקוֹמְךְ, יִהְיֶה רְצוֹנְךְ עִם עַמְּךְ יִשְׂרָאֵל לְעוֹלָם, וּפְדוּת יְמִינְךְ הַרְאֵה לְעַמְּךְ בְּבֵית מִקְדָּשְׁךְ, וּלְהַגִּיעַ לָנוּ מִטּוּב אוֹרְךְ וּלְקַבֵּל תְּפִלּוֹתֵינוּ בְּרַחֲמִים. יְהִי רָצוֹן מִלְּפָנֶיךְ, שֶׁתַּאֲרִיךְ לָנוּ חַיִּים בְּטוֹב, וְלִהְיוֹתִי נִפְקָד בֵּין הַצַּדִּיקִים לְרַחֵם עָלַי וְלִשְׁמֹר אוֹתִי, וְאֶת כָּל שֶׁלִּי וְשֶׁל כָּל עַמְּךְ יִשְׂרָאֵל. אַתָּה הוּא הַזָּן אֶת הַכֹּל, אַתָּה הוּא הַשּׁוֹלֵט עַל הַמְּלָכִים וּמְפַרְנֵס אֶת הַכֹּל. אַתָּה הוּא הַשּׁוֹלֵט עַל הַכֹּל, וְהַמַּלְכוּת שֶׁלְּךְ הִיא. אֲנִי עַבְדּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמִּשְׁתַּחֲוֶה לְפָנָיו וּמִלִּפְנֵי כְּבוֹד תּוֹרָתֵנוּ בְּכָל זְמַן וּזְמַן. לֹא עַל אִישׁ אֲנִי בּוֹטֵחַ וְלֹא עַל בְּנֵי אֱלֹהִים אֲנִי סוֹמֵךְ, אֶלָּא בֵּאלֹהֵי הַשָּׁמַיִם, שֶׁהוּא אֱלֹהֵי אֱמֶת וְתוֹרָתוֹ אֱמֶת וּנְבִיאָיו אֱמֶת, וּמַרְבֶּה לַעֲשׂוֹת טוֹבוֹת וֶאֱמֶת. בּוֹ אֲנִי בּוֹטֵחַ, וְלִשְׁמוֹ הַקָּדוֹשׁ וְהַנִּכְבָּד אֲנִי אוֹמֵר תִּשְׁבָּחוֹת. יְהִי רָצוֹן מִלְּפָנֶיךְ, שֶׁתִּפְתַּח לִבִּי בְּתוֹרָתְךְ, וְתִתֵּן לִי בָּנִים זְכָרִים שֶׁעוֹשִׂים רְצוֹנְךְ, וְתַשְׁלִים מִשְׁאֲלוֹת לִבִּי וְלֵב כָּל עַמְּךְ יִשְׂרָאֵל לְטוֹב וּלְחַיִּים וּלְשָׁלוֹם, אָמֵן.</p>\n<p>וְאָסוּר לִקְרֹא בְּסֵפֶר תּוֹרָה, רַק אֶחָד לְבַדּוֹ, וְכֻלָּם מַקְשִׁיבִים וְשׁוֹתְקִים, כְּדֵי שֶׁיִּשְׁמְעוּ הַדְּבָרִים מִפִּיו כְּאִלּוּ קִבְּלוּ אוֹתָהּ בְּאוֹתָהּ שָׁעָה מֵהַר סִינַי. וּמִי שֶׁקּוֹרֵא בַתּוֹרָה, שֶׁיִּהְיֶה אֶחָד עוֹמֵד עָלָיו וְשׁוֹתֵק, שֶׁלֹּא יִשָּׁמַע - רַק דִּבּוּר אֶחָד לְבַדּוֹ וְלֹא שְׁנֵי דִבּוּרִים. לְשׁוֹן קֹדֶשׁ אַחַת, וְאֶחָד הוּא, וְלֹא שְׁנֵי דִבּוּרִים. וְאִם נִמְצָאִים שְׁנַיִם בַּסֵּפֶר תּוֹרָה, זֶהוּ חִסָּרוֹן שֶׁל סוֹד הָאֱמוּנָה, וְחֶסְרוֹן כְּבוֹד הַתּוֹרָה נִמְצָא בַּסֵּפֶר תּוֹרָה. וְצָרִיךְ קוֹל אֶחָד, מְתַרְגֵּם אֶחָד, וְסוֹד זֶה - קְלִפָּה וּמֹחַ. (סוד העולם וסוד העולם הבא).</p>\n<p>כֻּלָּם שׁוֹתְקִים וְאֶחָד קוֹרֵא, שֶׁכָּתוּב (שמות כ) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. הוּא לְמַעְלָה, וְכָל הָעָם לְמַטָּה, שֶׁכָּתוּב (שמות יט) וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר. וְכָתוּב וּמֹשֶׁה עָלָה אֶל הָאֱלֹהִים.</p>\n<p>וְאוֹתוֹ שֶׁקּוֹרֵא בַתּוֹרָה, יָשִׂים לִבּוֹ וּרְצוֹנוֹ לְאוֹתָם דְּבָרִים, וְכִי הוּא שְׁלִיחַ רִבּוֹנוֹ בְּסִדּוּרָם שֶׁל הַדְּבָרִים הַלָּלוּ לְהַשְׁמִיעַ לְכָל הָעָם, שֶׁהֲרֵי הוּא עוֹמֵד כְּדֻגְמָה עֶלְיוֹנָה. מִשּׁוּם כָּךְ, מִי שֶׁעוֹלֶה לִקְרֹא בַתּוֹרָה, יְסַדֵּר אוֹתָם דְּבָרִים בָּרִאשׁוֹנָה בְּבֵיתוֹ, וְאִם לֹא, לֹא יִקְרָא בַתּוֹרָה. מִנַּיִן לָנוּ? מֵאוֹתוֹ דִּבּוּר, שֶׁטֶּרֶם יַשְׁמִיעַ תּוֹרָה לָעָם הַקָּדוֹשׁ, מַה כָּתוּב? (איוב כח) אָז רָאָהּ וַיְסַפְּרָהּ הֱכִינָהּ וְגַם חֲקָרָהּ. וְאַחַר כָּךְ, וַיֹּאמֶר לָאָדָם הֵן יִרְאַת ה' הִיא חָכְמָה וְגוֹ'.</p>\n<p>אָסוּר לוֹ לְמִי שֶׁקּוֹרֵא בַתּוֹרָה לְהַפְסִיק בַּפָּרָשָׁה אוֹ אֲפִלּוּ דָּבָר אֶחָד, אֶלָּא רַק בְּמָקוֹם שֶׁהִפְסִיק מֹשֶׁה אֶת הַפָּרָשָׁה לָעָם הַקָּדוֹשׁ - יַפְסִיק, וְלֹא יַפְסִיק דִּבְרֵי פָּרָשַׁת שַׁבָּת זוֹ בְּפָרָשַׁת שַׁבָּת אַחֶרֶת.</p>\n<p>הַסּוֹד הַזֶּה, בְּשָׁעָה שֶׁהִפְסִיקוּ פָרָשִׁיּוֹת, כָּל אַחַת וְאַחַת מִתְעַטֶּרֶת וְעוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁהִשְׁלִימוּ לְהַפְסִיק לְכָל הַשָּׁנָה אֶת הַפָּרָשִׁיּוֹת הַלָּלוּ, הִתְעַטְּרוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאוֹמְרוֹת: אֲנִי מִשַּׁבָּת פְּלוֹנִי (מצבור פלוני), וַאֲנִי מִשַּׁבָּת פְּלוֹנִי (מצבור פלוני).</p>\n<p>בְּאוֹתָהּ שָׁעָה קוֹרֵא לְיוּפִיאֵ\"ל מְמֻנֶּה הַגָּדוֹל, וְלַחֲמִשִּׁים וְשָׁלֹשׁ מֶרְכָּבוֹת קְדוֹשׁוֹת שֶׁתַּחַת יָדוֹ שֶׁהִתְמַנּוּ לְשִׁמּוּשָׁהּ שֶׁל תּוֹרָה, וְכָל מֶרְכָּבָה וּמֶרְכָּבָה מִנָּה אוֹתָהּ אֶת הַמֶּרְכָּבָה הַזּוֹ עַל פָּרָשָׁה פְּלוֹנִית שֶׁבְּשַׁבָּת פְּלוֹנִית, וּמֶרְכָּבָה פְּלוֹנִית עַל פָּרָשָׁה פְּלוֹנִית שֶׁל שַׁבָּת פְּלוֹנִית. וְכָל אַחַת וְאַחַת מְשַׁמֶּשֶׁת אֶת הַתּוֹרָה שֶׁל אוֹתָהּ שַׁבָּת שֶׁלָּהּ, וְאָסוּר לָנוּ לְעָרֵב אֵלֶּה בְּאֵלֶּה, וְלֹא לְהַכְנִיס מֶרְכָּבָה לְמֶרְכֶּבֶת חֲבֶרְתָּהּ אֲפִלּוּ כִּמְלֹא נִימָה, וַאֲפִלּוּ בְּתֵבָה אַחַת אוֹ אֲפִלּוּ בְּאוֹת אַחַת. אֶלָּא כָּל אַחַת וְאַחַת כְּפִי שֶׁפָּסַק לָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְמוֹ שֶׁמִּנָּה אוֹתָן בְּאוֹתָן פָּרָשִׁיּוֹת, כָּל אַחַת וְאַחַת עַל מִשְׁמַרְתָּהּ.</p>\n<p>וְלָכֵן כְּשֶׁמִּתְעַטֶּרֶת פָּרָשָׁה זוֹ, עוֹלוֹת אוֹתָן הַמִּלִּים שֶׁל אוֹתָהּ הַפָּרָשָׁה שֶׁנִּשְׁלְמָה בַּצִּבּוּר, וְאוֹתָהּ מֶרְכָּבָה לוֹקַחַת אוֹתָם, זוֹ שֶׁמְּמֻנָּה עַל אוֹתָהּ פָּרָשָׁה, וּמַעֲלָה אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹתָם מִלִּים מַמָּשׁ עוֹמְדוֹת לְפָנָיו וְאוֹמְרוֹת: אֲנִי פָּרָשָׁה פְּלוֹנִית שֶׁהִשְׁלִימוּנִי צִבּוּר פְּלוֹנִי כָּךְ וְכָךְ.</p>\n<p>אִם הִשְׁתַּלְּמָה כָּרָאוּי לָהּ, מַעֲלִים אֶת אוֹתָן מִלִּים, וּמִתְעַטְּרוֹת עַל הַכִּסֵּא הַקָּדוֹשׁ, וְאוֹתָהּ מֶרְכָּבָה מְשַׁמֶּשֶׁת לְפָנָיו, כָּל מֶרְכָּבָה וּמֶרְכָּבָה, הַפָּרָשָׁה שֶׁל כָּל שַׁבָּת וְשַׁבָּת, וְכֻלָּן מִתְעַטְּרוֹת בְּתוֹךְ הַכִּסֵּא הַקָּדוֹשׁ, וּבָהֶן הִיא עוֹלָה לְהִתְיַחֵד לְמַעְלָה לְמַעְלָה, וְהַכֹּל נַעֲשֶׂה כְּלָל אֶחָד. מִשּׁוּם כָּךְ, אַשְׁרֵי חֶלְקוֹ מִי שֶׁמַּשְׁלִים פָּרָשַׁת כָּל שַׁבָּת וְשַׁבָּת כָּרָאוּי כְּמוֹ שֶׁפִּסְּקוּ אוֹתָהּ לְמַעְלָה.</p>\n<p>פַּעָמַיִם קוֹרְאִים בְּסֵפֶר תּוֹרָה בְּשַׁבָּת; בַּמִּנְחָה, בְּשָׁעָה שֶׁהַדִּין תָּלוּי לְעֵת עֶרֶב, צְרִיכִים לְהַכְלִיל שְׂמֹאל בְּיָמִין, שֶׁהֲרֵי תּוֹרָה נִתְּנָה מִשְּׁנֵי צְדָדִים, שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, מִיָּמִין וּשְׂמֹאל. מִשּׁוּם כָּךְ לְסֵפֶר הַתּוֹרָה בְּמִנְחָה דַּי בַּעֲשָׂרָה פְסוּקִים אוֹ יוֹתֵר, אֲבָל לֹא שְׁלֵמוּת הַפָּרָשָׁה, שֶׁהֲרֵי שְׁלֵמוּת הַפָּרָשָׁה אֵינָהּ אֶלָּא בְּיָמִין, וְהַיָּמִין תָּלוּי עַד שְׁעַת הַמִּנְחָה, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בַּשֵּׁנִי בְּשַׁבָּת וּבַחֲמִישִׁי בְּשַׁבָּת, מִשּׁוּם שֶׁיּוֹרְדוֹת הַדְּרָגוֹת לְמַטָּה, שֶׁהֵם כְּלַל הַתּוֹרָה. וְאִם תֹּאמַר, הֲרֵי נְבִיאִים הִתְפָּרְשׁוּ לְמַטָּה - אֶלָּא כָּךְ זֶה וַדַּאי. אֲבָל אֵלֶּה שֶׁלְּמַטָּה, כֻּלָּם כְּלָל שֶׁל הַתּוֹרָה, וְכָל אֶחָד וְאֶחָד כּוֹלֵל כָּל אֶחָד וְאֶחָד.</p>\n<p>וְסוֹד הַדָּבָר - הַדְּרָגוֹת הָעֶלְיוֹנוֹת הַלָּלוּ הֵן נִקְרָאוֹת פָּרָשָׁה אַחַת, וְאַחַר כָּךְ יוֹצְאוֹת מֵהֶן תֵּשַׁע דְּרָגוֹת שֶׁנֶּאֱחָזוֹת כְּאחָד, וּמִשּׁוּם כָּךְ תִּשְׁעָה אֲנָשִׁים; שְׁלֹשָׁה בְּמִנְחָה בְּשַׁבָּת, וּשְׁלֹשָׁה בְּיוֹם שֵׁנִי, וּשְׁלֹשָׁה בְּיוֹם חֲמִישִׁי. הֲרֵי תִּשְׁעָה.</p>"]]});
